/// 两张卡的正文缩进 = 主干 `Margin=(22, Sp2, 0, 0)`（`:1078` 压缩摘要体 / `:1145` 成员列表）。
const DOMAIN_CARD_BODY_MARGIN: [f64; 4] = [22.0, space::S2, 0.0, 0.0];

/// 主干 `CompactionState`（`MessageDetails.cs:71-80`）+ 旁路表 `_compactions`（`:102`，
/// key = compactionId）的分叉等价物：**本文件内的插入序 Vec**（同 `DetailsLedger` 的
/// `model_retries` 口径 —— 主干 `:1027` 的 `LastOrDefault()` 取的就是最后插入那一格）。
/// 主干那格 `Expanded` 不存这里：分叉的展开态按气泡寻址键记在 [`Shell::compaction_open`]
/// （既有同族 = `reasoning_open`），因为查格会回落「最后一格」，态存进行里就会回错。
/// 主干那格 `Bubble`（对象引用）对应这里的 `row_key`。
struct CompactionRow {
    id: String,
    summary: Option<String>,
    shadowed_items: i64,
    shadowed_tokens: i64,
    running: bool,
    row_key: String,
}

/// 主干 `Str(data,"compactionId")` + `:687` 的回落。**只有 start 那一案有回落**
/// （`"compaction-" + envTime`）；摘要与收尾两案读不到 id 是**整案 return**（`:715`/`:735`），
/// 所以这两案走 [`frame_id_of`]，不许顺手共用本颗。
#[must_use]
fn compaction_start_id(event: &Value, time: i64) -> String {
    let id = frame_id_of(event, "compactionId");
    if id.is_empty() {
        format!("compaction-{time}")
    } else {
        id
    }
}

/// 主干那颗 `Str(data, key)`：读不出来（缺键 / 非字符串）一律 `""`。
#[must_use]
fn frame_id_of(event: &Value, key: &str) -> String {
    event["data"][key].as_str().unwrap_or_default().to_string()
}

/// 主干 `HandleCompactionStart`（`:684-707`）。返回 `true` = 这个 id 第一次见 ⇒ 调用方落行
/// （主干同一判据是 `st.Bubble is null ⇒ AppendBubble`，否则只 `RepaintBubble`；分叉每条 Msg
/// 整树重算 ⇒ repaint 档天然什么都不用做）。
fn note_compaction_start(rows: &mut Vec<CompactionRow>, id: &str) -> bool {
    if let Some(row) = rows.iter_mut().find(|row| row.id == id) {
        row.running = true;
        return false;
    }
    rows.push(CompactionRow {
        id: id.to_string(),
        summary: None,
        shadowed_items: 0,
        shadowed_tokens: 0,
        running: true,
        row_key: String::new(),
    });
    true
}

/// 主干 `ExtractContentText`（`:874-885`）：非数组 ⇒ `""`；数组里 `type` 是 text / reasoning
/// 取其 `text`，其余**原样吐回 raw 文本**（主干 `b.GetRawText()`，分叉取 serde 的紧凑形）；
/// 各段以 `\n` 连接。
#[must_use]
fn extract_content_text(slot: &Value) -> String {
    let Some(blocks) = slot.as_array() else {
        return String::new();
    };
    let mut parts: Vec<String> = Vec::new();
    for block in blocks {
        match block["type"].as_str().unwrap_or_default() {
            "text" | "reasoning" => {
                parts.push(block["text"].as_str().unwrap_or_default().to_string());
            }
            _ => parts.push(block.to_string()),
        }
    }
    parts.join("\n")
}

/// 主干 `HandleCompactionSummary`（`:711-731`）逐句镜像：
/// · id 空 / 表里查无此格 ⇒ 整案 return，一格都不动。
/// · `shadowedSeqs` **是数组**才取长度，否则记 0（`:716` 那句三元两头都返 0；`shadowedRange`
///   在主干只 `TryGetProperty` 判存在、值丢弃 ⇒ **无读者键**，分叉也不读，备案见报告 §4）。
/// · `shadowedTokenCount` 只有 Number 才取（缺键 / 脏型 ⇒ 保留旧值，主干那句没有 else）。
/// · `summary` 恒覆盖：缺键 ⇒ `ExtractContentText(Undefined)` = `""` ⇒ `Some("")` ⇒ 不可展。
/// · 收尾 `Running = false`。
fn note_compaction_summary(rows: &mut Vec<CompactionRow>, event: &Value, id: &str) {
    let Some(row) = rows.iter_mut().find(|row| !id.is_empty() && row.id == id) else {
        return;
    };
    row.shadowed_items = event["data"]["shadowedSeqs"]
        .as_array()
        .map_or(0, |seqs| seqs.len() as i64);
    if let Some(token) = event["data"]["shadowedTokenCount"].as_i64() {
        row.shadowed_tokens = token;
    }
    row.summary = Some(extract_content_text(&event["data"]["summary"]));
    row.running = false;
}

/// 主干 `HandleCompactionEnd`（`:733-739`）：同一道门，只把 `Running` 落下。
fn note_compaction_end(rows: &mut Vec<CompactionRow>, id: &str) {
    if id.is_empty() {
        return;
    }
    if let Some(row) = rows.iter_mut().find(|row| row.id == id) {
        row.running = false;
    }
}

/// 主干卡头查格（`:1022-1027`）：先按气泡对号，查不到回落**最后插入**那一格。
#[must_use]
fn compaction_row_for<'a>(rows: &'a [CompactionRow], key: &str) -> Option<&'a CompactionRow> {
    rows.iter()
        .find(|row| row.row_key == key)
        .or_else(|| rows.last())
}

/// 主干 `:1029-1038` 那枚状态文案 switch 的纯函数半（离线可逐格真测）。
/// 档序与主干逐条对齐：`null` → `{Running:true}` → `{items>0, tokens>0}` → `{Summary:not null}`
/// → 其余。**第 1 档与第 4 档同串**（主干就是同一句 `DetText`），别顺手合并。
#[must_use]
fn compaction_state_line(catalog: &Catalog, st: Option<&CompactionRow>) -> String {
    match st {
        None => catalog.dt("点击查看压缩摘要", "View compaction summary"),
        Some(row) if row.running => catalog.dt("正在压缩…", "Compacting context…"),
        Some(row) if row.shadowed_items > 0 && row.shadowed_tokens > 0 => catalog.dtf(
            "已压缩 {0} 条历史记录（约 {1} tokens）",
            "Compacted {0} history items (~{1} tokens)",
            &[row.shadowed_items.to_string(), row.shadowed_tokens.to_string()],
        ),
        Some(row) if row.summary.is_some() => {
            catalog.dt("点击查看压缩摘要", "View compaction summary")
        }
        Some(_) => catalog.dt("压缩摘要不可用", "Compaction summary unavailable"),
    }
}

/// 摘要读不读得出（= 主干 `expandable = st?.Summary is {Length:>0}`，`:1039`；
/// 那道门同时管着 ToggleButton 的 `IsEnabled` 与 Checked/Unchecked 挂不挂）。
#[must_use]
fn compaction_expandable(st: Option<&CompactionRow>) -> bool {
    st.and_then(|row| row.summary.as_deref())
        .is_some_and(|text| !text.is_empty())
}

/// 主干 `WorkflowMemberVm`（`:82-89`）。主干那格 `ChildId` 分叉**不存**：它在卡上没有任何读者
/// （`BuildWorkflowRunCard:1095-1200` 只读 Seq / Label / Phase / Outcome），存了就是只写字段
/// ⇒ 本仓 0-warning 门禁红。登记进报告 §4。
struct WorkflowMemberRow {
    seq: i64,
    label: String,
    phase: Option<String>,
    outcome: Option<String>
}

/// 主干 `WorkflowRunState`（`:91-98`）+ 旁路表 `_workflowRuns`（`:103`，key = runId）。
/// 主干 `_workflowBubbleRun`（`:104`，callId/runName → runId）分叉**没有**：那张表服务的是
/// `tool/call` 侧 keyed `workflow` 工具卡那一族（母本 §6 补充硬约束 3 判定「有意不做」），
/// 而本仓 `TOOL_TABLE` 里根本没有 `workflow` 条目。查格按气泡键，等价主干「ToolArgs 里的
/// runId」+「按 Bubble 引用回查」那两条路的合集。
struct WorkflowRunRow {
    id: String,
    name: String,
    members: Vec<WorkflowMemberRow>,
    stop_reason: Option<String>,
    row_key: String,
}

/// 主干 `HandleWorkflowRunStart:745` 的回落：`runId` 空 ⇒ `"run-" + envTime`。
#[must_use]
fn workflow_run_id(event: &Value, time: i64) -> String {
    let id = frame_id_of(event, "runId");
    if id.is_empty() {
        format!("run-{time}")
    } else {
        id
    }
}

/// 主干 `:742-769`。`name` 空 ⇒ 回落 runId（`:751`，**每次** start 都重算，不是只算一次）。
/// 返回 `true` = 第一次见这个 runId ⇒ 调用方落行。
fn note_workflow_run_start(rows: &mut Vec<WorkflowRunRow>, id: &str, name: &str) -> bool {
    let display = if name.is_empty() { id } else { name };
    if let Some(row) = rows.iter_mut().find(|row| row.id == id) {
        row.name = display.to_string();
        return false;
    }
    rows.push(WorkflowRunRow {
        id: id.to_string(),
        name: display.to_string(),
        members: Vec::new(),
        stop_reason: None,
        row_key: String::new(),
    });
    true
}

/// 主干 `HandleWorkflowAgentStart:772-787`：查无此 run ⇒ 整案 return；`seq` 非数字 ⇒
/// `Members.Count + 1`（`:777`，**自动续号**）；`phase` 非字符串 ⇒ `None`。
fn note_workflow_agent_start(rows: &mut Vec<WorkflowRunRow>, event: &Value, id: &str) {
    let Some(row) = rows.iter_mut().find(|row| !id.is_empty() && row.id == id) else {
        return;
    };
    let data = &event["data"];
    row.members.push(WorkflowMemberRow {
        seq: data["seq"].as_i64().unwrap_or(row.members.len() as i64 + 1),
        label: data["label"].as_str().unwrap_or_default().to_string(),
        phase: data["phase"].as_str().map(|v| v.to_string()),
        outcome: None,
    });
}

/// 主干 `HandleWorkflowAgentEnd:789-801`：`seq` 非数字 ⇒ **0**（与上一案不对称，逐字照抄），
/// 然后按 `m.Seq == seq` 全表匹配写 `Outcome`（主干赋的是 `Str` 的结果 ⇒ 缺键也赋 `Some("")`，
/// 那正是「原样吐回」档能演出空串的原因）。
fn note_workflow_agent_end(rows: &mut Vec<WorkflowRunRow>, event: &Value, id: &str) {
    let Some(row) = rows.iter_mut().find(|row| !id.is_empty() && row.id == id) else {
        return;
    };
    let data = &event["data"];
    let seq = data["seq"].as_i64().unwrap_or(0);
    let outcome = data["outcome"].as_str().unwrap_or_default().to_string();
    for member in &mut row.members {
        if member.seq == seq {
            member.outcome = Some(outcome.clone());
        }
    }
}

/// 主干 `HandleWorkflowRunEnd:803-808`：`StopReason = Str(data,"stopReason")` ⇒ **三态**：
/// 没发这一帧 = `None`（「运行中」），发了但省键 = `Some("")`（落 `_` 档、原样吐回空串），
/// 发了带值 = 那个值。三态各一条独立用例。
fn note_workflow_run_end(rows: &mut Vec<WorkflowRunRow>, event: &Value, id: &str) {
    let Some(row) = rows.iter_mut().find(|row| !id.is_empty() && row.id == id) else {
        return;
    };
    row.stop_reason = Some(frame_id_of(event, "stopReason"));
}

/// 主干卡头查格（`:1099-1109`）：按 runId / 按 Bubble 两条路都归到「这一格」，查不到回落
/// **最后插入**那一格。
#[must_use]
fn workflow_run_for<'a>(rows: &'a [WorkflowRunRow], key: &str) -> Option<&'a WorkflowRunRow> {
    rows.iter()
        .find(|row| row.row_key == key)
        .or_else(|| rows.last())
}

/// 主干运行级四档 + `_` 原样档（`:1113-1120`）。
#[must_use]
fn workflow_run_status_line(catalog: &Catalog, stop: Option<&str>) -> String {
    match stop {
        None => catalog.bt("运行中", "Running"),
        Some("completed") => catalog.bt("已完成", "Completed"),
        Some("cancelled") => catalog.bt("已取消", "Cancelled"),
        Some("error") => catalog.bt("失败", "Failed"),
        Some(other) => other.to_string(),
    }
}

/// 主干成员级四档 + `_` 原样档（`:1157-1166`）。**与运行级不同表**：成员级失败是
/// `failed`、运行级失败是 `error`（两族 wire 值本来就不对称，别互抄）。
#[must_use]
fn workflow_member_status_line(catalog: &Catalog, outcome: Option<&str>) -> String {
    match outcome {
        None => catalog.bt("运行中", "Running"),
        Some("completed") => catalog.bt("已完成", "Completed"),
        Some("failed") => catalog.bt("失败", "Failed"),
        Some("cancelled") => catalog.bt("已取消", "Cancelled"),
        Some(other) => other.to_string(),
    }
}

/// 主干成员行文案（`:1167-1169`）：`label` 空 ⇒「空成员名」，`phase` 非空 ⇒ 前面拼 `ph · `。
#[must_use]
fn workflow_member_label(catalog: &Catalog, member: &WorkflowMemberRow) -> String {
    let label = if member.label.is_empty() {
        catalog.dt("空成员名", "Empty member name")
    } else {
        member.label.clone()
    };
    match member.phase.as_deref() {
        Some(phase) if !phase.is_empty() => format!("{phase} · {label}"),
        _ => label,
    }
}

/// 主干 count 段（`:1131-1135`）：`count == 0` 单独一句文案。
#[must_use]
fn workflow_members_count_line(catalog: &Catalog, count: usize) -> String {
    if count == 0 {
        return catalog.dt("没有启动成员", "No members started");
    }
    catalog.dtf("{0} 个成员", "{0} members", &[count.to_string()])
}

/// 展开态槽位的开关（既有同族 = `Msg::Reason` 里那三行手工版，抽出来给两张新卡共用，
/// **不改**那颗既有臂）。
fn toggle_slot(slot: &mut Vec<String>, key: &str) {
    match slot.iter().position(|item| item == key) {
        Some(index) => {
            slot.remove(index);
        }
        None => slot.push(key.to_string()),
    }
}

/// 主干 `RetryStatusLine`（`MessageDetails.cs:651-671`）的纯函数半：`now_ms`（wall-clock）由调用点
/// 喂进来 ⇒ 离线可逐字节测。三档 label（`started` / `cancelled` / 默认「等待」）+ `maximum`
/// （normal 档显 `max_retries`、否则 `∞`）+ `seconds`，末拼
/// `DetFormat("{0}（{1}/{2}） · {3}s", "{0} ({1}/{2}) · {3}s", label, retry, maximum, seconds)`。
/// 全角括号 `（）`、`·` 两侧各一枚半角空格 —— 逐字照主干，一个字节都不许改。
///
/// `seconds` = `(int)Math.Max(1, Math.Ceiling(ms/1000.0))`（`:662/:667`）：`scheduled` 用
/// `deadline-now`、其余档用 `delay`。主干每 tick（`:639`）只把这一串重算回状态行文本 ⇒ 分叉
/// 渲染每帧现算即等价；真正的 250ms 定时器是片 D（运行时挂账，见 rt1 报告 §7）。
#[must_use]
fn retry_status_line(catalog: &Catalog, st: &ModelRetryState, now_ms: i64) -> String {
    let label = match st.state.as_str() {
        "started" => catalog.dt("已重试模型请求", "Retried model request"),
        "cancelled" => catalog.dt("模型请求重试已取消", "Model request retry cancelled"),
        _ => catalog.dt("等待重试模型请求", "Waiting to retry model request"),
    };
    let maximum = if st.mode == "normal" {
        st.max_retries.to_string()
    } else {
        "∞".to_string()
    };
    let seconds_ms = if st.state == "scheduled" {
        st.deadline_ms - now_ms
    } else {
        st.delay_ms
    };
    let seconds = (seconds_ms as f64 / 1000.0).ceil().max(1.0) as i64;
    catalog.dtf(
        "{0}（{1}/{2}） · {3}s",
        "{0} ({1}/{2}) · {3}s",
        &[label, st.retry.to_string(), maximum, seconds.to_string()],
    )
}

/// 浮层几何（主干 `MessageDetails.cs:1447` 的 `StackPanel{MinWidth=280, MaxWidth=420}` +
/// `:1453-1466` 那行的 `MinWidth=72` + `:1586-1594` 的 `ScrollViewer{MaxHeight=480}`）。
/// 四枚都写在这里而不是 `tokens.rs`：本刀可写面不含 token 文件，且这四枚只在主干这一处出现。
const DETAILS_PANEL_MIN_WIDTH: f64 = 280.0;
const DETAILS_PANEL_MAX_WIDTH: f64 = 420.0;
const DETAILS_SCROLL_MAX_HEIGHT: f64 = 480.0;
const DETAILS_LABEL_MIN_WIDTH: f64 = 72.0;

/// 一行「元数据」：主干 `void Field(string zhKey, string enKey, string value)`
/// （`MessageDetails.cs:1451-1468`）的载体。`value` 是**已经格式化完**的最终文本（时钟、
/// 用时、用量都在生成侧算好），`zh`/`en` 两枚键留给渲染侧按语种选档（主干 `DetText`）。
#[derive(Clone, Debug, PartialEq, Eq)]
struct DetailField {
    zh: &'static str,
    en: &'static str,
    value: String,
}

/// 元数据那一节的字段表：**次序**与**逐条前置判据**照主干 `:1469-1481`，一枚不许多、一枚
/// 不许少。本节与「浮层其余四节 + 卡尾那三枚复制钮」是主干同一颗 `ShowMessageDetailsFlyout`
/// 里互不相干的两段：这一张表只管**元数据**那十二格，`系统提示词` 那一格（`:1481`，门
/// `SystemPromptUpdate`）与后面那节同名的代码块节（`:1552`，门 `SystemPromptText`）是**两件
/// 事**，别在这儿给代码块占行。
///
/// `st` = 旁路表那一格（主干 `:1446` 的 `_messageDetails.TryGetValue(bubble, out var s)`，
/// 取不到就是 `null`）；取不到时只剩气泡自己那几项，与主干同一结果 —— 那颗钮在主干也是
/// **无条件**出现的，所以「没有旁路行」不等于「没有浮层」。
fn message_detail_fields(
    bubble: &Bubble,
    st: Option<&MessageDetails>,
    catalog: &Catalog,
) -> Vec<DetailField> {
    let mut fields: Vec<DetailField> = Vec::new();
    // 主干 `:1453` 那句 `if (value.Length == 0) return;` 在每一发的最前面 ⇒ 空值不占行由这里
    // 统一兜（上面的 `> 0` 判据是主干写在**调用点**的，两道都要，缺一道就会多占一行）。
    let mut field = |zh: &'static str, en: &'static str, value: String| {
        if value.is_empty() {
            return;
        }
        fields.push(DetailField { zh, en, value });
    };
    field("角色", "Role", bubble.role.to_string());
    if bubble.turn > 0 {
        field("轮次", "Turn", bubble.turn.to_string());
    }
    if bubble.seq > 0 {
        field("序号", "Seq", bubble.seq.to_string());
    }
    if bubble.time > 0 {
        field("时间", "Time", message_clock(bubble.time));
    }
    // 主干 `:1473-1474`：气泡自己的 Model 优先，**空了才**退旁路表那份（`request/context` 记的）。
    if !bubble.model.is_empty() {
        field("模型", "Model", bubble.model.clone());
    } else if let Some(model) = st.and_then(|st| st.model.as_ref()).filter(|m| !m.is_empty()) {
        field("模型", "Model", model.clone());
    }
    if let Some(provider) = st.and_then(|st| st.provider.as_ref()).filter(|v| !v.is_empty()) {
        field("提供方", "Provider", provider.clone());
    }
    if st.and_then(|st| st.context_window).is_some_and(|v| v > 0) {
        field(
            "上下文窗口",
            "Context window",
            st.and_then(|st| st.context_window).unwrap_or_default().to_string(),
        );
    }
    if bubble.duration_ms > 0 {
        field("用时", "Duration", duration_text(bubble.duration_ms));
    }
    if bubble.tokens > 0 {
        // 主干 `:1478` 是 `FormatTokensCompact(Tokens) + " tok"`（" tok" 不在 i18n 表里）。
        // `FormatTokensCompact`（`RunStats.cs:249-254`）本体在 [`tokens_text`]：五档 + locale 门。
        field(
            "用量",
            "Tokens",
            format!("{} tok", tokens_text(catalog.locale(), bubble.tokens)),
        );
    }
    if !bubble.id.is_empty() {
        field("消息 ID", "Message ID", bubble.id.clone());
    }
    // 主干 `:1480` 读的是**气泡自己**那枚 `bubble.ToolName`（`xaml.cs:6284` 由 `tool/call` 的
    // `data.name` 写进），不读旁路表 ⇒ 分叉同源读 [`Bubble::tool_name`]。旁路表那枚
    // `MessageDetails.tool_name`（`kernel.rs:5307`）在分叉**没有产品读者**：它的唯一写路径
    // `DetailsLedger::note_row_meta`（`kernel.rs:5693`）产品侧零调用，而 `kernel.rs` 是冻结面
    // ⇒ 这里不接它：分叉只留「气泡自己」这一份真相，不留一份产品侧读不到的第二真相。
    if !bubble.tool_name.is_empty() {
        field("工具", "Tool", bubble.tool_name.clone());
    }
    if st.and_then(|st| st.system_prompt_update) == Some(true) {
        field("系统提示词", "System prompt", catalog.dt("已更新", "updated"));
    }
    fields
}

/// 那颗钮的开合（主干 `button.Click += (_, _) => ShowMessageDetailsFlyout(button, bubble)`，
/// `:1440`）：原生 `Flyout` 在本依赖里**有**（旧注释写「不存在」是只查了 `generated.rs` 的
/// 误判，证据见上面 `Msg` 里 #75 那段的「#121 校准」块），但它只能挂在一颗钮上由那颗钮自己开、
/// 给不出主干这种 imperative 开 ⇒ 自绘层是有意保留，这一发既是「打开」也是「再点同一颗收起」。
/// 键 = 被点那颗气泡的 [`details_key_of`]，**同一时刻最多一张**（换气泡点 = 换键，不是叠两张）。
fn message_details_toggle(state: &mut Option<String>, key: &str) {
    let same = state.as_deref() == Some(key);
    *state = if same { None } else { Some(key.to_string()) };
}

/// 收那张浮层：Esc / 遮罩按下 / 切页 / 切会话四条出口共用（返回值 = 「这一发是不是浮层吃的」，
/// 口径同 [`file_menu_close`]，`Msg::PaletteClose` 那条借道的臂靠它决定要不要往下发给命令浮层）。
fn message_details_close(state: &mut Option<String>) -> bool {
    if state.is_none() {
        return false;
    }
    *state = None;
    true
}

// ==================== #93g 「消息详情」后三节 + #139 件一/件二 + 「跨会话召回」那张列表层的纯判据 ====================
//
// 主干 `MainWindow.MessageDetails.cs:1483-1536`（后三节）、`:1552-1555`（系统提示词那一节）、
// `:1558-1685`（卡尾那三枚复制钮与其 payload）与 `:1398-1421`（那张 chip 点开的列表层）。
// 能摘成纯判据的几件事摘在这里，文件末尾的 `details_sections_tests` 逐条断：
// ①「空节不占位」——三节的门都是 `st is { Xxx.Count: > 0 }`，`Count == 0` 时**连节标题都不出**；
// ②`MakeCodeBlock` 那段文本 = `label + "\n" + PrettyJson(json)`（`PrettyJson` 见 [`pretty_json`]）；
// ③「上下文注入」正文的 400 字符截断（`:1512` 的 `text.Length > 400 ? text[..400] + "…" : text`）；
// ④列表层的行点哪条会话（`:1414` / `:1533` 的 `sid.Length > 0 ? sid : label`）与状态格的开合；
// ⑤#139 件一：「系统提示词」正文的 2000 字符截断（`:1555`，见 [`clip_prompt_text`]）；
// ⑥#139 件二：卡尾三枚钮的 payload（[`build_detail_json`] / [`compact_json`] /
// [`detail_property_path`]，主干 `:1599-1657`）。
//
// 摘出来的仍是**数据**：节标题的选档由渲染侧现做（`catalog.bt`，#148 E2 的那一枚换道），与
// `message_detail_fields`
// 同一口径（那颗也只把 `(zh, en, value)` 三元组交出去）。

/// 「附加内容块」那一条 `MakeCodeBlock(..., maxHeight: 100)` 的高度上限（`:1489`）。
///
/// `maxHeight` 在主干是**形参**，同一颗 `MakeCodeBlock` 各处喂的值不同。本文件那两处浮层点
/// 现测两档：`:1489` = 100（附加内容块）、`:1555` = 140（系统提示词，见
/// [`DETAILS_PROMPT_MAX_HEIGHT`]）；`MessageDetails.cs` 里另有 `:1084` = 160（压缩摘要）、
/// `:1354` = 200、`:1361` = 120（`BuildContextCard` 的两档）。⇒ 合并成一枚常量就是把其余各档
/// 改歪，所以 [`Shell::details_code_block`] 收的是**入参**。
const DETAILS_CODE_MAX_HEIGHT: f64 = 100.0;
/// 「系统提示词」那一节的 `MakeCodeBlock(..., maxHeight: 140)`（主干 `:1555`）。
const DETAILS_PROMPT_MAX_HEIGHT: f64 = 140.0;
/// 主干 `MakeCodeBlock`（`MainWindow.ToolCards.cs:1097-1104`）的外壳：`CornerRadius(6)` +
/// `Padding = new Thickness(Sp6, Sp2, Sp6, Sp2)` + `HorizontalAlignment=Stretch`。
const CODE_BLOCK_CORNER_RADIUS: f64 = 6.0;
const CODE_BLOCK_PADDING: [f64; 4] = [space::S6, space::S2, space::S6, space::S2];
/// 主干 `MakeCodeText`（`MainWindow.ToolCards.cs:1107-1119`）：`FontSize=12` + `Wrap` +
/// `IsTextSelectionEnabled=true` + `TextSecondaryBrush`。`CodeFont()` 那一档抄不动
/// （reactor 的 `TextBlock` 没有 font_family 槽，见报告「抄不到的项」）。
const CODE_BLOCK_FONT_SIZE: f64 = 12.0;
/// 「上下文注入」正文的截断长度（`:1512` 的 `text.Length > 400`）。
const CONTEXT_TEXT_MAX_CHARS: usize = 400;
/// 「系统提示词」正文的截断长度（`:1555` 的 `sp.Length > 2000 ? sp[..2000] + "…" : sp`）。
/// 门是 **`>`**、不是 `>=` ⇒ 正好 2000 字**不**裁（用例
/// `the_prompt_section_clips_at_two_thousands_and_ranks_last` 钉这一格）。
const PROMPT_TEXT_MAX_CHARS: usize = 2000;
/// `ShowSessionReferenceFlyout` 的面板（`:1400` 的 `StackPanel{Spacing=Sp4, MinWidth=220}`）。
const SESSION_REF_PANEL_MIN_WIDTH: f64 = 220.0;

/// 「消息详情」浮层里除「元数据」之外那四节的**有序**表体。
///
/// 四道的门（主干 `:1483` / `:1492` / `:1520` 都写成 `if (st is { Xxx.Count: > 0 })`、
/// `:1552` 写成 `if (st?.SystemPromptText is { Length: > 0 })`）合在
/// [`message_details_blocks`] 里：门没过 ⇒ 整个变体都不出，节标题与条目一个都不生成。渲染侧
/// 因此**不必**再判一次空，也就没有第二道会漂移的判据。
#[derive(Clone, Debug, PartialEq, Eq)]
enum DetailsBlock {
    /// 「附加内容块」的一条（`:1487-1490`）：`MakeCodeBlock(label + "\n" + PrettyJson(json))`。
    Code(String),
    /// 「上下文注入」那一节的**整张**列表（`:1496-1518` 的 `list`，`Spacing=Sp2`）。
    Context(Vec<ContextLine>),
    /// 「跨会话召回」的一条（`:1524-1535`）。
    Reference { sid: String, label: String },
    /// 「系统提示词」那一节的那一枚代码块（主干 `:1552-1555`）：文本已经过
    /// [`clip_prompt_text`] 的 2000 字截断，渲染侧的高度上限是
    /// [`DETAILS_PROMPT_MAX_HEIGHT`]（主干那一处 `maxHeight: 140`）。
    /// 主干那一节**恒只有一枚**代码块（一条 `sp` 一个 `MakeCodeBlock`），所以这一变体装的是
    /// 裁好的串而不是 `Vec`。
    Prompt(String),
}

/// 「上下文注入」的一行：主干对每条 entry 最多发两枚 `TextBlock`（`:1499-1507` 的标题、
/// `:1508-1516` 的正文），**各自**判空 ⇒ 空标题不许占一行空位。
#[derive(Clone, Debug, PartialEq, Eq)]
enum ContextLine {
    Title(String),
    Text(String),
}

impl DetailsBlock {
    /// 这一节的节标题（主干 `MakeSectionLabel(DetText(zh, en))`：`:1486` / `:1495` / `:1523`）。
    /// 「附加内容块」与「跨会话召回」在主干是**多条共用同一枚节标题**（节标题在 `foreach` 外面），
    /// 所以渲染侧只在「上一条不是同一节」时补一枚 —— 见 [`Shell::message_details_card`] 里那颗
    /// `in_section`。
    fn section_title(&self) -> Option<(&'static str, &'static str)> {
        match self {
            Self::Code(_) => Some(("附加内容块", "Extra content block")),
            Self::Context(_) => Some(("上下文注入", "Context injection")),
            Self::Reference { .. } => Some(("跨会话召回", "Session recall")),
            Self::Prompt(_) => Some(("系统提示词", "System prompt")),
        }
    }
}

/// 浮层后四节的表体：**次序** `附加内容块 → 上下文注入 → 跨会话召回 → 系统提示词`（主干
/// `:1483`/`:1492`/`:1520`/`:1552`），前三道各带 `Count > 0` 的门、第四道带
/// `SystemPromptText is { Length: > 0 }`。`st` 为 `None`（旁路表没有那一格）⇒ 四节一个都不出，
/// 浮层只剩「元数据」，与主干 `:1446` 那句 `TryGetValue` 失败给 `null` 同一结果。
///
/// 主干在召回与系统提示词之间还夹了一道「跨会话中继」（`:1538`，门 `RelaySessionId`）——
/// **那一节本批仍不做**（不在 #139 四件里，见 [`Shell::message_details_card`] 的文档）。缺席
/// 它不影响新节的相对次序：主干序是 `Reference < Relay < Prompt`，去掉中继后
/// `Reference < Prompt` 依旧成立。
fn message_details_blocks(st: Option<&MessageDetails>) -> Vec<DetailsBlock> {
    let Some(st) = st else {
        return Vec::new();
    };
    let mut blocks: Vec<DetailsBlock> = Vec::new();
    if !st.extra_blocks.is_empty() {
        blocks.extend(
            st.extra_blocks
                .iter()
                .map(|(label, json)| DetailsBlock::Code(extra_block_text(label, json))),
        );
    }
    if !st.context_entries.is_empty() {
        blocks.push(DetailsBlock::Context(context_lines(&st.context_entries)));
    }
    if !st.references.is_empty() {
        blocks.extend(st.references.iter().map(|(sid, label)| DetailsBlock::Reference {
            sid: sid.clone(),
            label: label.clone(),
        }));
    }
    // 主干 `:1552` 的门是 `is { Length: > 0 }` ⇒ `None` 与 `Some("")` 同档：整节收起。
    if let Some(text) = st.system_prompt_text.as_deref().filter(|t| !t.is_empty()) {
        blocks.push(DetailsBlock::Prompt(clip_prompt_text(text)));
    }
    blocks
}

/// 浮层表体摊出来的**一格**：要么是一枚节标题，要么是一条内容。
///
/// 为什么要这一层（而不是让渲染侧自己记「上一条是哪一节」）：主干那三道的节标题都写在
/// `foreach` **外面**（`:1486` / `:1495` / `:1523`）⇒ 同节多条共用一枚。这一格「换节才补标题」
/// 的判据是**规格**，放在纯函数里才有离线用例可钉；留在渲染侧就是一段只有 GUI 轮才摸得到的
/// 逻辑，正是「把漏做断成规格」最容易藏身的形状。
#[derive(Clone, Debug, PartialEq, Eq)]
enum DetailsCell {
    /// 一枚节标题（主干 `MakeSectionLabel(DetText(zh, en))`）。
    Section(&'static str, &'static str),
    /// 一条内容（形状见 [`DetailsBlock`]）。
    Block(DetailsBlock),
}

/// 表体 → 带节标题的格子序列：只在「本格的节与上一格不同」时补一枚标题。
fn details_cells(blocks: &[DetailsBlock]) -> Vec<DetailsCell> {
    let mut cells: Vec<DetailsCell> = Vec::new();
    let mut in_section: Option<&'static str> = None;
    for block in blocks {
        if let Some((zh, en)) = block.section_title() {
            if in_section != Some(zh) {
                in_section = Some(zh);
                cells.push(DetailsCell::Section(zh, en));
            }
        }
        cells.push(DetailsCell::Block(block.clone()));
    }
    cells
}

/// 「附加内容块」那一条的文本：主干 `:1489` 是 `label + "\n" + PrettyJson(json)`。
fn extra_block_text(label: &str, json: &str) -> String {
    format!("{label}\n{}", pretty_json(json))
}

/// 主干 `PrettyJson`（`MainWindow.ToolCards.cs:1171-1183`）：能 `JsonDocument.Parse` 就按缩进
/// 重排，**任何**异常（空串、半截 JSON、标量都算）都原样吐回去 —— 主干写的是 `catch (Exception)`，
/// 不挑异常型。分叉同判据：解析失败 ⇒ 原文；解析成功但序列化失败（理论到不了）⇒ 也原文。
fn pretty_json(raw: &str) -> String {
    match serde_json::from_str::<serde_json::Value>(raw) {
        Ok(value) => serde_json::to_string_pretty(&value).unwrap_or_else(|_| raw.to_string()),
        Err(_) => raw.to_string(),
    }
}

/// 「上下文注入」那条列表：每条 entry 先标题后正文，**各自**判空（主干 `:1499`/`:1508`），
/// 正文过 [`clip_context_text`]。
fn context_lines(entries: &[(String, String)]) -> Vec<ContextLine> {
    let mut lines: Vec<ContextLine> = Vec::new();
    for (title, text) in entries {
        if !title.is_empty() {
            lines.push(ContextLine::Title(title.clone()));
        }
        if !text.is_empty() {
            lines.push(ContextLine::Text(clip_context_text(text)));
        }
    }
    lines
}

/// 主干 `:1512` 的 `text.Length > 400 ? text[..400] + "…" : text`。
///
/// 一处**已知不等价**（记在报告「有意偏差」）：主干切 UTF-16 **码元**，分叉切 Unicode **字符**。
/// 纯中文 / 纯 ASCII 两边逐格相同；只有正文含增补平面字符（emoji 等，主干算 2 枚）时分叉多留一点，
/// 换来的是「绝不把一对代理项劈成半个」—— 主干那一句会劈出孤立代理项。
fn clip_context_text(text: &str) -> String {
    if text.chars().count() <= CONTEXT_TEXT_MAX_CHARS {
        return text.to_string();
    }
    let clipped: String = text.chars().take(CONTEXT_TEXT_MAX_CHARS).collect();
    format!("{clipped}…")
}

/// 列表行 / 浮层行点下去打开哪条会话：主干 `:1414` 与 `:1533` 都是
/// `OpenReferencedSessionAsync(sid.Length > 0 ? sid : label)` —— **label 兜底**。采集层
/// （`MessageDetails.cs:287`，分叉同源 `kernel.rs` 的 `references`）只保证 `label` 非空
/// （`label || sessionId`），`sid` 可以空：内核没带 `sessionId` 的那些召回帧。
fn session_ref_target(sid: &str, label: &str) -> String {
    if sid.is_empty() {
        label.to_string()
    } else {
        sid.to_string()
    }
}

/// 主干 `:1555` 的 `sp.Length > 2000 ? sp[..2000] + "…" : sp`。
///
/// 体逐字照 [`clip_context_text`]，含那条**已备案的有意偏差**（分叉切 Unicode **字符**、主干切
/// UTF-16 **码元**；纯中文/纯 ASCII 两档逐格相同，只有含增补平面字符时主干会劈出孤立代理项）——
/// 偏差说明只立在那一颗的文档里，这里不再另立第二份。
fn clip_prompt_text(text: &str) -> String {
    if text.chars().count() <= PROMPT_TEXT_MAX_CHARS {
        return text.to_string();
    }
    let clipped: String = text.chars().take(PROMPT_TEXT_MAX_CHARS).collect();
    format!("{clipped}…")
}

/// 主干 `CompactJson`（`MainWindow.MessageDetails.cs:1673-1685`）：空串 ⇒ `""`；能解析 ⇒ 按
/// `WriteIndented = false` 重排（= 去掉一切多余空白）；**任何**解析异常 ⇒ 原样吐回。口径同
/// [`pretty_json`]：主干写的是 `catch (Exception)`，不挑异常型，所以标量/半截 JSON 都算失败档。
fn compact_json(raw: &str) -> String {
    if raw.is_empty() {
        return String::new();
    }
    match serde_json::from_str::<serde_json::Value>(raw) {
        Ok(value) => serde_json::to_string(&value).unwrap_or_else(|_| raw.to_string()),
        Err(_) => raw.to_string(),
    }
}

/// 一枚 JSON **字符串**字面量（带引号、按 `serde_json` 的转义口径）。主干那边是
/// `Utf8JsonWriter.WriteString`，转义表与 `serde_json` 同为 RFC 8259 那一套。
fn json_quote(text: &str) -> String {
    serde_json::to_string(text).unwrap_or_else(|_| "\"\"".to_string())
}

/// 主干 `DetailPropertyPath`（`MainWindow.MessageDetails.cs:1653-1657`）：`ToolName` 非空 ⇒
/// `tool.{name}`，否则 ⇒ `message`。读的是**气泡自己**那枚字段（与浮层「工具」那一格同源，
/// 见 [`message_detail_fields`]），不读旁路表。
fn detail_property_path(bubble: &Bubble) -> String {
    if bubble.tool_name.is_empty() {
        "message".to_string()
    } else {
        format!("tool.{}", bubble.tool_name)
    }
}

/// 主干 `BuildDetailJson`（`MainWindow.MessageDetails.cs:1599-1651`）：卡尾那三枚复制钮的
/// payload。**键的次序**就是主干 `Utf8JsonWriter` 那一串写入次序（`role`/`text` 恒写 →
/// `turn`/`seq`/`time` 各带 `> 0` → `model`/`messageId`/`tool` 各带「非空」→ `tokens` 带 `> 0`
/// → `arguments` → `extraBlocks[]` → `references[]`），空值不写键。分叉没开 `preserve_order`
/// （`Cargo.toml` 的 `serde_json`）⇒ `Map` 是 `BTreeMap`、键会按字典序走，所以这里**手工拼串**
/// 而不是攒 `Value`：次序本身就是规格，不能让序列化层去重排它。
///
/// `extraBlocks` 那一段主干写的是「`JsonDocument.Parse` 成功就 `WriteTo`、`catch` 就把原文当
/// 字符串写」（`:1621-1634`，且**只取 `json`、丢掉 label**）⇒ 分叉同判据。
fn build_detail_json(bubble: &Bubble, st: Option<&MessageDetails>) -> String {
    let mut parts: Vec<String> = Vec::new();
    parts.push(format!("\"role\":{}", json_quote(bubble.role)));
    parts.push(format!("\"text\":{}", json_quote(&bubble.text)));
    if bubble.turn > 0 {
        parts.push(format!("\"turn\":{}", bubble.turn));
    }
    if bubble.seq > 0 {
        parts.push(format!("\"seq\":{}", bubble.seq));
    }
    if bubble.time > 0 {
        parts.push(format!("\"time\":{}", bubble.time));
    }
    if !bubble.model.is_empty() {
        parts.push(format!("\"model\":{}", json_quote(&bubble.model)));
    }
    if !bubble.id.is_empty() {
        parts.push(format!("\"messageId\":{}", json_quote(&bubble.id)));
    }
    if bubble.tokens > 0 {
        parts.push(format!("\"tokens\":{}", bubble.tokens));
    }
    if !bubble.tool_name.is_empty() {
        parts.push(format!("\"tool\":{}", json_quote(&bubble.tool_name)));
    }
    // `arguments` 那一格**有意不写**（不是漏做）：主干的门是 `bubble.ToolArgs is { Length: > 0 }`
    // （`MainWindow.MessageDetails.cs:1614`），而分叉 `struct Bubble`（那十四枚字段）没有
    // `tool_args` —— `"tool/call"` 采集臂把 `data.arguments` 解析成 `tool_row` / `mutation_path`
    // 的入参之后就随作用域丢弃，从不留原文。主干之所以要留，是因为唯一读者 `BuildWorkflowRunCard`
    // （`:1099-1108`）要从气泡原文里回查 `runId`；分叉那张卡（#149）改读 `WorkflowRunState`
    // 旁路表，**不需要**气泡带原文 ⇒ 补字段只会长出一份没有产品读者的第二真相。所以这一格按主干
    // 同一道门自然降级成「恒不过」：JSON 里该键缺席，与主干「这次工具调用没带参数」那一档
    // **逐字同形**。代价 = 分叉复制出的 payload 在 tool 气泡上比主干少这一格；已登记，
    // 别在验收时按「主干有」判红。
    if let Some(st) = st {
        if !st.extra_blocks.is_empty() {
            let items: Vec<String> = st
                .extra_blocks
                .iter()
                .map(|(_, json)| match serde_json::from_str::<serde_json::Value>(json) {
                    Ok(value) => value.to_string(),
                    Err(_) => json_quote(json),
                })
                .collect();
            parts.push(format!("\"extraBlocks\":[{}]", items.join(",")));
        }
        if !st.references.is_empty() {
            let items: Vec<String> = st
                .references
                .iter()
                .map(|(sid, label)| {
                    format!(
                        "{{\"sessionId\":{},\"label\":{}}}",
                        json_quote(sid),
                        json_quote(label)
                    )
                })
                .collect();
            parts.push(format!("\"references\":[{}]", items.join(",")));
        }
    }
    format!("{{{}}}", parts.join(","))
}

/// 那张「跨会话召回」列表浮层的状态格（形状照 [`Shell::file_menu`]：reactor 没有 `Visibility`，
/// `None` = 整棵节点不入树）。存的是**这一发 chip 带过来的那份列表**，不是键 ——
/// 主干 `ShowSessionReferenceFlyout(anchor, refs)` 就是把 `st.References` 原样交给浮层，
/// 浮层自己不回查旁路表。
fn session_ref_list_show(state: &mut Option<Vec<(String, String)>>, items: Vec<(String, String)>) {
    // 空列表 ⇒ 不开（主干那颗 chip 本身就长在 `st.References.Count > 0` 那一档里，弹不出空层）。
    if items.is_empty() {
        return;
    }
    *state = Some(items);
}

/// 收那张列表层：返回值口径同 [`message_details_close`] / [`file_menu_close`]
/// （`true` = 「这一发是浮层吃的」，Esc 借道那条臂据此决定要不要再往下发给命令浮层）。
fn session_ref_list_close(state: &mut Option<Vec<(String, String)>>) -> bool {
    if state.is_none() {
        return false;
    }
    *state = None;
    true
}

// 三张自绘浮层（⋯ 菜单 / 消息详情 / 跨会话召回列表）之间的互斥**没有**收成一颗函数：
// 三条开臂各写自己的那两发兄弟 close（`Msg::FileMenuToggle` / `Msg::DetailsToggle` /
// `Msg::SessionRefList`），逐行看得见，且 `message_details_tests` 那把旧锁钉的就是这一形状。
// 「此刻场上有哪几张」的摘表只住在测试 mod 里 ⇒ 产品侧不参与建树，也不冒充第二份真相。


/// `request/context` 的锚（主干 `NoteRequestContext` `MessageDetails.cs:492` 的
/// `LastUserBubble() ?? _messages[^1]`）：最近一条**用户**行，没有就整屏末行，
/// 表空 ⇒ `None` ⇒ 采集层整帧丢弃（主干同口径）。主干那一档的判据是 `Role: "user"`
/// （`MainWindow.xaml.cs:6743`），与 [`Bubble::role`] 的同名值一一对应。
fn details_anchor_key(bubbles: &[Bubble]) -> Option<DetailsKey> {
    bubbles
        .iter()
        .rev()
        .find(|bubble| bubble.role == "user")
        .or_else(|| bubbles.last())
        .map(details_key_of)
}

/// #93d 的两处清表（主干 `MainWindow.xaml.cs:2590` → `ResetMessageDomainState`
/// `MessageDetails.cs:117-130`，全仓唯一调用点）：旁路表随气泡表一起作废。
///
/// 但那颗「本会话见过系统提示词没有」的位**不许跟着清**：主干它存在 `RunStats` 里
/// （`MessageDetails.cs:200-202`），`ResetMessageDomainState` 不碰 `RunStats` ⇒ 跨清表存活。
/// 分叉的等价台账是 `Shell::system_prompt_seen: Vec<String>`（按会话 id 存）⇒ 清完要按
/// **当前会话**把它补回采集层，否则换回来的会话整屏回放会把「系统提示词更新」错报成
/// 「系统提示词」（行文案由 `system_prompt_seen` 算、浮层文案由采集层那颗位算 ⇒ 两边会打架）。
fn reset_details(details: &mut DetailsLedger, session: &str, seen_sessions: &[String]) {
    details.reset();
    details.set_system_prompt_seen(seen_sessions.iter().any(|seen| seen == session));
}

/// 主干 `FeedbackItem`（`MainWindow.xaml.cs:2123`）：内核 `messageFeedback` 回的一条条目。
/// `rating` 只有 `positive`/`negative` 两个字面量；`version` 由内核每次 put 重新生成，
/// 壳只负责把观察到的值原样回传（乐观并发），本地不许自己造。
#[derive(Clone)]
struct FeedbackItem {
    rating: String,
    note: Option<String>,
    category: Option<String>,
    version: Option<String>,
}

/// 主干 `SetFeedbackStatus` 的三种落点：成功清成空、失败给文案，
/// 而 delete 那两条「本地已对齐」的提前 return 路径压根不碰 Status（旧文案留着）。
#[derive(Clone)]
enum FeedbackStatus {
    Keep,
    Clear,
    Text(String),
}

/// 一次 put/delete 后台状态机的最终落点，对应主干「写 `_feedback` + `RenderAllFeedbackRows()`
/// + `SetFeedbackStatus`」那一串副作用。分叉是声明式重渲染，所以整段折成一份补丁回 UI 线程。
/// 应用顺序固定：`aligned`（整表重建）→ `revoked`（摘掉这条）→ `adopted`（覆写这条）。
#[derive(Clone)]
struct FeedbackPatch {
    session: String,
    message: String,
    /// delete 前本地没有 version 时先做的 list 对齐（主干 `LoadFeedbackAsync` 同一步）。
    aligned: Option<Vec<Value>>,
    /// 内核权威条目：put 成功回的 item，或 version-conflict 采纳的 `error.current`。
    adopted: Option<Value>,
    /// 本地撤销这条：delete 成功 / 内核侧本就没有 / 采纳到 `current: null`。
    revoked: bool,
    status: FeedbackStatus,
}

/// `messageFeedback` 的业务失败：`error` 是内核原样回的 `{code, current?, maxBytes?, ...}`。
enum FeedbackFailure {
    Business(Value),
    /// 传输/网关层失败，字符串是 `Kernel::call` 拼的 `"<code>: <message>"`
    /// （主干那边是 `DshRpcException.Message`，同样只进 Status）。
    Transport(String),
}

impl FeedbackFailure {
    /// 主干 list 那条只 `catch` 到 `DshRpcException.Message`（`"<code>: <message>"`）并原样
    /// 写进状态，业务 `ok:false` 也是同一副面孔，所以这里不查表。
    fn code_text(&self) -> String {
        match self {
            Self::Transport(text) => text.clone(),
            Self::Business(error) => format!(
                "{}: {}",
                error["code"].as_str().unwrap_or_default(),
                error["message"].as_str().unwrap_or_default()
            ),
        }
    }
}

/// put/delete 的失败落进行内 Status：业务错误照主干 `FeedbackErrorText`（`xaml.cs:17001`）
/// 查表，传输层失败和主干一样直接上异常原文。
fn feedback_failure_message(catalog: &Catalog, failure: &FeedbackFailure) -> String {
    match failure {
        FeedbackFailure::Business(error) => feedback_error_text(catalog, error),
        FeedbackFailure::Transport(text) => text.clone(),
    }
}

/// 主干 `CallFeedbackAsync`（`MainWindow.xaml.cs:16787`）：**双层 ok**。外层信封
/// `{result:{ok,value}}` 由 `Kernel::call` 剥掉，剩下的 `value` 本身又是内核方法的返回体
/// `{ok:true,value:...}` / `{ok:false,error:...}`，所以 `call` 返回 Ok 并不等于业务成功。
/// 外层失败（gateway/鉴权）由 `call` 直接拼成 Err，这里归到 `Transport`。
fn feedback_call(shared: &Shared, method: &str, args: Value) -> Result<Value, FeedbackFailure> {
    let outcome = shared
        .lock()
        .map_err(|_| "内核状态不可用".to_string())
        .and_then(|mut kernel| kernel.call(method, args));
    let body = match outcome {
        Ok(body) => body,
        Err(error) => return Err(FeedbackFailure::Transport(error)),
    };
    if body["ok"].as_bool().unwrap_or(false) {
        return Ok(body.get("value").cloned().unwrap_or(Value::Null));
    }
    Err(FeedbackFailure::Business(
        body.get("error").cloned().unwrap_or(Value::Null),
    ))
}

/// 主干 `StoreFeedbackItem`（16811）：只认字符串字段，`messageId` 缺失整条丢弃。
fn parse_feedback(item: &Value) -> Option<(String, FeedbackItem)> {
    let id = item["messageId"].as_str()?;
    Some((
        id.to_string(),
        FeedbackItem {
            rating: item["rating"].as_str().unwrap_or_default().to_string(),
            note: item["note"].as_str().map(str::to_string),
            category: item["category"].as_str().map(str::to_string),
            version: item["version"].as_str().map(str::to_string),
        },
    ))
}

fn store_feedback(table: &mut Vec<(String, FeedbackItem)>, item: &Value) {
    if let Some((id, entry)) = parse_feedback(item) {
        set_pair(table, id, entry);
    }
}

fn feedback_of(table: &[(String, FeedbackItem)], id: &str) -> Option<FeedbackItem> {
    table
        .iter()
        .find(|(known, _)| known == id)
        .map(|(_, entry)| entry.clone())
}

/// 主干 `FeedbackErrorText`（16996）：文案逐字照抄，未知 code 走「失败（{0}）」，
/// 连 code 都没有就是「操作失败」（主干那边是 `GetProperty("error")` 抛异常，落到 `ex.Message`，
/// 分叉统一成同一句人话，不搬 .NET 异常文本）。
fn feedback_error_text(catalog: &Catalog, error: &Value) -> String {
    let code = error["code"].as_str();
    match code {
        Some("target-not-found") => catalog.l("该消息不在本会话日志里（子代理或已裁剪），无法反馈"),
        Some("session-not-found") => catalog.l("会话不存在或已归档"),
        Some("note-blank") => catalog.l("说明不能是空白"),
        Some("note-too-large") => match error["maxBytes"].as_i64() {
            Some(max) => catalog.lf("说明超长（上限 {0} 字节）", &[max.to_string()]),
            None => catalog.l("说明超长"),
        },
        Some("version-conflict") => catalog.l("反馈已被其他地方改动，请重试"),
        Some(other) => catalog.lf("失败（{0}）", &[other.to_string()]),
        None => catalog.l("操作失败"),
    }
}

/// 说明的字节上限：内核配置 `dsh-web-app/cordis.patch.yml:56` 的 `maxNoteBytes`，
/// 假内核 `rust/src/bin/fake_dsh.rs` 的 `MAX_NOTE_BYTES` 同值，超了回
/// `{code:"note-too-large",maxBytes:8192,actualBytes}`。行内编辑器拿它算字数提示，
/// **按 UTF-8 字节**（`str::len()`）而不是字符数 —— 与内核 `Buffer.byteLength` 同口径。
const MAX_NOTE_BYTES: i64 = 8192;

/// 主干 `FormatMessageClock`（`MainWindow.MessageActions.cs:769`）：同日 `HH:mm`、
/// 同年 `M月D日 HH:mm`、跨年再加年份。内核 `time` 是 epoch 毫秒。
fn message_clock(millis: i64) -> String {
    let value = DateTime::from_unix_millis(millis).to_local();
    let today = DateTime::now().to_local();
    let clock = format!("{:02}:{:02}", value.hour(), value.minute());
    if value.year() == today.year() && value.month() == today.month() && value.day() == today.day()
    {
        clock
    } else if value.year() == today.year() {
        format!("{}月{}日 {clock}", value.month(), value.day())
    } else {
        format!(
            "{}年{}月{}日 {clock}",
            value.year(),
            value.month(),
            value.day()
        )
    }
}

/// 主干 `{0:0.#}`：最多一位小数、不留尾随 0。
fn one_decimal(value: f64) -> String {
    let rounded = (value * 10.0).round() / 10.0;
    if rounded.fract() == 0.0 {
        format!("{}", rounded as i64)
    } else {
        format!("{rounded:.1}")
    }
}

/// 主干 `FormatTokensCompact`（`MainWindow.RunStats.cs:249-254`）**五档逐档照抄**：
/// 1. `>= 1e8` **且** locale 以 `zh` 开头 → `{0:0.#} 亿`
/// 2. `>= 1e4` **且** locale 以 `zh` 开头 → `{0:0.#} 万`
/// 3. `>= 1e6` → `{0:0.#}M`
/// 4. `>= 1e3` → `{0:0.#}K`
/// 5. 其余 → `ToString("N0")`
///
/// 三点等价说明（都不是自造）：
/// · locale 门 = 主干那两行的 `_shellLocale.StartsWith("zh", StringComparison.OrdinalIgnore
///   Case)`（`_shellLocale` 见 `xaml.cs:503`/`:2256`）⇒ `zh` 与 `zh-TW` 都进中文档，分叉
///   `SETTINGS_LOCALE_IDS` 里以 zh 开头的正是这两枚。
/// · 亿/万 两档主干过 `LF`，但它们**只有中文档才进得去**，而 `L` 的第一档就是 zh 直通 ⇒
///   模板原样落回同一串字面量，这里直接写模板体（与 [`Catalog::dt`] 的 zh 档同口径）。
/// · `{0:0.#}` = [`one_decimal`]（最多一位小数、不带尾随 0）；`M`/`K` 走 `InvariantCulture`
///   ⇒ 小数点恒 `.`。
/// · 末档 `N0` 带千分位，但 `>= 1000` 早被第 4 档截走 ⇒ 真进到第 5 档的只有 0..999，`N0`
///   与原值同串；两个调用点还各有 `> 0` 前置判据，负数走不到这里。
fn tokens_text(locale: &str, tokens: i64) -> String {
    let zh = locale
        .get(..2)
        .is_some_and(|head| head.eq_ignore_ascii_case("zh"));
    if tokens >= 100_000_000 && zh {
        format!("{} 亿", one_decimal(tokens as f64 / 100_000_000.0))
    } else if tokens >= 10_000 && zh {
        format!("{} 万", one_decimal(tokens as f64 / 10_000.0))
    } else if tokens >= 1_000_000 {
        format!("{}M", one_decimal(tokens as f64 / 1_000_000.0))
    } else if tokens >= 1_000 {
        format!("{}K", one_decimal(tokens as f64 / 1_000.0))
    } else {
        format!("{tokens}")
    }
}

/// 主干 `FormatDuration`：`{0} 小时 {1} 分` / `{0} 分 {1} 秒` / `{0} 秒`。
fn duration_text(ms: i64) -> String {
    let secs = ms / 1000;
    if secs >= 3600 {
        format!("{} 小时 {} 分", secs / 3600, (secs % 3600) / 60)
    } else if secs >= 60 {
        format!("{} 分 {} 秒", secs / 60, secs % 60)
    } else {
        format!("{secs} 秒")
    }
}

/// 内核 usage 口径（`MainWindow.xaml.cs:13992`）：优先 totalTokens，否则四项相加。
fn usage_tokens(usage: &Value) -> i64 {
    let total = usage["totalTokens"].as_i64().unwrap_or(0);
    if total > 0 {
        return total;
    }
    [
        "inputTokens",
        "outputTokens",
        "cacheReadTokens",
        "cacheWriteTokens",
    ]
    .iter()
    .map(|key| usage[key].as_i64().unwrap_or(0))
    .sum()
}

/// 统计页专用的 token 可读化 = 主干 `FormatTokens`（`MainWindow.xaml.cs:15804`，**三档**）：
/// zh 且 `>=1e8` → 「亿」，zh 且 `>=1e4` → 「万」，其余 `ToString("N0")` 千分位。
/// 与 [`tokens_text`] 不是一回事（那是 `FormatTokensCompact` 的五档，`12 345` 会掉成 `12.3K`），
/// 统计页五枚 KPI / 两张图的 UIA 串 / 模型行都用这一把。
fn stats_tokens_text(locale: &str, tokens: i64) -> String {
    let zh = locale
        .get(..2)
        .is_some_and(|head| head.eq_ignore_ascii_case("zh"));
    if zh && tokens >= 100_000_000 {
        format!("{} 亿", one_decimal(tokens as f64 / 100_000_000.0))
    } else if zh && tokens >= 10_000 {
        format!("{} 万", one_decimal(tokens as f64 / 10_000.0))
    } else {
        n0(tokens)
    }
}

/// 主干 `ToString("N0")`：三位一逗。shell 只在 zh/en 之间切（`SETTINGS_LOCALES`），
/// 两者当前 culture 的分组符都是 `,`，故写死。
fn n0(value: i64) -> String {
    let digits = value.abs().to_string();
    let mut out = if value < 0 { String::from("-") } else { String::new() };
    for (index, digit) in digits.char_indices() {
        if index > 0 && (digits.len() - index) % 3 == 0 {
            out.push(',');
        }
        out.push(digit);
    }
    out
}

/// 主干 `RunStats.cs:316-317` 那颗 `TokensN0` 的逐字等价（原文
/// `v.ToString("N0", CultureInfo.InvariantCulture) + " tok"`）：千分位、负号、`0 → "0"`
/// 全由 [`n0`] 给，这一颗只在尾部补主干写死在代码里、**不过 i18n 表**的那枚 `" tok"`。
/// 与 [`n0`] 的分工是**读者不同**而非重复：`n0` 的另外四位读者（两张统计图、KPI、模型行）
/// 在主干侧吃的也是裸 `ToString("N0")`，给它们加单位就是比主干多做 ⇒ 单位只挂在这一颗上。
fn mw5_tokens_n0(value: i64) -> String {
    n0(value) + " tok"
}

/// 主干 `RunStats.cs:237-240` 那颗 `FormatTps` 的纯函数版：`decode_ms > 0 &&
/// decode_tokens > 0` 才 `decode_tokens / (decode_ms / 1000.0)` 走 `ToString("0")`（离零取整、
/// 恒无小数），否则 `"—"`。`<= 0` 含**负数**（主干那两发的 `> 0` 本来就把负数挡在外面）。
///
/// ⚠ 返回串**不带** ` tok/s`：左胶囊那枚模板里已经写着字面 ` tok/s`（`RS:229`），面板第四行的
/// `" tok/s"` 也是调用点贴上去的（`RS:278`）⇒ 单位塞进这颗函数就是 `tok/s tok/s` 叠加，
/// 与 `:230` 注释记的 `%%` / `tok tok` 事故同一条根。
#[must_use]
fn run_stats_tps(decode_ms: i64, decode_tokens: i64) -> String {
    if decode_ms > 0 && decode_tokens > 0 {
        // `.round()` = 离零进位，与 `ToString("0")` 同档；`{:.0}` 只会再截一次，值不变。
        format!("{}", (decode_tokens as f64 * 1000.0 / decode_ms as f64).round() as i64)
    } else {
        STATS_DASH.to_string()
    }
}

/// 主干 `RunStats.cs:243-246` 那颗 `FormatCacheHit` 的纯函数版：分母 `cache_read + input > 0`
/// 才 `100.0 * read / 分母` 走 `{0:0.#}`（≤1 位小数、去尾零，即 [`one_decimal`]），否则 `"—"`。
/// ⚠ **不带 `%`** —— 百分号在两处调用点各贴一次（`RS:231` 拼接尾、`RS:307` 面板行尾），
/// 主干那行 doc 明写着这条（「不含 % 号——LF 模板里已带字面 %，重复会显示 %%」）。
#[must_use]
fn run_stats_cache_hit(cache_read: i64, input: i64) -> String {
    let denominator = cache_read + input;
    if denominator > 0 {
        one_decimal(100.0 * cache_read as f64 / denominator as f64)
    } else {
        STATS_DASH.to_string()
    }
}

/// 主干 `RenderStatsKpi` 里 `total > 0 ? FormatTokens(total) : "—"` 的那个破折号（U+2014）：
/// **只**在真无数据时出现，不许拿它当装饰。
const STATS_DASH: &str = "—";

/// 一枚 KPI 的三段文本（值 / 小注 / UIA HelpText），形状对齐主干 `MainWindow.xaml:1501-1508`
/// 那三行 `TextBlock`。
#[derive(Clone, Debug, PartialEq, Eq)]
struct KpiText {
    value: String,
    hint: String,
    help: String,
}

/// 主干 `RenderStatsKpi`（`MainWindow.xaml.cs:15284-15325`）的**纯函数版**：吃聚合结果吐五枚卡
/// 的全部文案，卡序 = `STATS_KPI_CARDS` 序。判据逐条照抄（含 hint 那五串无数据文案的**卡位**；
/// 表里 `hint` 列曾经与主干错位一格，#121 已按 `:15300-15325` 那五个 false 分支改正，两边由
/// `usage_stats_render_tests::the_kpi_hint_column_and_the_text_function_agree` 互校钉住 ——
/// 这里仍**自己写死**不吃表：三档文案都在这颗函数里，表只给「无数据」那一档）。
/// 渲染层只填字，不算数。
fn usage_kpi_texts(catalog: &Catalog, locale: &str, kpis: &UsageKpis) -> [KpiText; 5] {
    let no_usage = catalog.l("内核未返回任何 token 用量记录");
    let total = if kpis.total_tokens > 0 {
        KpiText {
            value: stats_tokens_text(locale, kpis.total_tokens),
            hint: catalog.lf("{0} 条用量记录", &[kpis.usage_messages.to_string()]),
            help: catalog.lf(
                "{0:N0} tokens（{1} 条用量记录）",
                &[n0(kpis.total_tokens), kpis.usage_messages.to_string()],
            ),
        }
    } else {
        KpiText {
            value: STATS_DASH.to_string(),
            hint: catalog.l("暂无用量记录"),
            help: no_usage.clone(),
        }
    };
    let peak = if kpis.peak_tokens > 0 {
        let day = kpis.peak_day.map_or_else(String::new, format_day);
        KpiText {
            value: stats_tokens_text(locale, kpis.peak_tokens),
            hint: catalog.lf("单日峰值 · {0}", &[day.clone()]),
            help: catalog.lf(
                "单日峰值：{0}，{1:N0} tokens",
                &[day, n0(kpis.peak_tokens)],
            ),
        }
    } else {
        KpiText {
            value: STATS_DASH.to_string(),
            hint: catalog.l("暂无用量记录"),
            help: no_usage,
        }
    };
    let talk = if kpis.longest_talk_ms > 0 {
        let text = duration_text(kpis.longest_talk_ms);
        KpiText {
            hint: catalog.lf(
                "{0} 个会话中的最大值",
                &[kpis.session_count.to_string()],
            ),
            value: text.clone(),
            help: catalog.lf(
                "单会话对话累计时长最大值：{0}（按 turn/start→turn/end 求和）",
                &[text],
            ),
        }
    } else {
        KpiText {
            value: STATS_DASH.to_string(),
            hint: catalog.l("无完整 turn 记录"),
            help: catalog
                .l("内核 journal 未包含任何完整 turn（turn/start → turn/end），无法计算"),
        }
    };
    let current = if kpis.current_streak > 0 {
        KpiText {
            value: catalog.lf("{0} 天", &[kpis.current_streak.to_string()]),
            hint: catalog.l("截至今日"),
            help: String::new(),
        }
    } else {
        KpiText {
            value: STATS_DASH.to_string(),
            hint: catalog.l("今日暂无记录"),
            help: String::new(),
        }
    };
    let longest = if kpis.longest_streak > 0 {
        KpiText {
            value: catalog.lf("{0} 天", &[kpis.longest_streak.to_string()]),
            hint: catalog.lf("共活跃 {0} 天", &[kpis.active_days.to_string()]),
            help: String::new(),
        }
    } else {
        KpiText {
            value: STATS_DASH.to_string(),
            hint: catalog.l("暂无活跃记录"),
            help: String::new(),
        }
    };
    [total, peak, talk, current, longest]
}

/// 主干 `RenderStatsSourceNote`（:15354）：一条模板 + 两段口径说明**拼接**（不是一整串字面量）。
fn usage_source_note(catalog: &Catalog, kpis: &UsageKpis) -> String {
    let (skipped, capped) = source_note_tails(catalog, kpis);
    catalog.lf(
        "数据来源：内核 journal（session/list + session/page）的用量记录；已聚合 {0} 个非空会话、{1} 条记录{2}{3}。",
        &[
            kpis.sessions_scanned.to_string(),
            kpis.usage_messages.to_string(),
            skipped,
            capped,
        ],
    ) + &catalog.l("「累计/峰值/连续天数」按全部历史，「时间范围」只作用于趋势图与模型用量；")
        + &catalog.l("费用/金额内核未提供对应字段，故不展示。")
}

