/// （格子才是 14，两者共用同一颗圆角），行距 `Space6`、整行右对齐。
const STATS_HEAT_LEGEND: f64 = 12.0;

/// 趋势图例那颗色块：主干 `xaml:1697` 的 `Width/Height=10`、`RadiusX/Y=2`，与模型名同一行
/// （行内 `Spacing=Space6`、条目之间 `Space12`）；取色 = 主干 `ChartBrush(i)` =
/// `ChartSeries{i%6+1}Brush` ⇒ 分叉同一把表 `theme::chart_palette`（此前零读者）。
const STATS_TREND_SWATCH: f64 = 10.0;
const STATS_TREND_SWATCH_RADIUS: f64 = 2.0;

/// 热力 0 档与图例第 0 颗的底色 = 主干 `ChartHeatEmptyBrush`（`Tokens.xaml` 的实色字面量；
/// 分叉的这份值一直躺在 `theme::CHART_HEAT_EMPTY` 里，此前**没有任何读者**）。
/// 此前分叉拿 `p.control_fill`（`ControlFillColorDefault` = 半透明白/黑）兜底，与主干这颗
/// 实色**不等价** ⇒ 换回真值。`theme.rs` 一个字都不动，颜色常量的唯一来源还是那张表。
fn heat_empty_brush(scheme: Scheme) -> Brush {
    let hex = theme::CHART_HEAT_EMPTY[usize::from(matches!(scheme, Scheme::Dark))];
    Brush::Solid(Color {
        a: (hex >> 24) as u8,
        r: (hex >> 16) as u8,
        g: (hex >> 8) as u8,
        b: hex as u8,
    })
}

