    /// 面板那一层 = 整格透明的**无回调**遮罩 + 居中那张卡。刻法逐字抄 [`Shell::todos_panel_layer`]：
    /// 主干那颗同样是 `CapabilityDialog` 裹的 `ContentDialog.ShowAsync()`（`Traj:729/791`）
    /// = 应用级模态，点遮罩**不关**（只有 `CloseButton` 与 Esc 关）。
    fn trajectory_panel_layer(&self, context: &mut ViewContext<Shell>, p: Palette) -> View {
        let scrim: View = Border::new()
            .grid_row(0)
            .horizontal_alignment(HorizontalAlignment::Stretch)
            .vertical_alignment(VerticalAlignment::Stretch)
            .background(p.transparent.clone())
            .into();
        Grid::new()
            .rows([GridLength::STAR])
            .children((scrim, self.trajectory_panel_card(context, p)))
    }

    /// 主干 `ShowCapabilityTrajectoryAsync` 的正文（`:656-792`）逐件对表：
    /// `StackPanel{Spacing=Sp10, Width=560}` `TrajectoryPanel` → 说明行 → 筛选头 + `ComboBox`
    /// `TrajectoryKindFilter`（MinWidth 160、左对齐、`SelectedIndex=0`）→ 「计时总览」标题
    /// （BodyStrong）→ `ScrollViewer{MaxHeight=180}` `TrajectoryTimingScroll` 套
    /// `StackPanel{Spacing=Sp6}` `TrajectoryTiming` → 「事件账本」标题 → `ScrollViewer
    /// {MaxHeight=300}` `TrajectoryLedgerScroll` 套 `StackPanel{Spacing=Sp4}` `TrajectoryLedger`
    /// → 尾行 status（CaptionText + TextTertiary，`共 {0} 条事件 · {1} 轮`）。
    /// 主干 `dialog.Opened` 才 `RebuildTiming()/RebuildLedger()`（`:782-789`）⇒ 分叉即时模式
    /// 每帧现算，**同一张表**（打开期间来新帧主干不重算、分叉会 ⇒ 已备案，报告 §6-D4）。
    fn trajectory_panel_card(&self, context: &mut ViewContext<Shell>, p: Palette) -> View {
        let Some(row) = self.trajectory_session() else {
            // 主干 `:661-662`：字典查不到就 `??= new TrajectoryState()` ⇒ 两档空态**照样画**
            // （零条目 ⇒ 账本走「暂无事件」那一臂）。分叉这里同一张卡，只是拿到空表。
            return self.trajectory_panel_body(context, p, None);
        };
        self.trajectory_panel_body(context, p, Some(row))
    }

    fn trajectory_panel_body(
        &self,
        context: &mut ViewContext<Shell>,
        p: Palette,
        row: Option<&TrajSession>,
    ) -> View {
        let filters = Self::TRAJECTORY_FILTERS;
        let kind = filters
            .get(row.map_or(0, |_| self.trajectory_filter))
            .or(filters.first())
            .map_or("all", |(key, _, _)| *key);
        let entries = row.map_or(&[] as &[TrajEntry], |row| row.entries.as_slice());
        let turns = row.map_or(&[] as &[(i64, TrajTurn)], |row| row.turns.as_slice());
        let mut cells: Vec<KeyedView> = Vec::new();
        // 说明行（`:697-703`）—— 一句长文，B 道。
        let note: View = TextBlock::new()
            .text(self.catalog.bt(
                "事件账本与交互计时总览（数据来自 session journal 渲染管线）。点击轮次可跳到对应消息；展开行只读查看参数/结果/差异 JSON。",
                "Event ledger and interaction timing overview (from the session journal pipeline). Click a turn to jump to its message; expand a row for read-only payload/result/diff JSON.",
            ))
            .font_size(type_ramp::BODY.size)
            .text_wrapping(TextWrapping::Wrap)
            .into();
        cells.push(KeyedView::new("traj-note", note));
        // 筛选头的 `ComboBox.Header`（`:669`）：reactor 那档没有 Header ⇒ 用同串的**上方一行**
        // 表达同一处视觉（报告 §6-D6）。
        let filter_head: View = TextBlock::new()
            .text(self.catalog.bt("类型筛选", "Kind filter"))
            .font_size(type_ramp::CAPTION.size)
            .into();
        cells.push(KeyedView::new("traj-filter-head", filter_head));
        let filter: View = ComboBox::new()
            .min_width(160.0)
            .horizontal_alignment(HorizontalAlignment::Left)
            .items_source(
                filters
                    .iter()
                    .map(|(_, zh, en)| self.catalog.bt(zh, en)),
            )
            .selected_index(Some(self.trajectory_filter))
            .automation_id("TrajectoryKindFilter")
            .automation_name(self.catalog.bt("类型筛选", "Kind filter"))
            .on_selection_changed(context.callback(move |value: Option<usize>| {
                Msg::TrajectoryFilter(value.unwrap_or(0))
            }))
            .into();
        cells.push(KeyedView::new("traj-filter", filter));
        // 两颗小标题（BodyStrongTextStyle = `:708/:719` 的 `AppStyle("BodyStrongTextStyle")`）。
        for (key, text) in [
            ("traj-timing-head", ("计时总览", "Timing overview")),
            ("traj-ledger-head", ("事件账本", "Event ledger")),
        ] {
            let head: View = TextBlock::new()
                .text(self.catalog.bt(text.0, text.1))
                .font_size(type_ramp::BODY_STRONG.size)
                .into();
            cells.push(KeyedView::new(key, head));
        }
        // ---- 计时区：`TrajectoryTiming` 宿主（Spacing=Sp6）+ `TrajectoryTimingScroll` ----
        let mut timing: Vec<KeyedView> = Vec::new();
        if turns.is_empty() {
            let empty: View = TextBlock::new()
                .text(self.catalog.bt("暂无轮次计时。", "No turn timing yet."))
                .font_size(type_ramp::BODY.size)
                .text_wrapping(TextWrapping::Wrap)
                .into();
            timing.push(KeyedView::new("traj-timing-empty", empty));
        } else {
            // 主干 `:744` 的 `OrderBy(t => t.Turn)`：本表按插入序存 ⇒ 读侧排序。
            let mut order: Vec<&(i64, TrajTurn)> = turns.iter().collect();
            order.sort_by_key(|(turn, _)| *turn);
            for (_, tr) in order {
                let view = self.trajectory_turn_row(tr, context, p);
                timing.push(KeyedView::new(format!("traj-turn-{}", tr.turn), view));
            }
        }
        let timing_host: View = StackPanel::new()
            .orientation(Orientation::Vertical)
            .spacing(space::S6)
            .automation_id("TrajectoryTiming")
            .automation_name(self.catalog.bt("计时总览", "Timing overview"))
            .keyed_children(timing)
            .into();
        let timing_scroll: View = ScrollViewer::new()
            .max_height(180.0)
            .vertical_scroll_bar_visibility(ScrollBarVisibility::Auto)
            .automation_id("TrajectoryTimingScroll")
            .automation_name(self.catalog.bt("计时总览", "Timing overview"))
            .content(timing_host)
            .into();
        cells.push(KeyedView::new("traj-timing-scroll", timing_scroll));
        // ---- 账本区：`TrajectoryLedger` 宿主（Spacing=Sp4）+ `TrajectoryLedgerScroll` ----
        let shown: Vec<&TrajEntry> = entries
            .iter()
            .filter(|entry| kind == "all" || entry.kind == kind)
            .collect();
        let mut ledger: Vec<KeyedView> = Vec::new();
        if shown.is_empty() {
            // 两态空态**分开**（`:767-769`）：整本空 vs 只有这一档空。
            let text = if entries.is_empty() {
                self.catalog.bt(
                    "暂无事件（打开会话并产生消息后，账本随 journal 回放/实时流填充）。",
                    "No events yet (the ledger fills from journal replay / live follow once the session has messages).",
                )
            } else {
                self.catalog.bt("当前筛选没有事件。", "No events for this filter.")
            };
            let empty: View = TextBlock::new()
                .text(text)
                .font_size(type_ramp::BODY.size)
                .text_wrapping(TextWrapping::Wrap)
                .into();
            ledger.push(KeyedView::new("traj-ledger-empty", empty));
        } else {
            // 主干 `:774` 的注释：账本按 seq 升序 = 官方 trajectory 时间线语义 ⇒ 分叉是
            // push 序（journal 本来就是 seq 升序），**不重排**，重排等于把这条语义写第二遍。
            for entry in shown {
                let view = self.trajectory_ledger_row(entry, context, p);
                ledger.push(KeyedView::new(format!("traj-row-{}", entry.seq), view));
            }
        }
        let ledger_host: View = StackPanel::new()
            .orientation(Orientation::Vertical)
            .spacing(space::S4)
            .automation_id("TrajectoryLedger")
            .automation_name(self.catalog.bt("事件账本", "Event ledger"))
            .keyed_children(ledger)
            .into();
        let ledger_scroll: View = ScrollViewer::new()
            .max_height(300.0)
            .vertical_scroll_bar_visibility(ScrollBarVisibility::Auto)
            .automation_id("TrajectoryLedgerScroll")
            .automation_name(self.catalog.bt("事件账本", "Event ledger"))
            .content(ledger_host)
            .into();
        cells.push(KeyedView::new("traj-ledger-scroll", ledger_scroll));
        // 尾行 status（`:689-695` + `:786-788`）：CaptionText + TextTertiaryBrush，可选中；
        // 零条目时主干写的是**空串**（`:788`）⇒ 这里同口径留空，不自造一句。
        let status: View = TextBlock::new()
            .text(if entries.is_empty() {
                String::new()
            } else {
                self.catalog.btf(
                    "共 {0} 条事件 · {1} 轮",
                    "{0} events · {1} turns",
                    &[entries.len().to_string(), turns.len().to_string()],
                )
            })
            .font_size(type_ramp::CAPTION.size)
            .foreground(p.text_tertiary.clone())
            .text_wrapping(TextWrapping::Wrap)
            .into();
        cells.push(KeyedView::new("traj-status", status));
        // 关闭钮：主干那枚是 `ContentDialog` 自长的 `CloseButtonText`（`CP:106-112`），
        // **没有** AutomationId ⇒ 分叉只留 Name（仓规：树内不许自造 UIA id）。
        let close: View = Button::new()
            .min_width(0.0)
            .horizontal_alignment(HorizontalAlignment::Left)
            .automation_name(self.catalog.bt("关闭", "Close"))
            .on_click(context.message(Msg::TrajectoryPanelClose))
            .content(
                TextBlock::new().text(self.catalog.bt("关闭", "Close")),
            )
            .into();
        cells.push(KeyedView::new("traj-close", close));
        let root: View = StackPanel::new()
            .orientation(Orientation::Vertical)
            .spacing(space::S10)
            .width(560.0)
            .automation_id("TrajectoryPanel")
            .automation_name(self.catalog.bt("轨迹面板", "Trajectory panel"))
            .keyed_children(cells)
            .into();
        Border::new()
            .background(p.card.clone())
            .border_brush(p.stroke.clone())
            .border_thickness(size::STROKE)
            .corner_radius(radius::LARGE)
            .padding(th([16.0, 12.0, 16.0, 12.0]))
            .horizontal_alignment(HorizontalAlignment::Center)
            .vertical_alignment(VerticalAlignment::Center)
            // 卡题 = `CapabilityDialog(TrajText("轨迹","Trajectory"), root)`（`:729`）：B 道。
            .automation_name(self.catalog.bt("轨迹", "Trajectory"))
            .content(ScrollViewer::new().content(root))
    }

    /// 主干 `TrajectoryStatRow`（`:981-998`）：`Grid{[*, Auto], ColumnSpacing=Sp16}` =
    /// 左标签 `Opacity=0.72` + 右值（右对齐），两行都 `TextWrapping=Wrap`。
    fn trajectory_stat_row(label: String, value: String) -> View {
        let left: View = TextBlock::new()
            .text(label)
            .opacity(0.72)
            .font_size(type_ramp::BODY.size)
            .text_wrapping(TextWrapping::Wrap)
            .into();
        let right: View = TextBlock::new()
            .text(value)
            .font_size(type_ramp::BODY.size)
            .horizontal_alignment(HorizontalAlignment::Right)
            .text_wrapping(TextWrapping::Wrap)
            .into();
        Grid::new()
            .columns([GridLength::STAR, GridLength::Auto])
            .column_spacing(16.0)
            .children((left, right))
            .into()
    }

    /// 一行展开/收起的**表头钮 + 条件正文**（主干 `Expander` 的分叉等价物，先例 =
    /// `compaction_card` / `workflow_run_card` 那两颗的 `*_open` 集）。
    fn trajectory_toggle_head(
        &self,
        key: &str,
        header: String,
        context: &mut ViewContext<Shell>,
    ) -> View {
        Button::new()
            .min_width(0.0)
            .horizontal_alignment(HorizontalAlignment::Stretch)
            .resource_overrides(
                ResourceOverrides::new()
                    .set("ButtonBackground", Color::transparent())
                    .set("ButtonBackgroundPointerOver", Color::transparent())
                    .set("ButtonBackgroundPressed", Color::transparent())
                    .set("ButtonBackgroundDisabled", Color::transparent())
                    .set("ButtonBorderBrush", Color::transparent())
                    .set("ButtonBorderBrushPointerOver", Color::transparent())
                    .set("ButtonBorderBrushPressed", Color::transparent())
                    .set("ButtonBorderBrushDisabled", Color::transparent())
                    .set("ButtonPadding", th([0.0, 2.0, 0.0, 2.0])),
            )
            .automation_name(header.clone())
            .on_click(context.message(Msg::TrajectoryRowToggle(key.to_string())))
            .content(TextBlock::new().text(header).text_wrapping(TextWrapping::Wrap))
            .into()
    }

    /// 主干 `BuildTrajectoryTurnRow`（`:810-879`）。表头四段拼接（`:815-827`）与九行正文
    /// （`:830-841`）+ 可选模型行（`:842-845`）+ 工具耗时块（`:846-861`）+ 跳轮钮
    /// （`:863-870`）逐件对表。`{0:N0}` 那一洞（`:859`）**必须** `btf`，且千分位由调用点
    /// 自己格式化（[`mw5_tokens_n0`] = Invariant N0，与主干同口径）。
    fn trajectory_turn_row(
        &self,
        tr: &TrajTurn,
        context: &mut ViewContext<Shell>,
        p: Palette,
    ) -> View {
        let duration = tr
            .end_ms
            .filter(|end| *end >= tr.start_ms && tr.start_ms > 0)
            .map_or(0, |end| end - tr.start_ms);
        let mut head = self.catalog.btf("第 {0} 轮", "Turn {0}", &[tr.turn.to_string()]);
        if let Some(round) = tr.goal_round {
            head += " · ";
            head += &if round > 0 {
                self.catalog.btf(
                    "目标 · Round {0}",
                    "Goal · Round {0}",
                    &[round.to_string()],
                )
            } else {
                // 母本 `Traj:366-367` 的**后半档**：`round <= 0` 时不是「没有目标段」，而是只写
                // 「目标」二字（`TrajText("目标","Goal")`）。旧代码把轮号折成空串 ⇒ 这一档整段少画
                // （M4F 必修清单第 5 条，读数级少做），本轮改成两档都在。
                self.catalog.bt("目标", "Goal")
            };
        }
        if !tr.prompt_preview.is_empty() {
            head += " · ";
            head += &tr.prompt_preview;
        }
        head += " · ";
        head += &if tr.end_ms.is_none() && tr.start_ms > 0 {
            self.catalog
                .bt("会话时间戳（运行中）", "Session timestamps (running)")
        } else if duration > 0 {
            duration_text(duration)
        } else {
            "—".to_string()
        };
        head += " · ";
        head += &self.catalog.btf("{0} 步", "{0} steps", &[tr.steps.to_string()]);
        let key = format!("turn-{}", tr.turn);
        let open = self.trajectory_open.iter().any(|k| *k == key);
        let mut cells: Vec<KeyedView> = vec![KeyedView::new(
            "head",
            self.trajectory_toggle_head(&key, head, context),
        )];
        if open {
            let not_recorded = || self.catalog.bt("未记录", "Not recorded");
            let body = [
                (
                    self.catalog.bt("开始时间", "Started"),
                    if tr.start_ms > 0 {
                        message_clock(tr.start_ms)
                    } else {
                        not_recorded()
                    },
                ),
                (
                    self.catalog.bt("总时长", "Total duration"),
                    if duration > 0 {
                        duration_text(duration)
                    } else {
                        "—".to_string()
                    },
                ),
                (
                    self.catalog.bt("模型用时", "LLM time"),
                    duration_text(tr.llm_ms),
                ),
                (
                    self.catalog.bt("工具调用用时", "Tool time"),
                    duration_text(tr.tool_ms),
                ),
                (
                    self.catalog.bt("首 token 延迟", "TTFT"),
                    if tr.ttft_steps > 0 {
                        duration_text(tr.ttft_ms / tr.ttft_steps)
                    } else {
                        "—".to_string()
                    },
                ),
                (
                    self.catalog.bt("输出速度（TPS）", "Throughput (TPS)"),
                    run_stats_tps(tr.decode_ms, tr.decode_tokens) + " tok/s",
                ),
                (
                    self.catalog.bt("缓存命中", "Cache hit"),
                    if tr.cache_read_tokens + tr.input_tokens > 0 {
                        format!(
                            "{:.1}",
                            100.0 * tr.cache_read_tokens as f64
                                / (tr.cache_read_tokens + tr.input_tokens) as f64
                        )
                        .trim_end_matches(".0")
                        .to_string()
                    } else {
                        "—".to_string()
                    } + "%",
                ),
                (
                    self.catalog.bt("Token", "Tokens"),
                    format!(
                        "{} · {} {}",
                        mw5_tokens_n0(tr.total_tokens),
                        self.catalog.bt("输出", "Output"),
                        mw5_tokens_n0(tr.output_tokens)
                    ),
                ),
            ];
            for (index, (label, value)) in body.into_iter().enumerate() {
                cells.push(KeyedView::new(
                    format!("stat-{index}"),
                    Self::trajectory_stat_row(label, value),
                ));
            }
            if !tr.model.is_empty() {
                cells.push(KeyedView::new(
                    "stat-model",
                    Self::trajectory_stat_row(self.catalog.bt("模型", "Model"), tr.model.clone()),
                ));
            }
            if !tr.tools.is_empty() {
                let title: View = TextBlock::new()
                    .text(self.catalog.bt("工具耗时", "Tool durations"))
                    .font_size(type_ramp::CAPTION.size)
                    .font_weight(FontWeight::SEMI_BOLD)
                    .into();
                cells.push(KeyedView::new("tool-title", title));
                for (index, tool) in tr.tools.iter().enumerate() {
                    let ms = tool
                        .end_ms
                        .filter(|end| *end >= tool.start_ms && tool.start_ms > 0)
                        .map_or(0, |end| end - tool.start_ms);
                    let mut label = if tool.name_fallback {
                        self.catalog.l("工具")
                    } else {
                        tool.name.clone()
                    };
                    if tool.is_error {
                        label += " · ";
                        label += &self.catalog.bt("失败", "Failed");
                    }
                    let value = if ms > 0 {
                        self.catalog
                            .btf("{0:N0} 毫秒", "{0:N0} ms", &[mw5_tokens_n0(ms)])
                    } else {
                        self.catalog.bt("未记录", "Not recorded")
                    };
                    cells.push(KeyedView::new(
                        format!("tool-{index}"),
                        Self::trajectory_stat_row(label, value),
                    ));
                }
            }
            // 跳轮钮（`:863-870`）：id 是**前缀 + 动态段**，不是整串字面量。
            let jump: View = Button::new()
                .min_width(0.0)
                .horizontal_alignment(HorizontalAlignment::Left)
                .automation_id(format!("TrajectoryJumpTurn_{}", tr.turn))
                .automation_name(self.catalog.btf(
                    "跳到第 {0} 轮消息",
                    "Jump to turn {0} message",
                    &[tr.turn.to_string()],
                ))
                .on_click(context.message(Msg::TrajectoryJumpTurn(tr.turn)))
                .content(
                    TextBlock::new().text(self.catalog.bt("跳到消息", "Jump to message")),
                )
                .into();
            cells.push(KeyedView::new("jump", jump));
        }
        let _ = p;
        StackPanel::new()
            .orientation(Orientation::Vertical)
            .spacing(space::S4)
            .horizontal_alignment(HorizontalAlignment::Stretch)
            .keyed_children(cells)
            .into()
    }

    /// 主干 `BuildTrajectoryLedgerRow`（`:881-959`）：表头 `#{Seq} · 时钟 · Label [· 来源] [· 第 N 轮]`
    /// （`:883-892`），正文 = 事件 / 来源 / 差异（三行 CodeText）/ 参数 JSON / 结果 JSON。
    /// 主干那三件各是**嵌套的 `Expander`**（`:935/:945/:949`）⇒ 分叉同样开三层，
    /// 键前缀 `diff-` / `payload-` / `result-`（默认全收起 = 主干默认态）。
    fn trajectory_ledger_row(
        &self,
        entry: &TrajEntry,
        context: &mut ViewContext<Shell>,
        p: Palette,
    ) -> View {
        let clock = if entry.time > 0 {
            message_clock(entry.time)
        } else {
            "—".to_string()
        };
        let mut header = format!("#{} · {} · {}", entry.seq, clock, entry.label);
        if !entry.source_label.is_empty() && !entry.label.contains(&entry.source_label) {
            header += " · ";
            header += &entry.source_label;
        }
        if entry.turn > 0 {
            header += " · ";
            header += &self
                .catalog
                .btf("第 {0} 轮", "Turn {0}", &[entry.turn.to_string()]);
        }
        let key = format!("row-{}", entry.seq);
        let open = self.trajectory_open.iter().any(|k| *k == key);
        let mut cells: Vec<KeyedView> = vec![KeyedView::new(
            "head",
            self.trajectory_toggle_head(&key, header, context),
        )];
        if open {
            cells.push(KeyedView::new(
                "ev",
                Self::trajectory_stat_row(self.catalog.bt("事件", "Event"), entry.type_name.clone()),
            ));
            if !entry.source_label.is_empty() {
                cells.push(KeyedView::new(
                    "src",
                    Self::trajectory_stat_row(
                        self.catalog.bt("来源", "Source"),
                        entry.source_label.clone(),
                    ),
                ));
            }
            if entry.diff_old.is_some() || entry.diff_new.is_some() {
                let diff_key = format!("diff-{}", entry.seq);
                let diff_open = self.trajectory_open.iter().any(|k| *k == diff_key);
                cells.push(KeyedView::new(
                    "diff-head",
                    self.trajectory_toggle_head(
                        &diff_key,
                        self.catalog.bt("差异", "Diff"),
                        context,
                    ),
                ));
                if diff_open {
                    let code = |text: String, brush: Option<Brush>| {
                        let mut block = TextBlock::new()
                            .text(text)
                            .font_size(type_ramp::CODE.size)
                            .text_wrapping(TextWrapping::Wrap);
                        if let Some(brush) = brush {
                            block = block.foreground(brush);
                        }
                        let view: View = block.into();
                        view
                    };
                    if !entry.diff_path.is_empty() {
                        cells.push(KeyedView::new(
                            "diff-path",
                            code(entry.diff_path.clone(), None),
                        ));
                    }
                    if let Some(old) = &entry.diff_old {
                        cells.push(KeyedView::new(
                            "diff-old",
                            code(format!("− {old}"), Some(p.error.clone())),
                        ));
                    }
                    if let Some(new) = &entry.diff_new {
                        cells.push(KeyedView::new(
                            "diff-new",
                            code(format!("+ {new}"), Some(p.success.clone())),
                        ));
                    }
                }
            }
            for (key, title, json) in [
                (
                    "payload",
                    self.catalog.bt("参数 JSON", "Payload JSON"),
                    &entry.payload_json,
                ),
                (
                    "result",
                    self.catalog.bt("结果 JSON", "Result JSON"),
                    &entry.result_json,
                ),
            ] {
                if json.is_empty() {
                    continue; // 主干 `!string.IsNullOrEmpty` 那两道门（`:943/:947`）
                }
                let inner = format!("{key}-{}", entry.seq);
                let inner_open = self.trajectory_open.iter().any(|k| *k == inner);
                cells.push(KeyedView::new(
                    format!("{key}-head"),
                    self.trajectory_toggle_head(&inner, title, context),
                ));
                if inner_open {
                    // 主干 `TrajectoryJsonExpander`（`:961-979`）：CodeText + Wrap + 可选中 +
                    // 套一层 `MaxHeight=180` 的滚动件。
                    let text: View = TextBlock::new()
                        .text(json.clone())
                        .font_size(type_ramp::CODE.size)
                        .text_wrapping(TextWrapping::Wrap)
                        .into();
                    let scroller: View = ScrollViewer::new()
                        .max_height(180.0)
                        .vertical_scroll_bar_visibility(ScrollBarVisibility::Auto)
                        .content(text)
                        .into();
                    cells.push(KeyedView::new(format!("{key}-body"), scroller));
                }
            }
        }
        StackPanel::new()
            .orientation(Orientation::Vertical)
            .spacing(space::S4)
            .horizontal_alignment(HorizontalAlignment::Stretch)
            .keyed_children(cells)
            .into()
    }

    /// 批 M2c（#108 切片9 第二张）：目标面板的浮层壳 = 主干那张 `ContentDialog`
    /// （`Capabilities.cs:166` 的 `CapabilityDialog(…, new ScrollViewer { … })` + `:291` 的
    /// `await dialog.ShowAsync()`）。形制逐字同 [`Shell::trajectory_panel_layer`]：一层透明
    /// scrim 铺满 + 卡片居中 ⇒ 「应用级模态」在分叉的等价物（报告 §6-D1 那条老账）。
    /// 显隐同口径：reactor 没有 `Visibility` ⇒ 不开就这棵节点根本不生成（`chat_page` 那一格）。
    fn goal_panel_layer(&self, context: &mut ViewContext<Shell>, p: Palette) -> View {
        let scrim: View = Border::new()
            .grid_row(0)
            .horizontal_alignment(HorizontalAlignment::Stretch)
            .vertical_alignment(VerticalAlignment::Stretch)
            .background(p.transparent.clone())
            .into();
        Grid::new()
            .rows([GridLength::STAR])
            .children((scrim, self.goal_panel_body(context, p)))
    }

    /// 主干 `ShowCapabilityGoalAsync` 的正文（`Capabilities.cs:145-292`）逐件对表：
    /// `ScrollViewer{MaxHeight=540}`（`:166`）套 `StackPanel{Spacing=12, Width=440}`（`:155`），
    /// 加入序 = `:156-165` 那六发 `body.Children.Add`：
    /// `state`（`:150`，Wrap + 可选中）→ `objective`（`:152`，Header + AcceptsReturn + Wrap +
    /// MaxHeight=160）→ `rounds`（`:153`，只有 Header）→ 警示行（`:159-163`）→
    /// `actions`（`:154`，`StackPanel{Spacing=8}`，七颗钮按 `:274-280` 的声明序）→
    /// `error`（`:151`，Wrap + 可选中，**零前景色**）。
    /// 关闭钮 = `CapabilityDialog` 的统一 `CloseButtonText`（`:110`）⇒ 它在主干是对话框按钮区，
    /// **不在** `ScrollViewer` 里 ⇒ 分叉把它挂在滚动件**之外**（与 M4 轨迹卡把它塞进正文尾部的
    /// 选择不同，这里跟主干的容器归属；报告 §6-D5）。
    ///
    /// 使能合取逐字照 `:190`：`!busy && !closed && _activeSessionId == sessionId && allowed`。
    /// 分叉这层只在卡开着时渲染 ⇒ `!closed` 恒真，剩下三件每帧现读（即时模式 = 主干那十二发
    /// `UpdateButtons()` 的等价物）。`allowed` 一律问 [`goal_action_gate`]，本文件**不**重写判据
    /// （施工图 §2.4 红线：`capabilities.rs` 是唯一真相）。
    fn goal_panel_body(&self, context: &mut ViewContext<Shell>, p: Palette) -> View {
        // `:173-175` 的三份现读值：hasGoal 看**原始**那一格是不是对象（不是看解析成不成），
        // phase/activation 走 `CapabilityString` 语义 ⇒ 解析成功才拿得到（缺键/非串都是空串）。
        let view = self
            .goal_view
            .as_ref()
            .and_then(|value| parse_goal_panel(value).ok())
            .flatten();
        let has_goal = self.goal_view.as_ref().is_some_and(Value::is_object);
        let gate = goal_action_gate(
            self.goal_loaded,
            has_goal,
            view.as_ref().map_or("", |view| view.phase.as_str()),
            view.as_ref().map_or("", |view| view.activation.as_str()),
        );
        // 主干 `:190` 的 `&& _activeSessionId == sessionId`（那张卡的 `sessionId` 是开卡时
        // `CapabilitySession()` 抓的，此后每次点钮都拿它对表 `:127/:224`）。
        let same_session = self
            .active
            .as_deref()
            .is_some_and(|id| self.goal_panel.as_deref() == Some(id));
        let actionable = same_session && !self.goal_busy;
        // `:192`：两颗框的使能**不看** allowed/会话，只看 `!busy && loaded`。
        let boxes_enabled = !self.goal_busy && self.goal_loaded;
        let mut cells: Vec<KeyedView> = Vec::new();
        // ---- state（`:204` + `TargetPanelText` `:131-143`）----
        // 三行格式逐字照 `:137-139`：`{phase} / {activation}` / `ID: {id}  revision: {rev}`（**两根**
        // 空格）/ 「已启动轮数：」+ roundsStarted；`blockedReason` 键在就再追一行（`:140-141`）。
        // phase / activation / id / revision / roundsStarted 全是**内核原文**，一根都不过 i18n ⇒
        // 只有「已启动轮数：」这根前缀过表（`:139`）。
        let state_text = match (&self.goal_view, view.as_ref()) {
            (Some(_), Some(parsed)) => {
                let mut text = format!(
                    "{} / {}\nID: {}  revision: {}\n{}{}",
                    parsed.phase,
                    parsed.activation,
                    parsed.id,
                    goal_json_text(&parsed.revision),
                    self.catalog.bt("已启动轮数：", "Rounds started: "),
                    goal_json_text(&parsed.rounds_started),
                );
                if let Some(reason) = &parsed.blocked_reason {
                    text.push('\n');
                    text.push_str(&reason.message);
                }
                text
            }
            // `:133-134`：只有 undefined / null 这一档算「尚未设置目标」；`false`/`0`/`""` 是
            // 「非对象」⇒ 走 `:136` 抛，`state.Text` 因此**不被赋值**（分叉同档：留空）。
            (Some(value), None) if value.is_null() => {
                self.catalog.bt("尚未设置目标", "Not set")
            }
            // 回读还在路上（`:197-198` 刚清过）⇒ 主干那张新对话框此时 `state.Text` 还是空串。
            _ => String::new(),
        };
        let state: View = TextBlock::new()
            .text(state_text)
            .font_size(type_ramp::BODY.size)
            .text_wrapping(TextWrapping::Wrap)
            .is_text_selection_enabled(true)
            .into();
        cells.push(KeyedView::new("goal-state", state));
        // ---- 两颗 TextBox 的 Header（`:152-153`）----
        // reactor 的 TextBox **没有** `Header` ⇒ 同串改成上方的标题行（M4 的 `traj-filter-head`
        // 先例，报告 §6-D6）；字号取 Header 的 CAPTION 档。加入序仍是主干那三对
        // （state → objective → rounds）。
        let objective_head = self.catalog.bt("目标内容", "Objective");
        let rounds_head = self.catalog.bt(
            "最大轮数（创建时可留空使用内核默认值）",
            "Maximum rounds (optional on creation)",
        );
        for (key, label) in [
            ("goal-objective-head", objective_head.clone()),
            ("goal-rounds-head", rounds_head.clone()),
        ] {
            let head: View = TextBlock::new()
                .text(label)
                .font_size(type_ramp::CAPTION.size)
                .into();
            cells.push(KeyedView::new(key, head));
        }
        let objective: View = TextBox::new()
            .text(self.goal_objective.clone())
            .is_enabled(boxes_enabled)
            // `:152`：AcceptsReturn + Wrap + MaxHeight=160 三件一起给。
            .accepts_return(true)
            .text_wrapping(TextWrapping::Wrap)
            .max_height(160.0)
            .automation_name(objective_head)
            .on_text_changed(context.callback(move |value: String| {
                Msg::GoalObjectiveDraft(value)
            }))
            .into();
        cells.push(KeyedView::new("goal-objective", objective));
        // `:153`：这颗只有 Header ⇒ 单行、不 AcceptsReturn、无 MaxHeight。
        let rounds: View = TextBox::new()
            .text(self.goal_rounds.clone())
            .is_enabled(boxes_enabled)
            .automation_name(rounds_head)
            .on_text_changed(context.callback(move |value: String| {
                Msg::GoalRoundsDraft(value)
            }))
            .into();
        cells.push(KeyedView::new("goal-rounds", rounds));
        // ---- 警示行（`:159-163`）：只有 Wrap，无选中、无前景色 ----
        let warning: View = TextBlock::new()
            .text(self.catalog.bt(
                "创建或恢复目标可能启动内核执行；仅在确认目标后操作。",
                "Creating or resuming a goal may start kernel execution. Act only after confirming the objective.",
            ))
            .font_size(type_ramp::BODY.size)
            .text_wrapping(TextWrapping::Wrap)
            .into();
        cells.push(KeyedView::new("goal-warning", warning));
        // ---- actions（`:154` + `:274-287`）：StackPanel{Spacing=8}，七颗、声明序 ----
        let mut actions: Vec<KeyedView> = Vec::new();
        for (verb, zh, en) in [
            (VERB_GET, "刷新", "Refresh"),
            (VERB_CREATE, "创建目标", "Create goal"),
            (VERB_EDIT, "保存编辑", "Save edits"),
            (VERB_PAUSE, "暂停", "Pause"),
            // ⚠ 内联英文面值必须是 `Resume`（主干 `:278` 的原文）：分叉 EN 表在架的是
            // `("恢复","Restore")`（`xaml.cs:1290` 的生效值）⇒ `bt` 第一档 `l()` 先赢，
            // 这一枚内联串是**死码**。把它「改对」成 Restore 反而造出真缺陷（施工图 §7-1）。
            (VERB_RESUME, "恢复", "Resume"),
            (VERB_COMPLETE, "标记完成", "Mark complete"),
            (VERB_CLEAR, "清除目标", "Clear goal"),
        ] {
            let label = self.catalog.bt(zh, en);
            let button: View = Button::new()
                .min_width(0.0)
                .horizontal_alignment(HorizontalAlignment::Stretch)
                .is_enabled(actionable && gate.enabled(verb))
                .automation_name(label.clone())
                .on_click(context.message(Msg::GoalRun(verb)))
                .content(TextBlock::new().text(label))
                .into();
            actions.push(KeyedView::new(format!("goal-act-{verb}"), button));
        }
        let actions_host: View = StackPanel::new()
            .orientation(Orientation::Vertical)
            .spacing(space::S8)
            .keyed_children(actions)
            .into();
        cells.push(KeyedView::new("goal-actions", actions_host));
        // ---- error（`:151` + `:258/:267`）：Wrap + 可选中，主干一个字都没上色 ----
        let error: View = TextBlock::new()
            .text(self.goal_error.clone())
            .font_size(type_ramp::BODY.size)
            .text_wrapping(TextWrapping::Wrap)
            .is_text_selection_enabled(true)
            .into();
        cells.push(KeyedView::new("goal-error", error));
        let body: View = StackPanel::new()
            .orientation(Orientation::Vertical)
            .spacing(space::S12)
            .width(440.0)
            .keyed_children(cells)
            .into();
        // 主干 `:166`：`new ScrollViewer { Content = body, MaxHeight = 540 }`（横向滚动没关，
        // 也没 VerticalScrollBarVisibility ⇒ 走控件默认 Auto，与轨迹卡那两颗显式写 Auto 的不同）。
        let scroll: View = ScrollViewer::new().max_height(540.0).content(body).into();
        // 卡题「目标」的**可见行**：主干 `CP:166` 把那一串交给 `CapabilityDialog` 的 `Title`
        // （`:106-112`）⇒ 它上屏在标题区 = 滚动件**之外**、正文**之上**。分叉是自绘壳，旧形只把
        // 同串塞进下面 `Border` 的 `automation_name`（可见性 = 零，缺陷 FA1-F-3）⇒ 现在两形共用
        // 同一枚现读值。字号取 `type_ramp::SUBTITLE`（20 SemiBold = WinUI `ContentDialog` 标题档），
        // 落点在滚动件之前，口径同 [`Shell::danger_confirm_card`] 那颗应用级模态的标题行先例。
        let title = self.catalog.bt("目标", "Goal");
        let title_row: View = TextBlock::new()
            .text(title.clone())
            .font_size(type_ramp::SUBTITLE.size)
            .font_weight(FontWeight::SEMI_BOLD)
            .text_wrapping(TextWrapping::Wrap)
            .into();
        // 关闭钮：主干 `CapabilityDialog` 的 `CloseButtonText`（`:110`）⇒ 对话框按钮区，
        // 在滚动件之外、正文之下。零 glyph、零 AutomationId（仓规：树内不许自造 id）。
        let close_label = self.catalog.bt("关闭", "Close");
        let close: View = Button::new()
            .min_width(0.0)
            .horizontal_alignment(HorizontalAlignment::Left)
            .automation_name(close_label.clone())
            .on_click(context.message(Msg::GoalPanelClose))
            .content(TextBlock::new().text(close_label))
            .into();
        Border::new()
            .background(p.card.clone())
            .border_brush(p.stroke.clone())
            .border_thickness(size::STROKE)
            .corner_radius(radius::LARGE)
            .padding(th([16.0, 12.0, 16.0, 12.0]))
            .horizontal_alignment(HorizontalAlignment::Center)
            .vertical_alignment(VerticalAlignment::Center)
            // 卡题 = `CapabilityDialog(CapabilityText("目标","Goal"), …)`（`:166`）：B 道。
            .automation_name(title)
            .content(
                StackPanel::new()
                    .orientation(Orientation::Vertical)
                    .spacing(space::S12)
                    .children((title_row, scroll, close)),
            )
    }

    /// 批 P155（#155：「计划（只读）」那张，spec §1 的 `ShowCapabilitySchedulesAsync`）：
    /// 浮层壳 = 主干 `CP:361-363` 那一发
    /// `CapabilityDialog(标题, new ScrollViewer{ Content = body, MaxHeight = 480 }).ShowAsync()`。
    /// 形制逐字同 [`Shell::goal_panel_layer`] / [`Shell::trajectory_panel_layer`]：一层透明 scrim
    /// 铺满 + 卡片居中 ⇒ 「应用级模态」。遮罩**不挂** `on_pointer_pressed`（简报 D-2 / MD1 报告
    /// F-1）：`ContentDialog` 一族的关闭通路只有 `CloseButtonText`（`CP:110`）与 Esc，主干
    /// 一处都没设 `ShouldCloseOnOutsideClick` ⇒ 点外面**不关**；**不是**
    /// [`Shell::workspace_menu_layer`] / [`Shell::selector_layer`] 那两族 `MenuFlyout` 的
    /// light-dismiss。挂位 = [`Shell::app_modal_host`] 的第四格（**不**挂 `chat_page`，D-1）。
    fn schedule_panel_layer(&self, context: &mut ViewContext<Shell>, p: Palette) -> View {
        let scrim: View = Border::new()
            .grid_row(0)
            .horizontal_alignment(HorizontalAlignment::Stretch)
            .vertical_alignment(VerticalAlignment::Stretch)
            .background(p.transparent.clone())
            .into();
        Grid::new()
            .rows([GridLength::STAR])
            .children((scrim, self.schedule_panel_card(context, p)))
    }

    /// 主干 `ShowCapabilitySchedulesAsync` 的正文（`CP:294-364`）逐件对表（spec §2.3 / §4）：
    /// `StackPanel{Spacing=10, Width=440}`（`:314`）→ **恒显示**的只读声明（`:315-321`，Wrap、
    /// **未设** `IsTextSelectionEnabled` ⇒ 不可选）→ 三档里的空态二选一（`:322-333`，Wrap +
    /// **可选中** ⇒ 与上一行**不同档，不许并档**）或 N 组行（`:334-360`：行容器
    /// `StackPanel{Spacing=2}` `:336` = prompt 行（`:339-341` Wrap + 可选中）+ meta 行
    /// （`:354-357` Wrap + `TextTertiaryBrush` + `CaptionTextStyle`））。
    /// 关闭钮 = `CapabilityDialog` 的统一 `CloseButtonText`（`:110`）⇒ 主干它在对话框按钮区、
    /// **不在** `ScrollViewer` 里 ⇒ 分叉同样挂在滚动件**之外**（同 [`Shell::goal_panel_body`]）。
    /// 排序（`:305-312`）、三档（`:322-333`）、meta 拼接（`:343-351`）与五枚频率 / 四枚量级
    /// （`:366-386`）全走文件级纯函数（[`schedule_order_keys`] / [`schedule_frequency`] /
    /// [`schedule_relative`] / [`schedule_local_stamp`]），本 fn 一条判据都不重写。
    /// 复制通道（D-9 / spec §6.5）：`CapabilityText` 那三枚走 `bt`、`LF()` 那几枚走 `lf`、
    /// `L("一次性")` 走 `l` ⇒ 走错就是把「字典生效」与「内联生效」两档对调。
    fn schedule_panel_card(&self, context: &mut ViewContext<Shell>, p: Palette) -> View {
        // `:305` 的 `now = DateTimeOffset.UtcNow`：即时模式 ⇒ 每帧现读（主干是开框那一刻读一次）。
        let now_ms = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map(|span| span.as_millis() as i64)
            .unwrap_or(0);
        // `:346` 的 `ToLocalTime()`：这里只要偏移，日序由 `schedule_local_stamp` 自己算。
        let (_, offset_secs) = local_clock();
        // `:307-311` 的两键排序（稳定 ⇒ 同刻保缓存原序，即投影数组到达序 `SS:157-171`）。
        let mut ordered: Vec<(Option<i64>, &ScheduleRecord)> = self
            .schedule_records
            .iter()
            .map(|record| (schedule_at_millis(&record.scheduled_at), record))
            .collect();
        ordered.sort_by_key(|(at, _)| schedule_order_keys(*at, now_ms));
        let mut cells: Vec<KeyedView> = Vec::new();
        // ---- 只读声明（`:315-321`）：spec §2.1 第 3 枚 = 全表 16 枚里**内联 en 真正生效**的两枚之一 ----
        // ⚠ 抄的是这句**短文**，不是 `MW:1446` 那条全仓零使用的孤儿长版（spec §0 第 6 条 / R3）。
        let note: View = TextBlock::new()
            .text(self.catalog.bt(
                "计划为只读清单（数据来自会话投影 schedule）。此入口不创建、编辑或删除计划，也不调用 schedules RPC。",
                "Schedules are a read-only list (data from the session schedule projection). No schedules are created, edited or deleted; no schedules RPC is called.",
            ))
            .font_size(type_ramp::BODY.size)
            .text_wrapping(TextWrapping::Wrap)
            .into();
        cells.push(KeyedView::new("schedule-note", note));
        if ordered.is_empty() {
            // ---- 空态两档（`:322-333`）：`seen` 真 ⇒ A（#4，内联 en **生效**）；假 ⇒ B（#5，字典在架）----
            let (zh, en) = if self.schedule_seen {
                ("当前会话没有计划。", "No schedules in this session.")
            } else {
                (
                    "尚未收到本会话的计划投影（投影随会话活动到达），此时不表示没有计划。",
                    "The schedule projection has not arrived yet (the kernel pushes it lazily); this does not mean there are no schedules.",
                )
            };
            let empty: View = TextBlock::new()
                .text(self.catalog.bt(zh, en))
                .font_size(type_ramp::BODY.size)
                .text_wrapping(TextWrapping::Wrap)
                // `:331`：只有这一行开了选中 ⇒ 与上面那枚声明刻意不同档。
                .is_text_selection_enabled(true)
                .into();
            cells.push(KeyedView::new("schedule-empty", empty));
        } else {
            for (index, (at, record)) in ordered.iter().enumerate() {
                // prompt 行（`:338-341`）：内核原文，一个字都不过 i18n。
                let prompt: View = TextBlock::new()
                    .text(record.prompt.clone())
                    .font_size(type_ramp::BODY.size)
                    .text_wrapping(TextWrapping::Wrap)
                    .is_text_selection_enabled(true)
                    .into();
                // meta 行（`:343-351`）：`频率` + 解析成功时再 `" · " 本地时间 " · " 相对量`
                // ⇒ 那枚 `" · "` 字面量**用两次**，与主干同发数（spec §2.3）。
                let mut meta = match schedule_frequency(&record.kind, record.every_seconds) {
                    Some((template, value)) => self.catalog.lf(template, &[value.to_string()]),
                    // `:371` 的 `L("一次性")`：**只有** `L()` 通道、无内联 en（#6）。
                    None => self.catalog.l("一次性"),
                };
                if let Some(at_ms) = *at {
                    meta.push_str(" · ");
                    meta.push_str(&schedule_local_stamp(at_ms, offset_secs));
                    let (head, tail, value) = schedule_relative(at_ms, now_ms);
                    // `LF("还剩 {0}", ScheduleMagnitudeLabel(left))`：两枚模板都是 `LF()` 单通道。
                    let magnitude = self.catalog.lf(tail, &[value.to_string()]);
                    meta.push_str(" · ");
                    meta.push_str(&self.catalog.lf(head, &[magnitude]));
                }
                let meta_row: View = TextBlock::new()
                    .text(meta)
                    // `:356-357`：`CaptionTextStyle` + `TextTertiaryBrush` 两件事一起给。
                    .font_size(type_ramp::CAPTION.size)
                    .foreground(p.text_tertiary.clone())
                    .text_wrapping(TextWrapping::Wrap)
                    .into();
                // 行容器（`:336`）：`StackPanel{Spacing=2}`，两行的加入序 = prompt → meta。
                let row: View = StackPanel::new()
                    .orientation(Orientation::Vertical)
                    .spacing(space::S2)
                    .children((prompt, meta_row))
                    .into();
                cells.push(KeyedView::new(format!("schedule-row-{index}"), row));
            }
        }
        let body: View = StackPanel::new()
            .orientation(Orientation::Vertical)
            .spacing(space::S10)
            .width(440.0)
            .keyed_children(cells)
            .into();
        // `:363`：`new ScrollViewer { Content = body, MaxHeight = 480 }`（与 goal 卡那一发同刻法：
        // 不写 `VerticalScrollBarVisibility` ⇒ 走控件默认 Auto）。
        let scroll: View = ScrollViewer::new().max_height(480.0).content(body).into();
        // 卡题的**可见行**：`:362` 把 `CapabilityText("计划（只读）","Schedules (read-only)")`
        // 交给 `CapabilityDialog` 的 `Title`（`:106-112`）⇒ 它上屏在标题区 = 滚动件**之外**、
        // 正文**之上**（口径同 goal 卡那一枚，缺陷 FA1-F-3 的教训：只塞 `automation_name` = 可见性零）。
        let title = self.catalog.bt("计划（只读）", "Schedules (read-only)");
        let title_row: View = TextBlock::new()
            .text(title.clone())
            .font_size(type_ramp::SUBTITLE.size)
            .font_weight(FontWeight::SEMI_BOLD)
            .text_wrapping(TextWrapping::Wrap)
            .into();
        // 关闭钮：`CP:110` 的统一 `CloseButtonText` ⇒ 本面板**唯一**那颗钮（spec §0 第 4 条：
        // 面板内按钮 0 颗，这颗是对话框自带的）。零 glyph、零 AutomationId（仓规：树内不许自造 id）。
        let close_label = self.catalog.bt("关闭", "Close");
        let close: View = Button::new()
            .min_width(0.0)
            .horizontal_alignment(HorizontalAlignment::Left)
            .automation_name(close_label.clone())
            .on_click(context.message(Msg::SchedulePanelClose))
            .content(TextBlock::new().text(close_label))
            .into();
        Border::new()
            .background(p.card.clone())
            .border_brush(p.stroke.clone())
            .border_thickness(size::STROKE)
            .corner_radius(radius::LARGE)
            .padding(th([16.0, 12.0, 16.0, 12.0]))
            .horizontal_alignment(HorizontalAlignment::Center)
            .vertical_alignment(VerticalAlignment::Center)
            // 卡题 = `CapabilityDialog(CapabilityText("计划（只读）","Schedules (read-only)"), …)`
            // （`:362`）：B 道，与上面那枚可见行共用同一现读值。
            .automation_name(title)
            .content(
                StackPanel::new()
                    .orientation(Orientation::Vertical)
                    .spacing(space::S12)
                    .children((title_row, scroll, close)),
            )
    }

    /// 真·整窗模态宿主（批 MD1）：三张应用级模态卡（#106 任务清单 / 批 M4 轨迹 /
    /// 批 M2c 目标）的**唯一**那一格。批 P155 起这格是**四张**共用（追加末位第四发 =
    /// 「计划（只读）」`schedules-panel`，`CP:363` 同族），下面那段 MD1 取证文案里的
    /// 「三张」按当时口径写、一字未改 ⇒ 计数类判据一律以第四发那条注释为准。
    /// 它们原先长在 `chat_page` 那台网格的**行 0**，而三个入口
    /// 却分布在行 1（composer 带里的 todos / 轨迹徽标）与右栏（dock chip）⇒ 入口在遮罩外、
    /// 照旧点得到 ⇒ 「两张模态卡同屏」那五格（L5×L6、L5×L7、L6×L7、L10×L6、L10×L7）就是这么来的。
    /// 挂到根网格（[`Shell::view`] 那一台）的末格之后，遮罩域 = 整窗，五格在指针路径上全不可达。
    ///
    /// 覆盖面（F-2 的静态证据，不靠跑起来看）：根网格只写 `.rows([Pixel(size::CAPTION_STRIP), STAR])`、
    /// **没有** `.columns(...)` ⇒ 隐式单列、宽度即窗宽；本宿主的根是
    /// `Grid::new().grid_row(0).grid_row_span(2).rows([GridLength::STAR])` ⇒ 行跨满那两行
    /// = 48px 顶条 + `body` 一整行，而 `body` 的三列（侧栏 / 内容 / 右栏 dock）全在行 1 之内
    /// ⇒ 三列一并盖住。行跨两颗的刻法先例 = [`Shell::turn_rail`]（`.grid_row(0).grid_row_span(2)`）。
    /// ⚠ 那颗被叫作「应用级」的 [`Shell::danger_confirm_card`] 实测只跨**列**不跨**行**
    /// （`.grid_column(0).grid_column_span(2)` 坐在 `body` 的第 1 行上，而 `body` 今天三列）
    /// ⇒ 它盖不到第 3 列与顶条，**不是**这一格的先例（本轮不动它，见报告 §续卡）。
    ///
    /// 遮罩抄谁（F-1：点外面**不关**）：显隐与遮罩都由各张 `*_layer` 自带，本宿主一颗都不新加。
    /// 那三枚 `scrim` 是「铺满 + `background(p.transparent)` + **不挂** `on_pointer_pressed`」，
    /// 同 [`Shell::danger_confirm_card`] 那一枚 = **`ContentDialog` 一族**（关闭只走
    /// `CloseButton` 那颗加 Esc；主干 `ShouldCloseOnOutsideClick` 一处没设 ⇒ 默认不关）；
    /// **不是** [`Shell::workspace_menu_layer`] / [`Shell::selector_layer`] 那一枚 =
    /// `MenuFlyout` 一族（挂 `on_pointer_pressed(..Close)` = light-dismiss，那三格 MG1 判「保持」）。
    /// 三张 layer fn 本轮一字未改 ⇒ 换整窗父格后它们的命中域自动跟着扩。
    ///
    /// 显隐同口径：reactor 没有 `Visibility` ⇒ 三格全空时这一棵节点根本不生成（返回 `None`，
    /// 与 [`Shell::goal_bar_view`] 同一刻法）；三张都随 `Msg::Nav(page)` 退役 ⇒ 提到根网格也
    /// 不会在设置页露出卡。
    ///
    /// ⚠ 反向互斥那 19 发（五臂各 3 发 + `DockMenuToggle` 1 + `TrajectoryPanelToggle` 1 +
    /// `GoalPanelToggle` 2，收的是「开 A 时把在场的模态卡收掉」）自本刀起在**指针路径上不可达**
    /// ⇒ **全留、删 0 处**：它们是键盘 / Esc / 退役路径与 UIA `Invoke`（绕过命中测试）那条通路上
    /// 的第二道保险，不是漏圈的后遗症。主干那条「同窗唯一 + throw」是类型级保证，分叉自绘层给不出，
    /// reducer 里的收点是唯一还能静态审的那一道 —— 两道都在 = 与主干「框架禁 + `_capabilityPanelOpen`」
    /// 双层同构。任何计数闸的期望常数一枚都不动。
    fn app_modal_host(&self, context: &mut ViewContext<Shell>, p: Palette) -> Option<View> {
        let mut cells: Vec<KeyedView> = Vec::new();
        // #106：主干 `TD:59-61` 的 `await dialog.ShowAsync()` = 应用级模态（层级高于壳内任何东西）。
        if self.todos_panel.is_some() {
            cells.push(KeyedView::new(
                "todos-panel",
                self.todos_panel_layer(context, p),
            ));
        }
        // 批 M4：`Traj:791` 同族第二张 ⇒ 与上一张共尾，序不变。
        if self.trajectory_panel.is_some() {
            cells.push(KeyedView::new(
                "trajectory-panel",
                self.trajectory_panel_layer(context, p),
            ));
        }
        // 批 M2c（#108 切片9 第二张）：`Capabilities.cs:291` 同族第三张（`MODAL_LEDGER` 里
        // `goal-panel` 早在册，本轮一张都不新登记）。
        if self.goal_panel.is_some() {
            cells.push(KeyedView::new("goal-panel", self.goal_panel_layer(context, p)));
        }
        // 批 P155（#155）：`CP:363` 同族第四张 ⇒ 追加在末位（简报 D-1 的宿主与格序）。
        // `MODAL_LEDGER` 里这张卡**早在册**（表里那一行在 `code_only` 之后 1 命中 ⇒ PS1 复核：
        // 本行原先把那枚锚针**裸写**在注释里，于是 `grep -cF` 量出来是 2 = 表 + 本注释，
        // 与 spec §6.3 的「全文件 1 命中」对不上 ⇒ 按 MS1 §M-2 同一条坑改写，锚不再自引用）
        // ⇒ 本轮一行都不登记、五个计数一个都不动（D-11）。
        if self.schedule_panel.is_some() {
            cells.push(KeyedView::new(
                "schedule-panel",
                self.schedule_panel_layer(context, p),
            ));
        }
        // 批 ERR1（#157）：错误弹层 = 本宿主的**第五格**（末位 ⇒ 压过前面四张与整棵 `body`）。
        // 槽位键与 `MODAL_LEDGER` 那行的 card 值**同名**（白送一致，故台账一行都不新登记）。
        // ⚠ 本行注释**不**把那枚带引号的针写全：PS1 在同一格里踩过自计数（`tmp/ps1-report.md`
        //   §2 的「表 + 本注释 = 2 命中」），针一律只在下面那把尺里以拆词形出现。
        if self.error_dialog.is_some() {
            cells.push(KeyedView::new(
                "error-dialog",
                self.error_dialog_layer(context, p),
            ));
        }
        // 批 SFB1（#158 卡 B）：会话反馈那张 = 本宿主的**第六格**（简报 C-1：宿主与格序都跟族 D
        // 先例，末位 ⇒ 压过前面五张与整棵 `body`）。槽位键与 `MODAL_LEDGER` 的登记口径**本卡一枚
        // 都不新登记**（简报 C-6：那张表 33/13/13/9/11 四个数不动）⇒ 台账那一行的缺挂登记在报告 §5。
        if self.session_feedback.is_some() {
            cells.push(KeyedView::new(
                "session-feedback",
                self.session_feedback_layer(context, p),
            ));
        }
        // 批 SKP1（#158 卡 A）：技能选择器那张 = 本宿主的**第七格**（末位 ⇒ 压过前面六张与整棵
        // `body`，形制逐字同上面那两格）。`MODAL_LEDGER` 里这张卡**早在册**（`CP:402` 那一行）⇒
        // 台账一行都不新登记、四个计数一个都不动（口径同上面 P155 / SFB1 那两段的自计数备案：
        // 那一行的 card 值只在下面那把尺里以拆词形出现，本注释不写全）。
        if self.skill_picker.is_some() {
            cells.push(KeyedView::new("skill-picker", self.skill_picker_layer(context, p)));
        }
        // 批 CD1（#158 面 B/C）：Cordis 面板那张 = 本宿主的**第八格**（末位 ⇒ 压过前面七张与整棵
        // `body`，形制逐字同上面那两格；主干那颗同样是 `XamlRoot = Content.XamlRoot` 的应用级模态
        // `CD:657` + `CP:111`）。`MODAL_LEDGER` 里这张卡**早在册**（`CD:661` 那一行）⇒ 台账一行都
        // 不新登记、四个计数一个都不动（自计数备案口径同上面 P155 / SFB1 / SKP1 那三段：那一行的
        // card 值只在下面那把尺里以拆词形出现，本注释不写全）。
        if self.cordis_panel.is_some() {
            cells.push(KeyedView::new(
                "cordis-panel",
                self.cordis_panel_layer(context, p),
            ));
        }
        if cells.is_empty() {
            return None;
        }
        Some(
            Grid::new()
                .grid_row(0)
                .grid_row_span(2)
                .rows([GridLength::STAR])
                .keyed_children(cells),
        )
    }

    /// 批 ERR1（#157）：错误弹层那一格 = 主干 `MW:13822` 的 `ShowErrorAsync` 的分叉等价物。
    /// 遮罩抄 [`Shell::schedule_panel_layer`] / [`Shell::danger_confirm_card`] 那一族 =
    /// **`ContentDialog` 一族**：铺满 + `background(p.transparent)` + **不挂** `on_pointer_pressed`
    /// ⇒ 点卡外既不关也不穿透（主干 `ShouldCloseOnOutsideClick` 一处都没设 ⇒ 默认不关）。
    /// **不抄** [`Shell::workspace_menu_layer`] / [`Shell::selector_layer`] 那两族的 light-dismiss
    /// （那是 `MenuFlyout` 替身，点外面即关；主干这颗不是 flyout ⇒ 抄它 = 凭空造主干没有的行为）。
    /// 挂位 = [`Shell::app_modal_host`] 的**第五格**（不是 `chat_page`，也不是 `body`）。
    fn error_dialog_layer(&self, context: &mut ViewContext<Shell>, p: Palette) -> View {
        let scrim: View = Border::new()
            .grid_row(0)
            .horizontal_alignment(HorizontalAlignment::Stretch)
            .vertical_alignment(VerticalAlignment::Stretch)
            .background(p.transparent.clone())
            .into();
        Grid::new()
            .rows([GridLength::STAR])
            .children((scrim, self.error_dialog_card(context, p)))
    }

    /// 主干那颗卡的**全部**字段（`MW:13825-13832` 的 `new ContentDialog { … }`），逐枚照抄、
    /// 一枚都不多：
    /// * `Title` = Blade² 那枚**硬字面量**、**不过** `L()` / `l()` / `bt()` ⇒ 中英界面同一个标题
    ///   （主干那颗是全仓唯一一颗标题不进字典的模态 ⇒ 分叉跟着不进字典，走表反而是偏离）；
    /// * `Content` = 那一格里存的**裸串**（主干唯一一颗正文是纯串的模态：不是 ScrollViewer、
    ///   不是对象图 ⇒ 分叉这里也不套滚动件、不加「查看详情」、不加复制钮、不加自动关闭）；
    /// * `CloseButtonText` = 「确定」那枚**硬字面量**（同样不过表，全仓独一份的写法）；
    /// * **不写** `DefaultButton`、**没有** `PrimaryButtonText`、**没有** `Timeout` ⇒ 台账那一行
    ///   记的 `enter: ModalResult::None` 就是这一档（Enter 不提交、卡不会自己关）。
    /// 卡体**一个尺寸都不设**：主干那颗也只给上面那四枚字段，宽高全是 `ContentDialog` 的默认档
    /// ⇒ 分叉不自造 440/548 那种别张卡的数（长文案的溢出代价进报告 §5，需真机）。
    fn error_dialog_card(&self, context: &mut ViewContext<Shell>, p: Palette) -> View {
        // 正文 = 那一格里存的那句话本身。`None` 时本 fn 压根不被叫到（宿主那一发有 `is_some` 闸），
        // 这里仍走 `unwrap_or_default`：不许 panic，分叉的渲染路径炸一次就是整窗没脸。
        let message = self.error_dialog.clone().unwrap_or_default();
        // 标题两通道同值：可见行 + 卡根的 UIA Name（主干 `ContentDialog.Title` 由标题模板渲染成
        // TextBlock，UIA 那侧读到的就是同一串 ⇒ 口径同那四张能力面板的 `automation_name(title)`）。
        let title = "Blade²";
        let title_row: View = TextBlock::new()
            .text(title)
            .font_size(type_ramp::SUBTITLE.size)
            .font_weight(FontWeight::SEMI_BOLD)
            .text_wrapping(TextWrapping::Wrap)
            .into();
        // `Wrap` 是分叉自绘层唯一的表达手段（主干那枚裸串由 `ContentPresenter` 承载、宽度天然受
        // 对话框钳制）；**不开** `is_text_selection_enabled` ⇒ 与主干那颗「正文不可选」同档。
        let body: View = TextBlock::new()
            .text(message)
            .font_size(type_ramp::BODY.size)
            .text_wrapping(TextWrapping::Wrap)
            .into();
        // 关闭钮 = `CloseButtonText` 那一颗 ⇒ 本卡**唯一**的控件。零 glyph、零自造 AutomationId
        // （仓规：树内不许自造 id；主干那颗也没有）。
        let close_label = "确定";
        let close: View = Button::new()
            .min_width(0.0)
            .horizontal_alignment(HorizontalAlignment::Left)
            .automation_name(close_label)
            .on_click(context.message(Msg::ErrorDialogClose))
            .content(TextBlock::new().text(close_label))
            .into();
        Border::new()
            .background(p.card.clone())
            .border_brush(p.stroke.clone())
            .border_thickness(size::STROKE)
            .corner_radius(radius::LARGE)
            .padding(th([16.0, 12.0, 16.0, 12.0]))
            .horizontal_alignment(HorizontalAlignment::Center)
            .vertical_alignment(VerticalAlignment::Center)
            .automation_name(title)
            .content(
                StackPanel::new()
                    .orientation(Orientation::Vertical)
                    .spacing(space::S12)
                    .children((title_row, body, close)),
            )
    }

    fn body(&self, context: &mut ViewContext<Shell>, p: Palette, row: i32) -> View {
        let on_chat = self.page == Page::Chat;
        // #140 刀1：主干那两页都长在 `ContentSurface` 上，皮肤层是它的 Background（`xaml.cs:8863-8881`）；
        // 分叉的等值物 = 把 Image 层压成两页**底下的一格**（表达形态不同 ⇒ 见报告 §1 备案）。
        // 唯一入树判据是 `self.skin_path`，与 `Msg::SkinClear` 清的是**同一格**，不留第二份真相。
        let pages = self.either(
            on_chat,
            ("page-chat", self.chat_page(context, p)),
            ("page-settings", self.settings_page(context, p)),
        );
        let surface: View = match self.mw2_skin_backdrop() {
            Some(backdrop) => Grid::new().children((backdrop, pages)).into(),
            None => pages,
        };
        let mut cells: Vec<KeyedView> = vec![
            KeyedView::new(
                "pane",
                Border::new().grid_column(0).content(self.nav(context, p)),
            ),
            KeyedView::new(
                "content",
                Border::new()
                    .grid_column(1)
                    .background(p.surface_alt)
                    .content(surface),
            ),
        ];
        // #138 K2-②：右栏宿主格。可见位读 [`dock::Dock::open`]（原来那颗恒 `false` 的
        // `right_host_visible` 已删 —— 母本 §5#4 点名的「第二份真相」就是它）。
        // 双闸 `on_chat && open`：主干那颗宿主长在 ChatPage 里（`MX:1356 Grid.Column="1"`），
        // 切到设置页它整棵不在场 ⇒ 分叉第三列同口径收起，否则设置页白多一列。
        let host_visible = self.dock.open && on_chat;
        // 两条把手挂在 keyed_children 的**末位**：框架没有 `Canvas.ZIndex`，只能靠文档序压上去
        // （`turn_rail` 已是这套；主干 `InstallColumnSplitters` 用的是 `Canvas.SetZIndex(_, 20)`）。
        // 可见性一律问 [`layout::sync_layout`]，**不在这里自己判**「有没有右栏」——
        // 首参 = 主干 `Nav.IsPaneOpen`，分叉的 pane 没有折叠档（没有 pane-toggle 入口），恒 true；
        // 第三参今天写死 `false` 的那一发（母本 K2-⑧）换成读 `self.dock.fullscreen`。
        let colsync = layout::sync_layout(true, host_visible, self.dock.fullscreen, self.rightbar_pref);
        if host_visible {
            cells.push(KeyedView::new("right-dock", self.dock_host(context, p)));
        }
        if colsync.sidebar_splitter_visible {
            cells.push(KeyedView::new(
                "splitter-sidebar",
                self.column_splitter(context, p, layout::SplitterEdge::Sidebar),
            ));
        }
        if colsync.rightbar_splitter_visible {
            cells.push(KeyedView::new(
                "splitter-right",
                self.column_splitter(context, p, layout::SplitterEdge::Rightbar),
            ));
        }
        // #138 K3-①：chip 右键那张菜单是浮层 ⇒ 压在宿主与两条把手之上。它**不进** `chat_page()`
        // 的入树序（那扇窗被六把锁共用，母本 §3 L-5/L-7 的雷区），挂在这一层的文档序里同效：
        // 主干那颗是系统级 `MenuFlyout`，压过壳内一切，但压不过应用级模态 `ContentDialog`
        // ⇒ 排在 `permission-confirm` **之前**，那张危险档确认卡仍然在最上面。
        if self.dock_menu.is_some() {
            cells.push(KeyedView::new("dock-menu", self.dock_tab_menu_layer(context, p)));
        }
        // #56 第二颗的危险档确认卡：最后一格 ⇒ 它压过两条把手与两页正文。
        // 为什么宿主在 `body` 而不是 `chat_page` 那几层里：主干那颗是
        // `ContentDialog` + `XamlRoot = Content.XamlRoot`（`PC:80`）= **应用级模态**，而分叉这张卡
        // 的两个入口分别长在**两页**上（聊天页 composer 那颗 `PermissionButton`、设置页那颗
        // `Setting_permission_defaultPreset` 下拉）⇒ 挂进任何一页都会让另一页「弹了一张看不见
        // 的卡」，那一格再也写不进去（自锁）。故那一格里既没有这颗键、也不该有。
        if self.permission_confirm.is_some() {
            cells.push(KeyedView::new(
                "permission-confirm",
                self.danger_confirm_card(context, p),
            ));
        }
        // 族 A **第二发**那张卡（`reset_confirm`，本刀 B-1a）：**同一档挂位**（`body` 末位、跨两列、
        // 同一枚透明遮罩），卡体与上面那张共吃 [`Shell::confirm_card`] ⇒ 渲染侧新代码 0 行
        // （SL1 案甲′）。排在 `permission-confirm` **之后** = 入树序，与上面 reducer 里键盘三档的
        // 问序逐字同序。
        // ⚠ 本刀**没有**开格那一发（`Msg::ResetSection` 与逐 ns 的 `settings/replace` 属 B-1b，
        // 零 RPC 是本刀边界）⇒ 这一格今天恒 `None`、那一棵节点今天根本不生成（不开时不入树 =
        // 与上面八格同一口径）。挂位与互斥先落齐，B-1b 才只需要加「点钮 → 建格」那一发。
        if self.reset_confirm.is_some() {
            cells.push(KeyedView::new(
                "reset-confirm",
                self.reset_confirm_card(context, p),
            ));
        }
        // 第三列的宽度：全屏那档主干写的是 `RightPaneHost.Width = double.NaN` + `Stretch`
        // （`LC:588`）⇒ 分叉的等价刻法 = 「自己那一列收成 0，宿主跨到第 0 列去」（跨列数由
        // [`dock::Dock::host_column_span`] 给，见 [`Shell::dock_host`]）；常态读
        // [`layout::current_rightbar_width`]（主干 `CurrentRightbarWidth()`，`300..vw*0.7` 的
        // clamp 口径归 #90 那侧管），**不在这里再算第二遍**。
        let dock_col_w = if !host_visible || self.dock.fullscreen {
            0.0
        } else {
            layout::current_rightbar_width(self.rightbar_pref, self.viewport_dip())
        };
        Grid::new()
            .grid_row(row)
            .columns([GridLength::Pixel(self.sidebar_w), GridLength::STAR, GridLength::Pixel(dock_col_w)])
            .keyed_children(cells)
    }

    /// #90 一条**完全透明**的列宽把手（主干 `MakeColumnSplitter:145-192`）。
    ///
    /// 「零可见墨迹」是验收口径而不是偷懒：主干那一条就是
    /// `Border { Background=Transparent, Width=SplitterHitWidth, Margin=(-4,0,0,0),
    /// VerticalAlignment=Stretch }` + 四个指针事件，**没有**分隔线、**没有** hover/pressed
    /// 反馈（规格 §1.5 要求 rest/hover/pressed 三张截图逐像素相同）。
    /// 所以这里刻意**只**挂 4 个事件（按下 / 移动 / 抬手 / 失去捕获），
    /// 一个 `on_pointer_entered` / `on_pointer_exited` 都不挂 —— 挂了就得画点啥，那已经是错。
    ///
    /// 命中宽 = [`layout::SPLITTER_HIT_WIDTH`]（8 DIP ⇒ 200% 缩放下 UIA 16 px），
    /// 骑在列边界上靠 `-4` 的负 margin（主干 `:111`/`:125` 的 `-SplitterHitWidth/2.0`）。
    fn column_splitter(
        &self,
        context: &mut ViewContext<Shell>,
        p: Palette,
        edge: layout::SplitterEdge,
    ) -> View {
        // 主干两条把手的差别只有**方向**与**骑在边界的哪一侧**（`:104-116` vs `:118-130`）。
        let (label, overlap_margin, alignment) = if edge == layout::SplitterEdge::Rightbar {
            (
                "调整右栏宽度",
                [0.0, 0.0, layout::SPLITTER_EDGE_OVERLAP, 0.0],
                HorizontalAlignment::Right,
            )
        } else {
            (
                "调整侧栏宽度",
                [layout::SPLITTER_EDGE_OVERLAP, 0.0, 0.0, 0.0],
                HorizontalAlignment::Left,
            )
        };
        Border::new()
            .grid_column(1)
            .width(layout::SPLITTER_HIT_WIDTH)
            .horizontal_alignment(alignment)
            .vertical_alignment(VerticalAlignment::Stretch)
            .background(p.transparent)
            .margin(th(overlap_margin))
            .automation_id(edge.automation_id())
            .automation_name(self.catalog.l(label))
            // 主干 `:156` 的 `CapturePointer`，reactor 把它做成按下时的声明式开关。
            // 少了它，指针一滑出这 8 DIP 就再也收不到 Moved —— 把手拖不动的第一成因。
            .capture_pointer_on_press(Some(true))
            .on_pointer_pressed(context.callback(move |info: PointerEventInfo| {
                Msg::SplitDragStart(edge, info.is_left_button_pressed, info.window_x)
            }))
            .on_pointer_moved(context.callback(move |info: PointerEventInfo| {
                Msg::SplitDrag(info.window_x)
            }))
            .on_pointer_released(context.callback(|_| Msg::SplitDragEnd))
            .on_pointer_capture_lost(context.callback(|_| Msg::SplitDragEnd))
            .into()
    }

    /// #90 视口宽（DIP）。主干 `ApplyRightbarWidth:216-220` 读的是三颗 `ActualWidth`，
    /// 分叉**零出口**（reactor 没有 `SizeChanged`、也没有 `ActualWidth`）⇒ 只能按客户区记账，
    /// 再把四个数喂 [`layout::rightbar_viewport`]（口径同 `chat_box_of`，见 `ly1-report` §D）。
    /// 问不到窗口时给 0；主干那条算式本来就带 `max(0, …)`，量不到只会走它的回落支路。
    fn viewport_dip(&self) -> f64 {
        let dpi = scroll::client_origin().map_or(0, |(_, dpi)| dpi);
        let root = scroll::px_to_dip(scroll::client_size().map_or(0, |(w, _)| w).max(0), dpi).max(0.0);
        let chatpage = (root - self.sidebar_w).max(0.0);
        layout::rightbar_viewport(&layout::ViewportProbe {
            chatpage_width: chatpage,
            right_host_visible: self.dock.open,
            rightbar_width: layout::current_rightbar_width(self.rightbar_pref, chatpage),
            root_width: root,
            open_pane_length: self.sidebar_w,
        })
    }

    // ---- #138 右栏 dock 的渲染层（K2–K4）------------------------------------------------
    //
    // 主干对照全在 `MainWindow.LayoutColumns.cs`（下称 `LC`）+ `MainWindow.xaml`（`MX`）：
    // 宿主 `MX:1356-1362` / `_rightDockRoot` `LC:335-368` / 条带 `RebuildRightTabStrip:417-473`
    // / 尾部两颗 `MakeDockIconButton:399-415` / 分栏体 `RebuildRightDockBody:781-853`
    // / 内层把手 `WireInnerSplitDrag:855-905` / chip 菜单 `ShowRightTabMenu:475-549`。
    // 三条例子在整块里都不许破：
    // ① UIA id 一律取自 [`dock::chrome`]（DP3 §1.4 那 19 枚的名册），本文件不手打第二份；
    // ② `chrome::PANE1_PANEL`（`FilesPanelPane1`）**在册不入树** —— 那颗型是 #76 的面板本体，
    //    K1–K4 只搭壳（DP3 §1.7 红线 2），本块一次都不引用它；
    // ③ 格子里的面板本体（文件树 / 预览）同样是 #76 的，这里只放主干那颗 header 关闭钮
    //    （`Pages/FilesPanel.xaml:94-102` → `FilesPanel.xaml.cs:515` 的 `CloseRequested`）——
    //    它是 dock 那两发「关闭」的唯一入口；#76 落地时由它的整条 header 取代（同 id 同 Name
    //    同发），不会撞车。

    /// 主干 `MW:17341-17344` 与 `LC:600-603` 那**同一条**懒初始化：开栏且宽度偏好还没落地时
    /// 补一颗 `max(RightbarMinWidth, CurrentRightbarWidth())` 种子。
    /// 判据本体在 [`dock::Dock::rightbar_seed`]，这里只喂它现算的当前宽 —— 与 #90 的口径一致：
    /// **只改内存里的偏好**，落盘仍旧只在松手那一发（`MW:17341` 那支也没落盘）。
    fn seed_rightbar_width(&mut self, open: bool) {
        let current = layout::current_rightbar_width(self.rightbar_pref, self.viewport_dip());
        if let Some(seed) = dock::Dock::rightbar_seed(open, self.rightbar_pref, current) {
            self.rightbar_pref = seed;
        }
    }

    /// 主干 `OnRightPaneAddTab:560-577`：新标签落进当前格、置 active、尾部自带开栏
    /// （`LC:576` 那一发在 [`dock::Dock::add_tab`] 里）。尾部 `RightPaneAddTab`（`LC:355`）与
    /// 菜单 `RightPaneNewTab`（`LC:516`）在主干就是**同一个 handler** ⇒ 分叉也只有这一个体。
    fn dock_add_tab(&mut self) {
        let catalog = &self.catalog;
        self.dock
            .add_tab(|number| catalog.lf("文件 {0}", &[number.to_string()]));
        self.seed_rightbar_width(self.dock.open);
        dock_menu_close(&mut self.dock_menu);
    }

    /// 主干 `SplitRightPane:616-641`。**权威侧**判据（[`dock::Dock::can_split`] →
    /// `layout::right_dock_can_split_into`，含官方 `dockPaneIds.length >= 2` 那一发短路）
    /// 不成立时 [`dock::Dock::split`] 自己早退，这里不重写第二份。
    fn dock_split(&mut self, mode: layout::RightSplitMode) {
        let catalog = &self.catalog;
        self.dock
            .split(mode, |number| catalog.lf("文件 {0}", &[number.to_string()]));
        dock_menu_close(&mut self.dock_menu);
    }

    /// 分叉没有 `ActualWidth` / `SizeChanged`（#90 的同一处硬缺口）⇒ 内层把手的 extent 只能按
    /// 客户区记账现算：横向 = 分栏体所在列的宽（全屏那档 = 聊天列整幅），纵向 = 客户区高 DIP。
    /// 量不到就是 0 —— [`layout::right_inner_ratio_from_drag`] 对 `extent <= 0` 的原样返回 base
    /// **是正确行为不是 fallback**（见 `Msg::DockInnerDrag` 那一臂）。
    fn dock_inner_extent(&self, axis: layout::RightSplitMode) -> f64 {
        let dpi = scroll::client_origin().map_or(0, |(_, dpi)| dpi);
        let (w_px, h_px) = scroll::client_size().map_or((0, 0), |(w, h)| (w, h));
        match axis {
            layout::RightSplitMode::Horizontal => {
                if self.dock.fullscreen {
                    (scroll::px_to_dip(w_px.max(0), dpi).max(0.0) - self.sidebar_w).max(0.0)
                } else {
                    layout::current_rightbar_width(self.rightbar_pref, self.viewport_dip())
                }
            }
            layout::RightSplitMode::Vertical => scroll::px_to_dip(h_px.max(0), dpi).max(0.0),
            layout::RightSplitMode::None => 0.0,
        }
    }

    /// 主干 `RightPaneHost`（`MX:1356`）+ `_rightDockRoot`（`LC:335-341` 那两行 row 定义）。
    /// 全屏那档 = `LC:585-588` 的 `SetColumn(0) + SetColumnSpan(2) + Width=NaN + Stretch`，
    /// 分叉的等价刻法是「第三列宽收成 0（见 `body()` 的 `dock_col_w`）+ 宿主从聊天列起跨两列」。
    fn dock_host(&self, context: &mut ViewContext<Shell>, p: Palette) -> View {
        let (column, span) = self.dock.host_column_span();
        Grid::new()
            // 主干那两个下标是 ChatPage 那侧的局部值（0=聊天列 / 1=宿主列），分叉 `body()` 的第 0
            // 列是侧栏 ⇒ 整段右移一格、跨列数不动。侧栏在全屏档依旧在场（主干它就不在 ChatPage 里）。
            .grid_column(column + 1)
            .grid_column_span(span)
            .rows([GridLength::Auto, GridLength::STAR])
            .automation_id(dock::chrome::HOST)
            .children((
                self.dock_tab_strip(context, p),
                self.dock_body(context, p),
            ))
    }

    /// 主干 `_rightTabStrip`（`LC:342-350`）+ 尾部 chrome（`LC:353-360`）+
    /// `RebuildRightTabStrip:417-473` 每回重建出来的那批 chip（`:427` 的 `foreach` 不排序、
    /// 不分格 ⇒ 两格的标签同排铺）。
    fn dock_tab_strip(&self, context: &mut ViewContext<Shell>, p: Palette) -> View {
        let mut cells: Vec<KeyedView> = Vec::new();
        for tab in self.dock.visible_tabs() {
            cells.push(KeyedView::new(
                format!("chip-{}", tab.id),
                self.dock_tab_chip(tab, context, p),
            ));
        }
        // 尾部两颗（主干把 chrome 放在 chip **之后**，`LC:353-360` + `:454-457` 重建时保留末两子级）。
        let exit = self.dock.fullscreen_label_is_exit();
        let fullscreen_label = if exit { "退出全屏" } else { "全屏" };
        let tail: View = StackPanel::new()
            .grid_row(0)
            .orientation(Orientation::Horizontal)
            .spacing(2.0)
            .keyed_children(vec![
                KeyedView::new(
                    "dock-add-tab",
                    self.dock_tail_button('\u{E710}', dock::chrome::ADD_TAB, "新标签页", Msg::DockAddTab, context, p),
                ),
                KeyedView::new(
                    "dock-fullscreen",
                    self.dock_tail_button(
                        self.dock.fullscreen_glyph(),
                        dock::chrome::FULLSCREEN,
                        fullscreen_label,
                        Msg::DockToggleFullscreen,
                        context,
                        p,
                    ),
                ),
            ]);
        cells.push(KeyedView::new("tail", tail));
        // 主干把 `Padding=6,4,6,0` 直接写在条带那颗 StackPanel 上（`LC:347`）；reactor 的
        // `padding` 不在这颗面板的货架上 ⇒ 外面套一层不画东西的 Border 承这点内边距
        // （UIA id 仍旧挂在面板本体上，包层不是控件、不新增控件节点）。
        let strip: View = StackPanel::new()
            .orientation(Orientation::Horizontal)
            .spacing(2.0)
            .automation_id(dock::chrome::TAB_STRIP)
            .automation_name(self.catalog.l("右栏标签栏"))
            .keyed_children(cells);
        Border::new()
            .grid_row(0)
            .padding(th([6.0, 4.0, 6.0, 0.0]))
            .content(strip)
    }

    /// 尾部那两颗 `MakeDockIconButton:399-415`：`Button{Content=FontIcon(Glyph, FontSize=12),
    /// Width=Height=28, MinWidth=0, Padding=0, CornerRadius=14, Background=Transparent}`，
    /// `Aut(id, name)` + `ToolTip = name` + `Click`。裸 Button 在分叉渲不成那个尺寸/圆角
    /// （#29/#33 定案）⇒ 整颗走 `pill_button`；`radius::PILL(24)` 在 28 的边上夹到短边一半
    /// = 14，正是主干写在实例上那颗数。
    fn dock_tail_button(
        &self,
        code: char,
        id: &str,
        label: &str,
        message: Msg,
        context: &mut ViewContext<Shell>,
        p: Palette,
    ) -> View {
        let label = self.catalog.l(label);
        pill_button(
            Button::new()
                .grid_row(0)
                .vertical_alignment(VerticalAlignment::Center)
                .automation_id(id.to_string())
                .automation_name(label.clone())
                .on_click(context.message(message)),
            mark_size(code, size::GLYPH_CAPTION),
            Pill {
                side: size::COMPOSER_ADD_BUTTON,
                radius: radius::PILL,
                ..Pill::ghost(p)
            },
            id,
            HoverSlot::Pill,
            self.pill_hover.as_deref(),
            self.pressed.as_deref(),
            context,
        )
        .tooltip(label)
    }

    /// 主干 `RebuildRightTabStrip:427-449` 那枚 chip：`Button{MinWidth=0, MaxWidth=140,
    /// Padding=10,4,10,4, Margin=0,0,2,0, FontSize=12, CornerRadius=6,
    /// Background=active?CardBrush:Transparent, BorderBrush=active?AccentBrush:StrokeSubtleBrush,
    /// BorderThickness=1, HorizontalContentAlignment=Left}` + `Aut($"RightPaneTab:{id}", Title)`。
    /// 事件两发：`Click → ActivateRightTab`（`:445`）与 `RightTapped → ShowRightTabMenu`（`:446-449`）。
    /// reactor 的指针事件只挂在 `Border` 上（`generated.rs` 里 `on_pointer_pressed` 的唯一宿主），
    /// `RightTapped` 整族都没有 ⇒ 外面套一层不画任何东西的 Border 收右键；左键那一发补
    /// [`Msg::DockMenuClose`]，等价于主干原生 flyout 的 light-dismiss（点外部即关）。
    fn dock_tab_chip(
        &self,
        tab: &dock::DockTab,
        context: &mut ViewContext<Shell>,
        p: Palette,
    ) -> View {
        let active = self.dock.is_active(&tab.id);
        let menu = Msg::DockMenuToggle(tab.id.clone());
        // 主干那枚 chip 是**一颗** Button，圆角/描边/底色都写在它实例上。reactor 的
        // `corner_radius` / `background` / `border_brush` 是 slot 级属性，`Button` 没有那些槽
        // （只有 `Border` 一类有，实测 E0599）⇒ 分叉等价刻法 = 外面那层 Border 画主干写在钮上的
        // 那张脸（圆角 6 / active 才有的 CardBrush 底 + Accent 描边），钮本体走 `button_ghost`
        // 把模板四态钉透明（#29 定案配方），只留命中与文本。
        // UIA id/Name 仍旧挂在**钮**上 —— 主干 `Aut(chip, …)`（`:444`）的那颗就是它。
        let chip: View = Button::new()
            .min_width(0.0)
            .max_width(140.0)
            .horizontal_content_alignment(HorizontalAlignment::Left)
            // 主干 `Padding=10,4,10,4`（`:433`）写在 Button 实例上；reactor 的 Button 没有
            // `padding` 槽 ⇒ 走模板资源键 `ButtonPadding`（分叉既有解法，见 `todos_entry_cell`）。
            .resource_overrides(
                button_ghost(None).set("ButtonPadding", th([10.0, 4.0, 10.0, 4.0])),
            )
            .vertical_alignment(VerticalAlignment::Center)
            .automation_id(format!(
                "{}{}",
                dock::chrome::TAB_PREFIX,
                tab.id
            ))
            .automation_name(tab.title.clone())
            .on_click(context.message(Msg::DockActivate(tab.id.clone())))
            .content(
                TextBlock::new()
                    .text(tab.title.clone())
                    .font_size(type_ramp::CAPTION.size)
                    .text_wrapping(TextWrapping::NoWrap)
                    .vertical_alignment(VerticalAlignment::Center),
            );
        Border::new()
            .grid_row(0)
            .margin(th([0.0, 0.0, 2.0, 0.0]))
            .corner_radius(6.0)
            .background(if active { p.card.clone() } else { p.transparent.clone() })
            .border_brush(if active { p.accent.clone() } else { p.stroke_subtle.clone() })
            .border_thickness(size::STROKE)
            .vertical_alignment(VerticalAlignment::Center)
            .on_pointer_pressed(context.callback(move |info: PointerEventInfo| {
                if info.is_right_button_pressed {
                    menu.clone()
                } else {
                    Msg::DockMenuClose
                }
            }))
            .content(chip)
    }

    /// 主干 `_rightDockBody`（`LC:362-365`）+ `RebuildRightDockBody:781-853`。
    /// 不分栏那档**只**铺 0 号格（`:791-798`，连 ColumnDefinitions 都不建）；分栏那档才
    /// `[ratio*, Auto, (1-ratio)*]` 三列或三行（`:815-817` / `:841-843`），把手恒在中间那一格。
    fn dock_body(&self, context: &mut ViewContext<Shell>, p: Palette) -> View {
        let mode = self.dock.mode;
        let cells: Vec<KeyedView> = if mode == layout::RightSplitMode::None {
            vec![KeyedView::new(
                "cell0",
                self.dock_pane_cell(dock::FIRST_PANE, 0, mode, context, p),
            )]
        } else {
            vec![
                KeyedView::new(
                    "cell0",
                    self.dock_pane_cell(dock::FIRST_PANE, 0, mode, context, p),
                ),
                KeyedView::new("inner-splitter", self.dock_inner_splitter(1, mode, context, p)),
                KeyedView::new(
                    "cell1",
                    self.dock_pane_cell(dock::SECOND_PANE, 2, mode, context, p),
                ),
            ]
        };
        let (first, second) = self.dock.inner_ratio_pair();
        let grid = Grid::new()
            .grid_row(1)
            .automation_id(dock::chrome::DOCK_BODY)
            .automation_name(self.catalog.l("右栏分栏宿主"));
        match mode {
            layout::RightSplitMode::Horizontal => grid
                .columns([
                    GridLength::Star(first),
                    GridLength::Auto,
                    GridLength::Star(second),
                ])
                .keyed_children(cells),
            layout::RightSplitMode::Vertical => grid
                .rows([
                    GridLength::Star(first),
                    GridLength::Auto,
                    GridLength::Star(second),
                ])
                .keyed_children(cells),
            layout::RightSplitMode::None => grid.keyed_children(cells),
        }
    }

    /// 两格共用的壳（主干 `_rightPane0Host` / `_rightPane1Host` 那两颗 `ContentControl`，
    /// `LC:375-381` / `LC:757-764`：`Horizontal/VerticalContentAlignment=Stretch` +
    /// `Aut("RightPaneCell0" | "RightPaneCell1", L("右栏第一格" | "右栏第二格"))`）。
    /// 里面**只有** header 那颗关闭钮：面板本体是 #76 的（见本块头上那条红线 ③）。
    /// 两枚格在主干各有自己的 `CloseRequested` 订阅，且**语义不同**：
    /// 0 号格 → `MW:2684` `SetFilesPanelOpen(false)`（收起宿主）= [`Msg::DockPanelToggle`]；
    /// 1 号格 → `LC:740-755`（只取消分栏）= [`Msg::DockClosePane1`]。
    fn dock_pane_cell(
        &self,
        pane: u8,
        slot: i32,
        axis: layout::RightSplitMode,
        context: &mut ViewContext<Shell>,
        p: Palette,
    ) -> View {
        let second = pane == dock::SECOND_PANE;
        let (id, label, message) = if second {
            (dock::chrome::CELL1, "右栏第二格", Msg::DockClosePane1)
        } else {
            (dock::chrome::CELL0, "右栏第一格", Msg::DockPanelToggle)
        };
        let shell = Border::new()
            .horizontal_alignment(HorizontalAlignment::Stretch)
            .vertical_alignment(VerticalAlignment::Stretch);
        let shell = if axis == layout::RightSplitMode::Vertical {
            shell.grid_row(slot)
        } else {
            shell.grid_column(slot)
        };
        let close: View = pill_button(
            Button::new()
                .automation_id("FilesPanelCloseButton")
                .automation_name(self.catalog.l("关闭文件面板"))
                .on_click(context.message(message)),
            mark_size(glyph::CLOSE, size::GLYPH_BODY),
            Pill::ghost(p),
            if second { "dock-close-1" } else { "dock-close-0" },
            HoverSlot::Pill,
            self.pill_hover.as_deref(),
            self.pressed.as_deref(),
            context,
        )
        .tooltip(self.catalog.l("关闭文件面板"));
        let content_slot: View = Border::new().grid_row(1).into();
        shell
            .automation_id(id.to_string())
            .automation_name(self.catalog.l(label))
            .content(
                Grid::new()
                    .rows([GridLength::Auto, GridLength::STAR])
                    .children((
                        StackPanel::new()
                            .grid_row(0)
                            .orientation(Orientation::Horizontal)
                            .horizontal_alignment(HorizontalAlignment::Right)
                            .keyed_children(vec![KeyedView::new(
                                format!("dock-close-{pane}"),
                                close,
                            )]),
                        // 下面那一整格是 #76 的面板槽：没有内容就是**不画**（分叉口径「不在树里 =
                        // 不可见」，不给它挂第二颗 Name/id 冒充面板）。
                        content_slot,
                    )),
            )
    }

    /// 主干 `WireInnerSplitDrag:855-905` 挂在把手上的那三发（**只有三发**）：
    /// `PointerPressed`（`:860-871`，唯一守卫是「只认左键」+ `CapturePointer`）、
    /// `PointerMoved`（`:872-899`，`dx/ActualWidth` 或 `dy/ActualHeight`，夹 `0.2..0.8`）、
    /// `PointerReleased`（`:900-904`，只解捕 + `dragging=false`，**不落盘**）。
    /// 这一条**没有** `PointerCaptureLost` 臂（与 #90 那两条外把手相反）⇒ 分叉也不补。
    /// 尺寸口径同外把手：`Width|Height = SplitterHitWidth(8)`、骑在 Auto 列两侧各
    /// `-SplitterHitWidth/2`（`:822-823` / `:847-848`）。
    fn dock_inner_splitter(
        &self,
        slot: i32,
        mode: layout::RightSplitMode,
        context: &mut ViewContext<Shell>,
        p: Palette,
    ) -> View {
        let vertical = mode == layout::RightSplitMode::Vertical;
        let overlap = -layout::SPLITTER_HIT_WIDTH / 2.0;
        let extent = self.dock_inner_extent(mode);
        let handle = Border::new()
            .background(p.transparent.clone())
            .automation_id(dock::chrome::INNER_SPLITTER)
            .automation_name(self.catalog.l("调整分栏比例"))
            .capture_pointer_on_press(Some(true))
            .on_pointer_pressed(context.callback(move |info: PointerEventInfo| {
                Msg::DockInnerDragStart(info.is_left_button_pressed, info.window_x, info.window_y)
            }))
            .on_pointer_moved(context.callback(move |info: PointerEventInfo| {
                Msg::DockInnerDrag(info.window_x, info.window_y, extent)
            }))
            .on_pointer_released(context.callback(|_| Msg::DockInnerDragEnd));
        if vertical {
            handle
                .grid_row(slot)
                .height(layout::SPLITTER_HIT_WIDTH)
                .margin(th([0.0, overlap, 0.0, overlap]))
                .horizontal_alignment(HorizontalAlignment::Stretch)
                .into()
        } else {
            handle
                .grid_column(slot)
                .width(layout::SPLITTER_HIT_WIDTH)
                .margin(th([overlap, 0.0, overlap, 0.0]))
                .vertical_alignment(VerticalAlignment::Stretch)
                .into()
        }
    }

    /// 那张 chip 菜单的层 = 整格透明「light-dismiss」垫子 + 菜单卡。
    /// 形制是 [`Shell::file_action_menu_layer`] 的姊妹：主干那颗是系统级 `MenuFlyout`
    /// （`ShowAt(anchor)`，`LC:548`），reactor 给不出「挂锚 + 点外即关」的原生通路 ⇒ 自绘。
    /// 垫子在卡**之前**入同一格 ⇒ 后入者在上，点行不会被垫子吃掉。
    fn dock_tab_menu_layer(&self, context: &mut ViewContext<Shell>, p: Palette) -> View {
        let scrim: View = Border::new()
            .grid_row(0)
            .horizontal_alignment(HorizontalAlignment::Stretch)
            .vertical_alignment(VerticalAlignment::Stretch)
            .background(p.transparent.clone())
            .on_pointer_pressed(context.callback(|_| Msg::DockMenuClose))
            .into();
        Grid::new()
            .rows([GridLength::STAR])
            .children((scrim, self.dock_tab_menu(context, p)))
    }

    /// 第 slot 行该发的那一发。主干 `ShowRightTabMenu:475-549` 里每项各有一枚 `Click` 闭包，
    /// 其中五枚**复用**了条带/尾部已有的那四颗 handler（`ActivateRightTab` / `OnRightPaneAddTab`
    /// / `SplitRightPane` / `OnRightPaneToggleFullscreen` / `CloseRightTab`）⇒ 分叉同口径：那五枚
    /// 直接发**本尊 Msg**，不给它们长第二发。剩下两枚（`FileActionMenuPreview` 的
    /// `OpenPathInRightPaneAsync`、`RightPaneMoveHere` 的 `MoveRightTabHere`）在分叉没有独立 Msg
    /// ⇒ 由 [`Msg::DockMenuPick`] 那一枚按槽位路由（同一个 dock_menu 状态带着 tab_id）。
    fn dock_menu_row_message(&self, slot: usize, tab_id: &str) -> Msg {
        match dock::chrome::MENU_ORDER.get(slot).copied().flatten() {
            Some(dock::chrome::MENU_OPEN) => Msg::DockActivate(tab_id.to_string()),
            Some(dock::chrome::SPLIT_HORIZONTAL) => Msg::DockSplit(layout::RightSplitMode::Horizontal),
            Some(dock::chrome::SPLIT_VERTICAL) => Msg::DockSplit(layout::RightSplitMode::Vertical),
            Some(dock::chrome::NEW_TAB) => Msg::DockAddTab,
            Some(dock::chrome::FULLSCREEN_ITEM) => Msg::DockToggleFullscreen,
            Some(dock::chrome::CLOSE_TAB) => Msg::DockCloseTab(tab_id.to_string()),
            _ => Msg::DockMenuPick(slot),
        }
    }

    /// 第 slot 行当前**可不可点**（主干那五枚 `IsEnabled`，逐枚对表 `LC:493/506/521/533`）：
    /// 两枚分栏项看**展示侧**判据（[`dock::Dock::can_show_split`]，与权威判据不同源，
    /// 两处各照不许合并）；「移到这里」看 `mode != None && tab.PaneIndex != TargetMovePane()`；
    /// 「关闭」看 [`dock::Dock::can_close_tab`]。其余三枚恒可点（主干就是恒 true）。
    fn dock_menu_row_enabled(&self, slot: usize, tab: Option<&dock::DockTab>) -> bool {
        match dock::chrome::MENU_ORDER.get(slot).copied().flatten() {
            Some(dock::chrome::MENU_OPEN) | Some(dock::chrome::MENU_PREVIEW) => true,
            Some(dock::chrome::SPLIT_HORIZONTAL) | Some(dock::chrome::SPLIT_VERTICAL) => {
                self.dock.can_show_split()
            }
            Some(dock::chrome::NEW_TAB) | Some(dock::chrome::FULLSCREEN_ITEM) => true,
            Some(dock::chrome::MOVE_HERE) => tab.is_some_and(|tab| {
                self.dock.mode != layout::RightSplitMode::None && tab.pane != self.dock.target_move_pane()
            }),
            Some(dock::chrome::CLOSE_TAB) => self.dock.can_close_tab(),
            // 两枚 `None`（分隔符槽）没有可点性这一说。
            _ => false,
        }
    }

    /// 第 slot 行的**文案**，与 UIA `Name` 分两问：
    /// 两枚分栏项在满员时 `Text` 换成「分栏已满（最多两格）」、`Name` **不换**
    /// （主干 `LC:491-498` / `:504-511` 是先 `Aut(id, L("左右分栏"))` 后改 `item.Text`）；
    /// 全屏那枚反过来 —— `Name` 就是当下那句 `Text`（`LC:527` 的 `Aut(full, id, full.Text)`）。
    fn dock_menu_row_label(&self, slot: usize) -> (String, String) {
        let id = dock::chrome::MENU_ORDER.get(slot).copied().flatten();
        let full = self.dock.fullscreen_label_is_exit();
        let (name, text) = match id {
            Some(dock::chrome::MENU_OPEN) => ("打开", "打开"),
            Some(dock::chrome::MENU_PREVIEW) => ("在侧边栏预览", "在侧边栏预览"),
            Some(dock::chrome::SPLIT_HORIZONTAL) => (
                "左右分栏",
                if self.dock.split_items_show_full_label() { "分栏已满（最多两格）" } else { "左右分栏" },
            ),
            Some(dock::chrome::SPLIT_VERTICAL) => (
                "上下分栏",
                if self.dock.split_items_show_full_label() { "分栏已满（最多两格）" } else { "上下分栏" },
            ),
            Some(dock::chrome::NEW_TAB) => ("新标签页", "新标签页"),
            Some(dock::chrome::MOVE_HERE) => ("移到这里", "移到这里"),
            Some(dock::chrome::FULLSCREEN_ITEM) => {
                if full { ("退出全屏", "退出全屏") } else { ("全屏", "全屏") }
            }
            Some(dock::chrome::CLOSE_TAB) => ("关闭", "关闭"),
            // 两枚 `None`（分隔符槽）与将来多出来的槽位：这一行根本不进上面那个分支（渲染侧
            // 先按 `MENU_ORDER` 的 `None` 铺分隔符），这里只是 `&str` 匹配无法穷举的兜底。
            _ => ("", ""),
        };
        (self.catalog.l(name), self.catalog.l(text))
    }

    /// 主干 `ShowRightTabMenu:537-547`：`Aut(flyout, "FileActionMenu")` + 那 8 项 + 2 枚
    /// `MenuFlyoutSeparator` 的**顺序**（顺序本体是 [`dock::chrome::MENU_ORDER`]，这里不重排）。
    /// 行宿主与交付物卡那张菜单同刻法：真 `Button` + `is_enabled(...)`，不可点的连回调都不挂。
    fn dock_tab_menu(&self, context: &mut ViewContext<Shell>, p: Palette) -> View {
        let tab_id = self.dock_menu.clone().map(|open| open.tab_id).unwrap_or_default();
        let tab = self.dock.tab_by_id(&tab_id).cloned();
        let mut rows: Vec<KeyedView> = Vec::new();
        for (slot, id) in dock::chrome::MENU_ORDER.iter().enumerate() {
            let key = format!("dock-menu-{slot}");
            let Some(id) = id else {
                // 分隔符：主干 `MenuFlyoutSeparator` 的等价物 = 一条 1px 描边、零 Name 零 id。
                let separator: View = Border::new()
                    .height(size::STROKE)
                    .margin(th([0.0, 4.0, 0.0, 4.0]))
                    .background(p.stroke.clone())
                    .into();
                rows.push(KeyedView::new(key, separator));
                continue;
            };
            let (name, text) = self.dock_menu_row_label(slot);
            let enabled = self.dock_menu_row_enabled(slot, tab.as_ref());
            let button = Button::new()
                .automation_id(id.to_string())
                .automation_name(name)
                .min_width(0.0)
                .horizontal_alignment(HorizontalAlignment::Stretch)
                .horizontal_content_alignment(HorizontalAlignment::Left)
                .is_enabled(enabled);
            // 不可点的那一项**连回调都不挂**（主干禁用项也收不到 Click）—— 与交付物卡那张菜单
            // 同一条口径（`file_action_menu` 里那句注释）。
            let button = if enabled {
                button.on_click(context.message(self.dock_menu_row_message(slot, &tab_id)))
            } else {
                button
            };
            let row: View = button
                .content(
                    TextBlock::new()
                        .text(text)
                        .font_size(type_ramp::BODY.size)
                        .text_wrapping(TextWrapping::NoWrap)
                        .vertical_alignment(VerticalAlignment::Center),
                )
                .into();
            rows.push(KeyedView::new(key, row));
        }
        Border::new()
            .grid_row(0)
            .horizontal_alignment(HorizontalAlignment::Left)
            .vertical_alignment(VerticalAlignment::Top)
            .margin(th([6.0, 32.0, 6.0, 6.0]))
            .background(p.card.clone())
            .border_brush(p.stroke.clone())
            .border_thickness(size::STROKE)
            .corner_radius(radius::MEDIUM)
            .automation_id(dock::chrome::MENU)
            .automation_name(self.catalog.l("右栏标签栏"))
            .content(
                StackPanel::new()
                    .orientation(Orientation::Vertical)
                    .keyed_children(rows),
            )
            .into()
    }

    /// 同一槽位二选一：只把选中的那棵放进 keyed_children，缺席那棵整棵退役。
    /// 不要用「两层常驻 + opacity(0)」隐藏 —— reactor 的 `opacity` 只映射到 SetOpacity，
    /// 透明层依然被布局且吃命中，隐藏层会把整块区域的点击全吞掉。
    fn either(&self, on_first: bool, first: (&str, View), second: (&str, View)) -> View {
        let (key, view) = if on_first { first } else { second };
        Grid::new().keyed_children(vec![KeyedView::new(key, view)])
    }

    /// NavigationView 的替身：主干把 pane 背景钉成 Transparent，自绘反而更保真。
    fn nav(&self, context: &mut ViewContext<Shell>, p: Palette) -> View {
        let on_chat = self.page == Page::Chat;
        self.either(
            on_chat,
            ("nav-sessions", self.nav_sessions(context, p)),
            ("nav-sections", self.nav_sections(context, p)),
        )
    }

    fn nav_sessions(&self, context: &mut ViewContext<Shell>, p: Palette) -> View {
        let rows = self.visible_rows();
        let mut items: Vec<KeyedView> = Vec::new();
        items.push(KeyedView::new(
            "new-session",
            self.nav_item(
                NavKind::NewSession,
                "new-session",
                self.catalog.l("新会话"),
                glyph::NEW_SESSION,
                false,
                // 主干 `OnNavItemInvoked` 的 `case "new-session": await CreateSessionAsync()`
                // —— 这颗钮**真的**建会话，不是「回到聊天页」。原先分叉只有自测条上那颗
                // 「新建会话」驱动 `Msg::NewSession`，自测条删掉后这条动线必须由真实 UI 接住。
                Msg::NewSession,
                context,
                p,
            ),
        ));
        items.push(KeyedView::new(
            "workspace",
            self.workspace_header(&rows, context, p),
        ));
        self.push_groups(&mut items, &rows, context, p);
        items.push(KeyedView::new(
            "settings",
            self.nav_item(
                NavKind::Settings,
                "settings",
                self.catalog.l("设置"),
                glyph::SETTINGS,
                self.page == Page::Settings,
                Msg::Nav(Page::Settings),
                context,
                p,
            ),
        ));
        StackPanel::new()
            .orientation(Orientation::Vertical)
            // 左右各 0：4 DIP 侧留白由 `nav_row` 自己的 margin 给（主干 NavigationViewItemButtonMargin），
            // 这里再给 4 就变成 8（实测带侧留白 9 DIP = 面板 4 + 行 4 + 模板描边 1，是主干两倍多）。
            .margin(th([0.0, 4.0, 0.0, 4.0]))
            .keyed_children(items)
    }

    /// 主干进设置时 `ShowSettingsAsync` 把固定项折叠、往 `Nav.MenuItems` 里塞 12 个分区项，
    /// 底部「设置」项不隐藏（再点一次是切回聊天页）。分区项没有任何尺寸覆写，全靠模板默认值。
    fn nav_sections(&self, context: &mut ViewContext<Shell>, p: Palette) -> View {
        let mut items: Vec<KeyedView> = SETTINGS_SECTIONS
            .iter()
            .map(|(id, title, code)| {
                KeyedView::new(
                    format!("section-{id}"),
                    self.nav_item(
                        NavKind::SettingsSection(id),
                        id,
                        self.catalog.l(title),
                        *code,
                        self.section == *id,
                        Msg::Section((*id).to_string()),
                        context,
                        p,
                    ),
                )
            })
            .collect();
        items.push(KeyedView::new(
            "settings",
            self.nav_item(
                NavKind::Settings,
                "settings",
                self.catalog.l("设置"),
                glyph::SETTINGS,
                // 主干 FooterMenuItems 里的 SettingsItem 是 SelectsOnInvoked="False"，
                // 进设置时 Nav.SelectedItem 已被清成 null 并被分区项接管 → 它永远不会带选中条。
                false,
                Msg::Nav(Page::Chat),
                context,
                p,
            ),
        ));
        StackPanel::new()
            .orientation(Orientation::Vertical)
            // 左右各 0：4 DIP 侧留白由 `nav_row` 自己的 margin 给（主干 NavigationViewItemButtonMargin），
            // 这里再给 4 就变成 8（实测带侧留白 9 DIP = 面板 4 + 行 4 + 模板描边 1，是主干两倍多）。
            .margin(th([0.0, 4.0, 0.0, 4.0]))
            .keyed_children(items)
    }

    /// 主干：工作区节点来自 follow 流且默认折叠；没有工作区记录时会话全落在「未分组」。
    fn push_groups(
        &self,
        items: &mut Vec<KeyedView>,
        rows: &[&SessionInfo],
        context: &mut ViewContext<Shell>,
        p: Palette,
    ) {
        if self.tree.workspaces.is_empty() {
            self.push_group(
                items,
                "",
                self.catalog.l("未分组"),
                glyph::UNSORTED,
                rows,
                context,
                p,
            );
            return;
        }
        for workspace in &self.tree.workspaces {
            let group = self.tree.group_sessions(&workspace.id, rows);
            self.push_group(
                items,
                &workspace.id,
                workspace.title.clone(),
                glyph::WORKSPACE,
                &group,
                context,
                p,
            );
        }
        let filed = self.tree.filed_ids();
        let unfiled: Vec<&SessionInfo> = rows
            .iter()
            .copied()
            .filter(|row| !filed.contains(&row.id.as_str()))
            .collect();
        if !unfiled.is_empty() {
            self.push_group(
                items,
                "",
                self.catalog.l("未分组"),
                glyph::UNSORTED,
                &unfiled,
                context,
                p,
            );
        }
    }

    fn push_group(
        &self,
        items: &mut Vec<KeyedView>,
        key: &str,
        title: String,
        code: char,
        rows: &[&SessionInfo],
        context: &mut ViewContext<Shell>,
        p: Palette,
    ) {
        let kind = group_nav_kind(key);
        let nested = !key.is_empty();
        items.push(KeyedView::new(
            format!("group-{key}"),
            self.nav_item_menu(
                kind,
                &format!("node-{key}"),
                title,
                code,
                false,
                Msg::ToggleGroup(key.to_string()),
                // #75：右键开菜单只给**真工作区**那一行。`nested`（= key 非空）与 `kind`
                // 问的是同一条判据 —— 主干「未分组」那颗节点的 Tag 是
                // `WorkspaceVm{WorkspaceId=""}`（`MainWindow.xaml.cs:3368`），
                // 五发里 `rename`/`delete` 在 `:3808`/`:3840` 的 `IsNullOrEmpty` 守卫下直接
                // return ⇒ 那一项的菜单点开也没事可做，`workspace_menu_toggle` 同样拒空串。
                nested.then_some(key),
                context,
                p,
            ),
        ));
        if !self.group_open(key) {
            return;
        }
        // 主干 `_expandedGroups` 就是分叉的 `uncapped` 那份表：它只被
        // `("expand-group"|"collapse-group", groupKey)` 那两发改（`MainWindow.xaml.cs:4446/4451`），
        // 与 NavigationViewItem 的 `IsExpanded`（上面那颗 `group_open`）是两回事。
        let tail = group_tail(
            rows.len(),
            self.uncapped.iter().any(|item| item == key),
            size::SESSION_PREVIEW_LIMIT,
        );
        // 画多少条会话 = 总数减掉尾巴行盖住的那些（`Expand` 才有 `hidden`；
        // `Collapse`/`None` 两臂下 `hidden` 恒 0，即全量，与主干 `shown` 同形）。
        let hidden = match tail {
            Some(GroupTail::Expand { hidden }) => hidden,
            _ => 0,
        };
        for row in &rows[..rows.len() - hidden] {
            let selected = self.active.as_deref() == Some(row.id.as_str());
            items.push(KeyedView::new(
                row.id.clone(),
                self.session_row(row, selected, nested, context, p),
            ));
        }
        match tail {
            // 「展开其余 N 个会话」：主干 `:3478` Content、`:3485` Name 与 Content 同串、
            // `:3482` glyph E70D、`:3479` `SelectsOnInvoked=false`、`:3481` Tag。
            Some(GroupTail::Expand { hidden }) => {
                items.push(KeyedView::new(
                    format!("expand-{key}"),
                    self.nav_item(
                        NavKind::ExpandGroup(key),
                        &format!("cap-{key}"),
                        self.catalog
                            .lf("展开其余 {0} 个会话", &[hidden.to_string()]),
                        glyph::EXPAND_GROUP,
                        false,
                        Msg::Cap(key.to_string(), true),
                        context,
                        p,
                    ),
                ));
            }
            // 「收起」：主干 `:3493` Content=`L("收起")`、`:3499` Name=`L("收起已展开的会话")`
            // （**与 Content 不同串**）、`:3497` glyph E70E、`:3494` `SelectsOnInvoked=false`，
            // 采纳后 `_expandedGroups.Remove(groupKey)`（`:4451`）⇒ 这一发必须是 `Cap(key,false)`。
            Some(GroupTail::Collapse) => {
                items.push(KeyedView::new(
                    format!("collapse-{key}"),
                    self.nav_item(
                        NavKind::CollapseGroup(key),
                        &format!("cap-{key}"),
                        self.catalog.l("收起"),
                        glyph::COLLAPSE_GROUP,
                        false,
                        Msg::Cap(key.to_string(), false),
                        context,
                        p,
                    ),
                ));
            }
            None => {}
        }
    }

    fn workspace_header(
        &self,
        rows: &[&SessionInfo],
        context: &mut ViewContext<Shell>,
        p: Palette,
    ) -> View {
        let empty = if rows.is_empty() {
            TextBlock::new()
                .text(self.catalog.l("暂无会话"))
                .font_size(type_ramp::CAPTION.size)
                .foreground(p.text_tertiary)
                .into()
        } else {
            blank()
        };
        // 主干 `MainWindow.xaml:229-270`：段头行 `[*,Auto,Auto]`、列距 Space2，右侧两枚
        // IconButtonStyle（32×32、Padding 0、r=CornerSmall、底 Transparent），字形 14。
        // 之前分叉只画了两枚裸 FontIcon（20px、无命中区），既撑大了段头也丢了 UIA 名。
        // 末参 = 这一发要送的消息：#75 把第二枚从「尚未移植」的占位换成真入口，
        // 第一枚仍留占位（它的 `MenuFlyout` 是「分组方式/排序方式」，
        // `MainWindow.xaml:259-261`，不属于工作区 CRUD 这一族 —— 见报告 §4）。
        let mut section_button = |code: char, column: i32, id: &str, name: &str, message: Msg| {
            pill_button(
                Button::new()
                    .grid_column(column)
                    .automation_id(id)
                    .automation_name(self.catalog.l(name))
                    .on_click(context.message(message)),
                mark_size(code, size::GLYPH_BODY),
                Pill::ghost(p),
                &format!("workspace-head-{id}"),
                HoverSlot::Row,
                self.hover.as_deref(),
                self.pressed.as_deref(),
                context,
            )
        };
        StackPanel::new()
            .orientation(Orientation::Vertical)
            .spacing(2.0)
            .margin(th([0.0, 10.0, 0.0, 0.0]))
            .children((
                Grid::new()
                    .columns([GridLength::STAR, GridLength::Auto, GridLength::Auto])
                    .column_spacing(2.0)
                    .children((
                        TextBlock::new()
                            .text(self.catalog.l("工作区"))
                            .font_size(type_ramp::CAPTION.size)
                            .foreground(p.text_secondary)
                            .vertical_alignment(VerticalAlignment::Center),
                        section_button(
                            glyph::MORE,
                            1,
                            "WorkspaceViewOptionsButton",
                            "视图选项",
                            Msg::Note(self.catalog.l("视图选项尚未移植")),
                        ),
                        // 主干 `Click="OnAddWorkspaceClick"`（`MainWindow.xaml:268` → `:3140`）
                        // 就一句 `await CreateWorkspaceAsync()` ⇒ 弹「新建工作区」那张卡。
                        section_button(
                            glyph::NEW_SESSION,
                            2,
                            "AddWorkspaceButton",
                            "添加工作区",
                            Msg::WorkspaceDialogShow(WorkspaceDialogKind::Create),
                        ),
                    )),
                empty,
            ))
    }

    /// NavigationViewItem 的可视替身：主干那颗行的模板根 `LayoutRoot` 写的是
    /// `Margin="{ThemeResource NavigationViewItemButtonMargin}"` = **`4,2`** +
    /// `MinHeight="{ThemeResource NavigationViewItemOnLeftMinHeight}"` = **36 DIP**
    /// （`generic.xaml:32078/32068/32187`），高亮就是 LayoutRoot 自己的 Background ⇒
    /// **带 = 该 item 的 UIA 矩形，侧留白 4 DIP、上下各 2 DIP，选中与悬停同一档同高**。
    /// 分叉这里三处对齐它：① 行 Button 的 margin 固定 `4,2,4,2`（侧留白只由这一处给，
    /// 外层 StackPanel 的左右 margin 已改成 0，见 `nav_sessions`/`nav_sections`；原先
    /// 「面板 4 + 行 4 + 模板描边 1 = 9 DIP」是主干的两倍多，实测侧留白 8 px = 4 DIP 已对上）；
    /// ② 内缩由 `TEMPLATE_INSET` 一次抵平 **且** content host 走 `VerticalContentAlignment=Stretch`
    /// 且不挂 `ButtonStyle::Subtle`（两条都实测过才写，见下面函数体里的注释），高亮才真铺满行的
    /// UIA 矩形：36 DIP = 200% 下 72 px，选中带与悬停带同源同色同高；
    /// ③ 缩进**只作用于行内容**（`indent` 加在高亮 Border 的左内边距上），不再把整行连同
    /// 高亮带往右推 —— 主干子代理行的 `row.Margin=(14,0,0,0)` 挂的也是行内容
    /// （`MainWindow.xaml.cs:3166`），高亮带仍然铺满 item。
    /// 选中时在左缘叠一条 3×16 的强调条（主干用 NavigationView 自带指示器）。
    /// 外壳用 Button 而非 Border 承接点击：主干的行是 NavigationViewItem，UIA 上有
    /// InvokePattern 且可键盘聚焦，自绘 Border 会让自动化测试和读屏都摸不到。
    /// UIA 身份两个属性来源分得很清：AutomationId 只由行型 `kind` 给（见 [`nav_automation_id`]），
    /// Name 只由调用方给的 `name` 给；两者都跟 `key`（分叉自己的 hover 寻址键）无关。
    fn nav_row(
        &self,
        kind: NavKind<'_>,
        key: &str,
        content: impl Into<View>,
        name: String,
        selected: bool,
        indent: f64,
        message: Msg,
        workspace_menu: Option<&str>,
        context: &mut ViewContext<Shell>,
        p: Palette,
    ) -> View {
        let hovered = self.hover.as_deref() == Some(key);
        let entered = key.to_string();
        // **不挂** `ButtonStyle::Subtle`：那颗样式自带的 PointerOver 视觉态会把整格 UIA 矩形
        // 刷成 `SubtleFillColorSecondary`（浅 `#09000000` ⇒ 实测 `#EAEAEA`），于是悬停行上叠出
        // 两层带（模板那层 72 px + 我们这层 48 px），选中行只有我们那层 48 px ⇒
        // 「选中带 47px、悬停带 71px 不同高」的真因就是这一层多出来的模板底。
        // 默认样式 + 下面那组 `ButtonBackground*` 透明覆写才是干净通路（`pill_button` 同一套覆写
        // 实测模板层什么都不画，见 tmp/ui10-bandA-cut-ComposerAddButton-hover.png 圆外无方角光晕）。
        let row = Button::new()
            .resource_overrides(
                ResourceOverrides::new()
                    .set("ButtonBackground", Color::transparent())
                    .set("ButtonBackgroundPointerOver", Color::transparent())
                    .set("ButtonBackgroundPressed", Color::transparent())
                    .set("ButtonBackgroundDisabled", Color::transparent())
                    // 描边靠四态透明画刷抹掉；见 `button_flat` 注释，
                    // `ButtonBorderThemeThickness` 这个键一动就让 WinUI fail-fast（0xC000027B 静默崩）。
                    .set("ButtonBorderBrush", Color::transparent())
                    .set("ButtonBorderBrushPointerOver", Color::transparent())
                    .set("ButtonBorderBrushPressed", Color::transparent())
                    .set("ButtonBorderBrushDisabled", Color::transparent())
                    .set("ButtonPadding", Thickness::uniform(0.0)),
            )
            // 主干 NavigationViewItemButtonMargin = `4,2`：侧留白 4 DIP、上下各 2 DIP，
            // 由这一处独家给（外层面板不再给左右 margin）。
            .margin(th([4.0, 2.0, 4.0, 2.0]))
            .min_width(0.0)
            .min_height(size::NAV_ITEM_MIN_HEIGHT)
            .horizontal_alignment(HorizontalAlignment::Stretch)
            .horizontal_content_alignment(HorizontalAlignment::Stretch)
            // 纵向也必须 Stretch：默认 `VerticalContentAlignment=Center` 会让内容按**自身
            // desired 高度**（行里那颗 24 DIP 的 ⋯ 钮 = 48 px）居中，`TEMPLATE_INSET` 那圈负
            // margin 就白抵了 —— 实测带高只有 48 px 而行的 UIA 矩形是 72 px。
            .vertical_content_alignment(VerticalAlignment::Stretch)
            .automation_name(name)
            .automation_id(nav_automation_id(kind))
            .on_click(context.message(message));
        // #75 右键挂菜单：**只有工作区那一行**有（主干 `wsItem.ContextFlyout = wsMenu`，
        // `MW:3355`；固定项 / 会话行 / 「未分组」都没有 `ContextFlyout` ⇒ 传 `None` 的行
        // 连指针按压回调都不挂，凭空多一个指针回调就是多一分行为）。
        //
        // 挂在**下面那颗内容 `Border`** 上，而不是外面那颗 `Button` 上 —— 这不是退让，是查过
        // 真名的：`generated.rs:490-561` 的 `impl Button` 一共只有 9 颗方法
        // （`new` / `element_ref` / `is_enabled` / `horizontal_content_alignment` /
        // `vertical_content_alignment` / `resource_overrides` / `style` / `key_accelerators` /
        // `on_click`），**一枚指针事件都没有**；七颗 `on_pointer_*`（pressed/moved/entered/
        // exited/released/capture-lost/canceled）加 `capture_pointer_on_press` 全在
        // `generated.rs:717` 起的 `impl Border` 上（`on_pointer_pressed` 在 874）⇒
        // `Button::on_pointer_pressed` 那枚方法在本依赖里根本不存在（上一片就是这么编的，
        // 编译期 E0599）。`Border` 那七颗在本仓已被三处实装用过（把手 9540、遮罩 11558/12409），
        // 且这颗 Border 本来就挂着 entered/exited 两枚 ⇒ 换体不换能力，只是把回调落到有的那一侧。
        //
        // reactor 0.100.0 没有 `RightTapped`（公开层与生成层里 `right_tapped`/`RightTapped`
        // 都零命中，`on_pointer_*` 也只有那七颗）⇒ 只能自己从
        // `PointerEventInfo::is_right_button_pressed`（`element.rs:282`）判键。
        // 左键那一发也必须回一条 `Msg`（`ViewContext::callback` 的签名是
        // `impl Fn(T) -> C::Message`，`component.rs:934`，reactor 没有「这发不发」的出口）
        // ⇒ 落 [`Msg::WorkspaceMenuClose`]：菜单没开时它是纯 no-op（`workspace_menu_close`
        // 空手 return false），开着时这一发本来就该收 —— 主干 `MenuFlyout` 的
        // light-dismiss 同口径（分叉既有的姊妹刻法见 [`Shell::file_action_menu_layer`]）。
        // 左键的真实跳转仍由上面那颗 `Button` 的 `on_click` 给（`Button` 只有这一枚事件，
        // 也正是主干 `NavigationViewItem` 的 Invoke 通路）。
        let highlight = Border::new()
            .padding(th([12.0 + indent, 0.0, 14.0, 0.0]))
            .corner_radius(radius::SMALL)
            .background(if selected || hovered {
                p.subtle_hover
            } else {
                p.transparent
            })
            .on_pointer_entered(context.callback(move |_| Msg::Hover(Some(entered.clone()))))
            .on_pointer_exited(context.callback(|_| Msg::Hover(None)));
        // `Some("")` 也一并挡掉：那是「未分组」那颗节点的空 id，[`workspace_menu_toggle`]
        // 本来就按主干 `:3808/3840` 的两道守卫不让它开菜单 ⇒ 这里连回调都不挂。
        let highlight = match workspace_menu {
            Some(id) if !id.is_empty() => {
                let toggled = id.to_string();
                highlight.on_pointer_pressed(context.callback(move |info: PointerEventInfo| {
                    if info.is_right_button_pressed {
                        Msg::WorkspaceMenuToggle(toggled.clone())
                    } else {
                        Msg::WorkspaceMenuClose
                    }
                }))
            }
            _ => highlight,
        }
        .content(content);
        row.content(
            // 模板那两层内缩（Padding=11,5,11,6 是 StaticResource 样式 setter、BorderThickness 每边 1 DIP）
                // 都由 TEMPLATE_INSET 一次抵掉，自绘的行高亮**铺满**这颗钮的 UIA 矩形：
                // 主干 NavigationViewItem 的高亮带 == 该 item 的 UIA 矩形，侧留白由行自己的 margin 给。
                Grid::new()
                    .margin(th(TEMPLATE_INSET))
                    // 兜第二道：host 万一不认 `VerticalContentAlignment`，行的 desired 高度
                    // 也至少等于主干的 36 DIP，带不会被行里那颗 24 DIP 的 ⋯ 钮拽矮。
                    .min_height(size::NAV_ITEM_MIN_HEIGHT)
                    .children((
                        // 行内容的左内缩 = 基础 12 DIP + `indent`（子代理 14、组内 20）：
                        // 缩进加在内容上、高亮带仍铺满整行，与主干 `row.Margin=(14,0,0,0)` 同形。
                        highlight,
                        Border::new()
                            .width(size::NAV_INDICATOR_WIDTH)
                            .height(size::NAV_INDICATOR_HEIGHT)
                            .corner_radius(size::NAV_INDICATOR_RADIUS)
                            .background(p.accent)
                            .horizontal_alignment(HorizontalAlignment::Left)
                            .vertical_alignment(VerticalAlignment::Center)
                            .opacity(if selected { 1.0 } else { 0.0 }),
                    )),
            )
    }

    fn nav_item(
        &self,
        kind: NavKind<'_>,
        key: &str,
        label: String,
        code: char,
        selected: bool,
        message: Msg,
        context: &mut ViewContext<Shell>,
        p: Palette,
    ) -> View {
        self.nav_item_menu(
            kind,
            key,
            label,
            code,
            selected,
            message,
            None,
            context,
            p,
        )
    }

    /// [`Shell::nav_item`] 加一颗「这一行右键开哪颗工作区的菜单」（`Some(id)` = 工作区行的
    /// `WorkspaceTree` id，`None` = 这一行没有右键）。单独立出来是为了让固定项那五处调用
    /// 不必每人写一遍 `None`。
    fn nav_item_menu(
        &self,
        kind: NavKind<'_>,
        key: &str,
        label: String,
        code: char,
        selected: bool,
        message: Msg,
        workspace_menu: Option<&str>,
        context: &mut ViewContext<Shell>,
        p: Palette,
    ) -> View {
        // 主干有 Content 与 Name **不同串**的三型行，其余行两者同串：
        // ① 「新会话」行 Content=`L("新会话")`、Name=`L("新建会话")`（`MainWindow.xaml` 那颗固定项）；
        // ② 「未分组」节点 Content=`L("未分组")`（`MainWindow.xaml.cs:3367`）、
        //    Name=`L("未分组会话")`（`:3373` 的 `Aut(groupItem, "UngroupedSessionsItem", …)`）；
        // ③ 「收起」行 Content=`L("收起")`（`:3493`）、Name=`L("收起已展开的会话")`（`:3499`）。
        // 「展开其余 N 个会话」那一行主干两串相同（`:3478` 与 `:3485` 都是 `LF(...)`）⇒ 走默认臂。
        let name = match kind {
            NavKind::NewSession => self.catalog.l("新建会话"),
            NavKind::Ungrouped => self.catalog.l("未分组会话"),
            NavKind::CollapseGroup(_) => self.catalog.l("收起已展开的会话"),
            _ => label.clone(),
        };
        let content = StackPanel::new()
            .orientation(Orientation::Horizontal)
            .spacing(10.0)
            .children((
                // 主干 NavigationViewItem.Icon 不写 FontSize，但模板把图标夹在
                // `Viewbox Height=16` 里 ⇒ 实际墨迹 16，不是 FontIcon 默认的 20。
                mark_vcenter(code, size::GLYPH_NAV),
                TextBlock::new()
                    .text(label)
                    .font_size(type_ramp::BODY.size)
                    .font_weight(if selected {
                        FontWeight::SEMI_BOLD
                    } else {
                        FontWeight::NORMAL
                    })
                    .foreground(p.text_primary)
                    .vertical_alignment(VerticalAlignment::Center),
            ));
        // 固定项/分组头的缩进为 0：侧留白 4 DIP 已由 `nav_row` 自己的 margin 给（主干同形）。
        self.nav_row(
            kind,
            key,
            content,
            name,
            selected,
            0.0,
            message,
            workspace_menu,
            context,
            p,
        )
    }

    /// 主干 `MakeSessionItem()`：`[*, Auto, Auto]`、列距 6；子代理按 `origin` 判定，缩进 14 并加 `↳ `。
    fn session_row(
        &self,
        row: &SessionInfo,
        selected: bool,
        nested: bool,
        context: &mut ViewContext<Shell>,
        p: Palette,
    ) -> View {
        let is_child = row.is_subagent();
        let running = self.is_running(&row.id);
        let title = self.row_title(row);
        // UIA Name 走 [`session_uia_name`]（主干 `:3520` 的序与本地化都在那颗函数里钉）。
        let shown = session_uia_name(&self.catalog, is_child, &title);
        let id = row.id.clone();
        // 那颗 ⋯ 钮自己也是一颗圆底钮。它**必须**走 `HoverSlot::Pill`（自己的那一格），
        // 不能和行高亮抢 `self.hover` 那一格：行 Border 是它的祖先，指针进入时先进钮、
        // 再冒泡进行 ⇒ 同一个槽里 `Msg::Hover(row.id)` 永远后到，钮的 `hover` 档被行抢走，
        // ⋯ 的圆底在行内**一辈子画不出来**（`ui8-shot` 对它报 NO-TRACE：三态里只有 rest）。
        // 反过来，行高亮要同时认 `pill_hover` 那颗钮的键，否则「进 ⋯ → 行判定为未悬停
        // → ⋯ 收起 → 又判定为悬停」会在两颗元素之间来回抖。
        let more_key = format!("session-more-{}", row.id);
        let hovered = self.hover.as_deref() == Some(row.id.as_str())
            || self.pill_hover.as_deref() == Some(more_key.as_str());
        // 主干 `MainWindow.xaml.cs` 的行内「…」钮（3252-3270 行）：24×24、`Padding=2`、
        // `Background=Transparent`、`BorderThickness=0`、`Opacity=0`（靠 `row.PointerEntered/Exited`
        // 在 3274/3275 行开合），**并且写了圆角**：
        //     CornerRadius rad = new(TokenDouble("RadiusPill", 24));   // 3269-3270 行
        // ⇒ 24 DIP 半径夹到边长一半 = 12 DIP，是一颗 **24 DIP 正圆**（200% 缩放 48 px 直径），
        // 不是小圆角方（`tokens.rs::ROW_MORE_BUTTON` 记着同一条）。`radius::PILL` 就是 24。
        // 无描边 / 圆角 / 四态底色全部走 `pill_button`（`button_ghost` 注释记着两条 fail-fast 成因）。
        let more: View = pill_button(
            Button::new()
                .grid_column(2)
                .opacity(if hovered || selected { 1.0 } else { 0.0 })
                .automation_id(format!("SessionMore_{}", row.id))
                .automation_name(self.catalog.lf("会话操作：{0}", &[title.clone()])),
            mark_size(glyph::MORE_12, size::GLYPH_CAPTION),
            Pill {
                side: size::ROW_MORE_BUTTON,
                radius: radius::PILL,
                // 主干靠 Opacity=0 隐藏，但隐藏态必须不可命中，否则 UIA 仍能 Invoke。
                enabled: hovered || selected,
                ..Pill::ghost(p)
            },
            &more_key,
            HoverSlot::Pill,
            self.pill_hover.as_deref(),
            self.pressed.as_deref(),
            context,
        );
        // 主干 `titleSlot`（`MainWindow.xaml.cs:3543-3606`）：标题与指示器是**同一格的并列子元素**，
        // 指示器 `HorizontalAlignment=Right` ⇒ 点画在标题**右侧**、星列右界。分叉原来把点放在横向
        // StackPanel 的第一个子级 ⇒ 画在标题左边，200% 下那个错位是整行宽级别。
        // 判据本体是 `status_dot_plan` 那颗纯函数（`status_dot_tests` 逐条钉）。
        // #74 步 23：三颗点的 producing 端现在都是真数据 —— 待交互档：当前会话现读台账
        // （`ledger_cards_shown` 挡住换代空窗里那一段假亮），其它会话读 `pending_marks`
        // 登记表（写入点 = `apply_events_frame`）；闹钟那刻读 `schedule` 投影
        // （`session/control` 的未建模键，走 `Projections::value_of`）。
        let plan = status_dot_plan(
            rail_pending_kind(
                &self.interactions,
                self.mux_generation,
                selected,
                &self.pending_marks,
                &row.id,
            ),
            running,
            schedule_active(
                self.control
                    .projections(&row.id)
                    .and_then(|projections| projections.value_of("schedule")),
            ),
        );
        let animations = system_animations_enabled();
        let mut slot: Vec<KeyedView> = Vec::new();
        for child in plan.children(animations) {
            match child {
                SlotChild::Title { margin_right } => slot.push(KeyedView::new(
                    "title",
                    TextBlock::new()
                        .text(if is_child {
                            format!("↳ {title}")
                        } else {
                            title.clone()
                        })
                        .font_size(type_ramp::BODY.size)
                        .font_weight(if selected {
                            FontWeight::SEMI_BOLD
                        } else {
                            FontWeight::NORMAL
                        })
                        .foreground(p.text_primary.clone())
                        .text_trimming(TextTrimming::CharacterEllipsis)
                        .vertical_alignment(VerticalAlignment::Center)
                        // 主干「画了点才给 13、只有闹钟给 20、什么都没有给 0」（`:3559/:3580/:3604`）。
                        .margin(th([0.0, 0.0, margin_right, 0.0])),
                )),
                SlotChild::Dot {
                    kind,
                    trailing,
                    breathes,
                } => {
                    let dot = Ellipse::new()
                        .fill(match kind {
                            StatusDotKind::Warning => p.warning.clone(),
                            StatusDotKind::Info => p.info.clone(),
                        })
                        .width(size::STATUS_DOT)
                        .height(size::STATUS_DOT)
                        .horizontal_alignment(if trailing {
                            HorizontalAlignment::Right
                        } else {
                            HorizontalAlignment::Left
                        })
                        .vertical_alignment(VerticalAlignment::Center)
                        // 主干 `Margin=(0,0,2,0)` ⇒ 点中心距星列右界 2 DIP（200% 下 4 px）。
                        .margin(th([0.0, 0.0, space::S2, 0.0]))
                        // 呼吸只走 Opacity（主干那颗是 Opacity 的 Storyboard），**不改颜色**。
                        .opacity(if breathes {
                            pulse_opacity(self.pulse_step, animations)
                        } else {
                            1.0
                        });
                    // 主干只给 pending 点挂 tooltip + `AutomationProperties.Name`（`:3561-3563`），
                    // 运行点两样都没有 ⇒ 这里不补。（`.tooltip()` 落在 `View` 上，所以它必须排最后。）
                    let dot: View = match plan.pending {
                        Some(kind) => {
                            let label = self.catalog.l(kind.label_key());
                            dot.automation_name(label.clone()).tooltip(label)
                        }
                        None => dot.into(),
                    };
                    slot.push(KeyedView::new("status-dot", dot));
                }
                SlotChild::Alarm { trailing } => {
                    let label = self.catalog.l("有活动定时任务");
                    slot.push(KeyedView::new(
                        "schedule-alarm",
                        Border::new()
                            .horizontal_alignment(if trailing {
                                HorizontalAlignment::Right
                            } else {
                                HorizontalAlignment::Left
                            })
                            .vertical_alignment(VerticalAlignment::Center)
                            .margin(th([0.0, 0.0, space::S2, 0.0]))
                            .automation_name(label.clone())
                            // 主干 `FontSize=GlyphCaption`（12 DIP）：reactor 的 FontIcon 没有字号
                            // setter，套 Viewbox 钉方块（同 `⋯` 那颗的刻法）。
                            .content(mark_size(glyph::ALARM, size::GLYPH_CAPTION))
                            .tooltip(label),
                    ));
                }
            }
        }
        let content = Grid::new()
            .columns([GridLength::STAR, GridLength::Auto, GridLength::Auto])
            .column_spacing(space::S6)
            .children((
                Grid::new().keyed_children(slot),
                TextBlock::new()
                    .text(relative_time(row.updated_at, &self.catalog))
                    .font_size(type_ramp::CAPTION.size)
                    .foreground(p.text_tertiary.clone())
                    .vertical_alignment(VerticalAlignment::Center)
                    .grid_column(1),
                more,
            ));
        self.nav_row(
            NavKind::Session(&id),
            &id,
            content,
            shown,
            selected,
            // 缩进加在行内容上（主干子代理 `row.Margin=(14,0,0,0)`、组内再缩一级），
            // 顶格行给 0 ⇒ 高亮带一律铺满整行、侧留白恒为 4 DIP。
            if is_child {
                size::SUBAGENT_INDENT
            } else if nested {
                size::NAV_GROUP_INDENT
            } else {
                0.0
            },
            Msg::Select(row.id.clone()),
            // 主干的会话行没有 `ContextFlyout`（那一族的菜单挂在行末 ⋯ 上，
            // `BuildSessionMenu:3741`）⇒ 会话行不吃右键。
            None,
            context,
            p,
        )
    }

    /// 主干 `QuestionPanel` + `BuildQuestionCard`（`MainWindow.xaml:965-980` +
    /// `MainWindow.UserQuestions.cs:177-344`）：一张贴在**输入区上方**的卡，不进聊天流。
    ///
    /// 几何逐属性照抄：`HorizontalAlignment=Stretch` / `Margin=StripMargin(12,2,12,2)` /
    /// `Background=CardBrush` / `BorderBrush=InfoBrush` + `BorderThickness=1` /
    /// `CornerRadius=CornerMedium(8)` / `Padding=CardPaddingWide(16,12,16,12)`，内层
    /// `StackPanel Spacing=Space10`（那颗 `QuestionHost`）。主干的 `Grid.Row="2"` 在分叉这一格
    /// 用 `grid_row(1)` + `vertical_alignment(Bottom)` 表达（与 `composer` 同格、贴输入卡上沿）。
    ///
    /// 卡内三块 = 表头 / 当前题 / 底栏，与主干往 `QuestionHost` 里依次塞的 `head` /
    /// `pageHost` / `footer` 一一对上（行距分别 `Sp6` / `Sp8` / `Sp6`+`Sp8`）。七颗 UIA id 全部
    /// 报得出主干那一行：`QuestionAbandonAll`（`:226-234`）、`QuestionNavPrev`（`:254-264`）、
    /// `QuestionNavProgress`（`:274-277`）、`QuestionNavNext`（`:279-289`）、`QuestionSkip`
    /// （`:311-318`）、`QuestionToChat`（`:320-327`）、`QuestionSubmitButton`（`:330-338`），
    /// 外加两族拼接 id `QuestionOption_{qid}_{rawLabel}`（`:460/471`）与 `QuestionCustom_{qid}`
    /// （`:489`）。**计划评审复用同一颗函数**：首题 id 只换表头文案与字形，不另立一套卡。
    ///
    /// 三处抄不过来（逐条记在 `tmp/w74c-report.md`）：①`RadioButton`/`CheckBox` 在这一层没有
    /// 对应控件 ⇒ 全用 `ToggleButton`，互斥在模型侧算（步 18，`QuestionUi::toggle`）；
    /// ②`TextAlignment=Center`（题号那行）在 reactor 的 `TextBlock` 上没有 setter ⇒ 只保住
    /// `min_width(48)`；③`agentId` 码片的 `Opacity=0.6` 抄不过来 ⇒ 退成 tertiary 字色。
    fn question_panel(
        &self,
        card: &QuestionCard,
        context: &mut ViewContext<Shell>,
        p: Palette,
    ) -> View {
        // ---- 表头（`:203-234`）：字形 + 标题 + agentId 码片 ‖「放弃整组问题」
        let mut title_bits: Vec<KeyedView> = vec![
            KeyedView::new(
                "question-glyph",
                mark_size(
                    if card.plan_review {
                        QUESTION_GLYPH_PLAN
                    } else {
                        QUESTION_GLYPH_ASK
                    },
                    size::GLYPH_BODY,
                ),
            ),
            KeyedView::new(
                "question-header",
                View::from(
                    TextBlock::new()
                        .text(card.header.clone())
                        .font_size(type_ramp::BODY_STRONG.size)
                        .font_weight(FontWeight::SEMI_BOLD)
                        .foreground(p.text_primary.clone())
                        .vertical_alignment(VerticalAlignment::Center)
                        // 主干那三行（header / 题面 / 红字）都是裸 `TextBlock`，既没有
                        // `x:Name` 也没走 `Aut()` ⇒ 这里**不自造 AutomationId**（历史上
                        // `FeedbackNoteEditor` 那类自造 id 被判过缺陷）。UIA 读到的 Name
                        // 就是可见文本本身，与主干同一条路。
                        .automation_name(card.header.clone()),
                ),
            ),
        ];
        if !card.agent.is_empty() {
            title_bits.push(KeyedView::new(
                "question-agent",
                View::from(
                    TextBlock::new()
                        .text(card.agent.clone())
                        .font_size(type_ramp::CODE.size)
                        .foreground(p.text_primary.clone())
                        .opacity(0.6)
                        .vertical_alignment(VerticalAlignment::Center)
                        .automation_name(card.agent.clone()),
                ),
            ));
        }
        let title_row: View = StackPanel::new()
            .orientation(Orientation::Horizontal)
            .spacing(space::S8)
            .vertical_alignment(VerticalAlignment::Center)
            .grid_column(1)
            .keyed_children(title_bits)
            .into();
        let abandon_label = self.catalog.l("放弃整组问题");
        let abandon: View = Button::new()
            .style(ButtonStyle::Default)
            .min_height(size::COMPACT_BUTTON_MIN_HEIGHT)
            .is_enabled(!card.disabled)
            .vertical_alignment(VerticalAlignment::Center)
            .automation_id("QuestionAbandonAll")
            .automation_name(abandon_label.clone())
            .on_click(context.message(Msg::AskAbandon(card.event_id.clone(), false)))
            .grid_column(2)
            .content(abandon_label)
            .into();
        let head: View = Grid::new()
            // 主干是三列 `[Auto, *, Auto]`，第 0 列空着（Auto ⇒ 0 DIP）：列数照抄，不并成两列。
            .columns([GridLength::Auto, GridLength::STAR, GridLength::Auto])
            .children((title_row, abandon))
            .into();

        // ---- 当前题（`:371-497`）：题面 + detail + 选项行 + 补充说明（翻页时整块重建）
        let mut page_rows: Vec<KeyedView> = vec![KeyedView::new(
            "question-text",
            View::from(
                TextBlock::new()
                    .text(card.text.clone())
                    .font_size(type_ramp::BODY.size)
                    .foreground(p.text_primary.clone())
                    .text_wrapping(TextWrapping::Wrap)
                    .automation_name(card.text.clone()),
            ),
        )];
        // 计划评审的 detail 是完整计划 markdown：原样呈现（`:394-410`，主干那里**没有** id）。
        if !card.detail.is_empty() {
            page_rows.push(KeyedView::new(
                "question-detail",
                View::from(
                    Border::new()
                        .background(p.card_secondary.clone())
                        .corner_radius(radius::MEDIUM)
                        .padding(th(pad::CARD_COMPACT))
                        .max_height(QUESTION_DETAIL_MAX_HEIGHT)
                        .content(View::from(
                            ScrollViewer::new().content(View::from(
                                TextBlock::new()
                                    .text(card.detail.clone())
                                    .font_size(type_ramp::BODY.size)
                                    .foreground(p.text_primary.clone())
                                    .text_wrapping(TextWrapping::Wrap)
                                    .automation_name(card.detail.clone()),
                            )),
                        )),
                ),
            ));
        }
        let option_name = |raw: &str| self.catalog.lf("选项：{0}", &[raw.to_string()]);
        for (position, row) in card.options.iter().enumerate() {
            let mut line_bits: Vec<KeyedView> = vec![KeyedView::new(
                "label",
                View::from(
                    TextBlock::new()
                        .text(row.display_label.clone())
                        .font_size(type_ramp::BODY.size)
                        .foreground(p.text_primary.clone())
                        .vertical_alignment(VerticalAlignment::Center)
                        .text_wrapping(TextWrapping::Wrap),
                ),
            )];
            if row.recommended {
                line_bits.push(KeyedView::new(
                    "chip",
                    View::from(
                        Border::new()
                            .background(p.accent.clone())
                            .corner_radius(radius::MEDIUM)
                            .padding(th(pad::CHIP_TIGHT))
                            .vertical_alignment(VerticalAlignment::Center)
                            .content(View::from(
                                TextBlock::new()
                                    .text(self.catalog.l("推荐"))
                                    .font_size(QUESTION_CHIP_FONT_SIZE)
                                    .foreground(p.text_primary.clone()),
                            )),
                    ),
                ));
            }
            if !row.description.is_empty() {
                line_bits.push(KeyedView::new(
                    "description",
                    View::from(
                        TextBlock::new()
                            .text(row.description.clone())
                            .font_size(type_ramp::CAPTION.size)
                            .foreground(p.text_secondary.clone())
                            .vertical_alignment(VerticalAlignment::Center)
                            .text_wrapping(TextWrapping::Wrap),
                    ),
                ));
            }
            let name = option_name(&row.raw_label);
            let (event_id, raw_label) = (card.event_id.clone(), row.raw_label.clone());
            page_rows.push(KeyedView::new(
                format!("question-option-{position}"),
                // 单选与多选在这一层**同一颗控件**（reactor 没有 RadioButton/CheckBox）：
                // 差别只在模型侧 —— `QuestionUi::toggle` 单选那支只认 `on == true` 且会摘掉
                // 同组其它颗，所以「只有我选中」这份真相永远由 `row.checked` 驱动。
                ToggleButton::new()
                    .min_height(size::COMPACT_BUTTON_MIN_HEIGHT)
                    .horizontal_alignment(HorizontalAlignment::Left)
                    .is_checked(row.checked)
                    .is_enabled(!card.disabled)
                    .on_is_checked_changed(context.callback(move |on: bool| {
                        Msg::AskToggle(event_id.clone(), raw_label.clone(), on)
                    }))
                    .automation_id(format!(
                        "QuestionOption_{}_{}",
                        card.question_id, row.raw_label
                    ))
                    .automation_name(name.clone())
                    .content(
                        StackPanel::new()
                            .orientation(Orientation::Horizontal)
                            .spacing(space::S6)
                            .keyed_children(line_bits),
                    )
                    .tooltip(name),
            ));
        }
        // 自由文本：内核 answer.custom（`:479-497`）；placeholder = 「输入你的答案」。
        let custom_name = self.catalog.l("补充说明");
        let (custom_event, custom_qid) = (card.event_id.clone(), card.question_id.clone());
        page_rows.push(KeyedView::new(
            "question-custom",
            TextBox::new()
                .text(card.custom.clone())
                .placeholder_text(self.catalog.l("输入你的答案"))
                .min_height(size::COMPOSER_INPUT_MIN_HEIGHT)
                .on_text_changed(context.callback(move |text: String| {
                    Msg::AskCustom(custom_event.clone(), text)
                }))
                .automation_id(format!("QuestionCustom_{custom_qid}"))
                .automation_name(custom_name.clone())
                .tooltip(custom_name),
        ));
        let page: View = StackPanel::new()
            .orientation(Orientation::Vertical)
            .spacing(space::S8)
            .keyed_children(page_rows)
            .into();

        // ---- 底栏（`:236-341`）：题号导航 | 红字 | 跳过 / 去聊天里说 / 确认执行
        let prev_label = self.catalog.l("上一题");
        let next_label = self.catalog.l("下一题");
        let prev_event = card.event_id.clone();
        let prev: View = Button::new()
            .style(ButtonStyle::Default)
            .min_height(size::COMPACT_BUTTON_MIN_HEIGHT)
            // 主干 `:564`：`_questionPrev.IsEnabled = index > 0`（步 21：没有层级 IsEnabled）
            .is_enabled(!card.disabled && card.index > 0)
            .vertical_alignment(VerticalAlignment::Center)
            .automation_id("QuestionNavPrev")
            .automation_name(prev_label.clone())
            .on_click(context.message(Msg::AskPrev(prev_event)))
            .content(mark_size(QUESTION_GLYPH_PREV, size::GLYPH_BODY))
            .tooltip(prev_label)
            .into();
        let next_event = card.event_id.clone();
        let next: View = Button::new()
            .style(ButtonStyle::Default)
            .min_height(size::COMPACT_BUTTON_MIN_HEIGHT)
            // 主干 `:565`：`_questionNext.IsEnabled = index < count-1` ⇒ 末题那颗是**灰的**，
            // 「确认执行」才负责末题汇总（`OnQuestionNextClick` 的 else 支只在程序性调用时到）。
            .is_enabled(!card.disabled && card.index + 1 < card.count)
            .vertical_alignment(VerticalAlignment::Center)
            .automation_id("QuestionNavNext")
            .automation_name(next_label.clone())
            .on_click(context.message(Msg::AskNext(next_event)))
            .content(mark_size(QUESTION_GLYPH_NEXT, size::GLYPH_BODY))
            .tooltip(next_label)
            .into();
        let pager: View = StackPanel::new()
            .orientation(Orientation::Horizontal)
            .spacing(space::S6)
            .vertical_alignment(VerticalAlignment::Center)
            .grid_column(0)
            .children((
                prev,
                View::from(
                    TextBlock::new()
                        .text(card.progress.clone())
                        .font_size(type_ramp::BODY_STRONG.size)
                        .font_weight(FontWeight::SEMI_BOLD)
                        .foreground(p.text_primary.clone())
                        .min_width(QUESTION_PROGRESS_MIN_WIDTH)
                        .vertical_alignment(VerticalAlignment::Center)
                        .automation_id("QuestionNavProgress")
                        .automation_name(card.progress_name.clone()),
                ),
                next,
            ))
            .into();
        let feedback: View = TextBlock::new()
            .text(card.feedback.clone())
            .font_size(type_ramp::CAPTION.size)
            .foreground(p.error.clone())
            .margin(th([space::S8, 0.0, space::S8, 0.0]))
            .vertical_alignment(VerticalAlignment::Center)
            .text_wrapping(TextWrapping::Wrap)
            .grid_column(1)
            .automation_name(card.feedback.clone())
            .into();
        let skip_label = self.catalog.l("跳过本题");
        let skip_event = card.event_id.clone();
        let skip: View = Button::new()
            .style(ButtonStyle::Default)
            .min_height(size::COMPACT_BUTTON_MIN_HEIGHT)
            .is_enabled(!card.disabled)
            .vertical_alignment(VerticalAlignment::Center)
            .automation_id("QuestionSkip")
            .automation_name(skip_label.clone())
            .on_click(context.message(Msg::AskSkip(skip_event)))
            .content(skip_label)
            .into();
        let chat_label = self.catalog.l("去聊天里说");
        let chat_event = card.event_id.clone();
        let to_chat: View = Button::new()
            .style(ButtonStyle::Default)
            .min_height(size::COMPACT_BUTTON_MIN_HEIGHT)
            .is_enabled(!card.disabled)
            .vertical_alignment(VerticalAlignment::Center)
            .automation_id("QuestionToChat")
            .automation_name(chat_label.clone())
            .on_click(context.message(Msg::AskAbandon(chat_event, true)))
            .content(chat_label)
            .into();
        let submit_label = self.catalog.l("确认执行");
        let submit_event = card.event_id.clone();
        let submit: View = Button::new()
            // 与审批那颗 `ApprovalAllow` 同一条件：`.style(Accent)` 不与 `resource_overrides`
            // 同挂（文件头那条 0xC000027B 复盘），这里两个都不碰资源。
            .style(ButtonStyle::Accent)
            .min_height(size::COMPACT_BUTTON_MIN_HEIGHT)
            .is_enabled(!card.disabled)
            .vertical_alignment(VerticalAlignment::Center)
            .automation_id("QuestionSubmitButton")
            .automation_name(submit_label.clone())
            .on_click(context.message(Msg::AskSubmit(submit_event)))
            .content(submit_label)
            .into();
        let actions: View = StackPanel::new()
            .orientation(Orientation::Horizontal)
            .spacing(space::S8)
            .vertical_alignment(VerticalAlignment::Center)
            .grid_column(2)
            .children((skip, to_chat, submit))
            .into();
        let footer: View = Grid::new()
            .columns([GridLength::Auto, GridLength::STAR, GridLength::Auto])
            .children((pager, feedback, actions))
            .into();
        Border::new()
            .grid_row(1)
            .vertical_alignment(VerticalAlignment::Bottom)
            .horizontal_alignment(HorizontalAlignment::Stretch)
            .margin(th(pad::STRIP))
            .padding(th(pad::CARD_WIDE))
            .background(p.card.clone())
            .border_brush(p.info.clone())
            .border_thickness(size::STROKE)
            .corner_radius(radius::MEDIUM)
            .automation_id("QuestionPanel")
            .automation_name(card.header.clone())
            .content(
                StackPanel::new()
                    .orientation(Orientation::Vertical)
                    .spacing(space::S10)
                    .children((head, page, footer)),
            )
            .into()
    }

    /// ChatPage：行 `[*, Auto]`；空态只有 34px 标记 + 28px 标题两件子元素。
    fn chat_page(&self, context: &mut ViewContext<Shell>, p: Palette) -> View {
        let empty_state = StackPanel::new()
            .orientation(Orientation::Vertical)
            .spacing(12.0)
            .horizontal_alignment(HorizontalAlignment::Center)
            .vertical_alignment(VerticalAlignment::Center)
            .children((
                brand_mark(self.brand(), size::EMPTY_STATE_MARK, ""),
                TextBlock::new()
                    .text(self.catalog.l("开始一段新的会话"))
                    .font_size(type_ramp::TITLE.size)
                    .font_weight(FontWeight::SEMI_BOLD)
                    .foreground(p.text_primary)
                    .text_wrapping(TextWrapping::Wrap)
                    .horizontal_alignment(HorizontalAlignment::Center)
                    .automation_name("开始一段新的会话"),
            ));
        let stream = ScrollViewer::new()
            .margin(th(pad::CHAT_COLUMN))
            .content(self.message_stream(p, context));
        // 主线：`ChatList` 常驻，`ChatHero` 只在 `IsHeroState() && KernelBootPanel 不亮` 时盖上去
        // （`UpdateEmptyState` MW:4376-4388；`ShowKernelBootPanel` KC:66「加载态不摆开始一段新的会话」）。
        // 分叉这一格是二选一的 keyed 槽，所以把那条与条件直接抄成 `hero` 取反：
        // 加载卡亮着时空态一定让位，而卡片**不铺满、无背景**，底下 `ChatList` 照常可交互
        // （一次性提示那条 system 行就得画在它上面，否则 §4 的气泡根本没地方显示）。
        let hero = self.hero_state() && !self.boot.showing;
        let mut cells: Vec<KeyedView> = vec![
            KeyedView::new(
                "stream",
                self.either(
                    !hero,
                    ("stream-live", stream.into()),
                    ("stream-empty", empty_state.into()),
                ),
            ),
            KeyedView::new("composer", self.composer(context, p, 1)),
        ];
        // 批 M1（#55）常驻目标条：主干那一格是 `ChatPage` 的 **Row 3**（`MainWindow.xaml:996-997`，
        // 与 `ComposerBar` 的 Row 4 平级、在它上面一整行）⇒ 入树排在 `composer` **之后**
        // （后入者在上 = 条贴输入卡上沿），排在 `rail` / `boot` / `palette` 与那九张模态层
        // **之前**（那九张在主干都是独立顶层窗口，层级本就高于条）。
        // ⚠ 槽位是**新起一枚 keyed 槽**，不是 `composer_host` 的那枚 `Option<View>` strip
        // （施工图 §3.1/§3.2：那颗已被 `run_stats_strip()` 独占，而主干的条根本不占那格；
        // 硬塞还要同刀改四把 sp2 锁 —— 本批一枚都不动）。
        // 显隐同口径：`None` ⇒ 这棵节点根本不生成（reactor 没有 `Visibility`）。
        if let Some(bar) = self.goal_bar_view(context, p) {
            cells.push(KeyedView::new("goal-bar", bar));
        }
        // #65 轮次轨：叠在正文右缘，**不给正文减宽**（主干那颗是 ChatViewport 的
        // `Column=1 RowSpan=2`，分叉这一格只有一列 ⇒ 同格浮层 + `grid_row_span(2)` 表达同一语义；
        // 真去加一列 `Auto` 就会把 48 DIP 从正文宽度里抠走，那是回归）。
        // 入树顺序在 `boot` 卡与命令浮层**之前** ⇒ 那两张浮层照旧盖在轨上（后入者在上）。
        // 条数不足 2 条时整条不显示：reactor 没有 `Visibility.Collapsed`，所以是「不生成这个节点」。
        let rail_marks = self.rail_marks();
        if turnrail::rail_visible(rail_marks.len()) {
            cells.push(KeyedView::new("rail", self.turn_rail(&rail_marks, context, p)));
        }
        // 主线 `KernelBootPanel`（MX:691-709）就在 `ChatViewport` 的 Row 1、与 ChatList/ChatHero
        // **同格叠放**，后入者在上 ⇒ 这张卡排在 `"stream"` 之后进树，且**只占内容面正中**。
        if self.boot.showing {
            cells.push(KeyedView::new("boot", self.kernel_boot_panel(context, p)));
        }
        // 主干 `CommandPalette`（MX:745-809）与 `ChatList`/`KernelBootPanel` 同格（ChatPage Row 1）、
        // 贴底（`VerticalAlignment=Bottom`）叠放，声明在最后 ⇒ 层级最高。分叉这一格同样是
        // 「后入者在上」，所以它排在 `stream`/`boot` 之后（见上面那条 keyed 槽位注释）。
        if self.palette.showing {
            cells.push(KeyedView::new("palette", self.command_palette(context, p)));
        }
        // #74 步 14/15/16（C 刀）：提问卡排在 `palette` 之后、`approval` **之前** —— 规格定的
        // 入树序是 `stream → composer → rail → boot → palette → question → approval`：两张卡
        // 都要压过补全浮层（它们**阻塞内核**，不回帧那一轮就永久挂住），而审批压在提问之上
        // （主干同一时刻两张卡宿在两个不同 Row，分叉只有一格 ⇒ 用文档顺序表达那层偏序）。
        // 落点是输入区那一格（主干 `MainWindow.xaml:966` 的 `Grid.Row="2"` = 贴输入区上方、
        // 不进聊天流），所以 `question_panel` 自己标 `grid_row(1)` + `vertical_alignment(Bottom)`。
        if let Some(card) = question_card(
            &self.interactions,
            self.ask.as_ref(),
            self.mux_generation,
            &self.catalog,
        ) {
            cells.push(KeyedView::new("question", self.question_panel(&card, context, p)));
        }
        // #74 步 14/15：审批卡**最后入树** ⇒ 后入者在上。入树次序规格定的是
        // `stream → composer → rail → boot → palette → question → approval`；
        // 审批要压过命令浮层，因为它是**阻塞内核**的那张卡 —— 不回帧那一轮就永久挂住
        // （wf1 §2.2：网关零应答没有超时），而补全浮层随时可以关。
        // 显隐同样是「整棵节点不生成」（reactor 没有 `Visibility`）：`approval_card` 给
        // `None` 就当场上没有这张卡。**只有代次不符那一段（步 8 空窗）才收起**；
        // 同代次里 `clientId` 还没落（`drop_stream` 之后、新 `ready` 之前）卡照旧亮着，
        // 收卡只准由 `cancel` / `settle` 驱动 —— 见测试
        // `a_dropped_stream_holds_the_frame_but_not_the_queue`。
        if let Some(card) = approval_card(&self.interactions, self.mux_generation, &self.catalog) {
            cells.push(KeyedView::new("approval", self.approval_panel(&card, context, p)));
        }
        // 批 CD3（A-12）：Cordis 审批**浮卡**紧跟 `"approval"` **之后**、`"file-menu"` 之前 ⇒
        // 既满足既有顺序锁 `palette < approval < file-menu`，又表达主干那句「同一格 (1,0)、
        // `grid.Children.Add` 居末 = 压在 `ApprovalHost` 之上」（`CD:496-500`）。
        // ⚠ 这一枚**不是**模态：不入 `fn app_modal_host(` 那八格、不进 `Msg::PaletteClose if` 档、
        // 不登记 `ModalLedgerRow`、与上面那张 `approval` 可以同屏并存（主干两张卡无共享旗，
        // `ShowNextCordisApproval` 的守卫只读 `_cordisSubmitting` / `_cordisActiveApproval`）。
        // 显隐同口径：`active` 为 `None` ⇒ 整棵不入树（= 主干 `CD:514` 那句 `Collapsed`）。
        if let Some(approval) = self.cordis_approvals.active.as_ref() {
            cells.push(KeyedView::new(
                "cordis-approval",
                self.cordis_approval_panel(approval, context, p),
            ));
        }
        // 交付物卡 ⋯ 那张菜单（主干 `FileActionMenu`）**最后**入树 ⇒ 压过前面所有层：
        // 主干那张是系统级 MenuFlyout（顶层窗口，层级高于壳内任何东西，包括 CommandPalette）。
        // 显隐同口径：reactor 没有 `Visibility` ⇒ 不开就这棵节点根本不生成。
        // 一处抄不动：主干 `ShowAt(anchor, BottomEdgeAlignedRight)` 要把菜单钉在那颗钮下面，
        // 而分叉读不回元素的屏幕矩形 ⇒ 只能贴内容面右下（最新那张卡在底部，离锚点最近）。
        if self.file_menu.is_some() {
            cells.push(KeyedView::new("file-menu", self.file_action_menu_layer(context, p)));
        }
        // #93e「消息详情」那张浮层排在 `file-menu` **之后** ⇒ 入树序扩成
        // `stream → composer → rail → boot → palette → question → approval → file-menu →
        // message-details`。为什么在最上层：主干它也是系统级 `Flyout`（顶层窗口，压过壳内一切），
        // 而且它和 ⋯ 菜单都是「同一次点击唤起的瞬时层」，彼此不会同时出现（reducer 里
        // `Msg::DetailsToggle` 先收 ⋯ 菜单、`Msg::FileMenuToggle` 先收这张），谁后点谁在上。
        // 判据用 [`message_details_bubble`] 而不是 `message_details.is_some()`：键还在、气泡表已换
        // （切会话）时整层不生成，与「没开」同义。
        if self.message_details_bubble().is_some() {
            cells.push(KeyedView::new(
                "message-details",
                self.message_details_layer(context, p),
            ));
        }
        // #93g「跨会话召回」那张列表层排在 `message-details` **之后** ⇒ 入树序扩成
        // `stream → composer → rail → boot → palette → question → approval → file-menu →
        // message-details → session-refs`。它压在详情浮层之上不是巧合：主干那颗 chip 长在详情
        // flyout 里面（`MainWindow.MessageDetails.cs:1520-1536`），列表层是「层中之层」，
        // 在分叉这套自绘贴角形制里只能是更上面那一层。
        // 判据用 `is_some()` 而不是「列表非空」：[`session_ref_list_show`] 已经把空列表挡在门外
        // ⇒ 状态格里 `Some` 就等于「至少一行」，与主干「chip 在 `Count > 0` 那一档里才存在」同义。
        if self.session_refs.is_some() {
            cells.push(KeyedView::new(
                "session-refs",
                self.session_ref_layer(context, p),
            ));
        }
        // #75 工作区右键菜单（主干 `wsItem.ContextFlyout`，`MW:3334-3357`）与那三张
        // `ContentDialog`（`:3806/:3838/:3884`）都排在 `session-refs` **之后** ⇒ 入树序扩成
        // `… → message-details → session-refs → workspace-menu → workspace-dialog`。
        // 为什么在壳内最上层：主干那两族一颗是系统级 `MenuFlyout`、一颗是 `ContentDialog`
        // （模态、独立顶层窗口），层级高于壳内任何自绘层，包括 `CommandPalette`。
        // 两族彼此也要分先后：菜单先入、卡后入 ⇒ 卡在上。主干同一时刻不会两开
        // （唤卡那一刻 `WorkspaceMenuAction` 那条分支自己收了菜单），这条序只是保险。
        // 显隐同口径：reactor 没有 `Visibility` ⇒ 不开就这棵节点根本不生成。
        if self.workspace_menu.is_some() {
            cells.push(KeyedView::new(
                "workspace-menu",
                self.workspace_menu_layer(context, p),
            ));
        }
        if self.workspace_dialog.is_some() || self.workspace_folder_dialog.is_some() {
            cells.push(KeyedView::new(
                "workspace-dialog",
                self.workspace_dialog_layer(context, p),
            ));
        }
        // #56 输入区选择器组（`AgentMode*` / `Permission*` / `Model*`）的开层：一张贴在输入带
        // 左上角的自绘卡 + 一整面透明遮罩（点外面即收，同 `Msg::SelectorClose`）。
        // 入树序：在 `workspace-dialog` **之后**（同一条 composer 带上的浮层，盖过那两张工作区
        // 对话框是它该做的事）、`todos-panel` **之前**（面板那颗是应用级模态 `ContentDialog`，
        // 且它开的时候 reducer 已经先收了选择器 ⇒ 这一格通常根本不在树里，序只是保险）。
        // 显隐同口径：reactor 没有 `Visibility` ⇒ 不开就这棵节点根本不生成。
        if self.selectors.is_some() {
            cells.push(KeyedView::new(
                "selectors",
                self.selector_layer(context, p),
            ));
        }
        // 批 MD1：那三张应用级模态卡（#106 任务清单 / 批 M4 轨迹 / 批 M2c 目标）**不再长在这一格里**。
        // 它们的宿主是 [`Shell::app_modal_host`]，挂在根网格（`view` 那一台）的末格 ⇒ 遮罩域 = 整窗，
        // 与主干 `ContentDialog` 的 `XamlRoot = Content.XamlRoot`（整窗根）同宽；长在这台行 0 时
        // 行 1 的 composer / goal-bar 入口与右栏那一列都在遮罩外 ⇒ 那正是「两张模态卡同屏」的根因。
        Grid::new()
            .rows([GridLength::STAR, GridLength::Auto])
            .keyed_children(cells)
    }

    /// 主干 `CommandPalette`（MX:745-809）：一张贴在内容面底部的浮层卡片。
    /// 主干那段 XAML 的注释就是这里的实现口径——「用普通元素做浮层而不是 Flyout/Popup：浮层不能
    /// 抢焦点，键盘全部由 InputBox 处理，鼠标点选后把焦点还给 InputBox」⇒ 分叉这里连一颗
    /// 可获得焦点的控件都不放（行是自绘 `Border`），按键走 `keys` 那条钩子通路。
    /// 几何逐属性照抄：`MaxWidth=640` / `MaxHeight=264` / `Margin=OverlayMargin(12,0,12,8)` /
    /// `CardBrush` 底 + `StrokeBrush` 1px 描边 / `CornerMedium=8`；内部两行 `[Auto, *]` =
    /// 标题（`HintTextStyle` + `OverlayHeaderMargin`）与列表（`MaxHeight=216` + `OverlayListPadding`）。
    ///
    /// 显隐：reactor 没有 `Visibility` ⇒ 整棵由 `chat_page` 那个 keyed 槽位增删；
    /// 「目录取不到」那一态（MW:17708-17714）列表区收起、只留标题那行原因，同样用槽位表达。
    fn command_palette(&self, context: &mut ViewContext<Shell>, p: Palette) -> View {
        let header_text = self.palette.header(&self.catalog);
        let header = TextBlock::new()
            .text(header_text.clone())
            .font_size(type_ramp::CAPTION.size)
            .foreground(p.text_tertiary.clone())
            .margin(th(pad::OVERLAY_HEADER))
            .grid_row(0)
            .automation_id("CommandPaletteHeader")
            .automation_name(header_text);
        let mut rows: Vec<KeyedView> = Vec::new();
        if self.palette.list_visible {
            for (index, command) in self.palette.matches.iter().enumerate() {
                let row: View = self.palette_row(index, command, p, context);
                rows.push(KeyedView::new(format!("command-{index}"), row));
            }
        }
        let list = ScrollViewer::new()
            .grid_row(1)
            .max_height(PALETTE_LIST_MAX_HEIGHT)
            .automation_id("CommandPaletteList")
            .content(
                // 主干 Padding 挂在 ListView 上；ScrollViewer 没有 padding ⇒ 内衬挪到里面这层
                // Border，量出来的行位置一致（4,0,4,6）。
                Border::new()
                    .padding(th(pad::OVERLAY_LIST))
                    .content(StackPanel::new().keyed_children(rows)),
            );
        Border::new()
            .grid_row(0)
            .horizontal_alignment(HorizontalAlignment::Stretch)
            .vertical_alignment(VerticalAlignment::Bottom)
            .max_width(PALETTE_MAX_WIDTH)
            .max_height(PALETTE_MAX_HEIGHT)
            .margin(th(pad::OVERLAY))
            .background(p.card.clone())
            .border_brush(p.stroke.clone())
            .border_thickness(size::STROKE)
            .corner_radius(radius::MEDIUM)
            .automation_id("CommandPalette")
            .content(Grid::new().rows([GridLength::Auto, GridLength::STAR]).children((header, list)))
            .into()
    }

    /// 主干 `CommandList` 的一行（`ItemContainerStyle` + `DataTemplate`，MX:779-806）：
    /// 行容器 `Padding=8,5,8,5` / `MinHeight=0` / 内容横向 Stretch；三列 `[Auto, *, Auto]`、
    /// 列距 `Space10=10` = `/名字`（`CodeTextStyle` 12，不换行）+ 描述（`CaptionTextStyle` 12 +
    /// `TextSecondaryBrush` + `CharacterEllipsis`）+ `input.hint`（`HintTextStyle` 12 + Tertiary）。
    /// 选中档 = 主干 ListViewItem 的 Selected 底色，这里用分叉既有的行级提亮画刷（与左栏行同源），
    /// 悬停档同理。行的 UIA Name 照主干 `CommandVm.ToString()`：有描述就 `/名字  描述`（两个空格）。
    ///
    /// 为什么是 `Border` 而不是 `Button`/`ListViewItem`：reactor 没有 `ItemContainerStyle` 那一层，
    /// 默认容器模板的 Padding(11,5,11,6) 与最小高会把主干钉死的 26 DIP 行撑回 40；
    /// `CodeTextStyle` 的 `FontFamily=Consolas…` 也抄不过来（`TextBlock` 公开面没有字体族属性，
    /// 见 `settings_code_text` 同一处偏差）。
    fn palette_row(
        &self,
        index: usize,
        command: &CommandEntry,
        p: Palette,
        context: &mut ViewContext<Shell>,
    ) -> View {
        let key = format!("palette-row-{index}");
        let selected = self.palette.index >= 0 && self.palette.index as usize == index;
        let hovered = self.hover.as_deref() == Some(key.as_str());
        let name = command.slash_name();
        let automation_name = if command.description.is_empty() {
            name.clone()
        } else {
            format!("{name}  {}", command.description)
        };
        let description = command.description.clone();
        let hint = command.hint.clone();
        let entered = key;
        Border::new()
            .padding(th(PALETTE_ROW_PADDING))
            .background(if selected || hovered {
                p.subtle_hover.clone()
            } else {
                p.transparent.clone()
            })
            // 两次回调都顺手把「指针在窗口内的 DIP 坐标」记进 `scroll` 的锚点槽
            // （`PointerEventInfo::window_x/window_y`，框架给的是根视觉坐标）。这是 #64 那条
            // 滚轮通路唯一的可信落点：`WM_MOUSEWHEEL` 归谁滚由 lParam 的点决定，而这个点是
            // 「指针确实在这一行里」的实证。返回的消息一个字都没改（还是 Hover / PalettePick），
            // 布局与观感零变化。
            .on_pointer_entered(context.callback(move |info: PointerEventInfo| {
                scroll::note_anchor(
                    scroll::AnchorSource::Palette,
                    scroll::Point { x: info.window_x as i32, y: info.window_y as i32 },
                );
                Msg::Hover(Some(entered.clone()))
            }))
            .on_pointer_exited(context.callback(|_| Msg::Hover(None)))
            .on_pointer_released(context.callback(move |info: PointerEventInfo| {
                scroll::note_anchor(
                    scroll::AnchorSource::Palette,
                    scroll::Point { x: info.window_x as i32, y: info.window_y as i32 },
                );
                Msg::PalettePick(index)
            }))
            .automation_name(automation_name)
            .content(
                Grid::new()
                    .columns([GridLength::Auto, GridLength::STAR, GridLength::Auto])
                    .column_spacing(space::S10)
                    .children((
                        TextBlock::new()
                            .grid_column(0)
                            .text(name)
                            .font_size(type_ramp::CODE.size)
                            .foreground(p.text_primary.clone())
                            .text_wrapping(TextWrapping::NoWrap)
                            .vertical_alignment(VerticalAlignment::Center),
                        TextBlock::new()
                            .grid_column(1)
                            .text(description)
                            .font_size(type_ramp::CAPTION.size)
                            .foreground(p.text_secondary.clone())
                            .text_trimming(TextTrimming::CharacterEllipsis)
                            .text_wrapping(TextWrapping::NoWrap)
                            .vertical_alignment(VerticalAlignment::Center),
                        TextBlock::new()
                            .grid_column(2)
                            .text(hint)
                            .font_size(type_ramp::CAPTION.size)
                            .foreground(p.text_tertiary.clone())
                            .text_wrapping(TextWrapping::NoWrap)
                            .vertical_alignment(VerticalAlignment::Center),
                    )),
            )
            .into()
    }

    /// 主干 `ChatList`：渲染 `_messages`，末尾接在途的 live 气泡与「少女祈祷中」占位行。
    /// 行距来自 `ListViewItem Margin=0,3`（逐条挂在气泡上），所以面板本身不给 spacing。
    fn message_stream(&self, p: Palette, context: &mut ViewContext<Shell>) -> View {
        let mut lines: Vec<KeyedView> = self
            .bubbles
            .iter()
            .rev()
            .take(200)
            .rev()
            .map(|bubble| {
                let answer = self.is_turn_answer(bubble);
                KeyedView::new(
                    bubble_key(bubble),
                    self.bubble_view(bubble, answer, !self.is_open_turn(bubble.turn), p, context),
                )
            })
            .collect();
        if let Some(live) = &self.live {
            let bubble = Bubble::new("assistant", live.text.clone(), live.turn, -1);
            lines.push(KeyedView::new(
                "live",
                self.bubble_view(&bubble, false, false, p, context),
            ));
        }
        if self.thinking {
            lines.push(KeyedView::new("pending", self.pending_row(p)));
        }
        StackPanel::new()
            .orientation(Orientation::Vertical)
            .keyed_children(lines)
    }

    /// 该轮最后一条 assistant 正文（主干 `_transcriptAnswers`）：只有它能分支、才显用时。
    fn is_turn_answer(&self, bubble: &Bubble) -> bool {
        bubble.role == "assistant"
            && bubble.seq > 0
            && !self.bubbles.iter().any(|other| {
                other.role == "assistant" && other.turn == bubble.turn && other.seq > bubble.seq
            })
    }

    /// 主干 `ProducedPathsForTurn`：本轮产出按到达顺序去重（只留首现），并截到答案气泡自己的
    /// `seq`——答案之后才落的结果不属于这条回答。
    fn produced_paths(&self, turn: i64, closing_seq: i64) -> Vec<String> {
        if turn <= 0 {
            return Vec::new();
        }
        let Some((_, rows)) = self.produced.iter().find(|(id, _)| *id == turn) else {
            return Vec::new();
        };
        let mut paths: Vec<String> = Vec::new();
        for (seq, path) in rows {
            if (closing_seq > 0 && *seq > closing_seq) || paths.iter().any(|keep| keep == path) {
                continue;
            }
            paths.push(path.clone());
        }
        paths
    }

    /// 主干 `RefreshProducedChips`：产出晚于答案落地（或 `turn/end` 收尾）时重算那一行的 chips。
    fn sync_produced(&mut self, turn: i64) {
        let Some(index) = self.bubbles.iter().rposition(|bubble| {
            bubble.turn == turn && bubble.role == "assistant" && bubble.seq > 0
        }) else {
            return;
        };
        let closing = self.bubbles[index].seq;
        let paths = self.produced_paths(turn, closing);
        self.bubbles[index].produced = paths;
    }

    /// 主干 `_closedTranscriptTurns` 的反面：`turn/start` 进表、`turn/end` 摘表，还在表里
    /// 说明这一轮没收尾，分支钮得灰着。
    fn is_open_turn(&self, turn: i64) -> bool {
        self.turn_starts.iter().any(|(id, _)| *id == turn)
    }

    /// 主干 `HintTextStyle`（caption 12 + TextTertiary）：操作行的时钟/型号/用量/用时都走它。
    fn hint(&self, text: String, p: Palette) -> View {
        TextBlock::new()
            .text(text)
            .font_size(type_ramp::CAPTION.size)
            .foreground(p.text_tertiary.clone())
            .vertical_alignment(VerticalAlignment::Center)
            .into()
    }

    // ---- #65 轮次轨的三棵树：宿主 / 一条刻度 / 预览卡 --------------------------------------
    //
    // 几何全部来自 `turnrail` 那张表（宿主 48、槽 20、刻度 6、圆角 3、三态 24/32/40 与
    // 0.55/0.9/1.0、卡 360 宽与 -370 左偏移），这里只把数填进构建器。
    //
    // 三处**明确不可移植**，照分叉规矩写清楚而不是假装做到了：
    // · `IsHitTestVisible=False`（预览卡不吃指针）：reactor 0.100.0 的公共面没有这个属性，
    //   `LayoutControl` 只到 `opacity` 为止。可观察后果与主干一致：卡本来就在宿主**左边**
    //   （-370 + 360 ⇒ 右缘还差 10 DIP 才贴到轨），指针往卡那边挪一定先离开槽 ⇒ 槽的
    //   `PointerExited` 把卡收起，卡永远抓不住指针。主干那颗卡同样是「一碰就收」。
    // · `Visibility.Collapsed`（response 空 ⇒ 那一行不出现）：分叉一律「不往子树里放那个节点」。
    // · 卡高实测（`ActualHeight`）：读不到 ⇒ `preview_y` 一直吃标称 100，见 `turnrail::CARD_NOMINAL_HEIGHT`。

    /// 宿主：`Grid` 宽 48、`Margin 0,0,4,0`、垂直居中于聊天视口带、贴在正文右缘**且不给正文减宽**
    /// （主干是 ChatViewport 的 `Column=1 RowSpan=2`；分叉那一格只有一列，所以是同格浮层 +
    /// `grid_row_span(2)` 去跨「列表行 + composer 行」，`HorizontalAlignment=Right` 收边）。
    fn turn_rail(&self, marks: &[TurnRailMark], context: &mut ViewContext<Shell>, p: Palette) -> View {
        let count = marks.len();
        let host = turnrail::host_height(turnrail::LIST_INSET, turnrail::SLOT_PITCH, count, CHAT_BAND_DIP);
        let mut slots: Vec<KeyedView> = Vec::with_capacity(count);
        for (index, mark) in marks.iter().enumerate() {
            let state = turnrail::state_of(
                self.rail_hover == Some(index),
                mark.turn == self.rail_active,
            );
            slots.push(KeyedView::new(
                format!("turn-{}", mark.turn),
                self.turn_rail_slot(index, state, context, p),
            ));
        }
        // 刻度条数超过宿主能装下的量时（`host_height` 夹过 420 / `band-64`）栈面板会溢出宿主，
        // 主干靠 `EnsureActiveMarkInView` 把活动那条拉回来 —— 那一族在分叉**不可移植**，钉死在这里：
        // 缺的 API 是 `ScrollViewer.ViewChanged`（事件）、`ScrollViewer.VerticalOffset` /
        // `ScrollableHeight`（读回位置）、`ItemsPanelRoot` + 子元素 `TransformToVisual`（量槽位），
        // 加上 `UIElement.IsHitTestVisible` 与 `ListViewItem` 的 `ScrollIntoView(Leading)`；
        // reactor 0.100.0 里 `ScrollIntoView` 全 crate 0 命中，`IScrollView` 只在
        // `pub(crate) native::winui::bindings` 那一侧，`View::native` 也不是 pub。
        // ⇒ `InitTurnRail` / `HookTurnRailScroll` / `OnTurnRailViewChanged` /
        //   `UpdateTurnRailActiveFromViewport` / `TopVisibleBubbleTurn` / `EnsureActiveMarkInView`
        //   六条一律不实现，也**不**用定时器去造一个假近似（那只会让活动轮跟着心跳抖）。
        // 逃生口就是下面这条 `ScrollViewer`：指针停在轨上时滚轮的 lParam 命中的正是它，
        // 用户能自己把够不着的刻度滚进视野。
        let list = ScrollViewer::new()
            .vertical_scroll_bar_visibility(ScrollBarVisibility::Hidden)
            .horizontal_scroll_bar_visibility(ScrollBarVisibility::Disabled)
            .content(
                StackPanel::new()
                    .orientation(Orientation::Vertical)
                    // 主干的 `Padding 0,2`：ScrollViewer/StackPanel 都没有 padding，
                    // 用等价的上下 margin 把第一条槽压到 inset 处（与 `turnrail::slot_top` 同一口径）。
                    .margin(th(pad::RAIL_LIST))
                    .vertical_alignment(VerticalAlignment::Stretch)
                    .horizontal_alignment(HorizontalAlignment::Right)
                    .automation_id("TurnRailMarks")
                    .automation_name("轮次刻度列表")
                    .keyed_children(slots),
            );
        let mut cells: Vec<KeyedView> = vec![KeyedView::new("marks", list)];
        if let Some(index) = self.rail_hover.filter(|index| *index < count) {
            cells.push(KeyedView::new(
                "preview",
                self.turn_rail_preview(&marks[index], index, host, p),
            ));
        }
        Grid::new()
            .width(turnrail::HOST_WIDTH)
            .height(host)
            .margin(th(pad::RAIL_HOST))
            .horizontal_alignment(HorizontalAlignment::Right)
            .vertical_alignment(VerticalAlignment::Center)
            .grid_row(0)
            .grid_row_span(2)
            .automation_id("TurnRailHost")
            .automation_name("历史快速定位")
            .keyed_children(cells)
    }

    /// 一槽：20 DIP 高的 `Border` 就是主干那颗「铺满的透明矩形」（命中区 —— 没有它指针得精确
    /// 压在 6 DIP 高的刻度上），`content` 是刻度本体 `Rectangle`（高 6、圆角 3、右对齐、垂直居中、
    /// `AccentBrush` 底 + 三态宽/不透明度）。
    /// ⚠ 参数表里**没有** `mark`：主干那颗 `<Grid Height="20">`（`MainWindow.xaml:692`）能拿到的
    /// 只有 `x:Bind MarkWidth/MarkOpacity` 两枚状态值 ⇒ 这一层不该见到轮次号。RT6 A-2 删掉刻度
    /// Name 之后 `mark` 就成了死参数，一并收掉（留下 `_mark` 就是留一颗等着被重新喂假的空位）。
    fn turn_rail_slot(
        &self,
        index: usize,
        state: MarkState,
        context: &mut ViewContext<Shell>,
        p: Palette,
    ) -> View {
        Border::new()
            .width(turnrail::HOST_WIDTH)
            .height(turnrail::SLOT_PITCH)
            .min_height(0.0)
            .padding(th([0.0, 0.0, 0.0, 0.0]))
            // 透明底 = 可命中（WinUI 的 `Background=null` 不参与命中测试，这层不能省）。
            .background(p.transparent.clone())
            .on_pointer_entered(context.callback(move |_| Msg::RailHover(Some(index))))
            .on_pointer_exited(context.callback(|_| Msg::RailHover(None)))
            .on_pointer_released(context.callback(move |info: PointerEventInfo| {
                // 与浮层行同一手：把这次真实指针事件的窗口坐标记成滚轮锚点（轨的落点还要
                // 往左挪 `RAIL_WHEEL_LEFT_OFFSET_DIP`，见 `jump_to_rail_turn`）。
                scroll::note_anchor(
                    scroll::AnchorSource::Rail,
                    scroll::Point { x: info.window_x as i32, y: info.window_y as i32 },
                );
                Msg::RailJump(index, info.window_x as i32, info.window_y as i32)
            }))
            // #101：刻度项这一层**不写**任何 UIA 标识 —— 主干 `MainWindow.xaml:676-677` 只给列表
            // 本体 `TurnRailMarks` 挂 id + Name，条目模板根是裸 `<Grid Height="20">`（`:691-692`），
            // 整块 DataTemplate 里既没有 `AutomationProperties.AutomationId` 也没有
            // `AutomationProperties.Name`；刻度状态只经 `x:Bind MarkWidth/MarkOpacity` 传，命中走
            // `OnTurnRailMarkClick`（`OriginalSource` 即刻度项），全仓 `TurnRailMark` 的命中也全是
            // C# 类型名而非 id。分叉原先在这一层多写了一枚自造 id（#101 删的就是那枚）与一枚自造
            // `Name`（RT6 表4 D-1，本轮连同只喂它的 `active_name` 一起删）；宿主那一层
            // （`TurnRailHost`/`TurnRailMarks`）逐字对齐主干，别在这里补回去。
            .content(
                Rectangle::new()
                    .width(turnrail::mark_width(state))
                    .height(turnrail::MARK_HEIGHT)
                    .radius_x(turnrail::MARK_RADIUS)
                    .radius_y(turnrail::MARK_RADIUS)
                    .fill(p.accent.clone())
                    .opacity(turnrail::mark_opacity(state))
                    .horizontal_alignment(HorizontalAlignment::Right)
                    .vertical_alignment(VerticalAlignment::Center),
            )
            .into()
    }

    /// 预览卡：360 宽、贴在宿主左缘外（`Margin -370, y, 0, 0`）、`CardBrush` 底 + `StrokeBrush`
    /// 1px 描边 + `CornerMedium` + `Padding 12,10`，里面一条 `MaxHeight 480` 的纵向滚动带。
    /// prompt 走 `BodyTextStyle`（14 + 主文本色）、response 走 `HintTextStyle`（12 + Tertiary），
    /// 两段都 `Wrap`，并且都先过 `turnrail::break_long_tokens` —— 长路径没有断点会被裁成半截。
    fn turn_rail_preview(&self, mark: &TurnRailMark, index: usize, host: f64, p: Palette) -> View {
        // 卡高读不到（无 `ActualHeight`）⇒ 恒用标称 100，`preview_y` 里那个「实测」分支留着，
        // 框架哪天补上出口就换一个数即可。
        let y = turnrail::preview_y_for_slot(
            index,
            turnrail::LIST_INSET,
            turnrail::SLOT_PITCH,
            turnrail::CARD_NOMINAL_HEIGHT,
            host,
        );
        // RT6 表1 A-1：主干 `MainWindow.TurnRail.cs:372` 把 `BreakLongTokens` 套在**三元式外面**
        // ⇒ 兜底串也过断行；分叉原先只套非空那一支（今天「第 7 轮 / Turn 7」不含断点字符 ⇒ 不可
        // 观察，i18n 文案一改就露）。这里改成同形：选择式整体进 `break_long_tokens`。
        let fallback = self.catalog.lf("第 {0} 轮", &[mark.turn.to_string()]);
        let prompt = turnrail::break_long_tokens(if mark.prompt.is_empty() {
            &fallback
        } else {
            &mark.prompt
        });
        let mut lines: Vec<KeyedView> = vec![KeyedView::new(
            "prompt",
            View::from(
                TextBlock::new()
                    .text(prompt.clone())
                    .font_size(type_ramp::BODY.size)
                    .foreground(p.text_primary.clone())
                    .text_wrapping(TextWrapping::Wrap),
            ),
        )];
        if !mark.response.is_empty() {
            lines.push(KeyedView::new(
                "response",
                View::from(
                    TextBlock::new()
                        .text(turnrail::break_long_tokens(&mark.response))
                        .font_size(type_ramp::CAPTION.size)
                        .foreground(p.text_tertiary.clone())
                        .text_wrapping(TextWrapping::Wrap),
                ),
            ));
        }
        Border::new()
            .width(turnrail::CARD_WIDTH)
            .horizontal_alignment(HorizontalAlignment::Left)
            .vertical_alignment(VerticalAlignment::Top)
            .margin(th([turnrail::CARD_LEFT_OFFSET, y, 0.0, 0.0]))
            .background(p.card.clone())
            .border_brush(p.stroke.clone())
            .border_thickness(size::STROKE)
            .corner_radius(radius::MEDIUM)
            .padding(th(pad::RAIL_PREVIEW))
            // RT6 表4 D-2（本轮删）：主干那颗 `<Border x:Name="TurnRailPreviewCard"`
            // （`MainWindow.xaml:709`）整块属性里只有 `:719` 一枚 `AutomationProperties.AutomationId`，
            // **零枚** `AutomationProperties.Name` ⇒ 卡靠 id 定位，别再抄一份主行文案当 Name
            // （那会让同一段文字在 UIA 树里出现两遍，主干没这个形状）。
            .automation_id("TurnRailPreviewCard")
            .content(
                ScrollViewer::new()
                    .max_height(turnrail::CARD_MAX_HEIGHT)
                    .vertical_scroll_bar_visibility(ScrollBarVisibility::Auto)
                    .horizontal_scroll_bar_visibility(ScrollBarVisibility::Disabled)
                    .content(
                        StackPanel::new()
                            .orientation(Orientation::Vertical)
                            .spacing(space::S4)
                            .keyed_children(lines),
                    ),
            )
            .into()
    }

    /// 主干操作行那颗钮（`MakeCopyButton` / `MakeWithdrawEditButton`，
    /// `MainWindow.MessageActions.cs`）：`SmallButtonSize(28)` 正方 + `MinWidth=0` +
    /// `Padding=0` + `CornerRadius=RadSmall(4)` + 字形 `GlyphBody(14)`。
    /// **是小圆角方，不是正圆**（4 远小于短边一半 14 ⇒ `radius_clamped` 原样传下去），
    /// 也必须走 `pill_button` 外壳：裸 Button 的模板描边与默认 4px 底在分叉里渲成
    /// 「带 1px 描边的方角默认按钮」，而且 UIA 量到 56×53px（=28×26.5 DIP）非正方
    /// —— 模板 `MinHeight=32` 没被抵掉，得靠外壳的 `.min_height(0.0)`。
    fn icon_button(
        &self,
        code: char,
        id: &str,
        name: &str,
        tip: &str,
        enabled: bool,
        key: &str,
        message: Msg,
        p: Palette,
        context: &mut ViewContext<Shell>,
    ) -> View {
        let tip = self.catalog.l(tip);
        // 同一张卡里两颗钮的悬停键得互不相同 ⇒ 键由调用方带上气泡 key 传进来（`tooltip`
        // 收尾同 `feedback_toggle`：链上先出钮再补 tip）。
        pill_button(
            Button::new()
                .on_click(context.message(message))
                .automation_id(id.to_string())
                .automation_name(self.catalog.l(name)),
            mark_size(code, size::GLYPH_BODY),
            Pill::action(p, enabled),
            key,
            HoverSlot::Pill,
            self.pill_hover.as_deref(),
            self.pressed.as_deref(),
            context,
        )
        .tooltip(tip)
    }

    /// 主干轮尾的用量段：E81E（12px、.8）+「用量 X tok」；内核没回 usage 时整段不出现。
    fn tokens_group(&self, bubble: &Bubble, p: Palette) -> View {
        StackPanel::new()
            .orientation(Orientation::Horizontal)
            .spacing(space::S6)
            .vertical_alignment(VerticalAlignment::Center)
            .children((
                Border::new()
                    .opacity(0.8)
                    .content(mark_size(glyph::USAGE, size::GLYPH_CAPTION)),
                self.hint(
                    self.catalog
                        .lf("用量 {0} tok", &[tokens_text(self.catalog.locale(), bubble.tokens)]),
                    p,
                ),
            ))
    }

    /// 反馈组的一行（主干 `BuildFeedbackRow` 的行首六件套，`MainWindow.xaml.cs:16569`）：
    /// **Like → Dislike → Note → NoteText → Revoke → Status**，全从 `self.feedback` 现算。
    /// 六个状态各自怎么落：
    /// · Like/Dislike：**真的 `ToggleButton`**（`feedback_toggle`），`rating` 命中那颗
    ///   `IsChecked=true` ⇒ 模板自己画强调色选中档，另一颗 `false` ⇒ 默认 ControlFill 静置档；
    ///   再点同一颗 = 原生翻回 false → `set_feedback_rating` 走 delete（撤回），
    ///   点另一颗 = true → put 改判且把旧 note 带上（互斥切换）。UIA 那侧因此带 Toggle 模式。
    /// · Note：主干只在「本条已有反馈」时 Visible，标签按有无 note 在「添加说明/编辑说明」间切；
    ///   点开即 `Msg::OpenNote` → `note_for` 置位 → 气泡下方长出行内编辑器。
    /// · NoteText：有 note 才出现的一行摘要（`说明：{0}`，MaxWidth 420、省略号截断）。
    /// · Revoke：有反馈才出现的「撤销」，走 `Msg::Revoke` → `delete_feedback`。
    /// · Status：`feedback_status` 里有文案才出现（put/delete 的业务错误、冲突重试都落这里）。
    /// 主干 `ApplyFeedbackOpacity`：本条已有反馈时**整行**常驻 1.0，不等悬停。
    fn feedback_cells(
        &self,
        bubble: &Bubble,
        p: Palette,
        context: &mut ViewContext<Shell>,
    ) -> Vec<View> {
        let message = bubble.id.as_str();
        let item = feedback_of(&self.feedback, message);
        let rating = item
            .as_ref()
            .map(|item| item.rating.as_str())
            .unwrap_or_default();
        let note = item
            .as_ref()
            .and_then(|item| item.note.clone())
            .filter(|note| !note.is_empty());
        let mut cells = vec![
            self.feedback_toggle(
                glyph::THUMB_UP,
                "positive",
                "FeedbackLike",
                "有帮助（再点一次撤销）",
                message,
                rating == "positive",
                context,
            ),
            self.feedback_toggle(
                glyph::THUMB_DOWN,
                "negative",
                "FeedbackDislike",
                "没帮助（再点一次撤销）",
                message,
                rating == "negative",
                context,
            ),
        ];
        if item.is_some() {
            cells.push(self.feedback_text_button(
                if note.is_some() { "编辑说明" } else { "添加说明" },
                &format!("FeedbackNote_{message}"),
                Msg::OpenNote(message.to_string()),
                context,
            ));
        }
        if let Some(note) = note {
            cells.push(
                TextBlock::new()
                    .text(self.catalog.lf("说明：{0}", &[note]))
                    .font_size(type_ramp::CAPTION.size)
                    .foreground(p.text_tertiary)
                    .max_width(size::FEEDBACK_NOTE_MAX_WIDTH)
                    .text_wrapping(TextWrapping::NoWrap)
                    .text_trimming(TextTrimming::CharacterEllipsis)
                    .vertical_alignment(VerticalAlignment::Center)
                    .into(),
            );
        }
        if item.is_some() {
            cells.push(self.feedback_text_button(
                "撤销",
                &format!("FeedbackRevoke_{message}"),
                Msg::Revoke(message.to_string()),
                context,
            ));
        }
        let status = pair_value(&self.feedback_status, message, String::new());
        if !status.is_empty() {
            cells.push(self.hint(status, p));
        }
        cells
    }

    /// 主干 `MakeFeedbackToggle`（`MainWindow.xaml.cs`）：那颗赞/踩是**裸 `ToggleButton`** ——
    /// `Width=Height=SmallButtonSize(28)` + `MinWidth=0` + `Padding=0` +
    /// `CornerRadius=RadSmall(4)` + 字形 `GlyphBody(14)`，四态与选中态全交给 WinUI 的
    /// `DefaultToggleButtonStyle`（generic.xaml:544-556：静置 `ControlFillColorDefault`、
    /// 悬停 Secondary、按下 Tertiary、禁用 Disabled、**Checked = AccentFillColorDefault +
    /// 反白字形**），并且对 UIA 暴露 **Toggle 模式**。
    /// 上一版分叉用普通 `Button` + `Pill::feedback` 自绘 ⇒ 静置整块透明、也没有 Toggle 模式。
    /// 这一版改回 reactor 的 `ToggleButton`（`generated.rs:2297`：只有 `is_checked` /
    /// `is_enabled` / `on_is_checked_changed` 三个自有 setter）：
    /// · 它**没有** `resource_overrides` —— 正好，这一族要的就是模板那套原生状态层，
    ///   不需要钉透明，也天然避开「`.style(Accent)` 与资源覆盖同挂一钮」那族 fail-fast。
    /// · 它也设不了 `CornerRadius`/`Padding` ⇒ 圆角吃模板默认 `ControlCornerRadius=4`
    ///   （generic.xaml:2324/7878，**与主干 RadSmall 同值**，不用另设），默认 `Padding`
    ///   11,5,11,6 用负 margin 抵掉（不抵 28 的钮只剩 6×17 内容区，字形成一条横线）。
    /// · 事件口径与幂等守卫见 `Shell::set_feedback_rating`。
    fn feedback_toggle(
        &self,
        code: char,
        rating: &str,
        prefix: &str,
        tip: &str,
        message: &str,
        checked: bool,
        context: &mut ViewContext<Shell>,
    ) -> View {
        let tip = self.catalog.l(tip);
        let (toggled_message, toggled_rating) = (message.to_string(), rating.to_string());
        ToggleButton::new()
            .width(size::SMALL_BUTTON)
            .height(size::SMALL_BUTTON)
            .min_width(0.0)
            .min_height(0.0)
            .vertical_alignment(VerticalAlignment::Center)
            .is_checked(checked)
            .on_is_checked_changed(context.callback(move |on: bool| {
                Msg::Rate(toggled_message.clone(), toggled_rating.clone(), on)
            }))
            .automation_id(format!("{prefix}_{message}"))
            .automation_name(tip.clone())
            .content(
                Border::new()
                    .margin(th(TEMPLATE_INSET))
                    .content(mark_cell(code, size::GLYPH_BODY)),
            )
            .tooltip(tip)
    }

    /// 主干 `MakeFeedbackButton`：高 28、`Padding=8,0,8,0`、`CornerRadius=RadSmall(4)`、
    /// **不设字号**（= Body 14）的**文字**钮（「添加说明 / 编辑说明 / 撤销」），而且它是
    /// 裸 `Button`：没写 `Background`/`BorderThickness` ⇒ 静置 `ControlFillColorDefault` +
    /// 1px `ControlElevationBorderBrush` 描边全由默认模板给（`ControlCornerRadius` 默认就是
    /// 4，与主干 RadSmall 同值）。没进 `pill_button`：那颗把钮钉成正方形，文字钮要按内容
    /// 自适应宽度；模板那套本来就对，自绘反而会错。
    /// 负 margin 那一步仍按 `pill_button` 的口径来，把模板 `Padding=11,5,11,6` 抵成主干的
    /// `8,0,8,0`，否则文字区只剩 6×17。
    fn feedback_text_button(
        &self,
        label: &str,
        id: &str,
        message: Msg,
        context: &mut ViewContext<Shell>,
    ) -> View {
        let label = self.catalog.l(label);
        Button::new()
            .height(size::SMALL_BUTTON)
            .min_width(0.0)
            .vertical_alignment(VerticalAlignment::Center)
            .automation_id(id.to_string())
            .automation_name(label.clone())
            .on_click(context.message(message))
            .content(
                Border::new()
                    .margin(th([
                        size::FEEDBACK_BUTTON_PADDING - 11.0,
                        -5.0,
                        size::FEEDBACK_BUTTON_PADDING - 11.0,
                        -6.0,
                    ]))
                    .padding(th([size::FEEDBACK_BUTTON_PADDING, 0.0, size::FEEDBACK_BUTTON_PADDING, 0.0]))
                    .content(
                        TextBlock::new()
                            .text(label)
                            // 主干 `MakeFeedbackButton` **不设字号** ⇒ 吃 Button 默认的
                            // `ControlContentThemeFontSize` = 14（generic.xaml:5590，Body 档），
                            // 不是 caption 12。上一版按 CAPTION 排，墨迹高实测只有 23px≈12DIP。
                            .font_size(type_ramp::BODY.size)
                            .vertical_alignment(VerticalAlignment::Center),
                    ),
            )
    }

    /// 便签编辑器：主干是 `ContentDialog`（`EditFeedbackNoteAsync`，`xaml.cs:17945`，卡本体
    /// `:17959-17968`，那张的 `DefaultButton` 是 `Primary`）里的一个
    /// `AcceptsReturn` 多行 TextBox + 保存/取消；**分叉有对话框原语**（reactor 那一型
    /// builder 与原生两截都在货架上，见 [`WorkspaceDialogKind`] 的文档），这张**没挂进**
    /// 自绘那一族 ⇒ 展开在气泡下方（主干那张是模态、这张不是，这一格是**分叉自绘路线的
    /// 未做项**，不是框架缺口），形态仍是「多行输入 + 保存/取消 + 字数上限提示」。
    /// 上限按内核 `maxNoteBytes = 8192`（假内核回 `note-too-large{maxBytes,actualBytes}` 同值），
    /// **按 UTF-8 字节**算：超了先把「说明超长（上限 N 字节）」摆出来，保存不本地拦死，
    /// 仍让内核回业务错误、由行内 Status 落话（口径与主干一致）。
    fn note_editor(&self, p: Palette, context: &mut ViewContext<Shell>) -> View {
        let bytes = self.note_text.len() as i64;
        let over = bytes > MAX_NOTE_BYTES;
        let save = |label: &str, id: &str, accent: bool, column: i32, message: Msg| {
            let label = self.catalog.l(label);
            Button::new()
                // 强调色钮：`.style(ButtonStyle::Accent)` 只有在不和 `resource_overrides` 同挂
                // 一个 Button 时才安全（见文件头那条 fail-fast 复盘），这里两个都不碰资源。
                .style(if accent {
                    ButtonStyle::Accent
                } else {
                    ButtonStyle::Default
                })
                .min_height(size::COMPACT_BUTTON_MIN_HEIGHT)
                .vertical_alignment(VerticalAlignment::Center)
                .grid_column(column)
                .automation_id(id.to_string())
                .automation_name(label.clone())
                .on_click(context.message(message))
                .content(
                    TextBlock::new()
                        .text(label)
                        .font_size(type_ramp::CAPTION.size),
                )
        };
        Grid::new()
            .rows([GridLength::Auto, GridLength::Auto])
            .row_spacing(space::S6)
            .margin(th([0.0, space::S4, 0.0, 0.0]))
            // lc1 项2：容器**不自造** AutomationId（原来那颗 `FeedbackNoteEditor` 主干查无此串）。
            // 主干这条链的容器是 `ContentDialog`（`MW:17977-17985`，只给 Title/按钮文字，不带
            // `Aut()`/`AutomationId`），唯一的把手就是那颗多行框 `Aut(box, "FeedbackNoteTextBox",
            // "反馈说明")` ⇒ 下面 KeyedView "box" 那颗已逐字同款。这里也不挂 `FeedbackNote_<messageId>`：
            // 那颗串在主干属于操作行的「添加说明」钮（`MW:17399`，分叉同形状在 `feedback_cells` 里），
            // 编辑器展开时那颗钮还在屏上 ⇒ 同屏两个同 id 元素，驱动 FindById 会抢错。
            // 容器**不写** UIA Name：主干 `Aut(box, "FeedbackNoteTextBox", "反馈说明")` 里
            // 「反馈说明」这个名字属于那颗多行输入框，驱动脚本按 Name 取值，重名会抢错元素。
            .keyed_children(
                vec![
                    KeyedView::new(
                        "box",
                        TextBox::new()
                            .grid_row(0)
                            .text(self.note_text.clone())
                            .accepts_return(true)
                            .text_wrapping(TextWrapping::Wrap)
                            .min_height(size::FEEDBACK_NOTE_EDITOR_HEIGHT)
                            .max_height(size::FEEDBACK_NOTE_EDITOR_HEIGHT)
                            .placeholder_text(
                                self.catalog.l("这条回复哪里好 / 哪里不好（可选，纯文本）"),
                            )
                            .automation_id("FeedbackNoteTextBox")
                            .automation_name(self.catalog.l("反馈说明"))
                            .on_text_changed(context.callback(|text: String| Msg::NoteText(text))),
                    ),
                    KeyedView::new(
                        "row",
                        Grid::new()
                            .grid_row(1)
                            .columns([GridLength::STAR, GridLength::Auto, GridLength::Auto])
                            .column_spacing(space::S6)
                            .children((
                                StackPanel::new()
                                    .orientation(Orientation::Vertical)
                                    .grid_column(0)
                                    .vertical_alignment(VerticalAlignment::Center)
                                    .children((
                                        TextBlock::new()
                                            .text(self.catalog.lf(
                                                "{0}/{1} 字节",
                                                &[bytes.to_string(), MAX_NOTE_BYTES.to_string()],
                                            ))
                                            .font_size(type_ramp::CAPTION.size)
                                            .foreground(p.text_tertiary),
                                        if over {
                                            TextBlock::new()
                                                .text(self.catalog.lf(
                                                    "说明超长（上限 {0} 字节）",
                                                    &[MAX_NOTE_BYTES.to_string()],
                                                ))
                                                .font_size(type_ramp::CAPTION.size)
                                                .foreground(p.error)
                                                .into()
                                        } else {
                                            blank()
                                        },
                                    )),
                                save("保存", "FeedbackNoteSaveButton", true, 1, Msg::CloseNote(true)),
                                save(
                                    "取消",
                                    "FeedbackNoteCancelButton",
                                    false,
                                    2,
                                    Msg::CloseNote(false),
                                ),
                            )),
                    ),
                ]
                .into_iter()
                .collect::<Vec<KeyedView>>(),
            )
    }

    /// #93e：那颗「消息详情」。主干 `MakeMessageDetailsButton`
    /// （`MainWindow.MessageDetails.cs:1425-1442`）逐属性是：
    /// `Button{Width=Height=SmallButtonSize, MinWidth=0, Padding=0, CornerRadius=RadSmall,
    /// VerticalAlignment=Center, Content=FontIcon{Glyph="\uE946", FontSize=GlyphBody}}`
    /// ＋ `ToolTipService.SetToolTip(button, tip)` ＋ `Aut(button, "MessageDetailsButton", tip)`
    /// ＋ `Click → ShowMessageDetailsFlyout(button, bubble)`。
    ///
    /// 落点全部走分叉既有那颗的译法（同文件 `icon_button`，即主干 `MakeCopyButton` 那一族）：
    /// `Pill::action(p, true)` 供 `side=size::SMALL_BUTTON`(28) 与 `radius::SMALL`(4)（主干
    /// `SmallButtonSize` 实测是 28 而不是 32，见 `tokens.rs:167` 的登记），`pill_button` 供
    /// `min_width(0)` / `vertical_alignment(Center)` / 无 padding 与四态脸，
    /// `mark_size(字形, size::GLYPH_BODY)` 供 `FontSize=GlyphBody`(14) —— reactor 的 `FontIcon`
    /// **没有** `font_size` 槽（`generated.rs` 里 `FontIcon` 只有 `glyph`/`font_family`），
    /// 所以分叉一律用 Viewbox 缩放，这是既有口径不是新造。
    ///
    /// 与 `icon_button` 唯一的实质差别是文案档：主干那颗的 tip 是 `DetText("消息详情",
    /// "Message details")`（调用点自带英文档，`ShellEnglish` 表里没这两枚键）⇒ 这里走 `dt`。
    /// 走 `l` 的话英文界面会露中文（本仓定案的复发缺陷类），补进 EN 表又要造主干没有的键。
    /// 悬停键 `details-{key}` 与同排那颗复制钮 `copy-{key}` 错开（同卡里的两颗必须不同键，
    /// 否则悬停会同时提亮两颗）。
    fn message_details_button(
        &self,
        bubble: &Bubble,
        key: &str,
        p: Palette,
        context: &mut ViewContext<Shell>,
    ) -> View {
        let tip = self.catalog.dt("消息详情", "Message details");
        pill_button(
            Button::new()
                .on_click(context.message(Msg::DetailsToggle(
                    details_key_of(bubble).as_str().to_string(),
                )))
                .automation_id("MessageDetailsButton")
                .automation_name(tip.clone()),
            mark_size(MESSAGE_DETAILS_GLYPH, size::GLYPH_BODY),
            Pill::action(p, true),
            &format!("details-{key}"),
            HoverSlot::Pill,
            self.pill_hover.as_deref(),
            self.pressed.as_deref(),
            context,
        )
        .tooltip(tip)
    }

    /// 浮层现在展示的那颗气泡：状态格里存的是**键**，回查气泡表拿正文。
    /// 键在而气泡不在（切会话后整张表换了）与「没开」同义 ⇒ `chat_page` 那一格按这个判据
    /// 决定生不生成节点（reactor 没有 `Visibility`，收起 = 不生成，口径同两张既有浮层）。
    fn message_details_bubble(&self) -> Option<&Bubble> {
        let key = self.message_details.as_deref()?;
        self.bubbles
            .iter()
            .find(|bubble| details_key_of(bubble).as_str() == key)
    }

    /// 遮罩 + 卡片，⋯ 菜单那张层（[`file_action_menu_layer`]）的姊妹：透明 `Border` 铺满内容面、
    /// 按下即收起（主干是系统级 Flyout 的 light-dismiss，分叉只能自己画这层遮罩）。
    /// 入树顺序在 `file-menu` **之后** ⇒ 压过它（见 [`chat_page`] 那段偏序注释）。
    fn message_details_layer(&self, context: &mut ViewContext<Shell>, p: Palette) -> View {
        let scrim: View = Border::new()
            .grid_row(0)
            .horizontal_alignment(HorizontalAlignment::Stretch)
            .vertical_alignment(VerticalAlignment::Stretch)
            .background(p.transparent.clone())
            .on_pointer_pressed(context.callback(|_| Msg::DetailsClose))
            .into();
        Grid::new()
            .rows([GridLength::STAR])
            .children((scrim, self.message_details_card(context, p)))
    }

    /// 主干 `ShowMessageDetailsFlyout`（`MessageDetails.cs:1444-1597`）里**元数据那一节**的卡：
    /// `ScrollViewer{MaxHeight=480, VerticalScrollBarVisibility=Auto}`（`:1586-1594`）包一张
    /// `StackPanel{Spacing=Sp6, MinWidth=280, MaxWidth=420}`（`:1447`），首行是
    /// `MakeSectionLabel(DetText("元数据","Metadata"))`（`MainWindow.ToolCards.cs:986-995`：
    /// `CaptionTextStyle` + `Opacity=0.7` + `FontWeights.SemiBold`），其余行是那张
    /// `meta`（`Spacing=Sp2`）里的字段表，字段次序与「空值不占行」由
    /// [`message_detail_fields`] 兜（单测 `field_order_and_empty_values_do_not_take_a_row`）。
    ///
    /// 浮层现已画**五节**：元数据（本节）+ [`message_details_blocks`] 那四节（附加内容块
    /// `:1483` / 上下文注入 `:1492` / 跨会话召回 `:1520` / 系统提示词 `:1552`），以及卡尾
    /// `:1558` 那三枚复制钮。**仍不做的只剩「跨会话中继」那一节**（主干 `:1538-1550`，门
    /// `RelaySessionId`，UIA `DetailRelay`）：它不在 #139 那四件里，是独立的一件；分叉的中继
    /// 目前只长在操作行那颗 chip 上（`reference_chips` 的 `if let Some(relay)` 那一支）。
    /// 那一节缺席不改新节的相对次序（`Reference < Relay < Prompt` 去掉中继仍是
    /// `Reference < Prompt`）。
    ///
    /// 另两处**主干有、分叉有意不做**：`BuildContextCard`（`:1275`，门 `:1352` 的
    /// `ContextEntries.Count == 0` 对 system/message 气泡永不成立 ⇒ #139 不需要它）。
    ///
    /// 卡片外壳抄分叉既有那张 ⋯ 菜单（`p.card` 底 + `p.stroke` 1px + `radius::MEDIUM` +
    /// `margin th(pad::OVERLAY)` + 贴内容面右下），因为主干的 `FlyoutPresenter` 内边距**不在
    /// 主干源里**（系统模板给的）⇒ 编不出来。这里唯一一处借用：内边距用主干另一枚**有源**的
    /// token `pad::OVERLAY_HEADER`（= 主干 `OverlayHeaderMargin` 12,8,12,4，命令面板的标题行就
    /// 用它），不是自造数值，但也不是这颗浮层自己的规格 ⇒ 已备案在 `tmp/w93e-audit.md` 的 B1j
    /// （「抄不到的项 + 有意偏差」），
    /// 运行时拿主干截图量一次再定。
    fn message_details_card(
        &self,
        context: &mut ViewContext<Shell>,
        p: Palette,
    ) -> View {
        let Some(bubble) = self.message_details_bubble() else {
            // `chat_page` 那一格已经按同一判据筛过；走到这里只可能是状态与气泡表脱钩。
            return Border::new().into();
        };
        let key = details_key_of(bubble);
        let st = self.details.get(&key);
        let fields = message_detail_fields(bubble, st, &self.catalog);
        // 主干 `Field` 的两列：左列 `HintTextStyle`（caption 12 + TextTertiary）+ `MinWidth=72`，
        // 右列 `CaptionTextStyle`（12/16/Regular，**不覆前景** ⇒ 继承页面的主文本刷，这里就
        // 显式给 `p.text_primary`）+ `TextWrapping=Wrap`。行 `Spacing=Sp6`。
        let rows: Vec<KeyedView> = fields
            .iter()
            .enumerate()
            .map(|(index, field)| {
                let row: View = StackPanel::new()
                    .orientation(Orientation::Horizontal)
                    .spacing(space::S6)
                    .children((
                        TextBlock::new()
                            .text(self.catalog.bt(field.zh, field.en))
                            .font_size(type_ramp::CAPTION.size)
                            .foreground(p.text_tertiary.clone())
                            .min_width(DETAILS_LABEL_MIN_WIDTH)
                            .vertical_alignment(VerticalAlignment::Top),
                        TextBlock::new()
                            .text(field.value.clone())
                            .font_size(type_ramp::CAPTION.size)
                            .foreground(p.text_primary.clone())
                            .text_wrapping(TextWrapping::Wrap)
                            .vertical_alignment(VerticalAlignment::Top),
                    ))
                    .into();
                KeyedView::new(format!("detail-{index}"), row)
            })
            .collect();
        let section_label: View = TextBlock::new()
            // 主干 `MakeSectionLabel`（`MainWindow.ToolCards.cs:986-995`）：
            // `CaptionTextStyle` + `Opacity=0.7` + `FontWeights.SemiBold`。
            .text(self.catalog.dt("元数据", "Metadata"))
            .font_size(type_ramp::CAPTION.size)
            .opacity(0.7)
            .font_weight(FontWeight::SEMI_BOLD)
            .into();
        let meta: View = StackPanel::new()
            .orientation(Orientation::Vertical)
            .spacing(space::S2)
            .keyed_children(rows)
            .into();
        // ---- #93g：后四节。门、次序、节标题「换节才补一枚」全在 [`details_cells`] 里，
        // 这里只把那一格一格摊成节点：`Code` / `Prompt` = 主干 `MakeCodeBlock`（两档高度不同），
        // `Context` = 一张 `Sp2` 列表，`Reference` = 一行 `HyperlinkButton`，
        // `Section` = 一枚 `MakeSectionLabel`。
        let mut cells: Vec<KeyedView> = vec![
            KeyedView::new("section-metadata", section_label),
            KeyedView::new("meta", meta),
        ];
        for (index, cell) in details_cells(&message_details_blocks(st)).into_iter().enumerate() {
            let (view, key) = match cell {
                DetailsCell::Section(zh, en) => (self.details_section_label(zh, en), format!("section-{zh}")),
                DetailsCell::Block(block) => (
                    match block {
                        DetailsBlock::Code(text) => {
                            self.details_code_block(&text, p, DETAILS_CODE_MAX_HEIGHT)
                        }
                        DetailsBlock::Context(lines) => self.details_context_list(&lines, p),
                        DetailsBlock::Reference { sid, label } => {
                            let click = context
                                .message(Msg::OpenSessionRef(session_ref_target(&sid, &label)));
                            self.reference_row(
                                &format!("DetailRef_{label}"),
                                label.clone(),
                                label,
                                click,
                            )
                        }
                        // 主干 `:1555` 那一处 `MakeCodeBlock` 喂的是 140，与附加内容块那 100
                        // 不是一档 ⇒ 高度由形参给，不另立第二颗构建函数。
                        DetailsBlock::Prompt(text) => {
                            self.details_code_block(&text, p, DETAILS_PROMPT_MAX_HEIGHT)
                        }
                    },
                    format!("detail-block-{index}"),
                ),
            };
            cells.push(KeyedView::new(key, view));
        }
        // ---- #139 件二：卡尾那三枚复制钮（主干 `:1558-1584`，`panel.Children.Add(copyRow)`
        // 在 `:1584` ⇒ 整张卡的**最后一格**，且**没有节标题**）。
        //
        // 门：**无条件** —— 主干那一段整段不带 `st` 判据，`st` 为 `None` 只影响 payload 的
        // 内容，不影响这一行出不出现。行 = `StackPanel{Horizontal, Spacing=Sp4}`（`:1559`），
        // 钮 = `CompactButtonStyle` ⇒ 现成的 [`compact_button`]（其文档已备案那四档形制）。
        //
        // 文案通道 = 四枚串**全走 `bt`**（三枚钮面 + 回落那一枚）。判据不是「`l(zh)` 是否
        // 恒等」而是「该 zh 键有没有登记进主干 `ShellEnglish`」：`复制属性路径` 在册
        // （`MainWindow.xaml.cs:1096` = "Copy property path"）、`已复制` 在册（`:1090` =
        // "Copied"）；两枚 `*JSON` 不在册，而 `bt` 对无键串与 `dt` 今日面值相同、`zh-TW` 档
        // 还更贴主干 ⇒ 同一段不留两种通道。
        // ⚠ 喂进 `compact_button` 的必须是**已经选完档**的那一串：那颗内部走 `catalog.l(label)`
        // （#62 那一族的成因），直接喂 zh 原串会让两枚 `*JSON` 在英文界面露中文；喂已选档串
        // 时 `l()` 查不到 ⇒ 原样返回，安全。
        //
        // 「已复制」的回落：主干用 1 秒 DispatcherQueue 定时器，reactor 借不到定时器 ⇒ 沿用
        // 本仓既有口径（见 `Msg::Hover` 那一臂的注释：指针离开那颗钮的容器即回落），容器就是
        // 下面这层 `Border`。键逐字用 UIA id —— `DetailCopy_` 前缀与操作行那颗 `bubble_key`
        // 天然不同域，所以 `copied` 这一格不用另开第二套状态。
        // 主干这三颗**没有** tooltip（`:1561-1582` 整段零次 `ToolTipService`）⇒ 这里也不给。
        let payload = build_detail_json(bubble, st);
        let copy_hover_key = "detail-copy-row";
        let copy_buttons: Vec<KeyedView> = [
            (
                "复制格式化 JSON",
                "Copy pretty JSON",
                "DetailCopy_Copy_pretty_JSON",
                pretty_json(&payload),
            ),
            (
                "复制紧凑 JSON",
                "Copy compact JSON",
                "DetailCopy_Copy_compact_JSON",
                compact_json(&payload),
            ),
            (
                "复制属性路径",
                "Copy property path",
                "DetailCopy_Copy_property_path",
                detail_property_path(bubble),
            ),
        ]
        .into_iter()
        .enumerate()
        .map(|(index, (zh, en, id, text))| {
            // 主干 `Aut(b, id, DetText(zh, en))` 在构建时写一次、点完不换 ⇒ Name 恒为本钮
            // 那一档，只有钮面（`b.Content`）换成「已复制」。
            let name = self.catalog.bt(zh, en);
            let shown = if self.copied.as_deref() == Some(id) {
                self.catalog.bt("已复制", "Copied")
            } else {
                name.clone()
            };
            let button: View =
                self.compact_button(&shown, Msg::Copy(id.to_string(), text), id, &name, context);
            KeyedView::new(format!("detail-copy-{index}"), button)
        })
        .collect();
        let copy_row: View = Border::new()
            .background(p.transparent.clone())
            .on_pointer_entered(context.callback(move |_| Msg::Hover(Some(copy_hover_key.to_string()))))
            .on_pointer_exited(context.callback(|_| Msg::Hover(None)))
            .content(
                StackPanel::new()
                    .orientation(Orientation::Horizontal)
                    .spacing(space::S4)
                    .keyed_children(copy_buttons),
            )
            .into();
        cells.push(KeyedView::new(copy_hover_key, copy_row));
        Border::new()
            .grid_row(0)
            .horizontal_alignment(HorizontalAlignment::Right)
            .vertical_alignment(VerticalAlignment::Bottom)
            .margin(th(pad::OVERLAY))
            .background(p.card.clone())
            .border_brush(p.stroke.clone())
            .border_thickness(size::STROKE)
            .corner_radius(radius::MEDIUM)
            .padding(th(pad::OVERLAY_HEADER))
            .content(
                ScrollViewer::new()
                    .max_height(DETAILS_SCROLL_MAX_HEIGHT)
                    .vertical_scroll_bar_visibility(ScrollBarVisibility::Auto)
                    .content(
                        StackPanel::new()
                            .orientation(Orientation::Vertical)
                            .spacing(space::S6)
                            .min_width(DETAILS_PANEL_MIN_WIDTH)
                            .max_width(DETAILS_PANEL_MAX_WIDTH)
                            // 两段先各自落成 `View`：`children` 的元组里混着两种构建器时
                            // `.into()` 的目标推不出来。列表是动态长度 ⇒ keyed_children。
                            .keyed_children(cells),
                    ),
            )
            .into()
    }

    /// 主干 `MakeSectionLabel`（`MainWindow.ToolCards.cs:986-995`）：`CaptionTextStyle`
    /// + `Opacity=0.7` + `FontWeights.SemiBold`。
    ///
    /// 文案通道 = `bt`（#148 E2 的那一枚换道，**保真**而非修缺陷）：喂进来的四枚节标题里
    /// `上下文注入`（`MainWindow.xaml.cs:1199` = "Context injection"）与 `系统提示词`
    /// （`:1197` = "System prompt"）在主干 `ShellEnglish` **在册**，`附加内容块`/`跨会话召回`
    /// 不在册。主干 `DetText` 的口径就是「字典先赢」⇒ `bt` 才是同一通道；在册那两枚分叉 EN 表
    /// 里同值 ⇒ 今日面值零差，只有 `zh-TW` 档 `bt` 落简体 = 主干（`dt` 会落英文）。
    /// 不在册那两枚走 `bt` 的 `zh` 前缀兜底门，结果与 `dt` 相同。
    /// **同一颗函数体里不许留两种通道** ⇒ 元数据那一节的节标题（主干 `:1449`）仍按 `dt`：
    /// `["元数据"]` 在主干 `ShellEnglish` 零命中，那一枚由源码锁钉着，不随本枚换道。
    fn details_section_label(&self, zh: &'static str, en: &'static str) -> View {
        TextBlock::new()
            .text(self.catalog.bt(zh, en))
            .font_size(type_ramp::CAPTION.size)
            .opacity(0.7)
            .font_weight(FontWeight::SEMI_BOLD)
            .into()
    }

    /// 主干 `MakeCodeBlock(text, wrap: true, maxHeight: 100)`（`MainWindow.ToolCards.cs:1086-1105`）
    /// + 里面的 `MakeCodeText`（`:1107-1119`）。逐格照抄的形制：
    /// `Border{Background=CardSecondaryBrush, CornerRadius=6, Padding=(Sp6,Sp2,Sp6,Sp2),
    /// HorizontalAlignment=Stretch}` 包 `ScrollViewer{Horizontal=Disabled(wrap:true 那一档),
    /// Vertical=Auto, MaxHeight=100, HorizontalAlignment=Stretch}` 包 `TextBlock{FontSize=12,
    /// TextWrapping=Wrap, IsTextSelectionEnabled=true, Foreground=TextSecondaryBrush,
    /// HorizontalAlignment=Stretch}`。
    ///
    /// 抄不动的一档：`CodeFont()`（`FontFamily=CodeFontFamily`，回落 Consolas）—— reactor 的
    /// `TextBlock` 公开面没有 font_family 槽（全仓既有的同一处缺口，见 `command_palette` 与
    /// 「JSON 视图」那两处自陈）⇒ 等宽落到默认字体上，已记进报告「抄不到的项」。
    ///
    /// `max_height` 收**入参**：主干那颗 `MakeCodeBlock` 的 `maxHeight` 本来就是形参，同一个
    /// 值文件里喂了 100 / 120 / 140 / 160 / 200 五档（见 [`DETAILS_CODE_MAX_HEIGHT`] 的文档）。
    /// [`Shell::domain_code_block`] 是那一批过程卡点上的同形件；本颗是浮层点这一族的。
    fn details_code_block(&self, text: &str, p: Palette, max_height: f64) -> View {
        Border::new()
            .background(p.card_secondary.clone())
            .corner_radius(CODE_BLOCK_CORNER_RADIUS)
            .padding(th(CODE_BLOCK_PADDING))
            .horizontal_alignment(HorizontalAlignment::Stretch)
            .content(
                ScrollViewer::new()
                    // 主干 `wrap: true` ⇒ `HorizontalScrollBarVisibility = Disabled`
                    //（不换行才给 Auto）；纵向一律 Auto。
                    .horizontal_scroll_bar_visibility(ScrollBarVisibility::Disabled)
                    .vertical_scroll_bar_visibility(ScrollBarVisibility::Auto)
                    .max_height(max_height)
                    .horizontal_alignment(HorizontalAlignment::Stretch)
                    .content(
                        TextBlock::new()
                            .text(text.to_string())
                            .font_size(CODE_BLOCK_FONT_SIZE)
                            .foreground(p.text_secondary.clone())
                            .text_wrapping(TextWrapping::Wrap)
                            .is_text_selection_enabled(true)
                            .horizontal_alignment(HorizontalAlignment::Stretch),
                    ),
            )
            .into()
    }

    /// 主干「上下文注入」那节的 `list`（`:1496`，`StackPanel{Spacing=Sp2}`）：每条 entry 最多两枚
    /// `TextBlock` —— 标题 `CaptionTextStyle` + `FontWeights.SemiBold`（`:1501-1506`，**不覆前景**
    /// ⇒ 继承页面主文本刷，分叉显式给 `text_primary`，与本卡右列同口径；主干那枚标题**没有**
    /// `TextWrapping=Wrap`，只有正文那枚有 ⇒ 分叉照抄这个不对称）；正文 `HintTextStyle` +
    /// `TextWrapping=Wrap`（`:1510-1515`）= caption 12 + `TextTertiaryBrush`，文本已经过
    /// [`clip_context_text`] 的 400 字截断。判空在 [`context_lines`] 里已经做完。
    fn details_context_list(&self, lines: &[ContextLine], p: Palette) -> View {
        let rows: Vec<KeyedView> = lines
            .iter()
            .enumerate()
            .map(|(index, line)| {
                let view: View = match line {
                    ContextLine::Title(text) => TextBlock::new()
                        .text(text.clone())
                        .font_size(type_ramp::CAPTION.size)
                        .foreground(p.text_primary.clone())
                        .font_weight(FontWeight::SEMI_BOLD)
                        .into(),
                    ContextLine::Text(text) => TextBlock::new()
                        .text(text.clone())
                        .font_size(type_ramp::CAPTION.size)
                        .foreground(p.text_tertiary.clone())
                        .text_wrapping(TextWrapping::Wrap)
                        .into(),
                };
                KeyedView::new(format!("context-{index}"), view)
            })
            .collect();
        StackPanel::new()
            .orientation(Orientation::Vertical)
            .spacing(space::S2)
            .keyed_children(rows)
            .into()
    }

    /// #93g：那张「跨会话召回」列表层 = 遮罩 + 卡片，[`message_details_layer`] 的姊妹
    /// （主干是系统级 `Flyout` 的 light-dismiss，分叉只能自绘这层遮罩）。
    fn session_ref_layer(&self, context: &mut ViewContext<Shell>, p: Palette) -> View {
        let scrim: View = Border::new()
            .grid_row(0)
            .horizontal_alignment(HorizontalAlignment::Stretch)
            .vertical_alignment(VerticalAlignment::Stretch)
            .background(p.transparent.clone())
            .on_pointer_pressed(context.callback(|_| Msg::CloseSessionRefs))
            .into();
        Grid::new().rows([GridLength::STAR]).children((
            scrim,
            self.session_ref_list(context, p),
        ))
    }

    /// 主干 `ShowSessionReferenceFlyout`（`MainWindow.MessageDetails.cs:1398-1421`）的表体：
    /// `StackPanel{Spacing=Sp4, MinWidth=220}`（`:1400`），每条引用一颗 `HyperlinkButton`
    /// {Content=label, Padding=0, HorizontalAlignment=Left}（`:1403-1408`），
    /// `Aut(link, "SessionRefItem_" + label, label)`（`:1409`，**中文 label 就这么拼进 id**，
    /// 主干原样，已备案），点击 = 先 `f.Hide()` 再
    /// `OpenReferencedSessionAsync(sid 非空 ? sid : label)`（`:1411-1415`）。
    ///
    /// 外壳与「消息详情」那张卡同一型制（贴内容面右下，读不回锚点矩形 ⇒ 已记进「有意偏差」），
    /// 但**不给** `MaxHeight` 的 `ScrollViewer`：主干那张 flyout 里就没有滚动件，
    /// 只有一列 `HyperlinkButton`。
    fn session_ref_list(&self, context: &mut ViewContext<Shell>, p: Palette) -> View {
        let rows: Vec<KeyedView> = self
            .session_refs
            .as_deref()
            .unwrap_or_default()
            .iter()
            .enumerate()
            .map(|(index, (sid, label))| {
                let link = self.reference_row(
                    &format!("SessionRefItem_{label}"),
                    label.clone(),
                    label.clone(),
                    context.message(Msg::OpenSessionRef(session_ref_target(sid, label))),
                );
                KeyedView::new(format!("session-ref-{index}"), link)
            })
            .collect();
        Border::new()
            .grid_row(0)
            .horizontal_alignment(HorizontalAlignment::Right)
            .vertical_alignment(VerticalAlignment::Bottom)
            .margin(th(pad::OVERLAY))
            .background(p.card.clone())
            .border_brush(p.stroke.clone())
            .border_thickness(size::STROKE)
            .corner_radius(radius::MEDIUM)
            .padding(th(pad::OVERLAY_HEADER))
            .content(
                StackPanel::new()
                    .orientation(Orientation::Vertical)
                    .spacing(space::S4)
                    .min_width(SESSION_REF_PANEL_MIN_WIDTH)
                    .keyed_children(rows),
            )
            .into()
    }

    /// 「跨会话召回」那一节与列表层共用的行：主干两处的形制是同一枚
    /// （`HyperlinkButton{Padding=0, HorizontalAlignment=Left}`，`:1403-1408` / `:1526-1531`）。
    ///
    /// 与 [`reference_link`][Self::reference_link] 的差别只有一处、而且是主干就有的差别：
    /// chip 那颗带 `Margin=(Sp4,0,0,0)`（`:263`/`:278` 的**横向**间隔），列表行**不带**margin
    /// 而是 `HorizontalAlignment=Left`。所以这里不复用 chip 那把，免得每一行凭空缩进 4 DIP。
    /// 共同的两处降级同 §D-4（`Padding=0` 与 `FontSize=11`：reactor 的 `HyperlinkButton` /
    /// `LayoutControl` 都没有 padding 槽 ⇒ 内边距只能吃默认模板那一档，字号改挂在内容上）。
    fn reference_row(
        &self,
        id: &str,
        text: String,
        name: String,
        message: Callback<()>,
    ) -> View {
        HyperlinkButton::new()
            .horizontal_alignment(HorizontalAlignment::Left)
            .automation_id(id.to_string())
            .automation_name(name)
            .on_click(message)
            .content(
                TextBlock::new()
                    .text(text)
                    .font_size(11.0)
                    .vertical_alignment(VerticalAlignment::Center),
            )
    }

    /// 气泡下的操作行（主干 `BuildFeedbackRow` 那一整行）：
    /// **反馈组（赞/踩/说明/说明摘要/撤销/状态）→ 复制 → 分支 → 时钟 → 型号 → 用量 → 用时**。
    /// 静置 0.35（用户行 0.62 且右对齐），指针进来或本条已有反馈时提到 1。
    fn bubble_actions(
        &self,
        bubble: &Bubble,
        is_answer: bool,
        closed: bool,
        p: Palette,
        context: &mut ViewContext<Shell>,
    ) -> View {
        let key = bubble_key(bubble);
        let user = bubble.role == "user";
        let copied = self.copied.as_deref() == Some(key.as_str());
        let lit = self.hover.as_deref() == Some(key.as_str());
        let mut cells: Vec<View> = Vec::new();
        if user {
            if bubble.time > 0 {
                cells.push(self.hint(message_clock(bubble.time), p));
            }
            if !bubble.model.is_empty() {
                cells.push(self.hint(format!("· {}", bubble.model), p));
            }
        }
        // 主干 `BuildFeedbackRow`：反馈组要按内核 `message.id` 寻址，无 id 的气泡（错误占位、
        // 用户行、工具/思考/交付物行）整组不出现；这一组排在复制之前（主干同一行的行首）。
        let feedback = !user && !bubble.id.is_empty();
        if feedback {
            cells.extend(self.feedback_cells(bubble, p, context));
        }
        // 主干 `ApplyFeedbackOpacity`：本条已有反馈 ⇒ 整行常驻 1.0，不等悬停。
        let rated = feedback && feedback_of(&self.feedback, &bubble.id).is_some();
        cells.push(self.icon_button(
            if copied { glyph::COPIED } else { glyph::COPY },
            "MessageCopyButton",
            "复制消息",
            if copied { "已复制" } else { "复制消息" },
            true,
            &format!("copy-{key}"),
            Msg::Copy(key.clone(), bubble.text.clone()),
            p,
            context,
        ));
        // 主干那颗「消息详情」（`MessageDetails.cs:1425-1442`）**两行各有**，都紧接在复制钮之后：
        // · 用户行 `MainWindow.MessageActions.cs:94`（`BuildUserActionsRow`，下一发是 `:96` 的
        //   `AppendReferenceChips`）；
        // · **助手/答案行 `MainWindow.xaml.cs:17429`**（`BuildFeedbackRow`，函数文档 `:17425` 就写着
        //   「操作组：复制 / 详情 / 分支 / 时间戳 / 本轮用时」）—— 次序是 `:17426` 复制 → `:17429`
        //   详情 → `:17434` 分支 → `:17455` 时钟 → `:17465` 型号 → `:17474` 用量 → `:17489` 用时。
        // 分叉把主干那两行并成了这一枚 `bubble_actions`（`if user` / `if !user` 两支共用同一段复制
        // 钮），所以这一发**不裹任何行别判据**：推在两支的分叉点之前 ⇒ 用户行拿到「复制→详情→chips」、
        // 助手行拿到「复制→详情→分支→…」，两侧次序各与主干那一行逐格对上。
        cells.push(self.message_details_button(bubble, &key, p, context));
        // 主干 `AppendReferenceChips`（`MainWindow.MessageActions.cs:253` 定义、`:96` 调用）排在
        // 那颗详情钮之后（`:94`→`:96`），再后面是 `:98-101` 的撤回编辑钮 —— 撤回编辑那一支分叉
        // 还没挂（独立确证见 `tmp/w93e-audit.md` A14 行）。**只给用户行**：
        // 主干那层 `UserActionsHost` 只长在用户气泡模板里（`MainWindow.xaml:492`）。
        if user {
            cells.extend(self.reference_chips(bubble, context));
        }
        if !user {
            if is_answer && bubble.seq > 0 {
                cells.push(self.icon_button(
                    glyph::OPEN_IN_APP,
                    "MessageBranchButton",
                    "在新对话中分支",
                    if closed {
                        "在新对话中分支"
                    } else {
                        "仅可从已完成轮次的最后一条消息分支"
                    },
                    closed,
                    &format!("branch-{key}"),
                    Msg::Branch(bubble.seq),
                    p,
                    context,
                ));
            }
            if bubble.time > 0 {
                cells.push(self.hint(message_clock(bubble.time), p));
            }
            if !bubble.model.is_empty() {
                cells.push(self.hint(format!("· {}", bubble.model), p));
            }
            if bubble.tokens > 0 {
                cells.push(self.tokens_group(bubble, p));
            }
            if is_answer && bubble.duration_ms > 0 {
                cells.push(
                    self.hint(
                        self.catalog
                            .lf("用时 {0}", &[duration_text(bubble.duration_ms)]),
                        p,
                    ),
                );
            }
        }
        let idle = if user {
            size::ROW_OPACITY_USER
        } else {
            size::ROW_OPACITY_ASSISTANT
        };
        let row = StackPanel::new()
            .orientation(Orientation::Horizontal)
            .spacing(space::S4)
            .margin(th([0.0, if user { 0.0 } else { space::S4 }, 0.0, 0.0]))
            .opacity(if lit || rated { 1.0 } else { idle })
            .keyed_children(
                cells
                    .into_iter()
                    .enumerate()
                    .map(|(index, cell)| KeyedView::new(format!("a{index}"), cell))
                    .collect::<Vec<KeyedView>>(),
            );
        // 助手行嵌在气泡 Border 里，主干的 hover 钩子也挂在那层（PointerEntered 会冒泡上来）；
        // 用户行是独立一段，主干把钩子挂在行本身，所以这里补一层 Border 当命中面。
        if !user {
            return row.into();
        }
        let role = bubble.role;
        Border::new()
            .background(p.transparent)
            .horizontal_alignment(HorizontalAlignment::Right)
            // 用户行与助手行同属正文带：这一发的指针事件也是 #89 贴底落点的证据（判据同 `bubble_anchor_source`）。
            .on_pointer_entered(context.callback(move |info: PointerEventInfo| {
                note_bubble_anchor(role, scroll::Point { x: info.window_x as i32, y: info.window_y as i32 });
                Msg::Hover(Some(key.clone()))
            }))
            .on_pointer_exited(context.callback(|_| Msg::Hover(None)))
            .content(row)
    }

    /// 主干 `AppendReferenceChips`（`MainWindow.MessageActions.cs:252-285`）：用户气泡那一行的
    /// 跨会话引用 chips，**两颗互斥**、中继优先（主干就是 `if (relay)` + `else if (references)`）。
    ///
    /// 数据只从旁路表来（主干 `_messageDetails.TryGetValue(bubble, out var st)`）：没有那一行
    /// ⇒ 一颗都不画。UIA 的 Name 用**原始** sessionId / labels，而可见文本的中继那颗用
    /// [`short_session_label`]（截 8 位 + `…`）—— 这个「Name 与文本不一致」是主干原样
    /// （`:260` 的 Content 用 `ShortSessionLabel(relay)` vs `:266` 的 Aut 用 `relay`），照抄并备案。
    fn reference_chips(&self, bubble: &Bubble, context: &mut ViewContext<Shell>) -> Vec<View> {
        let Some(st) = self.details.get(&details_key_of(bubble)) else {
            return Vec::new();
        };
        if let Some(relay) = st.relay_session_id.as_deref() {
            let arg = |value: String| {
                self.catalog.dtf(
                    "来自会话 {0}",
                    "From session {0}",
                    &[value],
                )
            };
            let message = context.message(Msg::OpenSessionRef(relay.to_string()));
            return vec![self.reference_link(
                "UserRelayLink",
                arg(short_session_label(relay)),
                arg(relay.to_string()),
                message,
            )];
        }
        if st.references.is_empty() {
            return Vec::new();
        }
        // 主干 `:272`：`string.Join(DetText("、", ", "), st.References.Select(r => r.Label))`
        let sep = self.catalog.dt("、", ", ");
        let labels = st
            .references
            .iter()
            .map(|(_, label)| label.clone())
            .collect::<Vec<String>>()
            .join(&sep);
        let text = self.catalog.dtf(
            "引用会话 · {0}",
            "Referenced session · {0}",
            &[labels],
        );
        let message = context.message(Msg::SessionRefList(st.references.clone()));
        vec![self.reference_link(
            "UserReferenceLink",
            text.clone(),
            text,
            message,
        )]
    }

    /// 上面那两颗 chip 的形制：主干 `HyperlinkButton` + `Padding=0` + `Margin=(Sp4,0,0,0)` +
    /// `FontSize=11` + `VerticalAlignment=Center`。
    ///
    /// 降级依据（不是「框架不支持」）：reactor 0.100.0 **有** `HyperlinkButton`
    /// （`src/generated.rs:576-638`，`ContentControl` + `LayoutControl` + `AutomationExt` 全齐 ⇒
    /// `automation_id`/`automation_name`/`on_click` 都挂得上），所以控件本体不降级；缺的只有两个槽：
    /// · `Padding=0` —— `LayoutControl`（`src/element.rs:2217` 起）只暴露 width/height/margin/
    ///   opacity/alignment 等，没有 `padding`，而 `HyperlinkButton` 自己的 builder
    ///   （`generated.rs:584-621`）只有 `navigate_uri`/`is_enabled`/`on_click` ⇒ 内边距只能吃
    ///   WinUI 默认模板那一档（比主干宽一截）。
    /// · `FontSize=11` —— 同理没有 `font_size` 槽，改挂在内容那颗 `TextBlock` 上（主干那颗
    ///   `ContentPresenter` 里的文字继承控件字号，两处最终作用在同一枚字形上 ⇒ 视觉等效）。
    /// 两条都进「留给运行时 GUI 验收」。
    fn reference_link(
        &self,
        id: &str,
        text: String,
        name: String,
        message: Callback<()>,
    ) -> View {
        HyperlinkButton::new()
            .margin(th([space::S4, 0.0, 0.0, 0.0]))
            .vertical_alignment(VerticalAlignment::Center)
            .automation_id(id.to_string())
            .automation_name(name)
            .on_click(message)
            .content(
                TextBlock::new()
                    .text(text)
                    .font_size(11.0)
                    .vertical_alignment(VerticalAlignment::Center),
            )
    }

    /// 主干 `ToolCallTpl` 的行：图标 12/.8 + 标题 + 半个透明度的「·」+ .85 的摘要。
    /// 主干运行态还有一道 LinearGradientBrush 扫光（Storyboard），reactor 没有动画原语，抄不了。
    fn tool_line(&self, bubble: &Bubble, p: Palette) -> View {
        let Some(code) = bubble.icon else {
            // 主干 `ToolTpl`：system/message 那类灰行，没图标、没摘要段、可换行、0.62。
            return Border::new()
                .margin(th(pad::LIST_ITEM))
                .padding(th(pad::BUBBLE_TOOL))
                .content(
                    TextBlock::new()
                        .text(bubble.text.clone())
                        .font_size(type_ramp::CAPTION.size)
                        .foreground(p.text_primary.clone())
                        .opacity(0.62)
                        .text_wrapping(TextWrapping::Wrap)
                        .is_text_selection_enabled(true),
                );
        };
        let mut cells: Vec<View> = vec![
            Border::new()
                .opacity(0.8)
                .content(mark_size(code, size::GLYPH_CAPTION)),
            TextBlock::new()
                .text(self.catalog.l(bubble.text.as_str()))
                .font_size(type_ramp::CAPTION.size)
                .foreground(p.text_primary.clone())
                .vertical_alignment(VerticalAlignment::Center)
                .into(),
        ];
        if !bubble.summary.is_empty() {
            cells.push(
                TextBlock::new()
                    .text("·")
                    .font_size(type_ramp::CAPTION.size)
                    .foreground(p.text_primary.clone())
                    .opacity(0.5)
                    .vertical_alignment(VerticalAlignment::Center)
                    .into(),
            );
            cells.push(
                TextBlock::new()
                    .text(bubble.summary.clone())
                    .font_size(type_ramp::CAPTION.size)
                    .foreground(p.text_primary.clone())
                    .opacity(0.85)
                    .text_wrapping(TextWrapping::NoWrap)
                    .text_trimming(TextTrimming::CharacterEllipsis)
                    .vertical_alignment(VerticalAlignment::Center)
                    .into(),
            );
        }
        Border::new()
            .margin(th(pad::LIST_ITEM))
            .padding(th(pad::BUBBLE_TOOL))
            .content(
                StackPanel::new()
                    .orientation(Orientation::Horizontal)
                    .spacing(space::S6)
                    .opacity(0.72)
                    // #101：这颗 id 原来是分叉自造的 `ToolCallRow`（主干全仓 0 命中，只有
                    // `MessageActions.cs:585` 的方法名 `BuildToolCallRow`）。同一位置主干写的是
                    // 卡根 `MainWindow.ToolCards.cs:273` 的 `ToolCard` ⇒ 换成主干那枚，不自造名。
                    .automation_id("ToolCard")
                    .automation_name(self.catalog.l(bubble.text.as_str()))
                    .keyed_children(
                        cells
                            .into_iter()
                            .enumerate()
                            .map(|(index, cell)| KeyedView::new(format!("t{index}"), cell))
                            .collect::<Vec<KeyedView>>(),
                    ),
            )
    }

    /// #104 主干 `BuildMaxTokensCard`（`MainWindow.MessageDetails.cs:932-962`）逐件复刻：
    /// 卡根 `StackPanel{HAlign=Stretch, Margin=(4,1,4,1), Spacing=Sp2}`（`:899-904`）
    /// ＋ `AutomationId="MessageDomainCard_" + tool`（`:905`，**只给 id、不给 Name**），
    /// 三行子件：
    /// 1. `:934-943` 行头：`StackPanel{Horizontal, Spacing=Sp6, VAlign=Center}` 装
    ///    `FontIcon{E7BA, 12, WarningBrush}` ＋ 标题 `TextBlock`（`CaptionTextStyle`
    ///    + `FontWeights.SemiBold` + `WarningBrush`）；
    /// 2. `:944-951` 说明：`TextBlock{HintTextStyle, Wrap}`（`HintTextStyle` 继承
    ///    `CaptionTextStyle`、只把前景换成 `TextTertiaryBrush` ⇒ 档位仍是 CAPTION 那一档）；
    /// 3. `:952-961` 「发送继续」钮：`CompactButtonStyle` + `HAlign=Left` + `Margin=(0,Sp2,0,0)`
    ///    + `Aut(id="MaxTokensContinueButton", name=钮面文案)`。
    ///
    /// 主干这一案**没有** `Count>0` 门、**没有**展开态：`BuildMaxTokensCard(root, bubble)`
    /// 通体不读 `bubble` 参数（只有签名用了它），三行一次性画完。
    ///
    /// 抄不动的一项（有逐字节证据，进「UIA 挂账」）：`FontIcon` 那颗的 `WarningBrush` 前景。
    /// reactor 0.100.0 全 crate 唯一的 `foreground` setter 长在 `TextBlock` 上
    /// （`generated.rs:465`），`impl FontIcon`（`generated.rs:3267-3282`）只有 `glyph` /
    /// `glyph_optional` ⇒ 字形着色在本框架无槽（与本文件 `:2004` 那条既有结论同一处缺口）。
    /// 标题那枚 `TextBlock` 的 `WarningBrush` 是能钉的，已钉。
    fn max_tokens_card(&self, p: Palette, context: &mut ViewContext<Shell>) -> View {
        let title = self
            .catalog
            .dt("已达到输出 token 上限", "Output token limit reached");
        let button = self.catalog.dt("发送继续", "Send continue");
        StackPanel::new()
            .horizontal_alignment(HorizontalAlignment::Stretch)
            .margin(th([4.0, 1.0, 4.0, 1.0]))
            .spacing(space::S2)
            .automation_id(format!("MessageDomainCard_{MAX_TOKENS_TOOL}"))
            .children((
                StackPanel::new()
                    .orientation(Orientation::Horizontal)
                    .spacing(space::S6)
                    .vertical_alignment(VerticalAlignment::Center)
                    .children((
                        mark_size(MAX_TOKENS_GLYPH, size::GLYPH_CAPTION),
                        View::from(
                            TextBlock::new()
                                .text(title)
                                .font_size(type_ramp::CAPTION.size)
                                .font_weight(FontWeight::SEMI_BOLD)
                                .foreground(p.warning.clone())
                                .text_wrapping(TextWrapping::Wrap)
                                .vertical_alignment(VerticalAlignment::Center),
                        ),
                    )),
                TextBlock::new()
                    .text(self.catalog.dt(
                        "回答被截断，已有输出保留在对话中。发送“继续”可让模型接着输出。",
                        "The reply was cut off; earlier output is preserved in the conversation. Send \"continue\" to let the model resume.",
                    ))
                    .font_size(type_ramp::CAPTION.size)
                    .foreground(p.text_tertiary.clone())
                    .text_wrapping(TextWrapping::Wrap),
                Button::new()
                    .style(ButtonStyle::Default)
                    .min_height(size::COMPACT_BUTTON_MIN_HEIGHT)
                    .horizontal_alignment(HorizontalAlignment::Left)
                    .margin(th([0.0, space::S2, 0.0, 0.0]))
                    .automation_id("MaxTokensContinueButton")
                    .automation_name(button.clone())
                    .on_click(context.message(Msg::SendContinue))
                    .content(
                        TextBlock::new()
                            .text(button)
                            .font_size(type_ramp::CAPTION.size),
                    ),
            ))
    }

    /// 主干思考段行（`MessageActions.cs:428`）：`ToggleButton` 头（透明底、无边框）+ 收起态
    /// 摘要，展开才画正文。分叉用 Button 加透明覆盖件复刻头部（ToggleButton 没有背景/内边距
    /// setter，也拿不到 resource_overrides），展开态按气泡键记在 `reasoning_open`。
    fn reasoning_row(&self, bubble: &Bubble, p: Palette, context: &mut ViewContext<Shell>) -> View {
        let key = bubble_key(bubble);
        let open = self.reasoning_open.iter().any(|item| item == &key);
        let first = bubble.text.lines().next().unwrap_or_default().to_string();
        let header = StackPanel::new()
            .orientation(Orientation::Horizontal)
            .spacing(space::S6)
            .children((
                mark_size(
                    if open {
                        glyph::THINK_OPEN
                    } else {
                        glyph::CHEVRON_RIGHT
                    },
                    size::GLYPH_MINI,
                ),
                TextBlock::new()
                    .text(self.catalog.l("思考"))
                    .font_size(type_ramp::CAPTION.size)
                    .foreground(p.text_primary.clone())
                    .vertical_alignment(VerticalAlignment::Center),
                TextBlock::new()
                    .text(first)
                    .font_size(type_ramp::CAPTION.size)
                    .foreground(p.text_tertiary.clone())
                    .max_width(480.0)
                    .text_wrapping(TextWrapping::NoWrap)
                    .text_trimming(TextTrimming::CharacterEllipsis)
                    .vertical_alignment(VerticalAlignment::Center),
            ));
        let mut lines: Vec<View> = vec![
            Button::new()
                .min_width(0.0)
                .resource_overrides(
                    // 主干是 ToggleButton{Background=Transparent, BorderThickness=0}。reactor 的
                    // ToggleButton 没暴露这两个 setter，所以退回 Button + 主题资源覆盖；
                    // 「无描边」只能靠四态透明画刷，`ButtonBorderThemeThickness` 是 double 型键，
                    // 用 Thickness 覆它会让 WinUI fail-fast（见 `button_flat` 注释）。
                    ResourceOverrides::new()
                        .set("ButtonBackground", Color::transparent())
                        .set("ButtonBackgroundPointerOver", Color::transparent())
                        .set("ButtonBackgroundPressed", Color::transparent())
                        .set("ButtonBackgroundDisabled", Color::transparent())
                        .set("ButtonBorderBrush", Color::transparent())
                        .set("ButtonBorderBrushPointerOver", Color::transparent())
                        .set("ButtonBorderBrushPressed", Color::transparent())
                        .set("ButtonBorderBrushDisabled", Color::transparent())
                        .set("ControlCornerRadius", CornerRadius::uniform(radius::SMALL)),
                )
                .horizontal_alignment(HorizontalAlignment::Left)
                .horizontal_content_alignment(HorizontalAlignment::Left)
                .automation_id("ReasoningToggle")
                .automation_name(self.catalog.l("思考"))
                .on_click(context.message(Msg::Reason(key.clone(), !open)))
                .content(header)
                .tooltip(self.catalog.l("思考"))
                .into(),
        ];
        if open {
            lines.push(
                TextBlock::new()
                    .text(bubble.text.clone())
                    .font_size(type_ramp::BODY.size)
                    .foreground(p.text_primary.clone())
                    .opacity(0.78)
                    .margin(th([20.0, space::S2, 0.0, 0.0]))
                    .text_wrapping(TextWrapping::Wrap)
                    .is_text_selection_enabled(true)
                    .into(),
            );
        }
        Border::new().margin(th(pad::LIST_ITEM)).content(
            StackPanel::new()
                .orientation(Orientation::Vertical)
                .keyed_children(
                    lines
                        .into_iter()
                        .enumerate()
                        .map(|(index, line)| KeyedView::new(format!("r{index}"), line))
                        .collect::<Vec<KeyedView>>(),
                ),
        )
    }

    /// 主干 `DeliverableTpl`：气泡材质的卡（r=12、padding 12,10）里嵌「交付物」标题 +
    /// 每个文件一张 r=8 的卡。打开/回显走宿主路由 `POST /api/present.open`（见 `present_open`）。
    /// #111 主干 `BuildRetryCard`（`MainWindow.MessageDetails.cs:964-1015`）逐件复刻：卡根同
    /// [`Shell::max_tokens_card`]（`MessageDomainCard_` + tool + `Margin=(4,1,4,1)` + `Spacing=Sp2`，
    /// **不设 Name**，`:899-905`）。子件按主干那两处条件分派：
    /// 1. 行头 `StackPanel{Horizontal, Spacing=Sp6}`（`:972`，**没有** `VAlign=Center`，与截断卡那处
    ///    不同）：`FontIcon{E72C,12,InfoBrush}` + 状态 `TextBlock{CaptionTextStyle}`，文本 =
    ///    `retry_for_bubble` 找到的行现算 [`retry_status_line`]，找不到回落「等待…」（`:977`，
    ///    主干 `st is null ? DetText(...) : RetryStatusLine(st)`）。
    /// 2. `st is not null` 才画：detail `StackPanel{Spacing=Sp2, Margin=(18,0,0,0)}`（`:985`）装
    ///    「重试延迟」（HintTextStyle）+ 有失败才有的「失败原因」行（`:991-1001`）；再 `state=="scheduled"`
    ///    才挂「取消重试」钮（`:1006-1015`，`Aut(id="CancelRetryButton", name=钮面文案)`）。
    ///
    /// `retry_for_bubble` 先按气泡寻址键对号、找不到回落 `_modelRetries` 最后插入的一个
    /// （`:966-969` 主干自带那发 `st ??= LastOrDefault()`，逐字照抄、不改成按 turn 查）。FontIcon
    /// 的 InfoBrush 前景与截断卡那颗的 WarningBrush 同因（reactor 无 `FontIcon.foreground` 槽）
    /// 落不进 ⇒ 运行时挂账（报告 §7）。
    fn model_retry_card(
        &self,
        bubble: &Bubble,
        p: Palette,
        context: &mut ViewContext<Shell>,
    ) -> View {
        let key = bubble_key(bubble);
        let st = self.details.retry_for_bubble(&key);
        let now_ms = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map(|span| span.as_millis() as i64)
            .unwrap_or(0);
        let status_text = match st {
            Some(st) => retry_status_line(&self.catalog, st, now_ms),
            None => self
                .catalog
                .dt("等待重试模型请求", "Waiting to retry model request"),
        };
        let header = StackPanel::new()
            .orientation(Orientation::Horizontal)
            .spacing(space::S6)
            .children((
                mark_size(RETRY_GLYPH, size::GLYPH_CAPTION),
                View::from(
                    TextBlock::new()
                        .text(status_text)
                        .font_size(type_ramp::CAPTION.size),
                ),
            ));
        let mut parts = vec![KeyedView::new("retry-header", View::from(header))];
        if let Some(st) = st {
            let mut detail = vec![KeyedView::new(
                "retry-delay",
                View::from(
                    TextBlock::new()
                        .text(self.catalog.dtf(
                            "重试延迟：{0} ms",
                            "Retry delay: {0} ms",
                            &[st.delay_ms.to_string()],
                        ))
                        .font_size(type_ramp::CAPTION.size)
                        .foreground(p.text_tertiary.clone()),
                ),
            )];
            if !st.failure_message.is_empty() || !st.failure_code.is_empty() {
                let mut reason = self.catalog.dt("失败原因：", "Failure reason: ");
                if !st.failure_code.is_empty() {
                    reason.push_str(&format!("[{}] ", st.failure_code));
                }
                reason.push_str(&st.failure_message);
                detail.push(KeyedView::new(
                    "retry-failure",
                    View::from(
                        TextBlock::new()
                            .text(reason)
                            .font_size(type_ramp::CAPTION.size)
                            .foreground(p.text_tertiary.clone())
                            .text_wrapping(TextWrapping::Wrap),
                    ),
                ));
            }
            parts.push(KeyedView::new(
                "retry-detail",
                View::from(
                    StackPanel::new()
                        .spacing(space::S2)
                        .margin(th([18.0, 0.0, 0.0, 0.0]))
                        .keyed_children(detail),
                ),
            ));
            if st.state == "scheduled" {
                let button = self.catalog.dt("取消重试", "Cancel retry");
                parts.push(KeyedView::new(
                    "retry-cancel",
                    View::from(
                        Button::new()
                            .style(ButtonStyle::Default)
                            .min_height(size::COMPACT_BUTTON_MIN_HEIGHT)
                            .horizontal_alignment(HorizontalAlignment::Left)
                            .margin(th([0.0, space::S2, 0.0, 0.0]))
                            .automation_id("CancelRetryButton")
                            .automation_name(button.clone())
                            .on_click(context.message(Msg::CancelModelRetry(key.clone())))
                            .content(
                                TextBlock::new()
                                    .text(button)
                                    .font_size(type_ramp::CAPTION.size),
                            ),
                    ),
                ));
            }
        }
        StackPanel::new()
            .horizontal_alignment(HorizontalAlignment::Stretch)
            .margin(th([4.0, 1.0, 4.0, 1.0]))
            .spacing(space::S2)
            .automation_id(format!("MessageDomainCard_{RETRY_TOOL}"))
            .keyed_children(parts)
    }

    fn deliverable_card(
        &self,
        bubble: &Bubble,
        p: Palette,
        context: &mut ViewContext<Shell>,
    ) -> View {
        let files: Vec<KeyedView> = bubble
            .files
            .iter()
            .map(|(index, raw, description)| {
                let name = raw
                    .rsplit(['/', '\\'])
                    .next()
                    .filter(|tail| !tail.is_empty())
                    .unwrap_or(raw.as_str())
                    .to_string();
                let path = raw.replace('\\', "/");
                let mut cells: Vec<KeyedView> = vec![
                    KeyedView::new(
                        "name",
                        TextBlock::new()
                            .text(name.clone())
                            .font_size(type_ramp::BODY.size)
                            .foreground(p.text_primary.clone())
                            .text_wrapping(TextWrapping::NoWrap)
                            .text_trimming(TextTrimming::CharacterEllipsis),
                    ),
                    KeyedView::new(
                        "path",
                        TextBlock::new()
                            .text(path.clone())
                            .font_size(type_ramp::CODE.size)
                            .foreground(p.text_primary.clone())
                            .text_wrapping(TextWrapping::NoWrap)
                            .text_trimming(TextTrimming::CharacterEllipsis)
                            .is_text_selection_enabled(true),
                    ),
                ];
                // 主干 DescriptionVisibility：说明为空整行收起，不占位。
                if !description.is_empty() {
                    cells.push(KeyedView::new(
                        "description",
                        self.hint(description.clone(), p),
                    ));
                }
                KeyedView::new(
                    format!("file-{index}"),
                    Border::new()
                        .background(p.card)
                        .border_brush(p.stroke)
                        .border_thickness(th([size::STROKE; 4]))
                        .corner_radius(radius::MEDIUM)
                        .padding(th([10.0, 8.0, 10.0, 8.0]))
                        .margin(th([0.0, 0.0, 0.0, space::S4]))
                        .content(
                            Grid::new()
                                .columns([GridLength::STAR, GridLength::Auto])
                                .column_spacing(space::S10)
                                .children((
                                    StackPanel::new()
                                        .orientation(Orientation::Vertical)
                                        .spacing(space::S2)
                                        .keyed_children(cells),
                                    StackPanel::new()
                                        .orientation(Orientation::Horizontal)
                                        .spacing(space::S6)
                                        .grid_column(1)
                                        .vertical_alignment(VerticalAlignment::Center)
                                        .children((
                                            self.text_button(
                                                "打开",
                                                "PresentedFileOpenButton",
                                                Msg::Present(bubble.seq, *index, "open".into()),
                                                context,
                                            ),
                                            // 主干 MX:636-641 的第二颗不是文字钮，是 `E712` 图标钮
                                            // + 一张五项 flyout（`FileActionMenu`）。
                                            self.file_action_trigger(
                                                bubble.seq,
                                                *index,
                                                context,
                                            ),
                                        )),
                                )),
                        ),
                )
            })
            .collect();
        Border::new()
            .margin(th(pad::LIST_ITEM))
            .background(p.bubble)
            .border_brush(p.stroke_subtle)
            .border_thickness(size::STROKE)
            .corner_radius(radius::LARGE)
            .padding(th([12.0, 10.0, 12.0, 10.0]))
            .content(
                StackPanel::new()
                    .orientation(Orientation::Vertical)
                    .spacing(space::S6)
                    .keyed_children(
                        vec![KeyedView::new(
                            "head",
                            StackPanel::new()
                                .orientation(Orientation::Horizontal)
                                .spacing(space::S6)
                                .children((
                                    mark_size(glyph::WORKSPACE, size::GLYPH_BODY),
                                    TextBlock::new()
                                        .text(self.catalog.l("交付物"))
                                        .font_size(type_ramp::CAPTION.size)
                                        .foreground(p.text_primary.clone())
                                        .text_wrapping(TextWrapping::NoWrap)
                                        .vertical_alignment(VerticalAlignment::Center)
                                        .automation_id("DeliverableCardTitle"),
                                )),
                        )]
                        .into_iter()
                        .chain(files)
                        .collect::<Vec<KeyedView>>(),
                    ),
            )
    }

    /// 主干 `MakeChip(text, brush, mono: false, id)`（`MainWindow.ToolCards.cs:997-1021`）的分叉
    /// 等价件：`Border{CornerRadius=4, Padding=(Sp4,1,Sp4,1), Background=SoftBrushFrom(brush,0.1)}`
    /// 包一枚 `TextBlock{CaptionTextStyle, Foreground=brush, MaxWidth=280,
    /// Trimming=CharacterEllipsis}`。**UIA id 长在 TextBlock 上**（`:1013`，不是外层那颗 Border）
    /// ⇒ 主干那枚 `WorkflowMemberStatus` 的寻址层级在这里必须同形。
    ///
    /// 底色走 [`soft_brush_from`]（主干那一句推导法本身，不是它的近似）：分叉吃得到实色的三档
    /// （`completed`→`success` / `cancelled`→`warning` / `_`→`text_secondary`）⇒ 同色 10% 底，
    /// 与主干逐字同果；吃不到的两档（`workflow`→`info`、`failed`→`error` 都是 `Brush::Theme`，
    /// 没有可拆的 RGBA 通道）⇒ 落主干自己那句「非 solid ⇒ Transparent」。主干那两枚在 XAML 里
    /// 确实写成 `SolidColorBrush`（`Theme/Tokens.xaml:186-190`）⇒ **这两档底色仍与主干不等价**，
    /// 残留偏差登记报告 §4/§7（补它得先给 `theme.rs` 开一枚带 RGB 的状态色出口）。
    /// 上一版这里写的是「底色统一退成中性 `p.control_fill`」—— 那是**多做**：`control_fill` 是
    /// `ControlFillColorDefault`（浅 `#B3FFFFFF` / 深 `#0FFFFFFF`），五档全画同一层不透明的白/黑底，
    /// 而主干五档各是**该档前景色**的 10% ⇒ 方向就错了，不只是差一档透明度。
    fn domain_status_chip(&self, text: String, foreground: Brush, p: Palette, id: &str) -> View {
        let background = soft_brush_from(&foreground, CHIP_SOFT_ALPHA, &p);
        Border::new()
            .background(background)
            .corner_radius(4.0)
            .padding(th([space::S4, 1.0, space::S4, 1.0]))
            .content(
                TextBlock::new()
                    .text(text)
                    .font_size(type_ramp::CAPTION.size)
                    .foreground(foreground)
                    .max_width(280.0)
                    .text_trimming(TextTrimming::CharacterEllipsis)
                    .automation_id(id),
            )
    }

    /// [`Shell::details_code_block`] 的**同形件**，只把 `maxHeight` 收成入参：主干
    /// `MakeCodeBlock` 的 `maxHeight` 本来就是**形参**，`MainWindow.MessageDetails.cs` 里
    /// 现测五处五档（`:1084` 压缩摘要 160 / `:1354` 提示词 200 / `:1361` 附加块 120 /
    /// `:1489` 浮层附加块 100 / `:1555` 浮层系统提示词 140），合并成一枚常量就是把另几档改歪。
    /// 当年「不就地给 `details_code_block` 加参数」的那句避让已经作废：#139 件二那一批就是
    /// `message_details_card` → `bubble_actions` 那把锁窗的主人，窗内那颗已收形参。本枚留着
    /// 是因为过程卡侧那几档不该去引用浮层自己那族常量名（两族各表各的出处）。
    fn domain_code_block(&self, text: &str, p: Palette, max_height: f64) -> View {
        Border::new()
            .background(p.card_secondary.clone())
            .corner_radius(CODE_BLOCK_CORNER_RADIUS)
            .padding(th(CODE_BLOCK_PADDING))
            .horizontal_alignment(HorizontalAlignment::Stretch)
            .content(
                ScrollViewer::new()
                    .horizontal_scroll_bar_visibility(ScrollBarVisibility::Disabled)
                    .vertical_scroll_bar_visibility(ScrollBarVisibility::Auto)
                    .max_height(max_height)
                    .horizontal_alignment(HorizontalAlignment::Stretch)
                    .content(
                        TextBlock::new()
                            .text(text.to_string())
                            .font_size(CODE_BLOCK_FONT_SIZE)
                            .foreground(p.text_secondary.clone())
                            .text_wrapping(TextWrapping::Wrap)
                            .is_text_selection_enabled(true)
                            .horizontal_alignment(HorizontalAlignment::Stretch),
                    ),
            )
    }

    /// #139 件三：主干 `BuildCompactionCard`（`MainWindow.MessageDetails.cs:1020-1093`）逐件复刻。
    /// 卡根同另两张过程卡（`MessageDomainCard_` + tool、`Margin=(4,1,4,1)`、`Spacing=Sp2`、
    /// **不设 Name**，`:897-905`）。子件：
    /// 1. 行头那颗 `ToggleButton{Background=Transparent, BorderThickness=0,
    ///    Padding=(Sp4,Sp2,Sp2,Sp2), HAlign=Stretch, HContentAlign=Left, IsEnabled=expandable}`
    ///    （`:1041-1050`，`Aut(id=CompactionExpand, name=「上下文已压缩」)`）—— reactor 的
    ///    ToggleButton 没有背景/内边距 setter ⇒ 同 [`Shell::reasoning_row`] 那发退成 Button +
    ///    四态透明覆盖件，展开态按气泡键记在 [`Shell::compaction_open`]。
    ///    内件序逐条对齐 `:1052-1073`：chevron(10) → 压缩字形 E943(12, Opacity 0.85) →
    ///    标题(Caption + Medium) → `·`(Opacity .45) → 状态句(Hint + 截断省略号)。
    /// 2. 摘要体：`StackPanel{Margin=(22,Sp2,0,0)}` 包 `MakeCodeBlock(summary, wrap, 160)`，
    ///    主干靠 `Visibility` 开合、分叉只在展开档**不入树**（Collapsed 与不入树在流式布局同果）。
    ///
    /// 三处**有意偏差**（都记进报告 §4）：
    /// · 主干 `IsChecked = st?.Expanded` 读的是格内态；分叉展开态按气泡键记，而查格会回落
    ///   「最后插入那一格」⇒ 键与格不同源时以**键**为准（否则点 A 卡会翻开 B 卡的摘要）。
    /// · `IsEnabled = expandable` 一判两用了三回（钮能不能点、Checked/Unchecked 挂不挂、体是否可展）
    ///   ⇒ 这里同判据现算，不另立第二道门。
    /// · 主干 `FontWeights.Medium` 在 reactor 的 `FontWeight` 常量表里没有对应档 ⇒ 沿用本仓既有
    ///   先例（截断卡标题同一档）落 `SEMI_BOLD`。
    fn compaction_card(
        &self,
        bubble: &Bubble,
        p: Palette,
        context: &mut ViewContext<Shell>,
    ) -> View {
        let key = bubble_key(bubble);
        let row = compaction_row_for(&self.compactions, &key);
        let expandable = compaction_expandable(row);
        let open = expandable && self.compaction_open.iter().any(|item| item == &key);
        let title = self.catalog.dt("上下文已压缩", "Context compacted");
        let header = StackPanel::new()
            .orientation(Orientation::Horizontal)
            .spacing(space::S6)
            .vertical_alignment(VerticalAlignment::Center)
            .children((
                mark_size(
                    if open {
                        COMPACTION_CHEVRON_OPEN
                    } else {
                        COMPACTION_CHEVRON
                    },
                    size::GLYPH_MINI,
                ),
                mark_faded(COMPACTION_GLYPH, size::GLYPH_CAPTION, 0.85),
                View::from(
                    TextBlock::new()
                        .text(title.clone())
                        .font_size(type_ramp::CAPTION.size)
                        .font_weight(FontWeight::SEMI_BOLD)
                        .vertical_alignment(VerticalAlignment::Center),
                ),
                View::from(
                    TextBlock::new()
                        .text("·")
                        .font_size(type_ramp::CAPTION.size)
                        .opacity(0.45)
                        .vertical_alignment(VerticalAlignment::Center),
                ),
                View::from(
                    TextBlock::new()
                        .text(compaction_state_line(&self.catalog, row))
                        .font_size(type_ramp::CAPTION.size)
                        .foreground(p.text_tertiary.clone())
                        .text_wrapping(TextWrapping::NoWrap)
                        .text_trimming(TextTrimming::CharacterEllipsis)
                        .vertical_alignment(VerticalAlignment::Center),
                ),
            ));
        let mut parts = vec![KeyedView::new(
            "compaction-header",
            View::from(
                Button::new()
                    .min_width(0.0)
                    .resource_overrides(
                        ResourceOverrides::new()
                            .set("ButtonBackground", Color::transparent())
                            .set("ButtonBackgroundPointerOver", Color::transparent())
                            .set("ButtonBackgroundPressed", Color::transparent())
                            .set("ButtonBackgroundDisabled", Color::transparent())
                            .set("ButtonBorderBrush", Color::transparent())
                            .set("ButtonBorderBrushPointerOver", Color::transparent())
                            .set("ButtonBorderBrushPressed", Color::transparent())
                            .set("ButtonBorderBrushDisabled", Color::transparent())
                            .set(
                                "ButtonPadding",
                                th([space::S4, space::S2, space::S2, space::S2]),
                            ),
                    )
                    .horizontal_alignment(HorizontalAlignment::Stretch)
                    .horizontal_content_alignment(HorizontalAlignment::Left)
                    .is_enabled(expandable)
                    .automation_id("CompactionExpand")
                    .automation_name(title)
                    .on_click(context.message(Msg::CompactionToggle(key.clone())))
                    .content(header),
            ),
        )];
        if open {
            if let Some(summary) = row.and_then(|row| row.summary.as_deref()) {
                if !summary.is_empty() {
                    parts.push(KeyedView::new(
                        "compaction-body",
                        StackPanel::new().margin(th(DOMAIN_CARD_BODY_MARGIN)).keyed_children(vec![
                            KeyedView::new(
                                "summary",
                                self.domain_code_block(summary, p, COMPACTION_SUMMARY_MAX_HEIGHT),
                            ),
                        ]),
                    ));
                }
            }
        }
        StackPanel::new()
            .horizontal_alignment(HorizontalAlignment::Stretch)
            .margin(th([4.0, 1.0, 4.0, 1.0]))
            .spacing(space::S2)
            .automation_id(format!("MessageDomainCard_{COMPACTION_TOOL}"))
            .keyed_children(parts)
    }

    /// #139 件四：主干 `BuildWorkflowRunCard`（`MainWindow.MessageDetails.cs:1095-1200`）逐件复刻。
    /// 卡根同上（`MessageDomainCard_` + `workflow-run`）。子件：
    /// 1. 行头 `StackPanel{Horizontal, Spacing=Sp6, VAlign=Center}`（`:1122`）：
    ///    E945(12, .85) → 运行名(Caption + Medium) → `·`(.45) → count 段(Hint) → `·`(.45) →
    ///    运行级状态段(Hint)。count 与状态都是**纯函数现算**（[`workflow_members_count_line`] /
    ///    [`workflow_run_status_line`]），档位差异见那两颗的文档（运行级失败 = `error`）。
    /// 2. `st is null || Members.Count == 0` ⇒ **整段 return**（`:1143`）：成员列表与那颗
    ///    展开钮一个都不画，卡只剩行头一行。
    /// 3. 成员列表 `StackPanel{Spacing=Sp2, Margin=(22,Sp2,0,0)}`（`:1145`），每行
    ///    `StackPanel{Horizontal, Spacing=Sp6}` = [`Shell::domain_status_chip`]（id
    ///    `WorkflowMemberStatus`）+ 成员名（Hint + 截断省略号）。成员级取色四档 + `_` 中性档
    ///    逐条照 `:1155-1162`；文案走 [`workflow_member_status_line`]（与运行级**不同表**）。
    /// 4. 展开钮 `Button{CompactButtonStyle, HAlign=Left, Margin=(0,Sp2,0,0)}`（`:1180-1197`），
    ///    `Aut(id=WorkflowMembersToggle, name=count 段)`，钮面文案随展开态在「N 个成员」与
    ///    「收起成员」之间翻（`:1193-1196`）。
    ///
    /// 与主干同的一点：`list` 与 `toggle` 都在 `st is null || count == 0` 那道门**之后**才建，
    /// 所以「查不到格」与「成员为空」两档在分叉长出完全一样的一行头。
    fn workflow_run_card(
        &self,
        bubble: &Bubble,
        p: Palette,
        context: &mut ViewContext<Shell>,
    ) -> View {
        let key = bubble_key(bubble);
        let row = workflow_run_for(&self.workflow_runs, &key);
        let count = row.map_or(0, |row| row.members.len());
        let name = match row.map(|row| row.name.clone()) {
            Some(name) if !name.is_empty() => name,
            _ => bubble.text.clone(),
        };
        let count_line = workflow_members_count_line(&self.catalog, count);
        let header = StackPanel::new()
            .orientation(Orientation::Horizontal)
            .spacing(space::S6)
            .vertical_alignment(VerticalAlignment::Center)
            .children((
                mark_faded(WORKFLOW_RUN_GLYPH, size::GLYPH_CAPTION, 0.85),
                View::from(
                    TextBlock::new()
                        .text(name)
                        .font_size(type_ramp::CAPTION.size)
                        .font_weight(FontWeight::SEMI_BOLD)
                        .vertical_alignment(VerticalAlignment::Center),
                ),
                View::from(
                    TextBlock::new()
                        .text("·")
                        .font_size(type_ramp::CAPTION.size)
                        .opacity(0.45)
                        .vertical_alignment(VerticalAlignment::Center),
                ),
                View::from(
                    TextBlock::new()
                        .text(count_line.clone())
                        .font_size(type_ramp::CAPTION.size)
                        .foreground(p.text_tertiary.clone())
                        .vertical_alignment(VerticalAlignment::Center),
                ),
                View::from(
                    TextBlock::new()
                        .text("·")
                        .font_size(type_ramp::CAPTION.size)
                        .opacity(0.45)
                        .vertical_alignment(VerticalAlignment::Center),
                ),
                View::from(
                    TextBlock::new()
                        .text(workflow_run_status_line(
                            &self.catalog,
                            row.and_then(|row| row.stop_reason.as_deref()),
                        ))
                        .font_size(type_ramp::CAPTION.size)
                        .foreground(p.text_tertiary.clone())
                        .vertical_alignment(VerticalAlignment::Center),
                ),
            ));
        let mut parts = vec![KeyedView::new("workflow-header", View::from(header))];
        if let Some(row) = row.filter(|row| !row.members.is_empty()) {
            let open = self.workflow_open.iter().any(|item| item == &key);
            let members: Vec<KeyedView> = row
                .members
                .iter()
                .enumerate()
                .map(|(index, member)| {
                    let outcome = member.outcome.as_deref();
                    let brush = match outcome {
                        None => p.info.clone(),
                        Some("completed") => p.success.clone(),
                        Some("failed") => p.error.clone(),
                        Some("cancelled") => p.warning.clone(),
                        Some(_) => p.text_secondary.clone(),
                    };
                    KeyedView::new(
                        format!("m{index}"),
                        View::from(
                            StackPanel::new()
                                .orientation(Orientation::Horizontal)
                                .spacing(space::S6)
                                .children((
                                    self.domain_status_chip(
                                        workflow_member_status_line(&self.catalog, outcome),
                                        brush,
                                        p.clone(),
                                        "WorkflowMemberStatus",
                                    ),
                                    View::from(
                                        TextBlock::new()
                                            .text(workflow_member_label(&self.catalog, member))
                                            .font_size(type_ramp::CAPTION.size)
                                            .foreground(p.text_tertiary.clone())
                                            .text_wrapping(TextWrapping::NoWrap)
                                            .text_trimming(TextTrimming::CharacterEllipsis)
                                            .vertical_alignment(VerticalAlignment::Center),
                                    ),
                                )),
                        ),
                    )
                })
                .collect();
            if open {
                parts.push(KeyedView::new(
                    "workflow-members",
                    StackPanel::new()
                        .spacing(space::S2)
                        .margin(th(DOMAIN_CARD_BODY_MARGIN))
                        .keyed_children(members),
                ));
            }
            let face = if open {
                self.catalog.dt("收起成员", "Hide members")
            } else {
                count_line.clone()
            };
            parts.push(KeyedView::new(
                "workflow-toggle",
                View::from(
                    Button::new()
                        .style(ButtonStyle::Default)
                        .min_height(size::COMPACT_BUTTON_MIN_HEIGHT)
                        .horizontal_alignment(HorizontalAlignment::Left)
                        .margin(th([0.0, space::S2, 0.0, 0.0]))
                        .automation_id("WorkflowMembersToggle")
                        .automation_name(count_line)
                        .on_click(context.message(Msg::WorkflowToggle(key.clone())))
                        .content(
                            TextBlock::new()
                                .text(face)
                                .font_size(type_ramp::CAPTION.size),
                        ),
                ),
            ));
        }
        StackPanel::new()
            .horizontal_alignment(HorizontalAlignment::Stretch)
            .margin(th([4.0, 1.0, 4.0, 1.0]))
            .spacing(space::S2)
            .automation_id(format!("MessageDomainCard_{WORKFLOW_RUN_TOOL}"))
            .keyed_children(parts)
    }

    /// 主干 MX:636-641 交付物卡的第二颗钮 —— 它**不是**文字钮，是一颗图标钮：
    /// `Button{ AutomationProperties.AutomationId="FileActionMenu",
    /// AutomationProperties.Name="更多文件操作", <FontIcon Glyph="&#xE712;" FontSize="12" /> }`。
    /// reactor 的 `FontIcon` 没有 `font_size` ⇒ 12 DIP 这档用 `Viewbox` 缩（分叉既有解法，
    /// `size::GLYPH_CAPTION = 12.0` 与主干那句 `FontSize="12"` 同值，不是默认 20）。
    /// Name 与 tooltip 同串（主干 localizer `MainWindow.xaml.cs:2148-2163` 给这颗补的正是
    /// `Name` + `ToolTip` 两样，串就是 i18n 表里那条「更多文件操作」）。
    fn file_action_trigger(
        &self,
        seq: i64,
        index: usize,
        context: &mut ViewContext<Shell>,
    ) -> View {
        let name = self.catalog.l("更多文件操作");
        Button::new()
            .automation_id("FileActionMenu")
            .automation_name(name.clone())
            .on_click(context.message(Msg::FileMenuToggle(seq, index)))
            .content(mark_size(glyph::MORE_12, size::GLYPH_CAPTION))
            .tooltip(name)
    }

    /// ⋯ 菜单那一层 = 整格透明的「light-dismiss」垫子 + 贴右下的那张菜单卡。
    /// 主干 `MenuFlyout` 默认 `IsLightDismissEnabled=true`（菜单外任意一处按下即关闭），
    /// reactor 的原生 flyout 只会「挂在一颗钮上、由那颗钮开」，给不出主干这种「菜单外按下即关 +
    /// 贴锚点开」的通路（原生侧也没有 `Popup`）⇒ 垫子用 `Border` + `on_pointer_pressed`
    /// （分叉唯一的鼠标通路，同 #90 那两颗把手的刻法）。菜单卡在垫子**之后**入同一个格子 ⇒
    /// 后入者在上，点行不会被垫子吃掉。
    fn file_action_menu_layer(&self, context: &mut ViewContext<Shell>, p: Palette) -> View {
        let scrim: View = Border::new()
            .grid_row(0)
            .horizontal_alignment(HorizontalAlignment::Stretch)
            .vertical_alignment(VerticalAlignment::Stretch)
            .background(p.transparent.clone())
            .on_pointer_pressed(context.callback(|_| Msg::FileMenuClose))
            .into();
        Grid::new()
            .rows([GridLength::STAR])
            .children((scrim, self.file_action_menu(context, p)))
    }

    /// 主干 `OnPresentedFileMenuClick`（MW:8092-8121）那五张 `MenuFlyoutItem`。
    /// 文案一律过 `self.catalog.l(...)`（主干 `Add` 里就是 `L(text)` + `SetName(item, L(text))`）——
    /// 「菜单项不过 i18n 表 ⇒ 英文界面露中文」是本仓定案的复发缺陷类。
    /// 行的宿主用**真 `Button` + `is_enabled(...)`**，不是自绘 `Border`：主干那一项禁用时是
    /// `MenuFlyoutItem.IsEnabled=false`（UIA 报得出禁用、模板自己压暗），分叉要的是同一个形制，
    /// 而不是「有名字但点了没反应」那种假控件。
    fn file_action_menu(&self, context: &mut ViewContext<Shell>, p: Palette) -> View {
        let selected = self.file_menu.map_or(-1, |open| open.selected);
        let mut rows: Vec<KeyedView> = Vec::new();
        for (slot, (label, id, _)) in FILE_MENU_ITEMS.iter().enumerate() {
            let text = self.catalog.l(label);
            let enabled = file_menu_enabled(slot, self.preview_host_live());
            let highlighted = enabled && selected == slot as i32;
            let shell_row = Button::new()
                .automation_id((*id).to_string())
                .automation_name(text.clone())
                .min_width(0.0)
                .horizontal_alignment(HorizontalAlignment::Stretch)
                .horizontal_content_alignment(HorizontalAlignment::Left)
                .is_enabled(enabled)
                // 键盘选中档：reactor 的 `Button` 没有 `background` 槽 ⇒ 用既有的 Accent 样式
                // 表达「↑↓ 现在停在这一行」（主干是 MenuFlyoutItem 的 PointerOver 灰底，
                // 这一处色差记在报告「留给运行时验收」，不许悄悄留不可见的选中态）。
                .style(highlighted.then_some(ButtonStyle::Accent));
            // 不可点的那一项**连回调都不挂**（主干禁用项也收不到 Click），避免日后误以为
            // 「挂了但被 is_enabled 挡住」。
            let shell_row = if enabled {
                shell_row.on_click(context.message(Msg::FileMenuPick(slot)))
            } else {
                shell_row
            };
            let row: View = shell_row
                .content(
                    TextBlock::new()
                        .text(text)
                        .font_size(type_ramp::BODY.size)
                        .text_wrapping(TextWrapping::NoWrap)
                        .vertical_alignment(VerticalAlignment::Center),
                )
                .into();
            rows.push(KeyedView::new(format!("file-menu-{slot}"), row));
        }
        Border::new()
            .grid_row(0)
            .horizontal_alignment(HorizontalAlignment::Right)
            .vertical_alignment(VerticalAlignment::Bottom)
            .margin(th(pad::OVERLAY))
            .background(p.card.clone())
            .border_brush(p.stroke.clone())
            .border_thickness(size::STROKE)
            .corner_radius(radius::MEDIUM)
            .automation_id("FileActionMenu")
            .automation_name(self.catalog.l("更多文件操作"))
            .content(
                StackPanel::new()
                    .orientation(Orientation::Vertical)
                    .keyed_children(rows),
            )
            .into()
    }

    // ---- #75 工作区：右键菜单 + 四张「对话框」的渲染层 --------------------------------------
    //
    // 主干那一族的两件东西 reactor 0.100.0 都没有对应物：
    // · `MenuFlyout`：这颗型**在本依赖里是有的**（`element.rs` 的 `Menu`/`MenuItem` 一族，
    //   底层就是原生 `MenuFlyout`；旧注释写「generated.rs 零命中 ⇒ 没有」取错了文件，
    //   完整证据见上面 `Msg` 里 #75 那段的「#121 校准」块）
    //   ⇒ 这里仍自绘一张卡片 + 一层透明遮罩（形制抄 [`Shell::file_action_menu_layer`]）：
    //   原生那条通路只能挂在一颗钮上由那颗钮开，给不出主干「右键钉在被点那一行下面」；
    // · `ContentDialog`（那颗型在货架上**两截都在**：builder 面 `generated.rs:4712` 的 9 格 +
    //   `:4723` 的 12 发构造器，原生面 `native/winui/content_dialog.rs:397-398` 真的在调
    //   `dialog.ShowAsync()`（COM 包装 `bindings.rs:7420/7425/7504`）——旧注释写「**没有**
    //   `ShowAsync`」是只 grep 了 `generated.rs` 一颗文件取来的假值（那里面确实 0 命中）。
    //   分叉用不上它的真理由有两条：① reactor 是声明式 Elm，结果走 `on_closed` 回调
    //   （`generated.rs:4785`）⇒ 没有主干那句 `if (await ShowAsync() != Primary) return;`
    //   的出口，必须拆成「开卡写状态格 + 采纳点写回执」两截；② 它**没有** `default_button`
    //   那一格（全 crate 搜 `DefaultButton` 恰 2 行，都是 `bindings.rs:7484/7485` 的 vtable
    //   槽）⇒ 保不住 `DefaultButton=Primary` 的逐张差异，那一档只能由分叉自己在键层给
    //   （判据在 [`WorkspaceDialogKind::enter_falls_on`]））
    //   ⇒ 自绘一张贴窗口居中的卡，形制抄 `note_editor`。两条理由的全文见
    //   [`WorkspaceDialogKind`] 的文档。
    // 两层的**显隐**一律走「不入树」（reactor 没有 `Visibility`），口径同上面三张自绘层。

    /// 工作区行**右键**菜单那一层（主干 `wsItem.ContextFlyout = wsMenu`，`MW:3334-3357`：
    /// **只有右键，那一行没有 ⋯ 触发钮**）。遮罩那一句 `on_pointer_pressed` 就是主干
    /// `MenuFlyout` 的 light-dismiss（菜单外按下 ⇒ 收）。
    fn workspace_menu_layer(&self, context: &mut ViewContext<Shell>, p: Palette) -> View {
        let scrim: View = Border::new()
            .grid_row(0)
            .horizontal_alignment(HorizontalAlignment::Stretch)
            .vertical_alignment(VerticalAlignment::Stretch)
            // 透明遮罩**不挂**回调时也能挡掉底下那一层（WinUI 里 `Background=Transparent`
            // 仍然命中测试）⇒ 对话框那两张的「模态」就是这么来的；这一张反过来，
            // 它要的就是「点哪儿都算没点中菜单」。
            .background(p.transparent.clone())
            .on_pointer_pressed(context.callback(|_| Msg::WorkspaceMenuClose))
            .into();
        Grid::new()
            .rows([GridLength::STAR])
            .children((scrim, self.workspace_menu_card(context, p)))
    }

    /// 那五发本身。表体是常量 [`WORKSPACE_MENU_ITEMS`]（五发、顺序、`Text`、`AutomationId`、
    /// UIA 名模板 `{0}`=标题 逐字对主干 `MW:3336-3355`），这里**只**把 `{0}` 换成当前那行的标题，
    /// 不再抄第二份表。
    fn workspace_menu_card(&self, context: &mut ViewContext<Shell>, p: Palette) -> View {
        let Some(id) = self.workspace_menu.clone() else {
            return blank();
        };
        let Some(title) = self
            .tree
            .workspaces
            .iter()
            .find(|ws| ws.id == id)
            .map(|ws| ws.title.clone())
        else {
            // 那一行已经不在了（follow 流刚删掉它 / 换了内核）⇒ 整层不生成，与「没开」同义。
            // 留着它只会画出一张「五发点点点都不做事」的卡，那才是假的。
            return blank();
        };
        let mut rows: Vec<KeyedView> = Vec::new();
        for (slot, (label, item_id, name_tpl, _action)) in WORKSPACE_MENU_ITEMS.iter().enumerate() {
            let text = self.catalog.l(label);
            let row: View = Button::new()
                .automation_id((*item_id).to_string())
                // 主干那颗是 `Aut(item, id, LF("…：{0}", ws.Title))` ⇒ UIA 名**带标题**，
                // 与 `Text`（不带）两枚不是一回事，自测矩阵按名取元素。
                .automation_name(self.catalog.lf(name_tpl, &[title.clone()]))
                .min_width(0.0)
                .horizontal_alignment(HorizontalAlignment::Stretch)
                .horizontal_content_alignment(HorizontalAlignment::Left)
                .on_click(context.message(Msg::WorkspaceMenuPick(slot)))
                .content(
                    TextBlock::new()
                        .text(text)
                        .font_size(type_ramp::BODY.size)
                        .text_wrapping(TextWrapping::NoWrap)
                        .vertical_alignment(VerticalAlignment::Center),
                )
                .into();
            rows.push(KeyedView::new(format!("workspace-menu-{slot}"), row));
        }
        Border::new()
            .grid_row(0)
            // 一处显著偏差：主干 `MenuFlyout` 钉在那一行下面（`ShowAt(anchor)`），分叉读不回
            // 元素的屏幕矩形 ⇒ 只能贴一个角。工作区那五行在左栏**上部**，左上就是离锚点最近
            // 的一角（口径同 `file_action_menu` 的「贴内容面右下」，那条也在报告里备案）。
            .horizontal_alignment(HorizontalAlignment::Left)
            .vertical_alignment(VerticalAlignment::Top)
            .margin(th(pad::OVERLAY))
            .background(p.card.clone())
            .border_brush(p.stroke.clone())
            .border_thickness(size::STROKE)
            .corner_radius(radius::MEDIUM)
            // **不自造 AutomationId**：主干那颗 `MenuFlyout` 一个 `Aut()` 都没挂（`:3335` 只给
            // 五发 `MenuFlyoutItem`），分叉替容器编一颗就是多一枚主干查无此串的 id
            // （本仓同类缺陷定案见 `note_editor` 里 `FeedbackNoteEditor` 那段复盘）。
            .content(
                StackPanel::new()
                    .orientation(Orientation::Vertical)
                    .keyed_children(rows),
            )
            .into()
    }

    /// 四张 `ContentDialog` 替身的那一层。底下那张（rename / delete / create）与层中之层
    /// （newfolder）**各占一格**、可以同屏 ⇒ 这一发最多连开两张，先画底下那张再在它之上画上面那张。
    /// 两张都带**没有回调**的透明遮罩 ⇒ 场上有卡时底下整个壳点不动，这就是主干 `ContentDialog`
    /// 的模态（Esc / Enter 那三档另由 `Msg::PaletteClose/PaletteMove/PaletteAccept` 那几臂路由）。
    fn workspace_dialog_layer(&self, context: &mut ViewContext<Shell>, p: Palette) -> View {
        let mut cells: Vec<KeyedView> = Vec::new();
        if let Some(card) = self.workspace_dialog.as_ref() {
            cells.push(KeyedView::new(
                "workspace-dialog",
                self.workspace_dialog_card(card, true, context, p),
            ));
        }
        if let Some(card) = self.workspace_folder_dialog.as_ref() {
            // 上面这张不再补第二层遮罩（底下那张的已经盖满整窗了）。
            cells.push(KeyedView::new(
                "workspace-folder-dialog",
                self.workspace_dialog_card(card, false, context, p),
            ));
        }
        Grid::new().rows([GridLength::STAR]).keyed_children(cells)
    }

    /// 一张卡的本体：`[卡题, 正文?, 标签?, 输入框?, 浏览钮?, 能力说明?, 浏览区?, 按钮行]`，
    /// 逐格都由 [`WorkspaceDialog`] 上那几发判据决定画不画 ⇒ 表里不留第二份真相。
    fn workspace_dialog_card(
        &self,
        card: &WorkspaceDialog,
        scrim: bool,
        context: &mut ViewContext<Shell>,
        p: Palette,
    ) -> View {
        let mut rows: Vec<KeyedView> = Vec::new();
        // 卡题那一档：主干走 `ContentDialog.Title`（模板里是 `TitleTextStyle`，数值本刀读不到），
        // 分叉沿用既有自绘卡的卡题档（`approval_panel`：`BODY_STRONG` + `SEMI_BOLD`）。
        rows.push(KeyedView::new(
            "title",
            TextBlock::new()
                .text(self.catalog.l(card.title_key()))
                .font_size(type_ramp::BODY_STRONG.size)
                .font_weight(FontWeight::SEMI_BOLD)
                .foreground(p.text_primary),
        ));
        // 正文那一句的 `{0}` = 唤出那一刻摘下的标题（`:3847`）。句子本体只在
        // [`WorkspaceDialog::body_key`] 一处，这里**只**补那颗参数 ⇒ 「哪一张有正文」这件事
        // 仍然只有一把尺子（`body_key()` 回不回 `Some`）。
        let body_arg = match &card.kind {
            WorkspaceDialogKind::Delete { title, .. } => Some(title.clone()),
            _ => None,
        };
        if let Some(key) = card.body_key() {
            let text = match &body_arg {
                Some(arg) => self.catalog.lf(key, &[arg.clone()]),
                None => self.catalog.l(key),
            };
            rows.push(KeyedView::new(
                "body",
                TextBlock::new()
                    .text(text)
                    .font_size(type_ramp::BODY.size)
                    .text_wrapping(TextWrapping::Wrap)
                    .foreground(p.text_primary),
            ));
        }
        // `input_id()` 与 `label_key()` 同一把尺子（要么都有 = 那一张有输入框，要么都没有），
        // 所以这里一次 `if let` 两发，不给「有框无标签 / 有标签无框」留组合。
        if let (Some(id), Some(label)) = (card.input_id(), card.label_key()) {
            let input = TextBox::new()
                .text(card.draft.clone())
                .automation_id(id.to_string())
                .automation_name(self.catalog.l(label))
                .on_text_changed(context.callback(|text: String| Msg::WorkspaceDialogDraft(text)));
            // `MinWidth` 逐张对表：rename 360 / create 420 / delete + newfolder 一个都不写。
            // 主干那两枚 420 里还有一枚挂在 create 的 `host` 面板上（`:3898`）—— 那颗面板的
            // desired 宽度本来就 >= 框的那枚 420 ⇒ 分叉只在框上写一次，几何同值、少一处真相。
            let input = match card.min_width() {
                Some(width) => input.min_width(width),
                None => input,
            };
            // `new-folder` 那枚占位是主干全族**唯一**的一颗，而且是字面量、不过 `L()`。
            let input = match card.placeholder() {
                Some(text) => input.placeholder_text(text.to_string()),
                None => input,
            };
            rows.push(KeyedView::new(
                "label",
                TextBlock::new()
                    .text(self.catalog.l(label))
                    .font_size(type_ramp::CAPTION.size)
                    .foreground(p.text_secondary),
            ));
            rows.push(KeyedView::new("input", input));
        }
        if matches!(card.kind, WorkspaceDialogKind::Create) {
            rows.push(KeyedView::new(
                "browse",
                Button::new()
                    .min_height(size::COMPACT_BUTTON_MIN_HEIGHT)
                    .horizontal_alignment(HorizontalAlignment::Left)
                    .automation_id("BrowseDirectoryButton".to_string())
                    // 主干 `Aut(browseButton, "BrowseDirectoryButton", L("浏览文件夹"))`：
                    // **Name 与 Content 不同串**（Content 是「浏览…（内核选择器）」）。
                    .automation_name(self.catalog.l("浏览文件夹"))
                    .on_click(context.message(Msg::WorkspaceDirectoryBrowse))
                    .content(
                        TextBlock::new()
                            .text(self.catalog.l("浏览…（内核选择器）"))
                            .font_size(type_ramp::CAPTION.size),
                    ),
            ));
            // `capabilityNote`（`:3902-3911`）：只有 `directoryPicker/list` 探失败才有这一行。
            if let Some(note) = &card.note {
                rows.push(KeyedView::new(
                    "note",
                    TextBlock::new()
                        .text(note.clone())
                        .font_size(type_ramp::CAPTION.size)
                        .text_wrapping(TextWrapping::Wrap)
                        .foreground(p.text_secondary),
                ));
            }
            // `browser`（`:3912` `Visibility = Collapsed`）：探不到就**不入树**，同一把尺子。
            if let Some(listing) = &card.listing {
                rows.push(KeyedView::new(
                    "browser",
                    self.directory_browser(listing, context, p),
                ));
            }
        }
        let foot = |label: &str, accent: bool, column: i32, message: Msg| {
            let label = self.catalog.l(label);
            Button::new()
                .style(if accent {
                    ButtonStyle::Accent
                } else {
                    ButtonStyle::Default
                })
                .min_height(size::COMPACT_BUTTON_MIN_HEIGHT)
                .vertical_alignment(VerticalAlignment::Center)
                .grid_column(column)
                // 主干 `ContentDialog` 那两枚脚钮是模板件、没有 `Aut()` ⇒ UIA 上只有
                // `Name = PrimaryButtonText / CloseButtonText` ⇒ 分叉照此**只写名字不写 id**。
                .automation_name(label.clone())
                .on_click(context.message(message))
                .content(
                    TextBlock::new()
                        .text(label)
                        .font_size(type_ramp::CAPTION.size),
                )
        };
        rows.push(KeyedView::new(
            "buttons",
            Grid::new()
                .columns([GridLength::STAR, GridLength::Auto, GridLength::Auto])
                .column_spacing(space::S6)
                .children((
                    blank(),
                    foot(card.primary_key(), true, 1, Msg::WorkspaceDialogSubmit),
                    // 三张的 `CloseButtonText` 全是 `L("取消")`（`:3815`/`:3845`/`:3930`/`:4120`）。
                    foot("取消", false, 2, Msg::WorkspaceDialogDismiss),
                )),
        ));
        let face: View = Border::new()
            .grid_row(0)
            .horizontal_alignment(HorizontalAlignment::Center)
            .vertical_alignment(VerticalAlignment::Center)
            .margin(th(pad::OVERLAY))
            .padding(th([space::S16; 4]))
            .background(p.card.clone())
            .border_brush(p.stroke.clone())
            .border_thickness(size::STROKE)
            .corner_radius(radius::MEDIUM)
            .content(
                StackPanel::new()
                    .orientation(Orientation::Vertical)
                    .spacing(space::S10)
                    .keyed_children(rows),
            )
            .into();
        if !scrim {
            return Grid::new()
                .rows([GridLength::STAR])
                .children((blank(), face));
        }
        // 遮罩那一句**不挂** `on_pointer_pressed`：主干 `ContentDialog` 默认
        // `ShouldCloseOnOutsideClick = false`，点卡外既不该关、也不该穿透到底下的壳。
        let scrim: View = Border::new()
            .grid_row(0)
            .horizontal_alignment(HorizontalAlignment::Stretch)
            .vertical_alignment(VerticalAlignment::Stretch)
            .background(p.transparent.clone())
            .into();
        Grid::new().rows([GridLength::STAR]).children((scrim, face))
    }

    /// 主干 `RenderDirectoryListing`（`MW:4002-4092`）那一整块，**逐格**照搬：
    /// 当前路径行 / 面包屑 / `使用此目录` + `新建文件夹…` / 目录项列表 / `truncated` 提示行。
    /// 空 `path` 的行一律跳过（`:4025-4027` 面包屑、`:4076-4078` 目录项）—— 走的是
    /// `kernel.rs` 那两发 [`DirectoryListing::visible_crumbs`] /
    /// [`DirectoryListing::visible_entries`]，判据只有一份。
    fn directory_browser(
        &self,
        listing: &DirectoryListing,
        context: &mut ViewContext<Shell>,
        p: Palette,
    ) -> View {
        let compact = |label: String, id: String, name: String, message: Option<Msg>| {
            let button = Button::new()
                .min_height(size::COMPACT_BUTTON_MIN_HEIGHT)
                .automation_id(id)
                .automation_name(name);
            // 禁用项**连回调都不挂**（口径同 `file_action_menu`：主干禁用项也收不到 `Click`）。
            match message {
                Some(message) => button.on_click(context.message(message)),
                None => button.is_enabled(false),
            }
            .content(
                TextBlock::new()
                    .text(label)
                    .font_size(type_ramp::CAPTION.size),
            )
        };
        let mut rows: Vec<KeyedView> = Vec::new();
        // ① 当前路径行（`:4005-4013`）：`CaptionTextStyle` + `TextTertiaryBrush` +
        //    `TextTrimming = CharacterEllipsis`（长路径必须截断，不许把面包屑挤下去）。
        rows.push(KeyedView::new(
            "current",
            TextBlock::new()
                .text(listing.path.clone())
                .font_size(type_ramp::CAPTION.size)
                .foreground(p.text_tertiary)
                .text_trimming(TextTrimming::CharacterEllipsis),
        ));
        // ② 面包屑（`:4016-4036`）：`StackPanel{Horizontal, Spacing=Sp4}`，每颗
        //    `DirectoryCrumb_{path}`，Name = `LF("跳转到 {0}", …)`；`name` 空则回落到 `path`
        //    （`:4029` 那一串 `crumbName.Length > 0 ? crumbName : crumbPath` 三处同刻法）。
        let mut crumbs: Vec<KeyedView> = Vec::new();
        for (index, crumb) in listing.visible_crumbs().into_iter().enumerate() {
            let label = if crumb.name.is_empty() {
                crumb.path.clone()
            } else {
                crumb.name.clone()
            };
            crumbs.push(KeyedView::new(
                format!("crumb-{index}"),
                compact(
                    label.clone(),
                    format!("DirectoryCrumb_{}", crumb.path),
                    self.catalog.lf("跳转到 {0}", &[label]),
                    Some(Msg::WorkspaceDirectoryEnter(Some(crumb.path.clone()))),
                ),
            ));
        }
        rows.push(KeyedView::new(
            "crumbs",
            StackPanel::new()
                .orientation(Orientation::Horizontal)
                .spacing(space::S4)
                .keyed_children(crumbs),
        ));
        // ③ 那两动作（`:4038-4047`）：`StackPanel{Horizontal, Spacing=Sp8}`。
        //    `UseDirectoryButton`：Content 与 Name **同串**「使用此目录」（`:4040`）。
        //    `NewFolderButton`：`Content = L("新建文件夹…")` 而 `Name = L("新建文件夹")`
        //    （`:4044` 两枚不是一回事，那枚省略号只在 Content 上），
        //    而且 `IsEnabled = current.Length > 0` —— 没有当前目录就建不出子目录。
        let can_mkdir = !listing.path.is_empty();
        let mut actions: Vec<KeyedView> = Vec::new();
        let use_label = self.catalog.l("使用此目录");
        actions.push(KeyedView::new(
            "use",
            compact(
                use_label.clone(),
                "UseDirectoryButton".to_string(),
                use_label,
                Some(Msg::WorkspaceDirectoryUse),
            ),
        ));
        actions.push(KeyedView::new(
            "mkdir",
            compact(
                self.catalog.l("新建文件夹…"),
                "NewFolderButton".to_string(),
                self.catalog.l("新建文件夹"),
                can_mkdir.then(|| {
                    Msg::WorkspaceDialogShow(WorkspaceDialogKind::NewFolder {
                        parent: listing.path.clone(),
                    })
                }),
            ),
        ));
        rows.push(KeyedView::new(
            "actions",
            StackPanel::new()
                .orientation(Orientation::Horizontal)
                .spacing(space::S8)
                .keyed_children(actions),
        ));
        // ④ 目录项列表（`:4049-4079`）：`ListView{MaxHeight=200, SelectionMode=None,
        //    IsItemClickEnabled=true}` + `Aut(id="DirectoryEntriesList", name=L("目录项"))`，
        //    行是 `ListViewItem{Content=name, Tag=path}`（**行上没有 id**，点一行 = 进一层）。
        //    分叉没有 `ListView` 的 ItemClick ⇒ 一行一颗 `Button`，UIA 名 = Content = `name`
        //    （主干 `ListViewItem` 的 Name 也是从 Content 推出来的）⇒ 不给行编 id。
        //    `MaxHeight` 挂在装行的那颗 `Border` 上；它到底截不截得动，本刀不能起 GUI ⇒ 挂 §5。
        let mut entries: Vec<KeyedView> = Vec::new();
        for (index, entry) in listing.visible_entries().into_iter().enumerate() {
            entries.push(KeyedView::new(
                format!("entry-{index}"),
                Button::new()
                    .min_width(0.0)
                    .horizontal_alignment(HorizontalAlignment::Stretch)
                    .horizontal_content_alignment(HorizontalAlignment::Left)
                    .automation_name(entry.name.clone())
                    .on_click(context.message(Msg::WorkspaceDirectoryEnter(Some(
                        entry.path.clone(),
                    ))))
                    .content(
                        TextBlock::new()
                            .text(entry.name.clone())
                            .font_size(type_ramp::BODY.size)
                            .text_wrapping(TextWrapping::NoWrap),
                    ),
            ));
        }
        rows.push(KeyedView::new(
            "entries",
            Border::new()
                .max_height(DIRECTORY_ENTRIES_MAX_HEIGHT)
                .automation_id("DirectoryEntriesList".to_string())
                .automation_name(self.catalog.l("目录项"))
                .content(
                    StackPanel::new()
                        .orientation(Orientation::Vertical)
                        .keyed_children(entries),
                ),
        ));
        // ⑤ `truncated` 提示行（`:4080-4090`）：**只在 `truncated == true` 那一档**才画，
        //    措辞与 `CaptionTextStyle` + `TextTertiaryBrush` 一起抄；假就是一行都不生成。
        if listing.truncated {
            rows.push(KeyedView::new(
                "truncated",
                TextBlock::new()
                    .text(self.catalog.l("目录项超过内核上限，仅显示前若干项。"))
                    .font_size(type_ramp::CAPTION.size)
                    .foreground(p.text_tertiary)
                    .text_wrapping(TextWrapping::Wrap),
            ));
        }
        StackPanel::new()
            .orientation(Orientation::Vertical)
            .spacing(space::S6)
            .keyed_children(rows)
    }

    /// 主干 `MakeProducedFileChip`：文件图标 + 基名，点击经内核 `session/openWorkspacePath`
    /// 交宿主桌面打开。主干是 HyperlinkButton，reactor 的公开构造器没有 content/padding，
    /// 所以换成 TextLink 样式的 Button（外观同族：透明底 + 强调色文字）。
    fn produced_chip(&self, path: &str, context: &mut ViewContext<Shell>) -> View {
        let flattened = path.replace('\\', "/");
        let name = flattened
            .rsplit('/')
            .next()
            .filter(|name| !name.is_empty())
            .unwrap_or(flattened.as_str())
            .to_string();
        let tip = self.catalog.lf("打开 {0}", &[path.to_string()]);
        Button::new()
            .style(ButtonStyle::TextLink)
            .min_width(0.0)
            .vertical_alignment(VerticalAlignment::Center)
            .automation_id(format!("ProducedFileChip_{name}"))
            .automation_name(tip.clone())
            .on_click(context.message(Msg::OpenPath(path.to_string())))
            .content(
                StackPanel::new()
                    .orientation(Orientation::Horizontal)
                    .spacing(space::S6)
                    .vertical_alignment(VerticalAlignment::Center)
                    .children((
                        mark_size(glyph::PRODUCED_FILE, size::GLYPH_CAPTION),
                        TextBlock::new()
                            .text(name)
                            .font_size(type_ramp::BODY.size)
                            .vertical_alignment(VerticalAlignment::Center),
                    )),
            )
            .tooltip(tip)
    }

    /// 主干 `BuildProducedFilesRow`：轮尾「本轮文件改动」行（标签 `[Auto, *]` chips）。
    /// 主干用 `SimpleWrapPanel` 按实际宽度换行，reactor 没有换行面板，这里按 chip 的估算
    /// 宽度分行——同一批文件的换行位置可能差一颗，行数与全展开的口径一致。
    fn produced_row(&self, bubble: &Bubble, p: Palette, context: &mut ViewContext<Shell>) -> View {
        const LINE_WIDTH: f64 = 520.0;
        let mut lines: Vec<Vec<String>> = vec![Vec::new()];
        let mut used = 0.0;
        for path in &bubble.produced {
            let name = path.replace('\\', "/");
            let name = name.rsplit('/').next().unwrap_or(name.as_str());
            let width = size::GLYPH_CAPTION + space::S6 + name.chars().count() as f64 * 7.2;
            let first = lines.last().is_some_and(|line| line.is_empty());
            if !first && used + width > LINE_WIDTH {
                lines.push(Vec::new());
                used = 0.0;
            }
            used += width + space::S6;
            lines.last_mut().unwrap().push(path.clone());
        }
        let chips: Vec<KeyedView> = lines
            .into_iter()
            .filter(|line| !line.is_empty())
            .enumerate()
            .map(|(index, paths)| {
                let cells = paths
                    .iter()
                    .map(|path| {
                        KeyedView::new(format!("chip-{path}"), self.produced_chip(path, context))
                    })
                    .collect::<Vec<KeyedView>>();
                KeyedView::new(
                    format!("line-{index}"),
                    StackPanel::new()
                        .orientation(Orientation::Horizontal)
                        .spacing(space::S6)
                        .keyed_children(cells),
                )
            })
            .collect();
        let label = StackPanel::new()
            .orientation(Orientation::Horizontal)
            .spacing(space::S6)
            .grid_column(0)
            .vertical_alignment(VerticalAlignment::Center)
            .children((TextBlock::new()
                .text(self.catalog.l("本轮文件改动"))
                .font_size(type_ramp::CAPTION.size)
                .opacity(0.7)
                .foreground(p.text_tertiary.clone())
                .vertical_alignment(VerticalAlignment::Center),));
        Grid::new()
            .columns([GridLength::Auto, GridLength::STAR])
            .column_spacing(space::S8)
            .margin(th([6.0, 2.0, 6.0, 2.0]))
            .automation_id("ProducedFilesRow")
            .automation_name(self.catalog.l("本轮文件改动"))
            .keyed_children(
                vec![
                    KeyedView::new("label", label),
                    KeyedView::new(
                        "chips",
                        StackPanel::new()
                            .orientation(Orientation::Vertical)
                            .spacing(space::S2)
                            .grid_column(1)
                            .keyed_children(chips),
                    ),
                ]
                .into_iter()
                .collect::<Vec<KeyedView>>(),
            )
    }

    /// 主干「打开/显示」那两颗没被改过样式的按钮：走 WinUI 默认度量（MinWidth 120 也保留）。
    fn text_button(
        &self,
        label: &str,
        id: &str,
        message: Msg,
        context: &ViewContext<Shell>,
    ) -> View {
        Button::new()
            .automation_id(id.to_string())
            .automation_name(self.catalog.l(label))
            .on_click(context.message(message))
            .content(
                TextBlock::new()
                    .text(self.catalog.l(label))
                    .font_size(type_ramp::BODY.size),
            )
    }

    /// 气泡照抄主干 `UserTpl` / `AssistantTpl` / `ToolCallTpl` / `ReasoningTpl` /
    /// `DeliverableTpl`：用户在右（MaxWidth 560、右下尖角胶囊），助手铺满成卡片，两者同材质
    /// （`BubbleMicaBrush` + `StrokeSubtle` 1px）。主干没有角色标签行，所以这里也不写「你/助手」。
    fn bubble_view(
        &self,
        bubble: &Bubble,
        is_answer: bool,
        closed: bool,
        p: Palette,
        context: &mut ViewContext<Shell>,
    ) -> View {
        let row = th(pad::LIST_ITEM);
        let body = TextBlock::new()
            .text(bubble.text.clone())
            .font_size(self.font_size)
            .foreground(p.text_primary.clone())
            .text_wrapping(TextWrapping::Wrap)
            .is_text_selection_enabled(true);
        match bubble.role {
            "user" => StackPanel::new()
                .horizontal_alignment(HorizontalAlignment::Right)
                .max_width(size::BUBBLE_MAX_WIDTH)
                .margin(row)
                .spacing(space::S2)
                .children((
                    Border::new()
                        .horizontal_alignment(HorizontalAlignment::Right)
                        .background(p.bubble)
                        .border_brush(p.stroke_subtle)
                        .border_thickness(size::STROKE)
                        .corner_radius(CornerRadius::new(
                            radius::XLARGE,
                            radius::XLARGE,
                            radius::SMALL,
                            radius::XLARGE,
                        ))
                        .padding(th(pad::BUBBLE_USER))
                        .content(body),
                    self.bubble_actions(bubble, false, closed, p, context),
                )),
            // 主线 `AppendSystemMessage` 的 Role=system 在模板选择器里落到 default ⇒ 同一个 `ToolTpl`
            // （`BubbleTemplateSelector.cs:22-32`）：无图标、无摘要的灰行。分叉给它单独一个 role 值，
            // 是为了让 `hero_state()` 把它当「非对话内容」排除掉（MW:4374 同口径）。
            // #104：主干 `BuildToolCard`（`ToolCards.cs:106-113`）在算 `ToolRowModel` **之前**
            // 先按 `MessageDomainTools.Contains(ToolName)` 整卡替换并 `return` ⇒ 截断那一行走的
            // 是过程卡、压根不是 `tool_line` 那条灰行。分叉同一处分派，位置也排在灰行前面。
            "tool" if bubble.tool_name == MAX_TOKENS_TOOL => self.max_tokens_card(p, context),
            // #111：`model-retry` 与 `max-tokens` 同走过程卡（主干 `MessageDetails.cs:911-912`
            // `case "model-retry": BuildRetryCard`），同样排在灰行 `tool_line` 之前。
            "tool" if bubble.tool_name == RETRY_TOOL => self.model_retry_card(bubble, p, context),
            // #139 件三 / 件四：主干 `BuildMessageDomainCard:914-919` 那两个 `case` 排在
            // `model-retry` 之后 ⇒ 分叉的臂序也照这个次序（match 自上而下首命中即赢，同一次序
            // 由 `rd5_domain_card_tests` 里那颗四臂次序锁钉死）。两族都不走 `tool_line` 那条灰行。
            "tool" if bubble.tool_name == COMPACTION_TOOL => {
                self.compaction_card(bubble, p, context)
            }
            "tool" if bubble.tool_name == WORKFLOW_RUN_TOOL => {
                self.workflow_run_card(bubble, p, context)
            }
            "tool" | "system" => self.tool_line(bubble, p),
            "reasoning" => self.reasoning_row(bubble, p, context),
            "deliverable" => self.deliverable_card(bubble, p, context),
            _ => {
                let key = bubble_key(bubble);
                let role = bubble.role;
                // 主干 turnTail 槽（本轮文件改动）渲染在动作行之前，且只挂轮尾答案。
                let produced = if is_answer && !bubble.produced.is_empty() {
                    Some(self.produced_row(bubble, p, context))
                } else {
                    None
                };
                let actions = self.bubble_actions(bubble, is_answer, closed, p, context);
                // 便签编辑器（主干那张是真 `ContentDialog`；分叉的对话框原语**有**——就是
                // 工作区那两张用的「遮罩 + 居中卡」自绘一族，只是这张没挂进去，见
                // `Shell::note_editor` 的文档）只挂在编辑目标
                // 那一条气泡下方，跟着动作行之后 —— 主干 `note_for` 只有一个槽，同时最多开一个。
                let editor = (self.note_for.as_deref() == Some(bubble.id.as_str()))
                    .then(|| self.note_editor(p, context));
                Border::new()
                    .margin(th(pad::LIST_ITEM_TAIL))
                    .background(p.bubble)
                    .border_brush(p.stroke_subtle)
                    .border_thickness(size::STROKE)
                    .corner_radius(radius::LARGE)
                    .padding(th(pad::BUBBLE_ASSISTANT))
                    // 这条气泡就是正文带：锚点判据在 `bubble_anchor_source`，消息一个字没改。
                    .on_pointer_entered(context.callback(move |info: PointerEventInfo| {
                        note_bubble_anchor(
                            role,
                            scroll::Point { x: info.window_x as i32, y: info.window_y as i32 },
                        );
                        Msg::Hover(Some(key.clone()))
                    }))
                    .on_pointer_exited(context.callback(|_| Msg::Hover(None)))
                    .content(
                        StackPanel::new()
                            .orientation(Orientation::Vertical)
                            .spacing(space::S2)
                            .keyed_children(
                                vec![KeyedView::new("body", body)]
                                    .into_iter()
                                    .chain(
                                        produced
                                            .map(|row| KeyedView::new("produced", row))
                                            .into_iter(),
                                    )
                                    .chain([KeyedView::new("actions", actions)])
                                    .chain(
                                        editor
                                            .map(|view| KeyedView::new("note-editor", view))
                                            .into_iter(),
                                    )
                                    .collect::<Vec<KeyedView>>(),
                            ),
                    )
            }
        }
    }

    /// `PendingTpl`：转圈 ProgressRing(14) + 「少女祈祷中…」。主干把 Padding 挂在 StackPanel 上，
    /// reactor 里只有 Border 有 `padding`，所以外层用 Border 承接内边距与 UIA 名称。
    fn pending_row(&self, p: Palette) -> View {
        Border::new()
            .margin(th(pad::LIST_ITEM_TAIL))
            .padding(th(pad::PENDING_ROW))
            .background(p.transparent)
            .automation_name(self.catalog.l("少女祈祷中"))
            .content(
                StackPanel::new()
                    .orientation(Orientation::Horizontal)
                    .spacing(space::S8)
                    .children((
                        ProgressRing::new()
                            .width(size::PENDING_RING)
                            .height(size::PENDING_RING)
                            .is_active(true)
                            .vertical_alignment(VerticalAlignment::Center),
                        TextBlock::new()
                            .text(self.catalog.l("少女祈祷中…"))
                            .font_size(type_ramp::CAPTION.size)
                            .foreground(p.text_tertiary.clone())
                            .vertical_alignment(VerticalAlignment::Center)
                            .automation_id("PendingThinkingText"),
                    )),
            )
    }

    // ---- #56 输入区选择器组：触发器 + 展开层（本轮只落 `AgentMode*`）-----------------------
    //
    // 主干那三颗都是 `DropDownButton` + 一张 `MenuFlyout Placement=Top`（`MX:1209-1295`）。
    // 形制裁决三条，逐条理由与后果见 `tmp/mt2-report.md` §1.4：
    // ① **仍自绘卡片 + 透明遮罩**，不用货架上那颗原生 `Flyout`/`Menu`（#121 已把「reactor 没有
    //    flyout」那句错注释清掉，原生那颗确实在）。理由不是没有，是这条通路分叉从来没跑过、
    //    而本轮 GUI 全挂起 ⇒ 离线轮不引入未验通路；形制照抄 [`Shell::file_action_menu_layer`]。
    // ② 菜单项**没有 checked 位**（`RadioMenuFlyoutItem` 与 `ToggleMenuFlyoutItem` 在
    //    windows-reactor 0.100.0 是永久抄不动那一档）⇒ 当前档由 Accent 底表达，
    //    UIA `Name` 保持与主干 `Text` 逐字同串（挂起的 GUI 脚本按 Name 找行，加了后缀就找不着）。
    // ③ UIA 一律用主干**裸真名**：容器 `AgentModeFlyout`、触发器 `AgentModeButton`、
    //    触发器那行字 `AgentModeLabel`、行 `AgentMode_{id}`（主干 `MW:4840/4868` 自己就是拼的）。
    //
    // 显隐照旧「不入树」：reactor 没有 `Visibility` ⇒ [`Shell::agent_mode_trigger`] 给 `None`
    // 就是主干那句 `Visibility.Collapsed`，[`Shell::selectors`] 给 `None` 就是那张 flyout 不存在。

    /// 待用预设的 **id** —— 那一格的唯一消费口，判据本体是纯函数 [`pending_preset_id`]
    /// （那三条离线可测，这里只是一层薄壳）。主干那边建会话只有一处拼请求：
    /// `CreateSessionCoreAsync`（`MW:4614-4633`）是**共用**壳子，发送时自动新建与「新建会话」钮
    /// 都走它 ⇒ 分叉这边两个建会话入口都调这一颗，不是两处各写一份判据。
    fn agent_preset_to_send(&self) -> Option<String> {
        pending_preset_id(self.pending_agent_preset.as_ref())
    }

    /// 主干 `LoadAgentModeMenuAsync`（`MW:4816-4878`）里那次 `await`。
    /// 三道守卫逐条对着原文抄：
    /// · `_rpc is null ⇒ return`（`MW:4818-4821`）：内核没起来时**连 `Items.Clear()` 都不做**
    ///   （`Clear()` 在那道守卫**之后**，`:4822`）⇒ 分叉这里也直接 `return`，上一轮的表原样留着。
    /// · 开层即清自定义表（= `:4822` 的 `Items.Clear()`，它在 `try` **之前**）⇒ 「重开时 RPC
    ///   失败」那一档菜单里只剩内置四档（内置四档在常量 [`AGENT_MODE_BUILTINS`] 里，从不进这格），
    ///   而不是上一轮的残留。这是主干行为，不是缓存丢失。
    /// · 请求体是 `new { }`（`MW:4847`）⇒ 扁平空对象，**没有** `request` 外壳。
    fn load_agent_mode_menu(&mut self, context: &ComponentContext<Shell>) {
        let Some(shared) = self.kernel.clone() else {
            return;
        };
        self.agent_presets.clear();
        context.spawn_background(move |_token| {
            let outcome = shared
                .lock()
                .map_err(|_| "内核状态不可用".to_string())
                .and_then(|mut kernel| {
                    kernel
                        .call("agentPresets/list", json!({}))
                        .map(|reply| parse_agent_presets(&reply))
                });
            Msg::AgentPresetsLoaded(outcome)
        });
    }

    /// #57 读数齐备闸的**唯一**取数口：当前会话的 `ContextOccupancy`。
    /// 分子或分母任一缺位 ⇒ `None` ⇒ 圈不入树、面板也没有锚点（主干 `CM:130-133` + `CM:163`
    /// + `CM:222-225` 三处共用同一判据）。**缺分母时画空、绝不显 0%** —— 0% 是「采到了、
    /// 用了 0」那一档（`used = 0` 是合法读数，圈在场、只剩轨道），与「没有读数」两回事。
    fn active_occupancy(&self) -> Option<cm::ContextOccupancy> {
        let session = self.active.as_deref()?;
        self.context_meters.occupancy(session)
    }

    /// 面板卡的三处局部常量：主干 `CM:230/240/246` 与 `RunStats.cs:353-359` 都是就地字面量
    /// （`Theme/Tokens.xaml` 里没有这几档）⇒ 按分叉既有惯例起局部名，不往 `tokens.rs` 塞
    /// （母本 = `PALETTE_MAX_WIDTH` 那一族）。
    const CONTEXT_PANEL_MIN_WIDTH: f64 = 250.0;
    const CONTEXT_PANEL_BAR_HEIGHT: f64 = 4.0;
    const CONTEXT_PANEL_PADDING: [f64; 4] = [14.0, 12.0, 14.0, 12.0];

    /// 主干 `MX:1301-1330` 那颗 `ContextMeterRing`（动作行第 6 列，「模型胶囊与发送之间」）。
    ///
    /// `Option` 判空即主干的 `Visibility="Collapsed"`（reactor 没有 `Visibility` ⇒ 不在场就
    /// 整棵节点不入树），挂法见 [`Shell::composer_band`] 那个 keyed 槽位循环。
    ///
    /// 三件形状逐格抄主干：外层 28×28（`cm::RING_BUTTON`）+ 内层 14×14（`cm::RING_BOX`）+
    /// 轨道 12×12 线宽 2（`RING_BOX - RING_STROKE`）；轨道画笔 `p.stroke` = `StrokeBrush`
    /// （`MX:1314-1316`），已用弧与满值整圆同用 `p.text_tertiary` = `TextTertiaryBrush`
    /// （`MX:1318-1328`）⇒ **主干没有按颜色分档**，别在这里发明。
    ///
    /// ⚠ 本轮唯一形态级不等价：reactor 0.100.0 的生成层没有 `Path` / `PathGeometry` /
    /// `ArcSegment`（`generated.rs:3045` 只有 `Ellipse`、`:3102` 只有 `Line`、`:2964` 只有
    /// `Rectangle`）⇒ 真弧只能折成 `Canvas` + N 枚 `Line` 的**内接弦近似**（段数与端点公式
    /// 见 `kernel::mw3_ring_chords`，端点逐字取主干 `CM:197-203` 自己那两行）。与主干真弧的
    /// 视觉差、以及主干那两枚 `StrokeStartLineCap`/`StrokeEndLineCap="Round"`（reactor 的
    /// `Line` 没有端点帽通道）画不出来 —— 这两条**挂起待前台许可**，本轮只离线锁
    /// 「折了几段、端点数值对不对、三态各出什么」。
    ///
    /// 明细面板这一发**不是**自绘层，是原生 `Flyout`：见 [`Shell::mw3_context_meter_flyout`]。
    fn context_meter_cell(&self, context: &mut ViewContext<Shell>) -> Option<View> {
        let occ = self.active_occupancy()?;
        let p = Palette::for_scheme(self.scheme);
        // 主干 `CM:168-170` 一发两贴：tooltip 与无障碍名是**同一枚串**。
        let aria = cm::tooltip_and_aria(&self.catalog, occ);
        let track_side = cm::RING_BOX - cm::RING_STROKE;
        let mut parts: Vec<KeyedView> = vec![KeyedView::new(
            "track",
            View::from(
                Ellipse::new()
                    .stroke(p.stroke.clone())
                    .stroke_thickness(cm::RING_STROKE)
                    .width(track_side)
                    .height(track_side)
                    .horizontal_alignment(HorizontalAlignment::Center)
                    .vertical_alignment(VerticalAlignment::Center),
            ),
        )];
        match cm::face_of(occ.percent) {
            // `percent == 0`：弧与整圆都不出，只剩轨道（主干 `CM:187-192`）。
            // ⚠ 这一档**不是**「整颗圈收起」—— `used = 0` 是采到的读数，圈照旧在场。
            cm::RingFace::TrackOnly => {}
            cm::RingFace::Arc(_) => {
                let lines: Vec<KeyedView> = mw3_ring_chords(occ.percent, MW3_RING_CHORD_SEGMENTS)
                    .into_iter()
                    .enumerate()
                    .map(|(index, [x1, y1, x2, y2])| {
                        KeyedView::new(
                            format!("arc-chord-{index}"),
                            View::from(
                                Line::new()
                                    .x1(x1)
                                    .y1(y1)
                                    .x2(x2)
                                    .y2(y2)
                                    .stroke(p.text_tertiary.clone())
                                    .stroke_thickness(cm::RING_STROKE)
                                    .canvas_left(0.0)
                                    .canvas_top(0.0),
                            ),
                        )
                    })
                    .collect();
                // 弦近似落在这面 14×14 `Canvas` 上：圆心 7、半径 6 ⇒ 端点全在 1..=13，
                // **没有负坐标**，所以「`Shape` 当 `Canvas` 子级时负坐标被裁」那条风险在本档
                // 天然不成立；包围盒偏移另裁一笔与否仍属视觉判据，挂起待前台许可。
                parts.push(KeyedView::new(
                    "arc",
                    View::from(
                        Canvas::new()
                            .width(cm::RING_BOX)
                            .height(cm::RING_BOX)
                            .keyed_children(lines),
                    ),
                ));
            }
            // 满值走第二枚整圆（主干 `CM:189` 的理由：弧起终重合是退化几何）。
            cm::RingFace::Full => {
                parts.push(KeyedView::new(
                    "full",
                    View::from(
                        Ellipse::new()
                            .stroke(p.text_tertiary.clone())
                            .stroke_thickness(cm::RING_STROKE)
                            .width(track_side)
                            .height(track_side)
                            .horizontal_alignment(HorizontalAlignment::Center)
                            .vertical_alignment(VerticalAlignment::Center),
                    ),
                ));
            }
        }
        let face: View = Grid::new()
            .width(cm::RING_BOX)
            .height(cm::RING_BOX)
            .vertical_alignment(VerticalAlignment::Center)
            .keyed_children(parts)
            .into();
        // 主干那颗 `Button` 只有 `Tapped`（`RS:263` ⇒ 开面板）与 `CM:169-170` 那两贴，
        // **没有** hover 展开 ⇒ 分叉这边不给 `on_click`：面板由下面那发原生 `Flyout` 自己开。
        let button = pill_button(
            Button::new()
                .vertical_alignment(VerticalAlignment::Center)
                .automation_id("ContextMeterRing")
                .automation_name(aria.clone()),
            face,
            Pill::card(p),
            "context-meter-ring",
            HoverSlot::Pill,
            self.hover.as_deref(),
            self.pressed.as_deref(),
            context,
        );
        Some(button.flyout_with(self.mw3_context_meter_flyout(occ)).tooltip(aria))
    }

    /// 主干 `CM:218-259` 的 `ShowContextPanel` → `RunStats.cs:328-365` 的 `ShowRunFlyout`：
    /// **系统级 `Flyout`、`Placement = Top`、light-dismiss、应用级互斥**（三张同族面板共用它）。
    ///
    /// 分叉这一发照 #121 那条校准走原生路：reactor 的 `Flyout` 一族在 `element.rs:585`
    /// （`Flyout::rich` + `FlyoutPlacement::Top` 是**默认档**，正对主干那句 `Placement=Top`），
    /// 它的开法只有「挂在元素上、由那颗元素自己开」—— 而 #57 的锚点**就是**这颗圈 ⇒ 一条不用绕。
    /// 于是三件主干行为全由框架给：点圈即开、点外面即收、同刻至多一张 flyout
    /// ⇒ 分叉**不需要** Msg、不需要状态格、不需要那 13 处同级互斥落点
    /// （那族自绘层的兄弟清单是给「拿不到锚点」的浮层准备的，这里不属于那种）。
    ///
    /// 齐备闸在这一发里是**结构性的**：`context_meter_cell` 拿不到读数就整棵不入树，
    /// 面板连开口都没有 ⇒ 主干 `CM:222-225` 那句「读数缺位直接返回」不必另写一遍。
    fn mw3_context_meter_flyout(&self, occ: cm::ContextOccupancy) -> Flyout {
        Flyout::rich(self.mw3_context_panel_body(occ)).placement(FlyoutPlacement::Top)
    }

    /// label 在左、value 右对齐的一行 = 主干 `RunStats.cs:336-348` 的 `StatRow`
    /// （`ColumnSpacing=16`、列 `[*, Auto]`、label `Opacity=0.72`、value 右对齐，**零 id**）。
    fn mw3_context_stat_row(&self, label: String, value: String) -> View {
        let cells: Vec<KeyedView> = vec![
            KeyedView::new(
                "label",
                View::from(TextBlock::new().text(label).grid_column(0).opacity(0.72)),
            ),
            KeyedView::new(
                "value",
                View::from(
                    TextBlock::new()
                        .text(value)
                        .grid_column(1)
                        .horizontal_alignment(HorizontalAlignment::Right),
                ),
            ),
        ];
        Grid::new()
            .column_spacing(space::S16)
            .columns([GridLength::STAR, GridLength::Auto])
            .keyed_children(cells)
            .into()
    }

    /// 台账 #135 家 A 那张折叠的**读侧口**：主干 `UpdateRunStatsStrip`（`RS:217-222`）开头
    /// `_runStats.TryGetValue(sid, out st)` 那一句的等价物。形制照上一颗 `active_occupancy`：
    /// 没有当前会话、或台账里没这一格 ⇒ `None`（**零兜底值**，`unwrap_or` 会把「没有数」糊成
    /// 一个数，`context_panel_tests` 里那条禁令同款）。
    fn active_run_fold(&self) -> Option<&blade2_rs::kernel::RunStepFold> {
        let session = self.active.as_deref()?;
        self.run_stats.fold(session)
    }

    /// 主干 `MX:1041-1046` 那条 `RunStatsStrip`（`ComposerBar` 的 **Row 0**，输入卡**上方**）的
    /// 分叉宿主：横向 `StackPanel{Spacing=Space6}` + `HorizontalAlignment=Center` + 两枚胶囊。
    ///
    /// 可见闸**只有一把** = [`RunStepFold::strip_visible`]（主干 `RS:224-228` 那句
    /// `st is null || st.Steps <= 0 ⇒ Collapsed`）。⚠ **验收口径**（别为「看得见」去改判据）：
    /// 假内核默认档 `--step=0` 不推 step 帧 ⇒ 接完宿主**整条不显是正确行为**，GUI / ipc 验收
    /// 必须显式 `--step=1`（RD6 §B-5 尾注）；`--step=4`（只 start 不 end，`llm_ms` 已偷跑）同样
    /// 收起 ⇒ 拿 `llm_ms > 0` 当判据就是主干没有的那一档。主干也**没有**「运行中/排队/重试/
    /// 完成」四态机（retry、`turn/*`、队列帧全不在六型白名单），别在这里发明。
    ///
    /// 两张浮层的**唯一**入口就是这两枚胶囊 ⇒ 条收起 = 条 + 两浮层三件同族一起消失，与主干一致
    /// （主干 `WireRunStatsUi` `RS:259-262` 那两发 `Tapped` 也只在条上）。
    fn run_stats_strip(&self) -> Option<View> {
        let fold = self.active_run_fold()?;
        if !fold.strip_visible() {
            return None;
        }
        let locale = self.catalog.locale();
        let turns = self.catalog.lf(
            "{0} 轮 {1} 步 · {2} tok/s",
            &[
                fold.turns.to_string(),
                fold.steps.to_string(),
                run_stats_tps(fold.decode_ms, fold.decode_tokens),
            ],
        );
        // 右胶囊 = 主干 `RS:231` 的**显式拼接**：表里那枚 `{0} tok · 缓存命中 {1}%` 虽然登记着，
        // 主干调用点却不走它（死行），照调用点逐字抄 ⇒ 单位与 `%` 各只出现一次（`:230` 注释
        // 记的 `%%` / `tok tok` 叠加事故就出在拿模板再贴一遍单位）。
        let tokens = format!(
            "{} tok · {} {}%",
            tokens_text(locale, fold.total_tokens),
            self.catalog.l("缓存命中"),
            run_stats_cache_hit(fold.cache_read_tokens, fold.input_tokens)
        );
        Some(
            StackPanel::new()
                .orientation(Orientation::Horizontal)
                .spacing(space::S6)
                .horizontal_alignment(HorizontalAlignment::Center)
                .children((
                    self.run_stats_strip_cell(
                        "RunStatsTurnsText",
                        turns,
                        self.run_stats_stats_body(fold),
                    ),
                    self.run_stats_strip_cell(
                        "RunStatsTokensText",
                        tokens,
                        self.run_stats_token_body(fold),
                    ),
                ))
                .into(),
        )
    }

    /// 条上那一枚胶囊 = 主干 `MX:1044/1045` 那两枚 `TextBlock x:Name=RunStatsTurnsText /
    /// RunStatsTokensText`（`HintTextStyle` = `CaptionTextStyle`(字号 12 / 行高 16) +
    /// `TextTertiaryBrush`，`VerticalAlignment=Center`）。UIA id 逐字取那两枚 `x:Name`
    /// （WinUI 的 `AutomationPeer` 在 `AutomationId` 缺席时回落元素名，与 `AgentModeLabel`
    /// 同一口径），**零 glyph、零图标**：主干这条上没有。
    ///
    /// 【框架现测 · 三层字节】这一格是本轮唯一**框架逼着的形态差**：主干那两枚 `TextBlock` 自己
    /// 能吃 `Tapped` 并开附着 flyout，reactor 0.100.0 的 flyout 只认两种宿主 ——
    /// · `element.rs:612-625`：`FlyoutExt` 是 `impl<T> FlyoutExt for T where T: Into<View>`
    ///   ⇒ 给 `TextBlock` 挂 `.flyout_with(…)` **编译得过**（只查这一层就会误判成「货架上有」）；
    /// · `native/winui/mod.rs:2138-2142`：`match target_handle { Handle::Button(…) => SetFlyout,
    ///   Handle::SplitButton(…) => SetFlyout, _ => return Err(RuntimeError::UnsupportedKind) }`
    ///   ⇒ 别的控件类型**运行期直接不吃**；
    /// · `native/winui/bindings.rs`：全表 `fn SetFlyout` 只有 `impl IButton`（`:5930`）与
    ///   `impl ISplitButton`（`:16027`）两枚，`IFlyoutBaseStatics` 那种附着属性入口在整个
    ///   bindings 与 `generated.rs` 里**零命中**（`fn flyout` 在 `generated.rs` 亦零命中）
    ///   ⇒ COM 侧根本没有「给任意 FrameworkElement 挂 flyout」这条通道。
    /// 于是照 `TextBlock` 画 = 一颗开不出来的死控件（本仓硬禁），这里换成**四态全透明**的
    /// `Button`（`button_ghost`，#29 定案配方），只留命中与文本；脸与串仍逐字照主干那一档。
    fn run_stats_strip_cell(&self, id: &str, text: String, body: View) -> View {
        let p = Palette::for_scheme(self.scheme);
        let face: View = TextBlock::new()
            .text(text.clone())
            .font_size(type_ramp::CAPTION.size)
            .foreground(p.text_tertiary.clone())
            .vertical_alignment(VerticalAlignment::Center)
            .into();
        let cell: View = Button::new()
            // `.style(ButtonStyle::Subtle)` 与 `resource_overrides` 同挂会 native fail-fast
            // （既有那条禁令记在 `agent_mode_trigger` 上），这里只走覆写那一族；
            // `BorderThickness` 那颗键**绝不能**覆（同族 fail-fast 成因，见 `button_ghost`）。
            .resource_overrides(button_ghost(None).set("ButtonPadding", th([0.0; 4])))
            .min_width(0.0)
            .vertical_alignment(VerticalAlignment::Center)
            .automation_id(id)
            .automation_name(text)
            .content(face)
            .into();
        cell.flyout_with(self.run_stats_flyout(body))
    }

    /// 主干 `ShowStatsPanel`（`RS:266-280`）那张 `panel`：`StackPanel{Spacing=10,MinWidth=250}`
    /// + 头行 + 四行 `StatRow`。行序与换算式逐格照抄，两处**主干自身的怪异一并忠实保留**：
    /// · TTFT 那行的 `—` 只看 `ttft_steps`（`RS:276-277`），时长走 `(ttft_ms / ttft_steps)` 的
    ///   **整除**（= 主干 `FormatDuration(double)` 里 `TimeSpan` 的向零截断；取整会多打一秒，
    ///   RD6 T4-6 那条 1999.6ms ⇒「1 秒」）；两侧都 `.max(0)`，抵掉主干秒档那句 `Math.Max(0,…)`；
    /// · TPS 那行画的是 `run_stats_tps(...) + " tok/s"` ⇒ 解码量为 0 时是 **`— tok/s`** 不是 `—`
    ///   （`RS:278` 那发拼接所致，不是漏判据）。
    fn run_stats_stats_body(&self, fold: &blade2_rs::kernel::RunStepFold) -> View {
        let ttft = if fold.ttft_steps > 0 {
            duration_text((fold.ttft_ms / fold.ttft_steps).max(0))
        } else {
            STATS_DASH.to_string()
        };
        let header = self.run_stats_panel_header(self.catalog.l("会话统计"));
        let llm_row = self.mw3_context_stat_row(
            self.catalog.l("模型用时"),
            duration_text(fold.llm_ms.max(0)),
        );
        let tool_row = self.mw3_context_stat_row(
            self.catalog.l("工具调用用时"),
            duration_text(fold.tool_ms.max(0)),
        );
        let ttft_row = self.mw3_context_stat_row(self.catalog.l("首 token 平均（TTFT）"), ttft);
        let tps_row = self.mw3_context_stat_row(
            self.catalog.l("输出速度（TPS）"),
            run_stats_tps(fold.decode_ms, fold.decode_tokens) + " tok/s",
        );
        StackPanel::new()
            .orientation(Orientation::Vertical)
            .spacing(space::S10)
            .min_width(Self::CONTEXT_PANEL_MIN_WIDTH)
            .children((header, llm_row, tool_row, ttft_row, tps_row))
            .into()
    }

    /// 主干 `ShowTokenPanel`（`RS:285-311`）那张 `panel`。⚠ 头行与上一张**不同构**：主干这里是
    /// **手搓两列 Grid**（`ColumnSpacing=16`、`[*,Auto]`，左标签**不加粗**、右格放总量），
    /// 而 `会话统计` 那张才走 `MakePanelHeader` 的「加粗 + 内嵌分隔件」双层壳 ⇒ 两张的头行
    /// 不许抄成一个样（#57 那把容量圈头行锁同一口径）。
    /// 总量那格是 `TotalTokens.ToString("N0") + " tok"`（**千分位，不是紧凑档**）= `mw5_tokens_n0`；
    /// 命中率那格 `run_stats_cache_hit(...) + "%"` ⇒ 分母为 0 时主干画的就是 **`—%`**（`:307`）。
    fn run_stats_token_body(&self, fold: &blade2_rs::kernel::RunStepFold) -> View {
        let head_cells: Vec<KeyedView> = vec![
            KeyedView::new(
                "label",
                View::from(TextBlock::new().text(self.catalog.l("Token 用量"))),
            ),
            KeyedView::new(
                "value",
                View::from(
                    TextBlock::new()
                        .text(mw5_tokens_n0(fold.total_tokens))
                        .grid_column(1)
                        .horizontal_alignment(HorizontalAlignment::Right),
                ),
            ),
        ];
        let head: View = Grid::new()
            .column_spacing(space::S16)
            .columns([GridLength::STAR, GridLength::Auto])
            .keyed_children(head_cells)
            .into();
        let separator = self.run_stats_panel_separator();
        let hit_row = self.mw3_context_stat_row(
            self.catalog.l("缓存命中"),
            run_stats_cache_hit(fold.cache_read_tokens, fold.input_tokens) + "%",
        );
        let input_row = self.mw3_context_stat_row(
            self.catalog.l("未缓存输入"),
            mw5_tokens_n0(fold.input_tokens),
        );
        let read_row = self.mw3_context_stat_row(
            self.catalog.l("缓存读取"),
            mw5_tokens_n0(fold.cache_read_tokens),
        );
        let output_row = self.mw3_context_stat_row(
            self.catalog.l("输出"),
            mw5_tokens_n0(fold.output_tokens),
        );
        StackPanel::new()
            .orientation(Orientation::Vertical)
            .spacing(space::S10)
            .min_width(Self::CONTEXT_PANEL_MIN_WIDTH)
            .children((head, separator, hit_row, input_row, read_row, output_row))
            .into()
    }

    /// 主干 `MakePanelHeader`（`RS:320-326`）：`StackPanel{Spacing=8}` 里一枚 **SemiBold** 标签
    /// 紧随一枚 1px 分隔件（双层壳）。只有这两张新面板走它（容量圈那张头行是手搓 Grid）。
    fn run_stats_panel_header(&self, label: String) -> View {
        let title: View = TextBlock::new()
            .text(label)
            .font_weight(FontWeight::SEMI_BOLD)
            .into();
        let separator = self.run_stats_panel_separator();
        StackPanel::new()
            .orientation(Orientation::Vertical)
            .spacing(space::S8)
            .children((title, separator))
            .into()
    }

    /// 主干 `MakePanelSeparator`（`RS:328-333`）：`Border{Height=1, Background=StrokeBrush}`，
    /// 读不到退**透明**（不是退白）。与 `mw3_context_panel_body` 里那枚同一刻法、同一档值。
    fn run_stats_panel_separator(&self) -> View {
        let p = Palette::for_scheme(self.scheme);
        Border::new()
            .height(1.0)
            .background(p.stroke.clone())
            .into()
    }

    /// 两张浮层共用的那颗壳 = 主干 `ShowRunFlyout`（`RS:350-365`）：`Flyout{Placement=Top}` +
    /// 一层 `Border{CardBrush 底 / StrokeBrush 1px / CornerRadius=8 / Padding 14,12,14,12}`。
    /// 三张同族面板（容量圈明细 + 这两张）在主干共用这一颗 ⇒ 分叉也共用，且**不新建第 11 张
    /// 自绘层、零 Msg、零状态格**：点即开、点外面即收、同刻至多一张全由框架给（#57 同款实证）。
    /// 外壳那四件与 `CONTEXT_PANEL_*` 三常量同值 ⇒ 直接读它们，不起第二份数值真相。
    fn run_stats_flyout(&self, body: View) -> Flyout {
        let p = Palette::for_scheme(self.scheme);
        let host: View = Border::new()
            .background(p.card.clone())
            .border_brush(p.stroke.clone())
            .border_thickness(th([size::STROKE; 4]))
            .corner_radius(radius::MEDIUM)
            .padding(th(Self::CONTEXT_PANEL_PADDING))
            .content(body)
            .into();
        Flyout::rich(host).placement(FlyoutPlacement::Top)
    }

    /// 主干 `ComposerBar` 那颗 `Grid`（`MX:1033-1046`，两行 `Auto`）的分叉等价：**Row 0 = 条、
    /// Row 1 = 输入卡**，序就两格。条是 `None` ⇒ 整格不入树（主干 `Visibility="Collapsed"` 的
    /// 等价物，reactor 无 `Visibility`）。用 `keyed_children` 而不是 `children`：件数会随条的
    /// 在场与否变（1 或 2），而 reactor 的 `IntoViews` 明确不收动态集合。
    /// 单开这一颗是为了让 `fn composer` 本体那一百六十行**一属性都不动**（那三把计数针见其 doc）。
    fn composer_host(strip: Option<View>, card: View) -> View {
        let mut parts: Vec<KeyedView> = Vec::with_capacity(2);
        if let Some(strip) = strip {
            parts.push(KeyedView::new("run-stats-strip", strip));
        }
        parts.push(KeyedView::new("composer-card", card));
        StackPanel::new()
            .orientation(Orientation::Vertical)
            .keyed_children(parts)
            .into()
    }

    /// 主干 `CM:226-258` 那张 `panel`（`ShowContextPanel` 的表体）：头行 + 分隔件 + 占比条 +
    /// 三张 `StatRow`。数值逐格抄：`Spacing=10` / `MinWidth=250` / 头行 `ColumnSpacing=16` /
    /// 条 `Min0 Max100 Value=percent Height=4`；三行 = `已用`「~used / window tok」、
    /// `已用 token`（`TokensN0(used)`）、`上下文容量`（`TokensN0(window)`）。
    /// 紧凑近似那格复用分叉既有的 [`tokens_text`]（`FormatTokensCompact` 的对应物，
    /// 行 1298 那处注释已认领），裸整数带单位那两格用 [`mw5_tokens_n0`]（`TokensN0` 的逐字等价，
    /// 千分位仍走 [`n0`]）⇒ **不**起第三份，也不许把单位塞进 `n0`（它有四位不带单位的读者）。
    /// 外壳那颗 `Border`（`CardBrush` 底 + `StrokeBrush` 1px + `CornerMedium=8` +
    /// padding `14,12,14,12`）逐字节抄 `RunStats.cs:350-365`。
    fn mw3_context_panel_body(&self, occ: cm::ContextOccupancy) -> View {
        let p = Palette::for_scheme(self.scheme);
        let locale = self.catalog.locale();
        let head_cells: Vec<KeyedView> = vec![
            KeyedView::new(
                "title",
                View::from(TextBlock::new().text(self.catalog.l("上下文"))),
            ),
            KeyedView::new(
                "percent",
                View::from(
                    TextBlock::new()
                        .text(format!("{}%", occ.percent))
                        .grid_column(1)
                        .horizontal_alignment(HorizontalAlignment::Right),
                ),
            ),
        ];
        let head: View = Grid::new()
            .column_spacing(space::S16)
            .columns([GridLength::STAR, GridLength::Auto])
            .keyed_children(head_cells)
            .into();
        let separator: View = Border::new()
            .height(1.0)
            .background(p.stroke.clone())
            .into();
        let bar: View = ProgressBar::new()
            .minimum(0.0)
            .maximum(100.0)
            .value(occ.percent as f64)
            .is_indeterminate(false)
            .height(Self::CONTEXT_PANEL_BAR_HEIGHT)
            .horizontal_alignment(HorizontalAlignment::Stretch)
            .into();
        let used_row = self.mw3_context_stat_row(
            self.catalog.l("已用"),
            format!(
                "~{} / {} tok",
                tokens_text(locale, occ.used),
                tokens_text(locale, occ.window)
            ),
        );
        let used_tokens_row = self.mw3_context_stat_row(
            self.catalog.l("已用 token"),
            mw5_tokens_n0(occ.used),
        );
        let capacity_row = self.mw3_context_stat_row(
            self.catalog.l("上下文容量"),
            mw5_tokens_n0(occ.window),
        );
        let rows: View = StackPanel::new()
            .orientation(Orientation::Vertical)
            .spacing(space::S10)
            .min_width(Self::CONTEXT_PANEL_MIN_WIDTH)
            .children((head, separator, bar, used_row, used_tokens_row, capacity_row))
            .into();
        Border::new()
            .background(p.card.clone())
            .border_brush(p.stroke.clone())
            .border_thickness(th([size::STROKE; 4]))
            .corner_radius(radius::MEDIUM)
            .padding(th(Self::CONTEXT_PANEL_PADDING))
            .content(rows)
            .into()
    }

    /// 输入区动作行**中间那一格**（原来只放 #106 那颗任务徽标）。主干那一格的列序是
    /// `+ / 工作区 / Agent 模式 / 权限 / *计划 chip / 模型 / 上下文容量 / 发送`
    /// （`MX:1130-1148` 那八列的定义），分叉这边只有 `[Auto, *, Auto]` 三列 ⇒ 把选择器组
    /// 并进中间那一格，**列数一个不改**（为浮层加列会把正文挤窄，那条口径见
    /// `chat_page` 里那把反向源码锁）。
    /// 顺序：任务徽标在前、选择器在后。#106 那颗的落点是 GUI 轮验过的（`tmp/md1-report.md` §3），
    /// 挪它等于回归；主干那颗本来也不在这条带上（它在会话头），所以这条序是**分叉既有偏差的延长线**。
    /// #57 在这一格里追加**第四枚** keyed 槽（键 `"context-meter"`），排在 `permission` 之后。
    fn composer_band(&self, context: &mut ViewContext<Shell>) -> View {
        let mut cells: Vec<KeyedView> =
            vec![KeyedView::new("todos", self.todos_entry_cell(context))];
        // 批 M4：主干那颗 `TrajectoryMenuItem` 长在「+」flyout 里（分叉没有那张）⇒
        // 沿 #106 那颗任务徽标的同一先例落进这条带，位置排在它之后（形制偏差，见报告）。
        // ⚠ 批 M4b 补上母本的**首帧才挂**（`Traj:172`：`EnsureTrajectoryUiEntry` 只在
        // `TrajectoryObserve` 收到第一发 journal 帧时被调，旗 `_trajectoryEntryWired` 一挂不摘）
        // ⇒ 零帧时主干那条 flyout 里**没有**这一项，分叉常驻就是多画一件主干没有的东西。
        // 判据取「账本为空」= 母本那枚一次性旗的等价物（每帧现算，喂过就一直在、没喂过就不在场）；
        // 不入树 = 本带下面那圈 `Option` 槽的既有口径（`Visibility.Collapsed` 的结构性等价）。
        if !self.trajectory_journal.is_empty() {
            cells.push(KeyedView::new("trajectory", self.trajectory_entry_cell(context)));
        }
        // 批 P155（#155）：主干 `SchedulesMenuItem`（`CP:95`）同族第三颗。挂在轨迹那颗**之后** =
        // 主干 `CP:82-92` 那条「插在 `L("会话反馈")` 之前，否则末位」的分叉等价物：本带**没有**
        // 「会话反馈」那一族（分叉没有 `ComposerAddFlyout`），末位就是这三颗 flyout 血统的徽标之后。
        // ⚠ **无条件**在场，与上一颗的「首帧才挂」**不**同档：主干 `EnsureCapabilityUiEntries` 在
        // boot（`MW:2615`）与切会话（`MW:4515`）两处都调、靠 `_capabilityFlyoutWired` 幂等，
        // 三颗恒挂、不按数据显隐（spec §4.4「缺数据整颗收起」那一行：本卡不收起）。
        cells.push(KeyedView::new("schedules", self.schedules_entry_cell(context)));
        // 批 SKP1（#158 卡 A）：技能那颗 = 主干 `CP:96` 的 `AddEntry("SkillsMenuItem", …)`。
        // 位置 = 计划之后、会话反馈之前 = 主干 `CP:82-92` 那句「插到 `Text == L("会话反馈")` 那一格
        // **之前**，找不到才末位」的**字面**等价物（主干 flyout 序 `计划 → 技能 → Cordis → 会话反馈`，
        // Cordis 那张还没移植 ⇒ 今天正好补齐前三枚的相对序）。
        // ⚠ 同样**无条件**在场：它与那三颗同族、同一幂等旗，不按数据显隐（本卡读会话 id，不是投影）。
        cells.push(KeyedView::new("skills", self.skill_picker_entry_cell(context)));
        // 批 CD1（#158 面 B）：Cordis 那颗 = 主干 `CP:97` 的 `AddEntry("CordisMenuItem", …)`。
        // 位置 = 技能之后、会话反馈之前 = 主干 `CP:82-92` 那句「插到 `L("会话反馈")` 那一格
        // **之前**」的字面等价物 ⇒ 上面 SKP1 那段注释里「今天正好补齐前三枚的相对序」从今天起
        // 补齐**前四枚**（计划 → 技能 → Cordis → 会话反馈，与主干 flyout 序逐枚同）。
        // ⚠ 同样**无条件**在场：它与那三颗同族、同一幂等旗，不按数据显隐（本卡读内核那一发清单）。
        cells.push(KeyedView::new("cordis", self.cordis_panel_entry_cell(context)));
        // 批 SFB1（#158 卡 B）：会话反馈那颗 = 主干那张「+」flyout 的第④项（`MX:1169`），
        // 排在计划那颗**之后**正是主干 `CP:82-92` 那句「插在 `L("会话反馈")` 之前，否则末位」的
        // 分叉等价物 ⇒ 上面 P155 那三行注释里「本带没有会话反馈那一族」从今天起只对**当时**成立
        // （它写的是 P155 落刀那一刻的现测，一字不改；此处补一句免得下一个读者拿它当今天的账）。
        // ⚠ 批 SKP1 之后上面那句「今天」的账再挪一格：能力那几颗的相对序现在补齐了
        //   （计划 → 技能 → 会话反馈），会话反馈仍是这三枚里最末那一枚，与主干同序。
        // ⚠ 同样**无条件**在场：主干那颗是 `EnsureCapabilityUiEntries` 恒挂的 flyout 项，不按数据
        // 显隐（本卡读的是会话 id，不是投影）。
        cells.push(KeyedView::new(
            "session-feedback",
            self.session_feedback_entry_cell(context),
        ));
        // 每一颗自己决定在不在场（`None` = 不入树 = 主干 `Visibility.Collapsed`）。
        for (key, cell) in [
            ("agent-mode", self.agent_mode_trigger(context)),
            // #56 第二颗。列序照主干 `MX:1216-1259`：Agent 模式在前、权限在后。
            ("permission", self.permission_trigger(context)),
            // #56 第四颗 = 主干 `MX:1259-1276` 的第 4 列（权限与模型**之间**）。这是本仓第一枚
            // 插在既有两枚**之间**的 keyed 槽：口径不是「追加到末尾」而是「按主干列序摆」，
            // 判据见 `the_plan_chip_sits_between_permission_and_model`。`Option` 判空即主干
            // 那颗 `Visibility="Collapsed"`（`MX:1261`）。
            ("plan-chip", self.plan_chip(context)),
            // #56 第三颗 = 主干 `MX:1277-1295` 的第 5 列。⚠ 这一枚**包在 `Some` 里不是漏改**：
            // 主干那颗 `ModelButton.Visibility` 全仓零赋值 ⇒ 它永远在场，`model_trigger` 也因此
            // 返 `View` 而不是 `Option<View>`（与旁边那颗的签名差别就在这一格）。
            ("model", Some(self.model_trigger(context))),
            // #57 那颗 = 主干带内顺序注释 `MX:1126` 的第 6 列「上下文容量」，落在「模型胶囊与
            // 发送之间」。#56 的模型钮落地后它仍是**最后一格**，与主干列序一致（模型第 5 列、
            // 上下文第 6 列）。**不开新列**（`composer` 那三列原样，见主控锁的反向半边）。
            ("context-meter", self.context_meter_cell(context)),
        ] {
            if let Some(cell) = cell {
                cells.push(KeyedView::new(key, cell));
            }
        }
        StackPanel::new()
            .orientation(Orientation::Horizontal)
            .spacing(space::S8)
            .vertical_alignment(VerticalAlignment::Center)
            .keyed_children(cells)
            .into()
    }

    /// 主干 `AgentModeButton`（`MX:1209-1231`）：`FontIcon E9D9` + `AgentModeLabel` 那颗
    /// `TextBlock`，`AutomationId="AgentModeButton"` + `Name="Agent 模式"` + tooltip
    /// 「即将开始的这个会话所用的 Agent 预设」。
    /// **只在空态在场**：`MW:4717-4720` 那句 `var hero = IsHeroState(); … AgentModeButton.Visibility = hero ? Visible : Collapsed`。
    /// ⚠ 那条判据里**没有** `KernelBootPanel` —— `UpdateEmptyState`（`MW:4804`）那句
    /// `IsHeroState() && KernelBootPanel.Visibility != Visible` 管的是 `ChatHero` 那块遮罩，
    /// 加载卡亮着时选择器照旧在场。分叉 `chat_page` 里那格 `hero` 是两件事共用的
    /// （`self.hero_state() && !self.boot.showing`）⇒ 这里**不复用那一格**，另读
    /// [`Shell::hero_state`] 单判据，不然加载期会凭空少三颗控件。
    fn agent_mode_trigger(&self, context: &mut ViewContext<Shell>) -> Option<View> {
        if !self.hero_state() {
            return None;
        }
        let name = self.catalog.l("Agent 模式");
        let tooltip = self.catalog.l("即将开始的这个会话所用的 Agent 预设");
        let button: View = Button::new()
            // 透明四态那组覆写 = `todos_entry_cell` / `nav_row` 里实测过能起的刻法；
            // `.style(ButtonStyle::Subtle)` 与 `resource_overrides` 同挂会 native fail-fast
            // （0xC000027B，两条都记在 `feedback_text_button` 那一带的注释上）。
            .resource_overrides(button_ghost(None))
            .min_width(0.0)
            .vertical_alignment(VerticalAlignment::Center)
            .horizontal_content_alignment(HorizontalAlignment::Left)
            .automation_id("AgentModeButton")
            .automation_name(name.clone())
            .on_click(context.message(Msg::SelectorToggle(SelectorKind::AgentMode)))
            .content(
                // 主干那颗 `DropDownButton.Content` 是个 `[Auto, *]` 的两列 Grid + `Spacing=Space6`
                // （`MX:1216-1226`）⇒ 这里用横向 `StackPanel{spacing=Space6}` 等价（列只在需要
                // `*` 吸收余量时才有意义，而这颗的 `TextBlock` 是 `TextTrimming=CharacterEllipsis`
                // + `NoWrap`，贴合内容）。
                StackPanel::new()
                    .orientation(Orientation::Horizontal)
                    .spacing(space::S6)
                    .vertical_alignment(VerticalAlignment::Center)
                    .children((
                        mark_size(AGENT_MODE_GLYPH, size::GLYPH_BODY),
                        TextBlock::new()
                            .text(agent_mode_label(
                                &self.catalog,
                                self.pending_agent_preset.as_ref(),
                            ))
                            .font_size(type_ramp::BODY.size)
                            .text_wrapping(TextWrapping::NoWrap)
                            .vertical_alignment(VerticalAlignment::Center)
                            // 主干那枚 `x:Name="AgentModeLabel"`（`MX:1223`）在 UIA 里就是
                            // AutomationId（WinUI 的 `AutomationPeer` 在 `AutomationId` 缺席时
                            // 回落元素名）⇒ 分叉显式挂同名，不自造、不拼串。
                            .automation_id("AgentModeLabel"),
                    )),
            )
            .into();
        Some(button.tooltip(tooltip))
    }

    /// 那张展开层 = 整格透明遮罩（light-dismiss）+ 贴左下那张卡。入树序与互斥见 `chat_page`
    /// 里 `"selectors"` 那一格与 `Msg::SelectorToggle` 那臂。
    fn selector_layer(&self, context: &mut ViewContext<Shell>, p: Palette) -> View {
        let scrim: View = Border::new()
            .grid_row(0)
            .horizontal_alignment(HorizontalAlignment::Stretch)
            .vertical_alignment(VerticalAlignment::Stretch)
            .background(p.transparent.clone())
            .on_pointer_pressed(context.callback(|_| Msg::SelectorClose))
            .into();
        let card: View = match self.selectors {
            Some(SelectorKind::AgentMode) => self.agent_mode_menu(context, p),
            // #56 第二颗：同一张层、同一把 `selectors` 单例槽 ⇒ 「同刻至多一张」不需要额外装置。
            Some(SelectorKind::Permission) => self.permission_menu(context, p),
            // #56 第三颗：同一张层、同一把单例槽 ⇒ 「同刻至多一张」继续不需要额外装置。
            Some(SelectorKind::Model) => self.model_menu(context, p),
            // `None` 由 `chat_page` 的判据挡在门外，这一支到不了；留着是为了 `match` 穷尽。
            None => blank(),
        };
        Grid::new()
            .rows([GridLength::STAR])
            .children((scrim, card))
    }

    /// `AgentModeFlyout` 的表体（主干 `MW:4822-4872`）：内置四档 + `agentPresets/list` 的自定义档。
    /// 抄不动的两件，逐条记在报告 §8：
    /// · `RadioMenuFlyoutItem` 的**单选点** ⇒ 用 `ButtonStyle::Accent` 那一档底当前档（与
    ///   [`Shell::file_action_menu`] 表达「这一行是选中的」同一件既有装置），行内文案与 UIA
    ///   `Name` 保持与主干 `Text` 逐字同串，不加「（当前）」那类推论；
    /// · 主干 `ShowAt(anchor, Top)` 要把卡片钉在触发器上沿，而分叉读不回元素的屏幕矩形
    ///   ⇒ 贴内容面**左下**（触发器在动作行左段，`Placement=Top` 的卡片就在它上面）。
    ///   偏移用主干自己那枚 `ComposerSelectorsMargin`（`Theme/Tokens.xaml:67` = `20,0,16,2`，
    ///   分叉 `pad::COMPOSER_SELECTORS` 同值），不另造数值。
    fn agent_mode_menu(&self, context: &mut ViewContext<Shell>, p: Palette) -> View {
        let current = self.pending_agent_preset.as_ref().map(|(id, _)| id.clone());
        let rows = agent_mode_rows(current.as_deref(), &self.agent_presets);
        let mut cells: Vec<KeyedView> = Vec::new();
        for row in rows {
            // 文案两条通路（`MW:4835` 过表 / `MW:4863` 不过表），别并成一条。
            let text = if row.builtin {
                self.catalog.l(&row.name)
            } else {
                row.name.clone()
            };
            let cell: View = Button::new()
                .automation_id(format!("AgentMode_{}", row.id))
                .automation_name(text.clone())
                .min_width(0.0)
                .horizontal_alignment(HorizontalAlignment::Stretch)
                .horizontal_content_alignment(HorizontalAlignment::Left)
                .style(row.checked.then_some(ButtonStyle::Accent))
                .on_click(context.message(Msg::AgentModePick(row.id.clone(), row.name)))
                .content(
                    TextBlock::new()
                        .text(text)
                        .font_size(type_ramp::BODY.size)
                        .text_wrapping(TextWrapping::NoWrap)
                        .vertical_alignment(VerticalAlignment::Center),
                )
                .into();
            cells.push(KeyedView::new(format!("agent-mode-{}", row.id), cell));
        }
        Border::new()
            .grid_row(0)
            .horizontal_alignment(HorizontalAlignment::Left)
            .vertical_alignment(VerticalAlignment::Bottom)
            .margin(th(pad::COMPOSER_SELECTORS))
            .background(p.card.clone())
            .border_brush(p.stroke.clone())
            .border_thickness(size::STROKE)
            .corner_radius(radius::MEDIUM)
            .automation_id("AgentModeFlyout")
            .automation_name(self.catalog.l("Agent 模式"))
            .content(
                StackPanel::new()
                    .orientation(Orientation::Vertical)
                    .keyed_children(cells),
            )
            .into()
    }

    /// ComposerCard：`Border(Card/Stroke/1/r=12, padding 0,8,4,0)` + 输入框 + 动作行。
    ///
    /// #58 M2 给外层那颗（= 主干 `ComposerBar`，带 `pad::COMPOSER_BAR` 边距的那颗）补上了
    /// 主干 **Row 0** 的宿主：content 过一道 `composer_host`，把 `run_stats_strip` 叠在输入卡
    /// **上方**（主干那条 `RunStatsStrip` 在卡**外面**、卡上面，不是 `composer_band` 那一格）。
    /// ⚠ 本窗那三把计数针（见 `tests/contextmeter_host.rs` 与本文件 `sp2` 前缀那颗宿主锁的
    /// 反向半边）一枚都不许漂 ⇒ 叠两行**只准**纵向 `StackPanel`，多开一列就是把正文挤窄。
    fn composer(&self, context: &mut ViewContext<Shell>, p: Palette, row: i32) -> View {
        // 主干的发送键是「发送/停止」二态切换，不因输入为空而禁用。
        let running = self.active_running();
        Border::new()
            .grid_row(row)
            .margin(th(pad::COMPOSER_BAR))
            .content(Self::composer_host(
                // 条不在场 ⇒ `composer_host` 只收卡那一格（主干 `Visibility="Collapsed"`）。
                self.run_stats_strip(),
                Border::new()
                    .background(p.card)
                    .border_brush(p.stroke)
                    .border_thickness(size::STROKE)
                    .corner_radius(radius::LARGE)
                    .padding(th(pad::COMPOSER_CARD))
                    .content(
                        StackPanel::new()
                            .orientation(Orientation::Vertical)
                            .children((
                                Border::new()
                                    .padding(th(pad::COMPOSER_INPUT))
                                    // 焦点证据（正向）：框架里只有 `Border` 挂了 `PointerPressed`，
                                    // 而指针按进 composer 那一格 = 主干那颗 InputBox 拿到焦点。
                                    // 只加事件回调，不加任何容器/尺寸 ⇒ 布局与观感零变化。
                                    .on_pointer_pressed(context.callback(|_| Msg::KeyFocus(KeyOwner::Composer)))
                                    .content(
                                    TextBox::new()
                                        .text(self.input.clone())
                                        .placeholder_text(
                                            self.catalog.l(
                                                "描述你想要构建的内容, / 调用指令, @ 文件或对话",
                                            ),
                                        )
                                        .accepts_return(true)
                                        .text_wrapping(TextWrapping::Wrap)
                                        .min_height(size::COMPOSER_INPUT_MIN_HEIGHT)
                                        .max_height(size::COMPOSER_INPUT_MAX_HEIGHT)
                                        .background(p.transparent)
                                        .border_thickness(0.0)
                                        .on_text_changed(
                                            context.callback(|text: String| Msg::Input(text)),
                                        )
                                        .automation_id("InputBox")
                                        .automation_name(self.catalog.l("消息输入框")),
                                ),
                                Border::new().padding(th(pad::COMPOSER_ROW)).content(
                                    Grid::new()
                                        .columns([
                                            GridLength::Auto,
                                            GridLength::STAR,
                                            GridLength::Auto,
                                        ])
                                        .column_spacing(8.0)
                                        .children((
                                            // 主干 `MainWindow.xaml:1055-1068` ComposerAddButton：
                                            // 28×28、Padding 0、CornerRadius=CornerPill(24)、
                                            // Background=CardHoverBrush、BorderThickness=0、
                                            // 字形 E710 @ GlyphSizeBody=14。
                                            // 旧写法用 `ButtonBorderThickness`（无效键）⇒ 留着一圈
                                            // 1px 灰描边；圆角走 `ControlCornerRadius` 覆盖 ⇒ 静默
                                            // 无效，渲染成 4px 圆角方块。现在整颗走 `pill_button`。
                                            pill_button(
                                                Button::new()
                                                    .on_click(context.message(Msg::Note(
                                                        self.catalog.l("附件尚未移植"),
                                                    )))
                                                    .automation_id("ComposerAddButton")
                                                    .automation_name(
                                                        self.catalog.l("添加附件或操作"),
                                                    ),
                                                mark_size(glyph::NEW_SESSION, size::GLYPH_BODY),
                                                Pill::card(p),
                                                "composer-add",
                                                HoverSlot::Row,
                                                self.hover.as_deref(),
                                                self.pressed.as_deref(),
                                                context,
                                            ),
                                            // #106（MD1）+ #56（MT2/MT3）：动作行的**中间那一格**。
                                            // 这一格现在由 [`Shell::composer_band`] 一家决定摆什么，
                                            // `composer` 自己不再直接点某一颗 —— 否则选择器那颗触发器
                                            // 就没有宿主（dead code）。格内逐颗的落点/偏差理由：
                                            // · 任务徽标：主干 `EnsureTodosUiEntry`
                                            //   （`MainWindow.SessionState.cs:563-641`）把这颗徽标钮
                                            //   插在**会话头动作区** `JobsTriggerButton` 之前
                                            //   （`SS:634-637`），且**非常驻**：`SnapshotTodos()` 为
                                            //   null 或空表时那一格 `Visibility=Collapsed`
                                            //   （`SS:656-657`，建出来即 Collapsed `SS:603`）。
                                            //   两处不得已的偏差，逐条记在 `tmp/md1-report.md` §3：
                                            //   ① 分叉至今没有那颗会话头（`JobsTriggerButton` /
                                            //      `SubagentList` 在 `main.rs` 零命中）⇒ 挂到输入区
                                            //      动作行的中间那一格（主干那一格本来就是权限/计划
                                            //      两颗钮的位置）；
                                            //   ② reactor 没有 `Visibility` ⇒ 「不入子树」= 这一格
                                            //      只放选中的那棵（本仓既有模式，见 `either`），
                                            //      收起态给一颗**空 Border**：零控件、零墨迹、
                                            //      UIA 上摸不到「任务」那一枚。
                                            //      主干那颗幂等闸（`SS:565` 的
                                            //      `if (_todosEntryButton is not null) return;`）
                                            //      在这里由「单一出处 + 单一槽」保证：重复刷新
                                            //      只会重算这一格，插不出第二颗。
                                            // · `AgentModeButton`：只在空态在场，判据与形状都在
                                            //   [`Shell::agent_mode_trigger`] 里，见那里的逐行出处。
                                            // 列数一列不加（`[Auto, *, Auto]` 原样）：为浮层加列会把
                                            // 正文挤窄，主干那三颗本来就在中间那一格内。
                                            Border::new()
                                                .grid_column(1)
                                                .horizontal_alignment(HorizontalAlignment::Left)
                                                .content(self.composer_band(context)),
                                            // 主干 `MainWindow.xaml:1254-1266` SendButton：
                                            // 34×34、Padding 0、CornerRadius=CornerPill(24)、
                                            // Style=AccentButtonStyle（强调色填充 + 反白前景 + 无描边）、
                                            // 字形 E74A/E71A @ GlyphSizeBody=14，注释明确「不重绑任何色值」。
                                            //
                                            // **`.style(ButtonStyle::Accent)` 在本分叉挂不上**：它与所有小钮
                                            // 都要用的 `resource_overrides` 同挂在一个 Button 上，启动即 native
                                            // fail-fast —— 退出码 0xC000027B、崩在 Microsoft.UI.Xaml.dll、
                                            // stdout/stderr 全 0 字节、连窗口都没了。2026-09-21 整树二分：
                                            // 只删那一行 `.style(...)`、其余一字未改，应用就正常起。
                                            // 触发条件是「同挂」而非 style 本身：`settings_button` 只挂
                                            // `.style(ButtonStyle::Accent)`、不带 resource_overrides，
                                            // 自测跑满 12 个分区都不崩。
                                            // 而 `pill_button` 一定要挂 `resource_overrides`（四态底色/描边
                                            // 全透明，否则模板那层 4px 方块高亮会从圆底外面支出去）⇒ 这里
                                            // 只能继续走 AccentButtonStyle 的**等值复刻**：底色仍是主题画刷
                                            // `p.accent`（AccentFillColorDefaultBrush，跟系统强调色走，
                                            // 不写死），悬停/按下按 generic.xaml:7631-7633 的
                                            // 「同色画刷降到 0.9 / 0.8」用 opacity 复刻，禁用换
                                            // `AccentFillColorDisabled`，反白前景四态钉死。
                                            pill_button(
                                                Button::new()
                                                    .grid_column(2)
                                                    .on_click(context.message(if running {
                                                        Msg::Cancel
                                                    } else {
                                                        Msg::Send
                                                    }))
                                                    .automation_id("SendButton")
                                                    .automation_name(self.catalog.l(if running
                                                    {
                                                        "停止运行"
                                                    } else {
                                                        "发送消息"
                                                    })),
                                                mark_size(
                                                    if running {
                                                        glyph::STOP
                                                    } else {
                                                        glyph::SEND
                                                    },
                                                    size::GLYPH_BODY,
                                                ),
                                                Pill::accent(p, size::COMPOSER_SEND_BUTTON),
                                                "composer-send",
                                                HoverSlot::Row,
                                                self.hover.as_deref(),
                                                self.pressed.as_deref(),
                                                context,
                                            ),
                                        )),
                                ),
                            )),
                    ),
            ))
    }

    /// 主线 `KernelBootPanel`（`MainWindow.xaml:748-764` + `MainWindow.KernelBoot.cs`）：
    /// 一张**只在内核起不来时才上屏**的失败卡，给原因与重试钮。
    ///
    /// #147 半 B 把这张卡上所有「加载中」显示拆掉了：主干引导全程静默，类文档（KC:8-14）原文
    /// 「引导全程不产生任何加载显示（没有进度条、没有阶段文案、没有提示气泡）」，卡片本体也从
    /// 原先的六件套缩成四件套（`MX:759-762`：Image / TextBlock / TextBlock / Button）—— 分叉多画的
    /// 那两件套（进度条 + 「第 n 步，共 4 步 · x%」那行步骤文案）在主干已连同 `x:Name` 一起删除：
    /// 全仓 grep 进度条控件现在只剩上下文用量那颗占比条（`MX:1740` / `ContextMeter.cs:243`），
    /// 引导卡上零命中。
    ///
    /// 层级逐属性对齐：Row 1（本函数 `.grid_row(0)`，分叉的 ChatPage 只有 `[*, Auto]` 两行）、
    /// H/V Center、`MaxWidth=360`、`Spacing=Space12(12)`；子元素四颗按 `MX:759-762` 的次序：
    /// Mark(`EmptyStateMarkSize`=34) / Stage(`EmptyStateTitleTextStyle` = Title 28 SemiBold，文案恒
    /// `内核启动失败`) / Hint(`HintTextStyle` = Caption 12 + `TextTertiaryBrush`，写 `FailKernelBoot`
    /// 那句 reason+detail 整句) / Retry（框架默认 Button，**不套样式**）。
    ///
    /// 显隐：reactor 0.100.0 没有 `Visibility` ⇒ 整颗卡由 `chat_page` 的那个 `if self.boot.showing`
    /// 决定进不进树，而 `showing` 现在**只有** `BootState::fail` 会点亮（= 主干 `FailKernelBoot` 里
    /// 那句点亮 `KernelBootPanel` 的 `Visibility`，KC:36）。
    ///
    /// 已知偏差（抄不过来，实测记录保留）：`TextAlignment=Center` —— reactor 的 `TextBlock` 没有
    /// `text_alignment`，`Style`/`Setter` 也不在外露面里（临时塞进去编译过：9 条错误、进程根本没起来），
    /// 只能靠 `.horizontal_alignment(Center)` 把整块居中，多行时行内退化成左对齐。
    ///
    /// 四颗 `automation_id` 逐字取自 `MainWindow.xaml:757-762` 的 `x:Name`（WinUI 由 x:Name 生成
    /// AutomationId）：面板本体 + Mark + 那两行文案 + 重试钮。面板的 `AutomationProperties.Name`
    /// 是「内核启动状态」（`MX:758`），原先那句「内核加载进度」是主干没有的说法，一并收掉。
    fn kernel_boot_panel(&self, context: &mut ViewContext<Shell>, p: Palette) -> View {
        // 这张卡只在失败态上屏 ⇒ 两行文案全从那份原文现算（主干 `RefreshKernelBootTexts` KC:65-76
        // 同一条：语言切换时按当前语言整卡重算，判据只有 `Visibility` 与 `(ReasonKey, Detail)`）。
        let (reason_key, detail) = self
            .boot
            .failure
            .clone()
            .unwrap_or_else(|| ("内核启动失败".to_string(), String::new()));
        let message = self.catalog.l(&reason_key);
        // 主干 KC:33 那句 `full`：detail 为空 ⇒ 只出定性那一句；非空 ⇒ 全角冒号 U+FF1A 接原文。
        let full = if detail.is_empty() {
            message
        } else {
            format!("{message}：{detail}")
        };
        let mark: View = brand_mark(self.brand(), size::EMPTY_STATE_MARK, "KernelBootMark");
        let stage_text = self.catalog.l("内核启动失败");
        let stage: View = TextBlock::new()
            .text(stage_text.clone())
            .font_size(type_ramp::TITLE.size)
            .font_weight(FontWeight::SEMI_BOLD)
            .foreground(p.text_primary.clone())
            .text_wrapping(TextWrapping::Wrap)
            .horizontal_alignment(HorizontalAlignment::Center)
            .automation_id("KernelBootStage")
            .automation_name(stage_text)
            .into();
        let hint: View = TextBlock::new()
            .text(full.clone())
            .font_size(type_ramp::CAPTION.size)
            .foreground(p.text_tertiary.clone())
            .text_wrapping(TextWrapping::Wrap)
            .horizontal_alignment(HorizontalAlignment::Center)
            .automation_id("KernelBootHint")
            .automation_name(full)
            .into();
        let retry: View = Button::new()
            .on_click(context.message(Msg::BootRetry))
            .horizontal_alignment(HorizontalAlignment::Center)
            .automation_id("KernelBootRetry")
            .automation_name("重试")
            // 主线没给它套样式 ⇒ 框架默认 Button（底 `ControlFillColorDefault`、
            // 描边 `ControlStrokeColorDefault`、字 `TextFillColorPrimary`）。
            // 注意别在这颗钮上同时挂 `ButtonStyle::Accent` 和 `resource_overrides`
            // ——那是 0xC000027B 静默 fail-fast 的已知成因之一。
            .content(self.catalog.l("重试"));
        StackPanel::new()
            .grid_row(0)
            .orientation(Orientation::Vertical)
            .max_width(size::BOOT_CARD_MAX_WIDTH)
            .spacing(space::S12)
            .horizontal_alignment(HorizontalAlignment::Center)
            .vertical_alignment(VerticalAlignment::Center)
            .automation_id("KernelBootPanel")
            .automation_name("内核启动状态")
            .keyed_children(vec![
                KeyedView::new("mark", mark),
                KeyedView::new("stage", stage),
                KeyedView::new("hint", hint),
                KeyedView::new("retry", retry),
            ])
    }

    /// 主干 `SettingsHost`：页头只有分区名（TitleTextBlockStyle + 36,24,36,4），
    /// 正文是 `SettingsScroller`(36,12,36,36) 里一个 MaxWidth 1064、Spacing 12 的 StackPanel。
    /// 钻取二级页时页头换成二级页标题并多出返回钮，正文整棵换成 `SettingsSubHost`。
    fn settings_page(&self, context: &mut ViewContext<Shell>, p: Palette) -> View {
        let section_title = SETTINGS_SECTIONS
            .iter()
            .find(|(id, _, _)| *id == self.section)
            .map(|(_, label, _)| *label)
            .unwrap_or("设置");
        let (title, cells) = match self.sub.as_deref() {
            Some(id) => (sub_title(id), self.settings_sub(id, context, p)),
            None => (section_title.to_string(), self.settings_section(context, p)),
        };
        let back: View = self.settings_back_button(context);
        Grid::new()
            .rows([GridLength::Auto, GridLength::STAR])
            .children((
                StackPanel::new()
                    .orientation(Orientation::Horizontal)
                    .spacing(space::S8)
                    .margin(th(pad::PAGE_HEADER))
                    .vertical_alignment(VerticalAlignment::Center)
                    .keyed_children(vec![
                        KeyedView::new(
                            "back-slot",
                            self.either(
                                self.sub.is_some(),
                                ("sub-back", back),
                                ("no-back", blank()),
                            ),
                        ),
                        KeyedView::new(
                            "header",
                            TextBlock::new()
                                .text(self.catalog.l(&title))
                                .font_size(type_ramp::TITLE.size)
                                .font_weight(FontWeight::SEMI_BOLD)
                                .foreground(p.text_primary.clone())
                                .vertical_alignment(VerticalAlignment::Center)
                                .automation_name(title.clone()),
                        ),
                    ]),
                ScrollViewer::new().grid_row(1).content(
                    Border::new().padding(th(pad::PAGE_SCROLL)).content(
                        StackPanel::new()
                            .orientation(Orientation::Vertical)
                            .spacing(12.0)
                            .max_width(size::PAGE_MAX_WIDTH)
                            .keyed_children(cells),
                    ),
                ),
            ))
    }

    /// 主干 `SettingsBreadcrumbParent`（`MainWindow.xaml:1392` 的 `x:Name` + `:1396` 的
    /// `AutomationProperties.AutomationId`，两串同一颗）：二级页页头里那颗返回入口，
    /// 与左上角 `ShellBackButton`、Esc 同走 `CloseSettingsSubPage`。lc1 项2 之前这里是分叉自造的
    /// 「二级页返回钮」串（主干查无此串，见 dr2 §③-P2-7 / dr3 §③-P2-5）。形态差异备案：主干是「面包屑上级名」（文字），
    /// 分叉是 32×32、无边框、CornerSmall 的图标钮 —— id 对齐，形态留给 #16/#91 那轮。
    /// 不选 `ShellBackButton`：那串在分叉已挂在顶条左上角那颗（`strip`），同屏两颗同 id 会抢。
    fn settings_back_button(&self, context: &mut ViewContext<Shell>) -> View {
        Button::new()
            .style(ButtonStyle::Subtle)
            .resource_overrides(
                ResourceOverrides::new()
                    .set("ButtonBackground", Color::transparent())
                    .set("ButtonBackgroundPointerOver", Color::transparent())
                    .set("ButtonBackgroundPressed", Color::transparent())
                    // 无描边靠四态透明画刷；`ButtonBorderThemeThickness` 是 double 型键，
                    // 用 Thickness 覆它会让 WinUI fail-fast（见 `button_flat` 注释）。
                    .set("ButtonBorderBrush", Color::transparent())
                    .set("ButtonBorderBrushPointerOver", Color::transparent())
                    .set("ButtonBorderBrushPressed", Color::transparent())
                    .set("ButtonBorderBrushDisabled", Color::transparent())
                    .set("ButtonPadding", Thickness::uniform(0.0)),
            )
            .width(size::SHELL_BACK_BUTTON)
            .height(size::SHELL_BACK_BUTTON)
            .min_width(0.0)
            .vertical_alignment(VerticalAlignment::Center)
            .automation_name(self.catalog.l("返回上一级"))
            .automation_id("SettingsBreadcrumbParent")
            .on_click(context.message(Msg::CloseSub))
            .content(
                // 模板内缩抵回去，见 TEMPLATE_INSET。
                Grid::new()
                    .margin(th(TEMPLATE_INSET))
                    .keyed_children(vec![KeyedView::new(
                        "chrome",
                        Border::new()
                            .corner_radius(radius::SMALL)
                            .content(mark_size(glyph::BACK, size::GLYPH_BODY)),
                    )]),
            )
    }

    /// 分区一级页正文。主干其余分区要读内核快照，分叉目前只有 general/plugins 有内容。
    fn settings_section(&self, context: &mut ViewContext<Shell>, p: Palette) -> Vec<KeyedView> {
        match self.section.as_str() {
            "general" => self.settings_general(context, p),
            "personalization" => self.settings_personalization(context, p),
            "models" => self.settings_models(p),
            "plugins" => self.settings_plugins(context, p),
            "skills" => self.settings_skills(p),
            "memory" => self.settings_memory(context, p),
            "agent-presets" => self.settings_agent_presets(p),
            "computer-control" => self.settings_computer_control(context, p),
            "browser-control" => self.settings_browser_control(context, p),
            "usage" => self.settings_usage(p),
            "pet" => self.settings_pet(context, p),
            "about" => self.settings_about(p),
            _ => Vec::new(),
        }
    }

    /// 二级页正文：主干每次进页按当前快照现建，不缓存；这里同样按 id 分派。
    fn settings_sub(
        &self,
        id: &str,
        context: &mut ViewContext<Shell>,
        p: Palette,
    ) -> Vec<KeyedView> {
        match id {
            "shell" => self.sub_shell(context, p),
            "agent-loop" => self.sub_agent_loop(context, p),
            "subagent" => self.sub_subagent(context, p),
            "web-search" => self.sub_web_search(context, p),
            "auto-approval" => self.sub_auto_approval(context, p),
            "defaults" => self.sub_defaults(p),
            _ => Vec::new(),
        }
    }

    /// 插件配置一级页：`MakeSectionDesc` + 6 张钻取卡。
    /// 主干上面还有一条 `SelectorBar`（插件配置 / 插件列表），reactor 的 SelectorBar 没有加条目的
    /// API（只有 `on_selected_text_changed`），画不出 Tab 条，所以分叉只呈现默认的「插件配置」内容。
    fn settings_plugins(&self, context: &mut ViewContext<Shell>, p: Palette) -> Vec<KeyedView> {
        let mut cells = vec![KeyedView::new(
            "section-desc",
            Border::new()
                .margin(th(pad::CARD_DESCRIPTION))
                .content(self.settings_note("配置和查看本部署已安装的插件。", p)),
        )];
        for (id, code, title, desc) in SETTINGS_PLUGIN_CARDS {
            cells.push(self.settings_nav_card(id, *code, title, desc, context, p));
        }
        cells
    }

    /// 主干 `MakeSettingsNavCard`：卡片本身是 Button（Padding 16,12、RadiusMedium 8、CardBrush+Stroke 1px），
    /// 内容 `[Auto,*,Auto]` 列距 16 —— 字形、标题+描述（Spacing 2）、右向箭头 E76B。
    fn settings_nav_card(
        &self,
        id: &str,
        code: char,
        title: &str,
        desc: &str,
        context: &mut ViewContext<Shell>,
        p: Palette,
    ) -> KeyedView {
        let key = id.to_string();
        KeyedView::new(
            format!("nav-card-{id}"),
            Button::new()
                .style(ButtonStyle::Subtle)
                .resource_overrides(
                    ResourceOverrides::new()
                        .set("ButtonBackground", Color::transparent())
                        .set("ButtonBackgroundPointerOver", Color::transparent())
                        .set("ButtonBackgroundPressed", Color::transparent())
                        // 同 `button_flat`：描边用四态透明画刷抹，绝不覆 `ButtonBorderThemeThickness`。
                        .set("ButtonBorderBrush", Color::transparent())
                        .set("ButtonBorderBrushPointerOver", Color::transparent())
                        .set("ButtonBorderBrushPressed", Color::transparent())
                        .set("ButtonBorderBrushDisabled", Color::transparent())
                        .set("ButtonPadding", Thickness::uniform(0.0)),
                )
                .min_width(0.0)
                .horizontal_alignment(HorizontalAlignment::Stretch)
                .horizontal_content_alignment(HorizontalAlignment::Stretch)
                .automation_name(self.catalog.l(title))
                .automation_id(format!("PluginsNav_{}", camel(id)))
                .on_click(context.message(Msg::OpenSub(key)))
                .content(
                    // 模板内缩（TEMPLATE_INSET）抵回去后，卡片外观与 16,12 内边距都落在内层 Border。
                    Grid::new()
                        .margin(th(TEMPLATE_INSET))
                        .keyed_children(vec![KeyedView::new(
                            "card",
                            Border::new()
                                .background(p.card.clone())
                                .border_brush(p.stroke.clone())
                                .border_thickness(th([size::STROKE; 4]))
                                .corner_radius(radius::MEDIUM)
                                .padding(th(pad::NAV_CARD))
                                .content(
                                    Grid::new()
                                        .columns([
                                            GridLength::Auto,
                                            GridLength::STAR,
                                            GridLength::Auto,
                                        ])
                                        .column_spacing(space::S16)
                                        .children((
                                            // 主干 `MakeSettingsNavCard`（xaml.cs:9279-9286）：
                                            // 图标 FontSize=GlyphSizeBody(14)。
                                            mark_center(code, size::GLYPH_BODY, 0),
                                            StackPanel::new()
                                                .orientation(Orientation::Vertical)
                                                .spacing(space::S2)
                                                .vertical_alignment(VerticalAlignment::Center)
                                                .grid_column(1)
                                                .children((
                                                    TextBlock::new()
                                                        .text(self.catalog.l(title))
                                                        .font_size(type_ramp::BODY.size)
                                                        .foreground(p.text_primary.clone()),
                                                    self.settings_note(desc, p),
                                                )),
                                            // 主干 xaml.cs:9302-9306：钻取 chevron 是 **E76C**（右向）、
                                            // FontSize=GlyphSizeCaption(12)、TextTertiaryBrush。
                                            // E76B 是左向，用错方向就反了。
                                            Border::new()
                                                .grid_column(2)
                                                .vertical_alignment(VerticalAlignment::Center)
                                                .opacity(0.72)
                                                .content(mark_size(
                                                    glyph::CHEVRON_RIGHT,
                                                    size::GLYPH_CAPTION,
                                                )),
                                        )),
                                ),
                        )]),
                ),
        )
    }

    /// 终端卡：命令超时 + 单流输出上限（`AddShellCard`）。
