/// 台账 #58 M2 的收口锁（SP2 批的尾巴）：运行态状态条的**宿主**、两张浮层的**入口**，
/// 外加「一条可见闸 + 零新状态格」两枚反向纪律。母本 = `MainWindow.RunStats.cs`
/// （`RS:215-365`）+ `MainWindow.xaml:1033-1046` 的 `ComposerBar`。
///
/// ⚠ 本 mod 整颗落在 `include_str!("main.rs")` 的射程里 ⇒ 凡拿源码当证据的串与锚点一律
///   `concat!` 现拆（拆在词内）：不拆的话正向锁被自己撑绿、反向锁被自己撑红，
///   连「锚点全文件唯一」那一发自证都只剩个形式。
/// ⚠ 窗口里的**注释行不算证据**（`RS:230` 那行注释本身就写着 `tok tok` / `%%` 的事故串，
///   `:19769` 还抄了一遍死模板名）⇒ 反向半颗先过一道 `code_only` 再判。
/// ⚠ 每条窗口都自证两枚锚点全文件各一发，并把窗口真实行数打出来（宽度量不得靠肉眼）。
#[cfg(test)]
mod sp2_runstats_host_tests {
    use super::*;

    const SRC: &str = include_str!("main.rs");

    const A_ACTIVE: &str = concat!(
        "fn active_run_fold(&self)",
        " -> Option<&blade2_rs::kernel::RunStepFold> {"
    );
    const A_STRIP: &str = concat!("fn run_stats_strip(&self)", " -> Option<View> {");
    const A_CELL: &str = concat!(
        "fn run_stats_strip_cell(&self",
        ", id: &str, text: String, body: View) -> View {"
    );
    const A_STATS: &str = concat!(
        "fn run_stats_stats_body(&self",
        ", fold: &blade2_rs::kernel::RunStepFold) -> View {"
    );
    const A_TOKEN: &str = concat!(
        "fn run_stats_token_body(&self",
        ", fold: &blade2_rs::kernel::RunStepFold) -> View {"
    );
    const A_HEAD: &str = concat!("fn run_stats_panel_header(&self", ", label: String) -> View {");
    const A_SEP: &str = concat!("fn run_stats_panel_separator(&self)", " -> View {");
    const A_FLYOUT: &str = concat!("fn run_stats_flyout(&self", ", body: View) -> Flyout {");
    const A_HOST: &str = concat!("fn composer_host(strip: Option<View>", ", card: View) -> View {");

    const E_ACTIVE: &str = concat!("\n    /// 主干 `MX:1041-", "1046");
    const E_STRIP: &str = concat!("\n    /// 条上那一枚", "胶囊");
    const E_CELL: &str = concat!("\n    /// 主干 `ShowStats", "Panel");
    const E_STATS: &str = concat!("\n    /// 主干 `ShowToken", "Panel");
    const E_TOKEN: &str = concat!("\n    /// 主干 `MakePanel", "Header");
    const E_HEAD: &str = concat!("\n    /// 主干 `MakePanel", "Separator");
    const E_SEP: &str = concat!("\n    /// 两张浮层", "共用的那颗壳");
    const E_FLYOUT: &str = concat!("\n    /// 主干 `ComposerBar", "` 那颗");
    const E_HOST: &str = concat!("\n    /// 主干 `CM:226-", "258");

    /// 左胶囊的模板（主干 `RS:229`）与那枚**登记着但调用点不走**的死模板（`RS:230` 注释）。
    const LEFT: &str = concat!("\"{0} 轮 {1} 步 · {2}", " tok/s\"");
    const RIGHT: &str = concat!("\"{} tok · {} ", "{}%\"");
    const DEAD: &str = concat!("{0} tok · 缓存命中 ", "{1}%");

    /// 切窗口 + 两枚锚点各自全文件唯一的自证 + 真实行数打印。
    fn window(name: &str, start: &str, end: &str) -> &'static str {
        assert_eq!(
            SRC.matches(start).count(),
            1,
            "起点锚不唯一（{name}）：{start:?}",
        );
        assert_eq!(
            SRC.matches(end).count(),
            1,
            "终点锚不唯一（{name}），窗口会在半途截断或吞掉下一颗"
        );
        let body = SRC
            .split_once(start)
            .unwrap_or_else(|| panic!("源码里找不到 {name} 的起点锚"))
            .1
            .split_once(end)
            .unwrap_or_else(|| panic!("{name} 的起点锚之后找不到终点锚"))
            .0;
        println!("[mr7#58M2] {name} 窗口实长 = {} 行", body.lines().count());
        assert!(!body.is_empty(), "{name} 窗口被终点锚切空了");
        body
    }

    /// 只自证**起点**唯一的窗口：终点锚在别家 mod 里被**裸写**过一发 ⇒ 它天生不可能唯一
    /// （现测恰好 2 发，多一发少一发都红）。`split_once` 取起点之后第一发 ⇒ 宽度仍精确。
    fn window_repeated_end(name: &str, start: &str, end: &str) -> &'static str {
        assert_eq!(
            SRC.matches(start).count(),
            1,
            "起点锚不唯一（{name}）：{start:?}"
        );
        assert_eq!(
            SRC.matches(end).count(),
            2,
            "终点锚（{name}）「别家裸写一发」的事实变了：{end:?}"
        );
        let body = cut(SRC, start, end);
        println!("[mr7#58M2] {name} 窗口实长 = {} 行", body.lines().count());
        assert!(!body.is_empty(), "{name} 窗口被终点锚切空了");
        body
    }

    /// 取 `start` 之后到第一个 `end` 之前那一小截（比形参名更硬的顺序证据）。
    fn cut<'a>(body: &'a str, start: &str, end: &str) -> &'a str {
        body.split_once(start)
            .unwrap_or_else(|| panic!("窗口里找不到 {start}"))
            .1
            .split_once(end)
            .unwrap_or_else(|| panic!("{start} 之后找不到 {end}"))
            .0
    }

    /// L1（闸）：条的可见性**只**由台账那一把 `strip_visible()` 给，读侧零兜底值；
    /// 主干没有的四态机与「拿 `llm_ms` 当判据」都不许在这里发明（SP2 §2.2 第三纠）。
    #[test]
    fn the_strip_has_one_gate_from_the_ledger_and_no_invented_state_machine() {
        let strip = window("条体", A_STRIP, E_STRIP);
        assert_eq!(
            strip.matches(concat!("self.", "active_run_fold()?")).count(),
            1,
            "读侧入口不是唯一那一发"
        );
        assert_eq!(
            strip.matches(concat!("fold.", "strip_visible()")).count(),
            1,
            "可见闸不是台账里那把纯判据（或被贴了第二遍）"
        );
        assert_eq!(
            strip.matches(concat!("if !", "fold")).count(),
            1,
            "闸的取反只许一发：`!strip_visible() ⇒ None`"
        );
        assert_eq!(strip.matches("return None;").count(), 1, "收起那一支少了或多了");
        let invented = [
            concat!("fold.", "steps > 0"),
            concat!("fold.", "steps <= 0"),
            concat!("llm_ms > ", "0"),
            concat!("decode_ms > ", "0"),
            "runn",
            "queue",
            "retry",
        ];
        let code = code_only(&strip);
        for needle in invented {
            assert!(
                !code.contains(needle),
                "条体里出现了自造判据 {needle} ⇒ 主干没有的四态机/兜底档被发明了"
            );
        }
        let reader = window("读侧", A_ACTIVE, E_ACTIVE);
        let reader_code = code_only(&reader);
        assert_eq!(reader.matches("as_deref()?").count(), 1, "没有当前会话要短路");
        assert_eq!(
            reader.matches(concat!("self.", "run_stats.", "fold(session)")).count(),
            1,
            "读侧只准吃台账那一颗"
        );
        for fallback in [concat!("unwrap_", "or"), concat!(".unwrap", "(")] {
            assert!(
                !reader_code.contains(fallback),
                "读侧出现 {fallback} ⇒ 「没有数」被糊成一个数（主干是 Collapsed）"
            );
        }
        // 一本真相：喂料口与读侧口在全文件各只一发（M1 那颗喂料闸不许长出第二处读者）。
        assert_eq!(
            SRC.matches(concat!("self.", "run_stats.", "note(")).count(),
            1,
            "台账出现第二个写入者 ⇒ 六型白名单外还在记账"
        );
        assert_eq!(
            SRC.matches(concat!("self.", "run_stats.", "fold(")).count(),
            1,
            "台账出现第二个读者 ⇒ 换了投影源（SP2 §1.3：读的是 UI journal 折叠，不是 sessionStats）"
        );
    }

    /// L2（文本道 + 单位各一枚）：两枚胶囊的串**逐字**照主干调用点，十二枚串全部在册走 `l`/`lf`，
    /// 零 `bt`/`btf`；那枚登记着的死模板**不许**回到调用点（`RS:230` 的 `%%` / `tok tok` 事故）。
    #[test]
    fn the_two_pills_wear_the_mainline_templates_and_exactly_one_unit_each() {
        let strip = window("条体", A_STRIP, E_STRIP);
        let code = code_only(&strip);
        assert_eq!(strip.matches(LEFT).count(), 1, "左胶囊的模板串不是主干那一发");
        assert_eq!(strip.matches(RIGHT).count(), 1, "右胶囊不是主干那发显式拼接");
        assert_eq!(
            strip.matches(concat!("self.", "catalog.", "lf(")).count(),
            1,
            "左胶囊走模板：整条上只许一发 `lf(`"
        );
        assert_eq!(
            strip.matches(concat!("self.", "catalog.", "l(\"", "缓存命中", "\")")).count(),
            1,
            "右胶囊那枚标签走表（主干 `L(...)`），不许内联成中文裸串"
        );
        assert!(!code.contains("bt(\""), "本轮零内联串：出现了 `bt(`");
        assert!(!code.contains("btf("), "本轮零内联串：出现了 `btf(`");
        assert!(!code.contains("tok tok"), "单位叠了第二枚");
        assert!(!code.contains("%%"), "百分号叠了第二枚");
        assert!(
            !code.contains(DEAD),
            "死模板被拿回调用点 ⇒ 单位与 `%` 又要各出现两枚"
        );
        assert_eq!(
            strip.matches(concat!("self.", "run_stats_strip_cell(")).count(),
            2,
            "条上就是两枚胶囊，一枚不多"
        );
        for name in ["\"RunStatsTurnsText\"", "\"RunStatsTokensText\""] {
            assert_eq!(strip.matches(name).count(), 1, "主干裸真名 {name} 不在位或重复");
        }
        // 死模板仍在 i18n 表里登记着（我们既没删它、也没用它）。
        let lib = include_str!("i18n.rs");
        assert_eq!(
            lib.matches(DEAD).count(),
            1,
            "主干那枚在册模板从分叉表里漂走了"
        );
    }

    /// L3（宿主形态）：胶囊 = **原生 flyout 宿主**，不是第 11 张自绘层；id/Name 一发两贴；
    /// 零 `Msg`、零状态格、旧互斥闸一枚不漂。框架三层现测记在 `run_stats_strip_cell` 的 doc 上。
    #[test]
    fn the_cell_is_a_native_flyout_host_not_another_self_drawn_layer() {
        let cell = window("胶囊", A_CELL, E_CELL);
        assert_eq!(
            cell.matches(concat!(
                "cell.",
                "flyout_with(self.run_stats_flyout(body))"
            ))
            .count(),
            1,
            "浮层的入口不是那颗原生 flyout"
        );
        assert_eq!(cell.matches(".automation_id(id)").count(), 1, "id 没从形参走");
        assert_eq!(cell.matches(".automation_name(text)").count(), 1, "Name 没和脸共用同一枚串");
        assert_eq!(cell.matches("TextBlock::new()").count(), 1, "脸不再是主干那枚 TextBlock");
        assert!(cell.contains(concat!(".font_size(type_ramp::", "CAPTION.size)")));
        assert!(cell.contains(concat!(".foreground(p.", "text_tertiary.clone())")));
        for dead in ["on_click(", "is_open", "Glyph", "\\u{e"] {
            assert!(!code_only(&cell).contains(dead), "胶囊里冒出 {dead} ⇒ 又多一层自绘");
        }
        assert_eq!(
            SRC.matches("automation_id(\"RunStats").count(),
            0,
            "id 被焊死在实现里 ⇒ 两枚胶囊共用一颗的形参档塌了"
        );
        for absent in [
            concat!("Msg::Run", "Stats"),
            concat!("run_stats_", "strip_open"),
            concat!("run_stats_", "visible:"),
            concat!("ShowRunFlyout", "()"),
        ] {
            assert!(!SRC.contains(absent), "产品码里出现了 {absent} ⇒ 新造了一层状态/消息");
        }
        assert_eq!(
            code_only(SRC)
                .matches(concat!("self.todos_panel = ", "None;"))
                .count(),
            10,
            "面板走原生 flyout ⇒ 那六把「互斥枚数 == 10」的旧闸一都不许漂（针过 `code_only`）"
        );
    }

    /// L3 续（壳与两张表体）：两枚浮层**共用一颗壳**；两张头行不同构（主干易抄错条）；
    /// 行序 = 主干 `Children.Add` 的序，一件不多一件不少。
    #[test]
    fn the_two_flyouts_share_one_shell_and_keep_their_heads_different() {
        let flyout = window("壳", A_FLYOUT, E_FLYOUT);
        assert_eq!(flyout.matches(concat!("Flyout::rich(", "host)")).count(), 1);
        assert_eq!(
            flyout
                .matches(concat!(".placement(FlyoutPlacement::", "Top)"))
                .count(),
            1,
            "主干 `RS:363` 的 `Placement = Top` 对位漂了"
        );
        for chrome in [
            concat!(".background(p.", "card.clone())"),
            concat!(".border_brush(p.", "stroke.clone())"),
            concat!(".border_thickness(th([size::", "STROKE; 4]))"),
            concat!(".corner_radius(radius::", "MEDIUM)"),
            concat!(".padding(th(Self::CONTEXT_PANEL_", "PADDING))"),
        ] {
            assert_eq!(
                flyout.matches(chrome).count(),
                1,
                "共用壳少了或重复了 {chrome}（起第二份数值真相）"
            );
        }
        let stats = window("统计面板", A_STATS, E_STATS);
        let token = window("Token 面板", A_TOKEN, E_TOKEN);
        assert_eq!(
            cut(&stats, ".children((", "))"),
            "header, llm_row, tool_row, ttft_row, tps_row",
            "统计那张的行序 = 主干 `RS:266-280`"
        );
        assert_eq!(
            cut(&token, ".children((", "))"),
            "head, separator, hit_row, input_row, read_row, output_row",
            "Token 那张的行序 = 主干 `RS:285-311`"
        );
        for body in [&stats, &token] {
            assert_eq!(body.matches("self.mw3_context_stat_row(").count(), 4, "四行 `StatRow`");
            assert_eq!(
                body.matches(concat!(".spacing(space::", "S10)")).count(),
                1,
                "面板 `Spacing=10`（主干 `RS:266/285`）"
            );
            assert_eq!(
                body
                    .matches(concat!(".min_width(Self::CONTEXT_PANEL_", "MIN_WIDTH)"))
                    .count(),
                1,
                "面板 `MinWidth=250` 必须读那一颗常量，不许起第二份"
            );
        }
        assert_eq!(
            stats.matches(concat!("self.", "run_stats_panel_header(")).count(),
            1,
            "统计那张走 `MakePanelHeader` 的双层壳"
        );
        assert_eq!(
            token.matches(concat!("self.", "run_stats_panel_header(")).count(),
            0,
            "Token 那张的头被换成了另一张的壳（SP13 §3.1 易抄错条）"
        );
        assert!(
            token.contains(concat!("Grid::", "new()")),
            "Token 头行不再是手搓两列 Grid"
        );
        assert!(token.contains(".columns([GridLength::STAR, GridLength::Auto])"));
        assert!(token.contains(concat!(".column_spacing(space::", "S16)")));
        assert!(stats.contains(concat!("StackPanel::", "new()")));
        assert!(!code_only(&stats).contains("Grid::new()"), "统计头行被换成了手搓 Grid");
        assert!(!code_only(&token).contains("font_weight"), "Token 头行加了粗 = 主干没有的");
        let head = window("头行", A_HEAD, E_HEAD);
        assert_eq!(head.matches(concat!("FontWeight::", "SEMI_BOLD")).count(), 1, "标题 SemiBold");
        assert_eq!(head.matches(concat!(".spacing(space::", "S8)")).count(), 1, "`Spacing=8`");
        assert_eq!(head.matches("self.run_stats_panel_separator()").count(), 1, "头行内嵌一枚分隔件");
        let sep = window("分隔件", A_SEP, E_SEP);
        assert_eq!(
            sep.matches(concat!(".height(", "1.0)")).count(),
            1,
            "分隔件 = 1px（`RS:328-333`）"
        );
        assert!(sep.contains(concat!(".background(p.", "stroke.clone())"),));
    }

    /// L3 尾（宿主位置）：条叠在输入卡**上方**、条不在场时那一枚整格不入树；
    /// `fn composer` 本体那一百六十行一属性都不动（三把计数针不漂）。
    #[test]
    fn the_host_puts_the_strip_above_the_card_and_drops_the_absent_one() {
        let host = window("宿主", A_HOST, E_HOST);
        assert_eq!(
            host.matches(concat!("if let Some(", "strip) = strip {")).count(),
            1,
            "条不在场不再等于那一枚整格不入树"
        );
        assert_eq!(
            host.matches(concat!("KeyedView::new(\"run-stats-strip\", ", "strip)")).count(),
            1
        );
        assert_eq!(
            host.matches(concat!("KeyedView::new(\"composer-card\", ", "card)")).count(),
            1
        );
        assert!(
            host.find("run-stats-strip") < host.find("composer-card"),
            "序反了：条在输入卡上方（主干 `ComposerBar` Row 0 / Row 1）"
        );
        assert_eq!(host.matches(concat!(".orientation(Orientation::", "Vertical)")).count(), 1);
        assert_eq!(
            host.matches("keyed_children(parts)").count(),
            1,
            "件数会随条的在场与否变 ⇒ 必须走 `keyed_children`"
        );
        assert!(!code_only(&host).contains(".columns("), "宿主不是 Grid ⇒ 不许有列定义");
        assert_eq!(
            SRC.matches(concat!("Self::", "composer_host(")).count(),
            1,
            "宿主只挂一颗：`fn composer` 外壳的 content"
        );
        assert_eq!(
            SRC.matches(concat!("self.", "run_stats_strip(),")).count(),
            1,
            "条的读者不止一处（或干脆为零）"
        );
        // 终点锚那一发天生**不**唯一：别家 mod 在 `:33387` 把它裸写过一发（现测全文件 2 发），
        // 而 `split_once` 取的是起点之后第一发 = `fn composer` 的收口 ⇒ 宽度仍精确。
        // 这一发只能钉住「恰好 2」这个事实：别家那颗针一动这里就红，别拿它当唯一性证据。
        let composer = window_repeated_end(
            "输入卡",
            concat!("fn composer", "(&self"),
            concat!("fn kernel_boot", "_panel("),
        );
        assert_eq!(composer.matches("GridLength::Auto").count(), 2);
        assert_eq!(composer.matches("GridLength::STAR").count(), 1);
        assert_eq!(composer.matches(".columns(").count(), 1, "为条单开一列 = 把正文挤窄");
    }

    /// L5（换算行为）：`FormatTps` 的 `ToString("0")` = 离零进位、`FormatCacheHit` 的 `{0:0.#}`
    /// = ≤1 位小数去尾零，两处的 `<= 0`（含负数）都走破折号，且两枚**都不带自己的单位**。
    #[test]
    fn tps_and_cache_hit_reproduce_the_mainline_rounding_and_dash() {
        assert_eq!(run_stats_tps(0, 5), STATS_DASH, "主干 `DecodeMs > 0` 那一挡");
        assert_eq!(run_stats_tps(2_000, 0), STATS_DASH, "主干 `DecodeTokens > 0` 那一挡");
        assert_eq!(run_stats_tps(-1, 100), STATS_DASH, "负数也挡在外面（`> 0` 本来的语义）");
        assert_eq!(run_stats_tps(2_000, 5), "3", "2.5 → `ToString(\"0\")` 离零进位，不是截断");
        assert_eq!(run_stats_tps(3_000, 1), "0", "0.33 → 0（会打，只是打 0）");
        assert_eq!(run_stats_tps(1_000, 12_345), "12345", "恒无小数、恒不带分组符");
        assert!(!run_stats_tps(1_000, 8).contains("tok"), "单位塞进纯函数 = 条上叠加");
        assert_eq!(run_stats_cache_hit(0, 0), STATS_DASH, "分母 0 ⇒ 主干那枚破折号");
        assert_eq!(run_stats_cache_hit(1, 1), "50", "`{{0:0.#}}` 去尾零");
        assert_eq!(run_stats_cache_hit(50, 100), "33.3");
        assert_eq!(run_stats_cache_hit(100, 50), "66.7");
        assert!(!run_stats_cache_hit(1, 1).contains('%'), "`%` 由两处调用点各贴一枚");
        let strip = code_only(&window("条体", A_STRIP, E_STRIP));
        assert_eq!(
            strip.matches("run_stats_tps(fold.decode_ms, fold.decode_tokens)").count(),
            1
        );
        assert_eq!(
            strip.matches("run_stats_cache_hit(fold.cache_read_tokens, fold.input_tokens)").count(),
            1
        );
    }

    /// L5 续（两处主干自身的怪异 + TTFT 的截断档）：TPS 行是 `— tok/s`、命中率行是 `—%`，
    /// TTFT 走整除（= 主干 `TimeSpan` 的向零截断），取整会多打一秒（RD6 T4-6 的 1999.6ms）。
    #[test]
    fn the_two_faithful_weirdnesses_stay_weird_and_ttft_truncates() {
        let stats = code_only(&window("统计面板", A_STATS, E_STATS));
        assert_eq!(
            stats
                .matches(concat!(
                    "run_stats_tps(fold.decode_ms, fold.decode_tokens) + \"",
                    " tok/s\""
                ))
                .count(),
            1,
            "TPS 行少了那发拼接 ⇒ `— tok/s` 这一档没了（`RS:278`）"
        );
        assert!(stats.contains("if fold.ttft_steps > 0"), "TTFT 的破折号只看步数（`RS:276-277`）");
        assert!(
            stats.contains("duration_text((fold.ttft_ms / fold.ttft_steps).max(0))"),
            "TTFT 不再是整除 + 向零截断"
        );
        assert!(!stats.contains("round"), "TTFT 取了整 = 比主干多打一秒");
        let token = code_only(&window("Token 面板", A_TOKEN, E_TOKEN));
        assert_eq!(
            token
                .matches(concat!(
                    "run_stats_cache_hit(fold.cache_read_tokens, fold.input_tokens) + \"",
                    "%\""
                ))
                .count(),
            1,
            "命中率行少了 `%` ⇒ `—%` 这一档没了（`RS:307`）"
        );
        assert_eq!(
            token.matches("mw5_tokens_n0(fold.").count(),
            4,
            "总量一格 + 三行裸整数格，全走带单位那颗"
        );
        assert_eq!(duration_text(1_999), "1 秒", "1999ms ⇒ 1 秒（截断）");
        assert_eq!(duration_text(1_500), "1 秒", "取整会打 2 秒 = 比主干多做");
        assert_eq!(duration_text(60_000), "1 分 0 秒");
        assert_eq!(duration_text(3_660_000), "1 小时 1 分");
    }

    /// L4（文本道的行为半边）：十二枚串在 EN 档全部走表 ⇒ 英文界面不露中文；
    /// 左胶囊的模板两档各一枚单位；右胶囊那一串与主干调用点同形（**不是**那枚死模板的形）。
    #[test]
    fn the_strip_text_goes_through_the_table_in_both_locales() {
        let zh = Catalog::load("zh", None);
        let en = Catalog::load("en", None);
        let left = |catalog: &Catalog| {
            catalog.lf(
                concat!("{0} 轮 {1} 步 · {2}", " tok/s"),
                &["12".to_string(), "34".to_string(), "56".to_string()],
            )
        };
        assert_eq!(left(&zh), "12 轮 34 步 · 56 tok/s");
        assert_eq!(left(&en), "12 turns 34 steps · 56 tok/s");
        assert_eq!(left(&en).matches("tok/s").count(), 1, "单位在模板里只写了一枚");
        let right = |catalog: &Catalog| {
            format!(
                concat!("{} tok · {} ", "{}%"),
                "1.2K",
                catalog.l(concat!("缓存", "命中")),
                "45.6"
            )
        };
        assert_eq!(right(&zh), "1.2K tok · 缓存命中 45.6%");
        assert_eq!(right(&en), "1.2K tok · Cache hit 45.6%");
        for key in [
            concat!("会话", "统计"),
            concat!("模型", "用时"),
            concat!("工具调用", "用时"),
            concat!("首 token 平均（", "TTFT）"),
            concat!("输出速度（", "TPS）"),
            concat!("Token ", "用量"),
            concat!("未缓存", "输入"),
            concat!("缓存", "读取"),
            concat!("缓存", "命中"),
            concat!("输", "出"),
        ] {
            let rendered = en.l(key);
            assert_ne!(rendered, *key, "{key} 在 EN 档回落成中文 ⇒ 不在册");
            assert!(
                rendered.chars().all(|ch| (ch as u32) < 0x2E80),
                "EN 档的 {key} 露了中日韩字形：{rendered}"
            );
        }
        assert_eq!(
            en.lf(DEAD, &["1.2K".to_string(), "45.6".to_string()]),
            "1.2K tok · cache hit 45.6%",
            "死模板仍在册（大小写与调用点不同 ⇒ 这正是它不许回到调用点的实证）"
        );
        assert_ne!(
            right(&en),
            en.lf(DEAD, &["1.2K".to_string(), "45.6".to_string()]),
            "调用点与死模板同形 ⇒ 主干那发显式拼接被换掉了"
        );
    }
}

#[cfg(test)]
mod schedule_panel_tests {
    //! 批 P155（#155「计划（只读）」`schedules-panel`，spec §7 第 14 行点名那五件）的自家锁：
    //! 三档不并档 / 两枚内联 en 生效串走 `bt` / `" · "` 两段 / 排序「已到期在前 + 同刻稳定」/
    //! `scheduledAt` 解析失败 ⇒ 只出频率档。
    //! 三条口径都是本仓既有教训，不是新规矩：
    //! ① 全文件计数型针一律 `concat!` 拆词（FX1：整串写出来就把本行数进产品码）且过 crate 根的
    //!    [`code_only`]（MS1 §M-2：数串闸不许把注释里那句裸写法数进去）；**窗口内**的计数不拆，
    //!    因为针落在那把窗之外；
    //! ② 能打在**行为**上的一律不降级成文本锁 ⇒ 解析 / 排序 / 频率 / 量级 / 相对量 / 本地戳
    //!    六件全直接调那六颗文件级纯函数（翻产品码就翻红，不需要人读注释）；
    //! ③ 取窗锚一律本卡独有的 fn 名或臂名 ⇒ 一把窗只量一件事。
    use super::*;

    /// 一份**固定的** `now`（主干 `CP:305` 的 `DateTimeOffset.UtcNow` 在分叉是每帧现读 ⇒
    /// 判据不许建在墙上时钟上）。
    const NOW: i64 = 1_777_000_000_000;
    /// `" · "` 那枚 meta 分隔符的针。中间那个点写成 `\\u{00B7}` 转义 ⇒ 本行源码里**没有**那枚
    /// 裸字符，产品码那两发不会被自计数（FX1 口径的转义版）。
    const META_DOT: &str = "push_str(\" \u{00B7} \")";

    fn code() -> String {
        code_only(include_str!("main.rs"))
    }

    /// 取窗：`start` 之后、`end` 之前那一段（两枚锚都不在段内 ⇒ 计数不会把锚行自己数进去）。
    fn window<'a>(source: &'a str, start: &str, end: &str) -> &'a str {
        let (_, rest) = source
            .split_once(start)
            .unwrap_or_else(|| panic!("取窗锚 {start} 在文件里找不到"));
        match rest.split_once(end) {
            Some((body, _)) => body,
            None => panic!("取窗锚 {start} 之后找不到 {end}"),
        }
    }

    /// 针在源码里的位置（找不到就 panic，别拿 `usize::MAX` 蒙过判据）。
    fn pos(source: &str, needle: &str) -> usize {
        source
            .find(needle)
            .unwrap_or_else(|| panic!("锚针 {needle} 在文件里找不到"))
    }

    /// 一条记录（主干那五字段元组，`SS:153-172`）。调用点 = 下面那把
    /// `the_two_empty_tiers_…` 里补的「投影 → 记录表」反证（PS1：P155 建了这颗却没接上
    /// ⇒ 交回一棵带 `function 'record' is never used` 警告的树）。
    fn record(id: &str, kind: &str, prompt: &str, at: &str, every: i64) -> ScheduleRecord {
        ScheduleRecord {
            id: id.to_string(),
            kind: kind.to_string(),
            prompt: prompt.to_string(),
            scheduled_at: at.to_string(),
            every_seconds: every,
        }
    }

    /// ① `scheduledAt` 只吃 RFC3339 那一形（`CP:307-309` 的 `TryParse` + `AssumeUniversal`）。
    /// 变异证明：把 `schedule_at_millis` 里那句 `if parts.next().is_some() …` 的月份界删掉 ⇒
    /// `2026-13-01` 那一条翻红；把 `None` 那一档改成回落 0 ⇒ 后四条全翻红。
    #[test]
    fn only_rfc3339_parses_and_a_bad_stamp_yields_no_time() {
        let day0 = days_from_civil(2026, 10, 1) * 86_400_000;
        let seven_thirty = day0 + 7 * 3_600_000 + 30 * 60_000;
        assert_eq!(
            schedule_at_millis("2026-10-01T07:30:00Z"),
            Some(seven_thirty),
            "`Z` 那一档就是 UTC 本体"
        );
        // 无时区后缀 ⇒ 按 UTC 读（= 主干那枚 `DateTimeStyles.AssumeUniversal`）。
        assert_eq!(schedule_at_millis("2026-10-01T07:30:00"), Some(seven_thirty));
        // `+08:00` ⇒ 同一本地墙上时钟对应的 UTC 要**往前**退 8 小时。
        assert_eq!(
            schedule_at_millis("2026-10-01T07:30:00+08:00"),
            Some(seven_thirty - 8 * 3_600_000)
        );
        assert_eq!(
            schedule_at_millis("2026-10-01T15:30:00+0800"),
            Some(seven_thirty),
            "`±HHMM`（无冒号）也吃，与 .NET 同档"
        );
        // 秒以下**截断**（主干 `ToString("g")` 也不打秒以下）。
        assert_eq!(
            schedule_at_millis("2026-10-01T07:30:00.123Z"),
            Some(seven_thirty),
            "小数秒被丢掉，不是四舍五入"
        );
        // 不合形 ⇒ `None`：这一档正是主干 `TryParse` 返回 `false` 那一档，上游只出频率标签。
        for bad in [
            "",
            "2026-10-01",
            "2026-13-01T07:30:00Z",
            "2026-10-01T24:00:00Z",
            "2026-10-01T07:30:00X",
            "tomorrow",
        ] {
            assert_eq!(
                schedule_at_millis(bad),
                None,
                "非规范形 {bad:?} 被吃下了 ⇒ 分叉发明了主干没有的兜底时间"
            );
        }
    }

    /// ② 排序两键（`CP:310-311`）：**已到期整块在前**，其余按目标时间升序，解析失败排最后；
    /// 同刻保持缓存原序（= 投影数组到达序）靠 `sort_by_key` 的稳定性 —— 与主干 LINQ `OrderBy`
    /// 稳定同一条口径。变异证明：把 `schedule_order_keys` 第一键的 `<=` 改成 `<` ⇒ 恰在 `now`
    /// 那一条落到后块、顺序断言翻红；把第二键的 `i64::MAX` 换成 `i64::MIN` ⇒ `None` 那条跑到最前。
    #[test]
    fn due_records_lead_and_equal_instants_keep_the_cache_order() {
        let stamps: [Option<i64>; 6] = [
            None,
            Some(NOW + 60_000),
            Some(NOW - 60_000),
            Some(NOW - 60_000),
            Some(NOW + 3_600_000),
            Some(NOW),
        ];
        let mut order: Vec<usize> = (0..stamps.len()).collect();
        order.sort_by_key(|index| schedule_order_keys(stamps[*index], NOW));
        assert_eq!(
            order,
            vec![2, 3, 5, 1, 4, 0],
            "已到期(2,3) → 恰在 now(5) → 未来升序(1,4) → 解析失败(0)；同刻的 2/3 保原序"
        );
        // 同刻稳定这一条单独钉一次：两条 `now - 60_000` 谁在前，只可能由加入序决定。
        assert!(
            schedule_order_keys(Some(NOW - 60_000), NOW) == schedule_order_keys(Some(NOW - 60_000), NOW),
            "同刻的两条键不相等 ⇒ 稳定排序也救不回原序"
        );
    }

    /// ③ 频率档（`CP:366-377`）：判据是**取余**、不是「≥ 阈值」⇒ 取能整除的最大自然单位；
    /// `kind != "every"` 或 `everySeconds <= 0` ⇒ 一次性（`None`，读侧走 `l("一次性")`）。
    /// 变异证明：把那张三档表里的 `3_600` 删掉 ⇒ `7200` 那一条回落成「分」而翻红。
    #[test]
    fn frequency_takes_the_largest_dividing_natural_unit() {
        for (kind, every, expect) in [
            ("every", 86_400 * 2, Some(("每 {0} 天", 2))),
            ("every", 86_400, Some(("每 {0} 天", 1))),
            ("every", 7_200, Some(("每 {0} 小时", 2))),
            ("every", 180, Some(("每 {0} 分", 3))),
            // ⚠ PS1 复核实测：这一档**原用例期望错了**（写的是「每 {0} 分 1」= 截断读法），
            // 与主干 `CP:373-376` 逐字相反 ⇒ 改的是**用例**，产品码一字未动。主干原文（只读取证）：
            //   if (everySeconds % 86400 == 0) return LF("每 {0} 天", everySeconds / 86400);
            //   if (everySeconds % 3600  == 0) return LF("每 {0} 小时", everySeconds / 3600);
            //   if (everySeconds % 60    == 0) return LF("每 {0} 分",  everySeconds / 60);
            //   return LF("每 {0} 秒", everySeconds);
            // ⇒ 升档判据是**整除**（`%  == 0`），整除不了就直接落秒档；`/ 60` 只出现在
            //   `% 60 == 0` 那条分支里，**主干没有任何「除不尽就截断升档」的路径**。
            //   90 % 86400 = 90、90 % 3600 = 90、90 % 60 = 30 ⇒ 三档全不落 ⇒ 「每 90 秒」。
            //   （对照：`schedule_magnitude` 走的才是「≥ 阈值 + 截断」那一族，`CP:380-385`，
            //     两族判据不同 ⇒ 本卡不许把频率档读成量级档。）
            ("every", 90, Some(("每 {0} 秒", 90))),
            ("every", 61, Some(("每 {0} 秒", 61))),
            ("every", 45, Some(("每 {0} 秒", 45))),
            ("every", 1, Some(("每 {0} 秒", 1))),
            // `kind == "at"` 天生没有 `everySeconds`（主干给 0）⇒ 一次性，别读成「每 0 秒」。
            ("at", 0, None),
            ("every", 0, None),
            ("every", -5, None),
            ("", 60, None),
            ("Every", 60, None),
        ] {
            assert_eq!(
                schedule_frequency(kind, every),
                expect,
                "kind={kind:?} every={every} 的频率档漂了"
            );
        }
    }

    /// ④ 量级 + 相对量（`CP:347-350` + `CP:379-386`）：四档一律截断；正负号只看 `left` 的
    /// **毫秒**精度 ⇒ `left == 0` 落「已过期」那一档（主干 `left > TimeSpan.Zero` 才走「还剩」）。
    /// 变异证明：把 `schedule_magnitude` 的 `>=` 改成 `>` ⇒ 86_400 秒那一条翻成「小时」档。
    #[test]
    fn magnitude_truncates_and_the_sign_follows_the_raw_difference() {
        assert_eq!(schedule_magnitude(86_400 + 7_200), ("{0}天", 1));
        assert_eq!(schedule_magnitude(86_400), ("{0}天", 1));
        assert_eq!(schedule_magnitude(3_661), ("{0}小时", 1));
        assert_eq!(schedule_magnitude(61), ("{0}分钟", 1));
        assert_eq!(schedule_magnitude(59), ("{0}秒", 59));
        assert_eq!(schedule_magnitude(0), ("{0}秒", 0));
        assert_eq!(
            schedule_relative(NOW + 5_000, NOW),
            ("还剩 {0}", "{0}秒", 5),
            "还有 5 秒却报成过期 ⇒ 方向反了"
        );
        assert_eq!(
            schedule_relative(NOW - 5_000, NOW),
            ("已过期 {0}", "{0}秒", 5),
            "过期那一档主干传的是 `-left` ⇒ 数值不许带负号"
        );
        assert_eq!(
            schedule_relative(NOW, NOW),
            ("已过期 {0}", "{0}秒", 0),
            "`left == 0` 走「还剩」= 与主干 `>` 不同档"
        );
        assert_eq!(
            schedule_relative(NOW + 90_000, NOW),
            ("还剩 {0}", "{0}分钟", 1),
            "跨档的相对量没落到分钟"
        );
    }

    /// ⑤ 本地戳（`CP:346` 的 `ToLocalTime()`）：跨日界必须换日。
    /// ⚠ 分叉形制 = `yyyy-MM-dd HH:mm`，主干是 `ToString("g", CurrentCulture)` ⇒ **区域格式差**，
    /// 记报告 §3，这把尺只钉「同一瞬间、偏移正确、会跨日」这三件可静态证死的事。
    #[test]
    fn the_local_stamp_rolls_the_day_across_the_offset() {
        let late = days_from_civil(2026, 10, 1) * 86_400_000 + 23 * 3_600_000 + 30 * 60_000;
        assert_eq!(schedule_local_stamp(late, 0), "2026-10-01 23:30");
        assert_eq!(
            schedule_local_stamp(late, 3_600),
            "2026-10-02 00:30",
            "偏移一小时没跨过日界"
        );
        assert_eq!(
            schedule_local_stamp(late, -8 * 3_600),
            "2026-10-01 15:30",
            "负偏移方向反了"
        );
    }

    /// ⑥ 三档不并档（`CP:322-333`）：`parse_schedule_records` 对「没见过投影」与「见过但是空」
    /// **同返回空表**（① 那颗函数的 doc 自陈这条差距）⇒ 分叉只能靠**第二格** `schedule_seen`
    /// 分档（D-12「两枚不许并成一枚」的实证）。
    /// 变异证明：把卡片体里 `if self.schedule_seen` 换成 `if true` ⇒ 文本锁翻红。
    #[test]
    fn the_two_empty_tiers_stay_two_tiers_because_the_parser_cannot_tell_them_apart() {
        assert!(parse_schedule_records(None).is_empty());
        assert!(parse_schedule_records(Some(&json!([]))).is_empty());
        assert!(parse_schedule_records(Some(&json!({ "active": [] }))).is_empty());
        // 反证（PS1 补）：**有**内容时它吐非空表，且五字段逐字钉回主干那枚元组（`SS:153-172`）、
        // 丢条判据是「`id` 与 `prompt` **同时**为空」那两发的 AND（`:161-164`，不是「缺 id 就丢」）、
        // 五根字段一律「非串 ⇒ `""`」（`string_field` 口径）且 `everySeconds` 非数 ⇒ 0（主干
        // `(long)GetDouble()` 的回落方向）。⇒ 卡片正文读的就是这张表，而它在「投影缺席」与
        // 「投影到了但是空」两档**同返回空表** ⇒ 分档只能靠第二格 `schedule_seen`。
        let value = json!([
            { "id": "s-1", "kind": "at", "prompt": "明早跑一次", "scheduledAt": "2026-10-01T07:30:00Z" },
            { "id": "", "kind": "every", "prompt": "", "scheduledAt": "2026-09-27T00:00:00Z",
              "everySeconds": 86_400 },
            { "id": "", "kind": 7, "prompt": "只有 prompt 也成一条", "scheduledAt": "",
              "everySeconds": "not-a-number" },
        ]);
        assert_eq!(
            parse_schedule_records(Some(&value)),
            vec![
                record("s-1", "at", "明早跑一次", "2026-10-01T07:30:00Z", 0),
                record("", "", "只有 prompt 也成一条", "", 0),
            ],
            "投影 → 记录表的折法漂了 ⇒ 卡片正文读的就不是主干那份缓存快照"
        );
        // 两格都在状态结构里，且初值各一发。
        let source = include_str!("main.rs");
        for needle in [
            concat!("schedule_records: ", "Vec<ScheduleRecord>,"),
            concat!("schedule_seen: ", "bool,"),
            concat!("schedule_seen: ", "false,"),
        ] {
            assert_eq!(
                code().matches(needle).count(),
                1,
                "状态格 {needle} 的枚数漂了 ⇒ 两格被并成一体或多出一格"
            );
        }
        assert_eq!(
            code()
                .matches(concat!("schedule_records: ", "Vec::new(),"))
                .count(),
            1,
            "初值只许一发"
        );
        // 卡片体：`seen` 只被读**一次**，两串各一发，且空态那一行开了选中而声明那一行没开。
        let card = window(source, "fn schedule_panel_card(", "fn app_modal_host(");
        assert_eq!(card.matches("if self.schedule_seen {").count(), 1);
        assert_eq!(card.matches("当前会话没有计划。").count(), 1);
        assert_eq!(card.matches("尚未收到本会话的计划投影").count(), 1);
        assert_eq!(
            card.matches("is_text_selection_enabled(true)").count(),
            2,
            "选中性两档并了：只读声明（`CP:320` 未设）与空态行（`CP:331` 设了）不是同一档"
        );
        assert_eq!(card.matches("TextWrapping::Wrap").count(), 5, "五枚 Wrap 少一枚");
    }

    /// ⑦ 复制通道（D-9 / spec §2.0 那条坑）：**字典先赢、内联 en 是死码**，而 #3/#4 两枚
    /// 字典没收录 ⇒ 它们的内联 en 才是生效值。EN 表**零改动**（禁把这两枚补进表里）。
    /// 变异证明：往 `src/i18n.rs` 加一枚 `("当前会话没有计划。", …)` ⇒ 本把立刻红（表面试那一发）。
    #[test]
    fn the_copy_channels_match_the_trunk_dict_first_rule() {
        let lib = include_str!("i18n.rs");
        for key in ["当前会话没有计划", "计划为只读清单"] {
            assert!(
                !lib.contains(key),
                "分叉 EN 表里冒出主干也没有的键 {key} ⇒ 把主干「内联 en 生效」改成「字典生效」= 造档"
            );
        }
        let en = Catalog::load("en", None);
        let zh = Catalog::load("zh", None);
        // #3 / #4：字典没收 ⇒ 内联 en 生效（活码）。
        assert_eq!(
            en.bt("当前会话没有计划。", "No schedules in this session."),
            "No schedules in this session."
        );
        // #1 / #5：字典在架 ⇒ 传一枚**错的**内联 en 也必须回字典值（内联是死码）。
        assert_eq!(en.bt("计划（只读）", "WRONG"), "Schedules (read-only)");
        assert_eq!(
            en.bt(
                "尚未收到本会话的计划投影（投影随会话活动到达），此时不表示没有计划。",
                "WRONG"
            ),
            "The schedule projection has not arrived yet (the kernel pushes it lazily); this does not mean there are no schedules."
        );
        // #6 频率 / #11-#13 量级：`L()` / `LF()` 单通道 ⇒ 查表填洞。
        assert_eq!(en.l("一次性"), "One-time");
        assert_eq!(en.lf("每 {0} 天", &["2".to_string()]), "Every 2 days");
        assert_eq!(en.lf("每 {0} 秒", &["45".to_string()]), "Every 45 seconds");
        assert_eq!(en.lf("{0}分钟", &["1".to_string()]), "1m");
        assert_eq!(
            en.lf("还剩 {0}", &[en.lf("{0}秒", &["5".to_string()])]),
            "5s left",
            "两层 `LF` 的嵌套口径漂了：主干是 `LF(还剩…, ScheduleMagnitudeLabel(left))` 两发套一发"
        );
        assert_eq!(en.lf("已过期 {0}", &["5s".to_string()]), "5s overdue");
        // 中文档：一律原样，且 `bt` 的那两枚也不许被英文污染。
        assert_eq!(zh.l("一次性"), "一次性");
        assert_eq!(zh.bt("计划（只读）", "WRONG"), "计划（只读）");
    }

    /// ⑧ 收点形制：本族只走助手壳，直写 `= None` 一枚都不许有（同 `goal_panel_tests` 判据一）。
    /// 账目 **15 发** = 六发兄弟层开臂 + `Branched` + 五张同级模态卡的开臂（批 SFB1（#158 卡 B）
    /// 会话反馈那张是第五张 ⇒ SFB2 报告 §2 第 6 把从 14 抬到 15）+ `Close` 臂 +
    /// `Toggle` 的「已开⇒收」分支 + 键盘三档那一档（口径逐字同上面那颗壳的 doc）。
    /// 批 SKP1（#158 卡 A）：技能选择器那张入同级 mesh、开臂收这张一次 ⇒ 15→**16**。
    /// 批 CD1（#158 面 B/C）：Cordis 面板那张入同级 mesh、开臂收这张一次 ⇒ 16→**17**
    /// （那一发住在 `Msg::CordisPanelToggle` 的开臂里，账目见 `cordis_panel_tests` 判据①②）。
    /// 变异证明：删掉 `Msg::SchedulePanelClose` 那一臂里的一发 ⇒ 17 变 16，本把红。
    #[test]
    fn the_card_retires_only_through_its_shell_form() {
        let shell = concat!("schedule_panel_close(&mut self.", "schedule_panel);");
        assert_eq!(
            code().matches(shell).count(),
            17,
            "收点枚数漂了：少一处 = 两张模态卡同屏，多一处 = 有人在往别的状态上收"
        );
        assert_eq!(
            code()
                .matches(concat!("self.schedule_", "panel = None;"))
                .count(),
            0,
            "出现了直写赋值形 ⇒ 形制又交回「改动者自己去数」"
        );
        // 关闭臂**只**收那一格：投影那两格是缓存，主干这张卡没有 `Closed` 订阅（spec §5.3）。
        let source = include_str!("main.rs");
        let close = window(source, "Msg::SchedulePanelClose => {", "Msg::GoalPanelToggle => {");
        assert_eq!(close.matches(shell).count(), 1);
        assert!(
            !close.contains(concat!("schedule_", "records")),
            "关闭时清了投影缓存 = 主干没有的「关闭清理」"
        );
        // 切会话那一臂（spec §3.1 腿 D `MW:4508-4511`）是**唯一**复位两格的地方。
        assert_eq!(
            code()
                .matches(concat!("self.schedule_", "records = Vec::new();"))
                .count(),
            1,
            "投影缓存的复位点漂了：主干只在切会话清，别处清就是多一个生命周期"
        );
        assert_eq!(
            code()
                .matches(concat!("self.schedule_", "seen = false;"))
                .count(),
            1
        );
    }

    /// ⑨ 键盘三档不并档（spec §7 第 4 行：Close 动手、Move/Accept **吞掉**）+ 槽位注册。
    /// 变异证明：把 `Msg::PaletteAccept if self.schedule_panel…` 那一臂删掉 ⇒ 第二把红；
    /// 把 `publish_keys` 里那一枚 `schedule_panel.is_some()` 删掉 ⇒ 最后一把红（Esc 再也进不来）。
    #[test]
    fn the_three_keyboard_tiers_are_three_arms_and_the_slot_is_registered() {
        let source = include_str!("main.rs");
        let close = concat!("Msg::PaletteClose if self.", "schedule_panel.is_some()");
        let move_tier = concat!("Msg::PaletteMove(_) if self.", "schedule_panel.is_some()");
        let accept = concat!("Msg::PaletteAccept if self.", "schedule_panel.is_some()");
        assert_eq!(code().matches(close).count(), 1, "Esc 那一档没了或多了一档");
        assert_eq!(
            code().matches(move_tier).count(),
            1,
            "↑/↓ 吞键那一档并到 Close 里了：面板开着时方向键会去动底下的浮层"
        );
        assert_eq!(
            code().matches(accept).count(),
            1,
            "Enter 吞键那一档没了：本面板零输入件 ⇒ Enter 不许落到底下的命令浮层"
        );
        assert!(
            pos(source, close) < pos(source, "Msg::PaletteClose if self.file_menu"),
            "三档的先后漂了：模态卡那几档必须排在浮层档之前"
        );
        assert!(
            code().contains("|| self.schedule_panel.is_some()"),
            "`publish_keys` 没把这一格并进 overlay 槽 ⇒ Esc 永远投不进来（FA1-F-2 的老账）"
        );
    }

    /// ⑩ 宿主那一格：第四发、末位、槽位枚数 1，且显隐判据在（reactor 没有 `Visibility`）。
    /// 变异证明：把第四发的 `if self.schedule_panel.is_some()` 删掉 ⇒ 第一把红。
    /// ⚠ PS1 复核：红 2 也是**用例自计数**（不是宿主多挂了一棵）。原写法在下面那颗
    ///   `at_key("schedule-panel")` 里把针**整串裸写**了一遍 ⇒ `code()` 数到 2（宿主那一发 +
    ///   本行这一发）。产品码侧的枚数**从来就是 1**，且宿主四格每格都关在
    ///   `if self.<那一张>.is_some()` 里 ⇒ 未开时那棵 keyed 节点根本不生成（MD1/ML1 定案口径）。
    ///   现改走已拆词的 `slot` ⇒ 量的是宿主，不是自己。
    #[test]
    fn the_fourth_push_mounts_last_in_the_shared_modal_host() {
        let source = include_str!("main.rs");
        let slot = concat!("\"schedule-", "panel\"");
        assert_eq!(
            code().matches(slot).count(),
            1,
            "面板槽位枚数变了：一处不多一处不少（不开时那棵节点根本不生成）"
        );
        let host = window(source, "fn app_modal_host(", "fn body(");
        assert!(host.contains("if self.schedule_panel.is_some()"));
        // 入树序 = 简报 D-1 点名的四格序：todos → trajectory → goal → schedules。
        let at_key = |key: &str| host.find(key).unwrap_or_else(|| panic!("宿主少了 {key} 那一格"));
        let todos = host.find(concat!("\"todos-", "panel\"")).expect("todos 那一格");
        assert!(
            todos < at_key(concat!("\"trajectory-", "panel\""))
                && at_key(concat!("\"trajectory-", "panel\""))
                    < at_key("\"goal-")
                && at_key("\"goal-") < at_key(slot),
            "四格的入树序漂了：末位那一格才是主干「后开的压在顶上」的等价物"
        );
    }

    /// ⑪ 入口只一颗（D-10）：`SchedulesMenuItem` 全文件一枚、走 `bt`、点它发的是 `Toggle`；
    /// 且它**无条件**入 composer 带（与轨迹那颗的「首帧才挂」不同档，spec §4.4 末行）。
    /// 变异证明：给入口补一枚 `FontIcon` ⇒ 文本锁不红，但把 `on_click` 换成 `PanelClose` 会红。
    #[test]
    fn the_entry_is_one_cell_with_the_trunk_automation_id_and_no_glyph() {
        let source = include_str!("main.rs");
        assert_eq!(
            code()
                .matches(concat!("SchedulesMenu", "Item"))
                .count(),
            1,
            "主干那颗 id 全仓唯一（`CP:81`+`CP:95`）：多一枚就是自造 id"
        );
        let entry = window(source, "fn schedules_entry_cell(", "fn trajectory_panel_layer(");
        assert!(entry.contains(concat!("Msg::SchedulePanel", "Toggle")));
        assert_eq!(entry.matches(".bt(").count(), 1, "入口文案只许一发 B 道");
        assert!(
            !entry.contains("FontIcon"),
            "那颗 `MenuFlyoutItem` 没有字形 ⇒ 分叉不许长出一枚主干查无此物的图标"
        );
        let band = window(source, "fn composer_band(", "fn agent_mode_trigger(");
        assert_eq!(
            band.matches(concat!("KeyedView::new(\"", "schedules\",")).count(),
            1
        );
        let schedules_push = band
            .find(concat!("KeyedView::new(\"", "schedules\","))
            .expect("composer 带里那一发入口");
        let gate = band.find("if !self.trajectory_journal.is_empty()");
        assert!(
            gate.is_none_or(|head| schedules_push > head),
            "入口被挂进了轨迹那颗的「首帧才挂」判据里：主干那三颗恒挂、不按数据显隐"
        );
    }

    /// ⑫ 卡面几何与件数（spec §2.3 / §0 第 4 条 / D-8）：`Spacing=10, Width=440` 的正文 +
    /// `MaxHeight=480` 的外滚 + **零输入框 / 零 RPC / 零遮罩回调**，按钮只有 `CloseButtonText` 那一颗。
    /// 变异证明：给卡体加一颗 `Button::new()` ⇒ 第一把红；把 `max_height(480.0)` 改成 540 ⇒ 第二把红。
    #[test]
    fn the_card_geometry_matches_the_trunk_and_paints_no_inputs() {
        let source = include_str!("main.rs");
        let card = window(source, "fn schedule_panel_card(", "fn app_modal_host(");
        assert_eq!(card.matches(".width(440.0)").count(), 1);
        assert_eq!(card.matches(".max_height(480.0)").count(), 1);
        assert_eq!(card.matches(".spacing(space::S10)").count(), 1);
        assert_eq!(card.matches(".spacing(space::S2)").count(), 1, "行容器那一发");
        assert_eq!(
            card.matches("Button::new()").count(),
            1,
            "面板内按钮 0 颗：唯一那颗是对话框统一的 `CloseButtonText`（`CP:110`）"
        );
        assert_eq!(card.matches("TextBox").count(), 0, "本卡零输入件（spec §0 第 4 条）");
        assert_eq!(
            card.matches("automation_id").count(),
            0,
            "树内不许自造 id（仓规）：卡题走 `automation_name`"
        );
        assert_eq!(
            card.matches(META_DOT).count(),
            2,
            "meta 那枚分隔符在主干用**两次**（`CP:348`/`CP:350`）：三段变两段或反过来都是漂"
        );
        assert_eq!(card.matches(".foreground(").count(), 1, "只有 meta 行上色（TextTertiary `CP:356`）");
        assert_eq!(
            card.matches("type_ramp::CAPTION").count(),
            1,
            "`CaptionTextStyle` 那一档只落在 meta 行（`CP:357`）"
        );
        let layer = window(source, "fn schedule_panel_layer(", "fn schedule_panel_card(");
        assert_eq!(
            layer.matches("on_pointer_pressed").count(),
            0,
            "遮罩挂了回调 = 抄成 `MenuFlyout` 那族的 light-dismiss（D-2 / MD1 F-1 的红线）"
        );
        assert!(layer.contains("p.transparent"));
    }

    /// ⑬ 零 RPC 面（D-8 / spec §6.1）：全文件不许出现 `schedules/` 那一族端点名，也不许有
    /// 任何 `schedule` 相关的**出站**调用；`"schedule"` 那枚投影键在本文件仍只有一枚字面量
    /// （读点与侧栏闹钟同一颗，spec §7 第 11 行）。
    /// 变异证明：把开臂里的投影读取换成 `self.call("schedules" 拼 "/list", …)` ⇒ 前两把同时红。
    /// ⚠ PS1 复核：这一把它自己踩了**两次**本仓 FX1/MS1 点名的坑，红 1 的全部来源就是这里 ——
    ///   ① assert 消息里那句裸 `\"schedules/` 在源码层面就是同一串字节 ⇒ 针把**消息**数了进去；
    ///   ② 取窗走的是**未过 `code_only`** 的原文 ⇒ 开臂注释里那句取证用的 `_rpc is null`
    ///     被算成 RPC 出口。⇒ 现一律改量 `code_only` 之后的源码，且读点针收窄到赋值那一发
    ///     （`parse_schedule_records(` 裸名在本 mod 的 ⑥ 里被调了四发，量全文件必然虚高）。
    ///   **产品码一字未动**：全仓 `\"schedules/` 在 `code_only` 之后确为 0 发（见报告 §1 红 1）。
    #[test]
    fn the_panel_reads_the_projection_and_calls_no_endpoint() {
        let code = code_only(include_str!("main.rs"));
        assert_eq!(
            code.matches(concat!("\"schedules", "/")).count(),
            0,
            "造出 schedules/list 一类的端点 = 假移植面（主干全仓 schedules/ 前缀零命中）"
        );
        assert_eq!(
            code
                .matches(concat!("self.schedule_records = parse_schedule_", "records("))
                .count(),
            1,
            "折记录表的读点只许一发（② 净增量核心；多一发就是第二份真相）"
        );
        assert_eq!(
            code.matches("value_of(\"schedule\")").count(),
            2,
            "投影键读点两发：侧栏闹钟那刻 + 本卡开臂（简报 D-4 说的那把尺按 `code_only` 量）"
        );
        let toggle = window(&code, "Msg::SchedulePanelToggle => {", "Msg::SchedulePanelClose => {");
        assert!(
            !toggle.contains("self.call(") && !toggle.contains("rpc"),
            "开臂里冒出 RPC：这张面板一颗请求都不发（spec §3）"
        );
        assert!(toggle.contains("请先连接内核并选择会话。"));
        // 批 ERR2（#161 扩面 F-1）：那一发从「落一行 `DIAG:` 自持日志」换成了 ERR1 建好的错误卡
        // ⇒ 旧的那句正向断言从此是**反向**判据：同一句话只许一条出口，`DIAG:` 回来了就是长出第二份
        // 真相。针一律拆词写（MS1 §M-2 族规：判据原文不许被自己数进去）。
        assert!(!toggle.contains(concat!("DIAG", ":")));
        assert!(toggle.contains(concat!("Msg::ErrorDial", "og(")));
    }

    /// ⑭ 三档渲染的**形状**判据（打在 keyed 槽名上，不是打像素）：有记录 = 一枚 `schedule-row-N`；
    /// 空 = 恰一枚 `schedule-empty`；声明行恒在。行容器加入序 = prompt → meta（`CP:336-357`）。
    #[test]
    fn the_three_tiers_differ_by_their_slot_names_and_order() {
        let source = include_str!("main.rs");
        let card = window(source, "fn schedule_panel_card(", "fn app_modal_host(");
        for slot in [
            concat!("\"schedule-", "note\""),
            concat!("\"schedule-", "empty\""),
            "schedule-row-",
        ] {
            assert_eq!(
                card.matches(slot).count(),
                1,
                "槽名 {slot} 的枚数漂了：三档共用同一批名字才能被取树尺读出来"
            );
        }
        assert!(
            card.find(concat!("\"schedule-", "note\"")).expect("声明行")
                < card.find(concat!("\"schedule-", "empty\"")).expect("空态行"),
            "只读声明必须在空态之前入树（`CP:315-333` 的加入序）"
        );
        assert!(
            card.find("let prompt: View").expect("prompt 行")
                < card.find("let meta_row: View").expect("meta 行"),
            "行内两行的加入序反了（主干 `:338` 先 `prompt` 后 `meta`）"
        );
        // 三档的判据只有一枚：`ordered.is_empty()`（`CP:322`）。
        assert_eq!(card.matches("ordered.is_empty()").count(), 1);
        assert_eq!(card.matches("ordered.iter().enumerate()").count(), 1);
    }
}

#[cfg(test)]
mod error_dialog_tests {
    //! 批 ERR1（#157「错误弹层通道」，槽位键 = `MODAL_LEDGER` 那颗 `card` 的既有值）的自家锁。
    //! 主干那一份 = `MW:13822` 的 `ShowErrorAsync(string message)`：**一颗、零重载**、四枚字段
    //! （Title / Content 裸串 / CloseButtonText / XamlRoot）、一颗 **drop 型**重入闸
    //! （`_errorDialogShowing`，`MW:13820`）、被别的模态挡住时那一句话**静默丢失**。
    //! 本 mod 只钉：主干形状 / 遮罩族别 / 闸的语义 / 收法壳 / 不进同级 mesh / 键盘三档与报位 /
    //! 入树末位 / **火口逐臂白名单**（ERR1 只授权一枚，ERR2 按 SKP2 §4.3 的主干 catch 证据把 7 枚
    //! 登进 `WIRED_TRIGGERS` 那张表 ⇒ 「只接一个触发点」那把旧闸已按授权作废，反半换成总数硬闸）/
    //! 台账与字典零增量 —— 一件都不在表外扩。
    //! 三条口径逐字同 `schedule_panel_tests`：① 全文件计数型针一律 `concat!` 拆词（FX1：整串
    //! 写出来就把本行数进产品码）且过 crate 根的 [`code_only`]；② 能打在形制上的不降级成注释锁；
    //! ③ 取窗锚一律本卡独有的 fn 名或臂名，一把窗只量一件事。
    use super::*;

    fn code() -> String {
        code_only(include_str!("main.rs"))
    }

    /// 取窗：`start` 之后、`end` 之前那一段（两枚锚都不在段内 ⇒ 计数不会把锚行自己数进去）。
    fn window<'a>(source: &'a str, start: &str, end: &str) -> &'a str {
        let (_, rest) = source
            .split_once(start)
            .unwrap_or_else(|| panic!("取窗锚 {start} 在文件里找不到"));
        match rest.split_once(end) {
            Some((body, _)) => body,
            None => panic!("取窗锚 {start} 之后找不到 {end}"),
        }
    }

    /// 针在源码里的位置（找不到就 panic，别拿 `usize::MAX` 蒙过判据）。
    fn pos(source: &str, needle: &str) -> usize {
        source
            .find(needle)
            .unwrap_or_else(|| panic!("锚针 {needle} 在文件里找不到"))
    }

    /// ① 主干形状：入参**只有一枚** `String`（没有 title+content 那枚两参重载 ⇒ 造它就是自造
    /// 主干没有的态）；卡体只有那四枚字段，标题与关闭钮两枚是**硬字面量**（零 i18n 通道），
    /// `DefaultButton` / `Timeout` / `PrimaryButton` / 滚动件 / 「查看详情」/ 复制钮 / 自造宽度
    /// 一个都不许长出来。
    /// 变异证明：把 `let title = "Blade²";` 换成 `self.catalog.l("Blade²")` ⇒ `self.catalog`
    /// 那一把红；给卡体补一发 `.max_height(480.0)` ⇒ 缺席清单那一把红。
    #[test]
    fn the_card_is_the_trunk_single_argument_bare_string_dialog() {
        let code = code();
        let source = include_str!("main.rs");
        // 声明侧：`ErrorDialog` 只吃一枚 `String`，全文件没有第二形。
        assert_eq!(code.matches(concat!("ErrorDialog(Str", "ing),")).count(), 1);
        assert!(
            !code.contains(concat!("ErrorDialog(String", ", String")),
            "长出了主干没有的两参重载"
        );
        let card = window(source, "fn error_dialog_card(", "fn body(");
        // 两枚硬字面量都在卡体里（`\u{00B2}` 转义：本行源码里没有那枚裸上标，别处的计数不受牵连）。
        assert!(
            card.contains("Blade\u{00B2}"),
            "标题那枚硬字面量没了（主干 `Title = Blade²` 那枚）"
        );
        assert!(
            card.contains("确\u{5B9A}"),
            "关闭钮那枚硬字面量没了（主干 `CloseButtonText` 那枚，全仓独一份）"
        );
        assert_eq!(
            card.matches("self.catalog").count(),
            0,
            "卡体里有一枚走了表 ⇒ 与主干偏离（那颗标题与关闭钮都不过 `L()`）"
        );
        for absent in [
            "DefaultButton",
            "Timeout",
            "PrimaryButton",
            "ScrollViewer",
            "FontIcon",
            ".width(",
            ".max_height(",
            "on_pointer_pressed",
        ] {
            assert!(!card.contains(absent), "卡体长出了主干没有的那一件：{absent}");
        }
        // 关闭钮 = 本卡**唯一**那颗控件（主干只给 `CloseButtonText`）。
        assert_eq!(card.matches("Button::new()").count(), 1);
        assert!(card.contains(concat!("Msg::ErrorDialog", "Close")));
    }

    /// ② 遮罩那一族：抄 `ContentDialog` 一族（铺满 + `transparent` + **不挂**指针处理器 ⇒ 点卡外
    /// 既不关也不穿透），**不抄**那两族 `MenuFlyout` 替身的 light-dismiss。
    /// 变异证明：给那颗 `scrim` 补一发 `.on_pointer_pressed(..)` ⇒ 反向那把红。
    #[test]
    fn the_scrim_belongs_to_the_content_dialog_family() {
        let source = include_str!("main.rs");
        let layer = window(source, "fn error_dialog_layer(", "fn error_dialog_card(");
        assert!(layer.contains("let scrim: View = Border::new()"), "那颗遮罩没了");
        assert!(layer.contains("background(p.transparent.clone())"));
        assert!(layer.contains(".grid_row(0)"));
        assert!(layer.contains("HorizontalAlignment::Stretch"));
        assert!(layer.contains("VerticalAlignment::Stretch"));
        assert!(
            !layer.contains("on_pointer_pressed"),
            "遮罩挂了指针处理器 = 抄了 flyout 那族（主干那颗点外面不关）"
        );
    }

    /// ③ 闸 = 一格 `Option`、语义是 **drop 不排队**（逐字同主干 `if (_errorDialogShowing) return;`）：
    /// 全文件**只留一个写口**，且那个写口被 `is_none` 守卫裹着 ⇒ 第二发直接丢、不自创队列。
    /// 变异证明：把那道守卫删掉（后发顶掉先发）⇒ 前两把红。
    #[test]
    fn the_gate_drops_the_second_message_instead_of_queueing() {
        let code = code();
        let arm = window(&code, concat!("Msg::ErrorDialog", "(text) => {"), "Msg::ErrorDialogClose => {");
        assert!(
            arm.contains("if self.error_dialog.is_none()"),
            "重入闸没了：第二发会顶掉第一发 ⇒ 主干是**丢**，不是顶"
        );
        assert_eq!(
            arm.matches(concat!("self.error_dialog = So", "me(")).count(),
            1,
            "那一臂写了两格 ⇒ 编出了主干没有的第二状态"
        );
        assert!(
            !arm.contains("Vec<") && !arm.contains("push_str"),
            "编出了主干没有的队列（`_errorDialogShowing` 那颗 bool 之后什么都没有）"
        );
        assert_eq!(
            code.matches(concat!("self.error_dialog = So", "me(")).count(),
            1,
            "写口不止一处 ⇒ drop 闸判不准，同一句话会有第二条出口"
        );
        assert_eq!(
            code.matches(concat!("self.error_dialog = No", "ne;")).count(),
            0,
            "不许直写那一枚 = None：收法走 helper 壳，形制才有锁"
        );
    }

    /// ④ 收法只那颗 helper 壳，且**两个**出口就够（关闭钮那一发 + Esc 那一档）⇒ 主干那颗卡
    /// 的关闭通路只有 `CloseButton` 与 Esc 两条，第三条（点外面 / 自动关 / 队列）一概没有。
    /// 变异证明：把 `Msg::ErrorDialogClose` 臂里那一发直写成 `= None` ⇒ 第一把红。
    #[test]
    fn the_card_retires_only_through_its_shell_form() {
        let code = code();
        let close = concat!("error_dialog_close(&mut self.error_", "dialog);");
        assert_eq!(code.matches(close).count(), 2, "收点枚数变了：只许「关臂 + Esc 档」两发");
        assert_eq!(
            code.matches(concat!("fn error_dialog_clo", "se(")).count(),
            1,
            "收法壳不许有第二颗"
        );
        let helper = window(
            &code,
            concat!("fn error_dialog_", "close(state: &mut Option<String>) -> bool {"),
            "\n}\n",
        );
        assert!(helper.contains("let had = state.is_some();"));
        assert!(helper.contains("*state = None;"));
    }

    /// ⑤ **不进**同级 mesh（E1 §3-2 那句「五枚针 +0 不是运气，是设计决定」）：本卡的臂不收任何
    /// 兄弟层，兄弟层的开臂也不写本卡的收法 ⇒ 那五枚针一枚都不因本卡而抬。
    /// 变异证明：往 `Msg::GoalPanelToggle` 那一臂里补一发本卡的 close ⇒ 反向那半把红。
    #[test]
    fn it_stays_out_of_the_sibling_mesh_in_both_directions() {
        let code = code();
        let arms = window(&code, concat!("Msg::ErrorDialog", "(text) => {"), "Msg::GoalPanelToggle => {");
        for sibling in [
            "goal_panel_close(",
            "danger_confirm_close(",
            "todos_panel_close(",
            "dock_menu_close(",
            "schedule_panel_close(",
            "selector_close(",
            concat!("self.trajectory_panel_", "close("),
        ] {
            assert!(
                !arms.contains(sibling),
                "本卡的臂收了兄弟层 ⇒ 塞进了同级 mesh（主干那颗既不闭兄弟、兄弟也不闭它）"
            );
        }
        // 反向半边：兄弟层的开臂里连本卡那一格的名字都不许出现（要收它 = 造主干没有的并存态）。
        for (start, end) in [
            ("Msg::GoalPanelToggle => {", "Msg::GoalPanelClose => {"),
            ("Msg::SchedulePanelToggle => {", "Msg::SchedulePanelClose => {"),
        ] {
            let arm = window(&code, start, end);
            assert!(
                !arm.contains(concat!("self.error_", "dialog")),
                "{start} 那一臂收了本卡 ⇒ 主干没有的「兄弟层关错误卡」"
            );
        }
    }

    /// ⑥ 键盘三档不并档 + 报位（同 `schedule_panel_tests` ⑨）。本卡排在 todos **之前**问：
    /// 它是压住全部的最上面一层，而且可与四张兄弟同屏（不进 mesh）⇒ Esc 该先摘它。
    /// 变异证明：删掉 `Msg::PaletteAccept if self.error_dialog..` 那一臂 ⇒ 第三把红；
    /// 把 `publish_keys` 里那一枚报位删掉 ⇒ 第五把红。
    #[test]
    fn the_three_keyboard_tiers_are_three_arms_and_the_slot_is_registered() {
        let source = include_str!("main.rs");
        let code = code();
        // 那两枚前缀一律**拆在 `if` 之前**（ERR1 §4-4 的修法）：拆在 `if ` 之后会把「`PaletteClose`
        // 空格 `if`」那枚前缀留在明文里 ⇒ 全文件量它的人凭空多读两发（自家自计数隐患）。
        let close = concat!("Msg::PaletteClose ", "if self.error_dialog.is_some()");
        let move_tier = concat!("Msg::PaletteMove(_) if sel", "f.error_dialog.is_some()");
        let accept = concat!("Msg::PaletteAccept if sel", "f.error_dialog.is_some()");
        assert_eq!(code.matches(close).count(), 1, "Esc 那一档没了或多了一档");
        assert_eq!(
            code.matches(move_tier).count(),
            1,
            "↑/↓ 吞键那一档并到 Close 里了：卡开着时方向键会去动底下的浮层"
        );
        assert_eq!(
            code.matches(accept).count(),
            1,
            "Enter 吞键那一档没了：主干那颗不写 `DefaultButton` ⇒ Enter 本就不提交"
        );
        assert!(
            pos(source, close) < pos(source, concat!("Msg::PaletteClose ", "if self.todos_panel")),
            "判序漂了：最上面那一层该最先问"
        );
        assert!(
            code.contains(concat!("|| self.error_", "dialog.is_some()")),
            "`publish_keys` 没把这一格并进浮层槽 ⇒ Esc 永远投不进来（FA1-F-2 的老账）"
        );
        // 那一档的**总枚数**：只能取窗量，不能整文件朴素数 —— 那枚前缀在别的 `mod` 的断言里
        // 也是字面量 ⇒ 整文件 raw 数到 34（`code_only` 口径 33：本窗 15 发 + 其余住在各 mod 的
        // 锚串与本卡自己那一发里）。ERR2 把本 mod 那两枚拆点改到 `if` **之前** ⇒ 两个口径各降 2/2
        // （原 35 / 34，见报告 §4-2 的两态实测）。批 CD1（#158 面 B/C）Cordis 面板那张入 Esc 档
        // ⇒ 两口径各 +1（33→34 / 32→33，实测 = 上面那条 `grep -oF` 复跑命令；本 mod 与
        //    `cordis_panel_tests` 的锚串一律拆在 `if` **之前** ⇒ 不自我进账）。上面
        // `Msg::PaletteClose if self.goal_panel..` 那一臂的注释（`:13676`）记的就是同一桩账。
        // 批 CB1（#162 B-1a）族 A 第二发那张入 Esc 档 ⇒ 本窗 15→**16**（上面那把等号形闸同步抬）；
        // 整文件两枚口径今数 37 / 36（CB1 只进 1 发，其余是各 mod 锚串与注释的历史账，本刀不并）。
        // 窗：本卡那一发之后（`close` 那枚锚被 split_once 吃进左段）到浮层自己的兜底臂之前。
        let esc_tier = window(
            &code,
            close,
            "Msg::PaletteMove(delta) => self.move_palette(",
        );
        assert_eq!(
            esc_tier.matches(concat!("Msg::PaletteClose i", "f ")).count(),
            16,
            "Esc 档的枚数漂了：每张可 Esc 的层各一发（本卡之外 16 发，批 SFB1 会话反馈那张是第十三级、\
             批 SKP1 技能选择器那张是第十四级、批 CD1 Cordis 面板那张是第十五级 ⇒ SFB2 报告 §2 第 2 把，\
             批 CB1 族 A 第二发那张是第十六级），多一枚少一枚都是形制变了"
        );
    }

    /// ⑦ 入树：宿主那一格里本卡**仍压在前四张能力面板之后**、槽位枚数 1、显隐判据在
    /// （reactor 没有 `Visibility`）。⚠ 批 SFB1（#158 卡 B）按简报 C-1 把会话反馈那张落成
    /// **第六格**（排在错误卡之后）⇒ 「本卡是末格」从今天起只对「四张能力面板 vs 本卡」这一
    /// 对比成立，宿主的总发数 5→**6**（SFB2 报告 §2 第 1 把 / §6 的 z 序判据）；批 SKP1 技能选择器
    /// 那张 = 第七格（6→7）；批 CD1（#158 面 B/C）Cordis 面板那张 = **第八格**（7→8）⇒ 本卡之后
    /// 还有两张压着它，「末位」那半句从今天起只对「四张能力面板 + 本卡 vs 会话反馈 / 技能 / Cordis」成立。
    /// 变异证明：把第五发的 `if self.error_dialog.is_some()` 删掉 ⇒ 第二把红；
    /// 把它挪到 todos 之前 ⇒ 末位那把红。
    #[test]
    fn the_fifth_push_mounts_last_in_the_shared_modal_host() {
        let source = include_str!("main.rs");
        let host = window(source, "fn app_modal_host(", "fn error_dialog_layer(");
        let slot = concat!("\"error-", "dialog\"");
        assert_eq!(
            host.matches(slot).count(),
            1,
            "槽位枚数变了：一处不多一处不少（不开时那棵节点根本不生成）"
        );
        assert!(
            host.contains(concat!("if self.error_dial", "og.is_some()")),
            "显隐判据没了 ⇒ 关着的时候也会画出一层遮罩"
        );
        let at_key = |key: &str| host.find(key).unwrap_or_else(|| panic!("宿主少了 {key} 那一格"));
        let schedule = at_key(concat!("\"schedule-", "panel\""));
        assert!(
            schedule < at_key(slot),
            "第五发不再末位 ⇒ 它压不住前面那四张（主干那颗是压在一切之上）"
        );
        assert_eq!(
            host.matches("KeyedView::new(").count(),
            8,
            "宿主那一格的发数 = 四张能力面板 + 本卡 + 会话反馈那张（简报 C-1 裁第六格）\
             + 技能选择器那张（批 SKP1 裁第七格）+ Cordis 面板那张（批 CD1 裁第八格，末位）；\
             多一发就是另起一张脸"
        );
    }

    /// ⑧ 火口**逐臂白名单**（正半 + 反半，两半都要在）：批 ERR1 只授权一枚（`Msg::GoalPanelToggle`
    /// 臂），批 ERR2（#161 扩面）按 SKP2 §4.3 的主干证据（入口 wrapper `CP:73-79` 对**每一发**
    /// throw 都 `await ShowErrorAsync(ex.Message)`）把另外 6 发有肉的接进同一颗通道 ⇒ 表长 **7**。
    /// 反半 = 总数硬闸：`Msg::ErrorDialog(` 的枚数 = 表长 + 火臂那一枚 = **8**（批 ERR3 把 cordis 那
    /// 三枚接进来 ⇒ 表长 7 → 10、枚数 8 → 11；闸本身是指向 `WIRED_TRIGGERS.len() + 1` 的派生式，
    /// 一硬数字都没写）；多一枚而没登表 = 红
    /// （没授权的扩面），登了表而产品码没接 = 正半那一行红 ⇒ 两头都堵。
    /// ⚠ 表里三枚串锚一律**本臂独有**，且起锚止锚成对（SKP2 红 2 的教训：那枚
    /// `|| self.active.as_deref().unwrap_or("").trim().is_empty()` 全文件四发，拿它当锚会把窗拽到
    /// 兄弟臂的开臂收点圈里）；针一律 `concat!` 拆词 ⇒ 判据原文不许被自己数进去（MS1 §M-2 族规）。
    /// ⚠ 末行的「主干原文」那一列装的是**形制针**（F-6 上屏的是内核原话，不过 i18n 表 ⇒ 压根没有
    /// 一句原文可钉，见简报 §2 表 F-6 那一格）。
    /// 变异证明（红态原文见 ERR2 报告 §4）：把 F-1 那一发退回 `DIAG:` ⇒ 正半第一档红、总数那把也红
    /// （8 → 7）；在表外多发火（守卫 ② 那一块）⇒ 总数那把红（8 → 9）+ 最下面那把禁针红。
    /// 批 ERR3（#161 扩面 cordis 族）：**7 → 10**。末三行 = 浮卡那四颗 outcome 钮的提交腿那一枚
    /// **带前缀**的火（`CD:615`，主干唯一一枚过文案表的）+ run/stop 与 `移除` **共用**的回执臂
    /// （主干 `CD:784` 与 `CD:868` 两发裸 `ex.Message` 在分叉**并成一枚落点** ⇒ 报告 §3-B）+ 两颗
    /// 动作钮共用的前置闸第③道（`CD:323/357/363` 那三发 `throw`，经上面同一批 `catch` 才成的卡）。
    /// ⚠ 三行的锚全打在 **cordis 自己那一族内**，末两枚的止锚取「那一臂/那一颗自己尾上的句子」而不是
    /// 「紧邻下家」（`47001-47008` 备案的那场事故：CD1 在 `Msg::SkillPickerListed` 与
    /// `Msg::SchedulePanelToggle` 之间插进 cordis 那一排臂 ⇒ 窗从 34 行涨到 105 行、圈进邻臂合法的
    /// `DIAG:` = 假红）。总数闸仍是指向 `WIRED_TRIGGERS.len() + 1` 的**派生式**（11 = 10 + 1）⇒ 表长
    /// 一改它就自己抬，本刀一个硬数字都没写进去。
    const WIRED_TRIGGERS: [(&str, &str, &str); 10] = [
        (
            "Msg::GoalPanelToggle => {",
            "Msg::GoalPanelClose",
            "请先连接内核并选择会话。",
        ),
        (
            "Msg::SchedulePanelToggle => {",
            "Msg::SchedulePanelClose",
            "请先连接内核并选择会话。",
        ),
        (
            "Msg::SkillPickerToggle => {",
            "Msg::SkillPickerClose",
            "请先连接内核并选择会话。",
        ),
        (
            "Msg::SkillPickerPick(index) => {",
            "Msg::SkillPickerListed(outcome, session_id)",
            "会话已切换，请关闭后重新打开。",
        ),
        (
            "Msg::SkillPickerListed(outcome, session_id) => {",
            "Msg::SchedulePanelToggle",
            "会话已切换，请关闭后重新打开。",
        ),
        (
            "Msg::SkillPickerListed(outcome, session_id) => {",
            "Msg::SchedulePanelToggle",
            "技能列表响应格式不正确。",
        ),
        (
            // F-6：`Err(message) => { self.update(Msg::ErrorDialog(message), context); }` —— 消息
            // 就是内核原话 ⇒ 钉的是**直传形制**（它替掉了「本臂自己编一句」那条老路）。
            "Msg::SkillPickerListed(outcome, session_id) => {",
            "Msg::SchedulePanelToggle",
            concat!("Msg::ErrorDial", "og(message)"),
        ),
        // ---- 批 ERR3（#161 扩面 cordis 族）三行：锚全在本族内，止锚一律取「那一臂自己尾上」----
        (
            // 落点①：`CD:615` 那枚**带前缀**的火 ⇒ 钉前缀原文（B 道，见报告 §2-D 的 `ShellEnglish`
            // 现测：那一格压根不在表里 ⇒ 不许套 `l`）。止锚 = 本臂自己的第一句状态复位（`finally` 的
            // 第一步）⇒ 窗天然只量这一臂，与「下一臂是谁」解耦。
            "Msg::CordisApprovalDone(request_id, outcome) => {",
            "cordis_approvals.submitting = false;",
            "审批回传失败：",
        ),
        (
            // 落点②：`CD:784` + `CD:868` 那两发裸 `ShowErrorAsync(ex.Message)` 在分叉**并成这一枚回执臂**
            // ⇒ 钉的是**直传形制**（同上面 F-6 那一格：内核原话不许本刀替它编第二句、不过 i18n 表）。
            "Msg::CordisActDone(index, outcome) => {",
            "Msg::CordisRowInspect(index) => {",
            concat!("Msg::ErrorDial", "og(message)"),
        ),
        (
            // 落点③：两颗动作钮共用的前置闸第③道 = `CD:323/357/363` 那三发 `throw` 的原文
            // （「内核未连接。」），分叉经同一批 `catch` 才成的卡 ⇒ 钉主干那句中文原文。
            // 它是 **helper** 不是臂 ⇒ 起锚用签名、止锚用它自己尾上那枚在途旗（`body` 那把尺按
            // `\n    fn ` 收，`window` 这一把按显式止锚收 ⇒ 两把都出不了那颗函数的身体）。
            "fn cordis_take_row",
            "draft.busy.push(index);",
            "内核未连接。",
        ),
    ];

    #[test]
    fn wired_triggers_match_the_authorized_table_exactly() {
        let code = code();
        // 火口构造点的针（拆词写 ⇒ 本 mod 自己不许进那枚总数的账）。
        let wired = concat!("Msg::ErrorDial", "og(");
        // 正半：逐枚窗口 = 「那一臂真接了那颗卡」+「主干那句话原文还在」+「旧出口已拆」。
        for (start, end, trunk) in WIRED_TRIGGERS {
            // 批 CD1B（抢救）：窗口在 `window` 之后**再按臂边界收一刀** —— 只量「那一臂自己」。
            // 立这一刀的理由（三步实测 + 逐行等价性见 `tmp/cd1-report.md` §2-B）：上面那三行
            // `Msg::SkillPickerListed` 的终点锚是按 ERR2 当时的**紧邻下家**硬写成 `Msg::SchedulePanelToggle`
            // 的，批 CD1 在两臂之间插进 cordis 那一排臂 ⇒ 窗口从 34 行涨到 105 行、把 cordis 两臂里
            // 那三发**合法**的 `DIAG:` 取证圈了进来 = 假红（同一臂本体零 `push_log`，且
            // `Msg::ErrorDialog(` 的 `code_only` 枚数 CD1 接手前后都是 8 ⇒ 火口一枚没多接）。
            // 收了这一刀 ⇒ 这把白名单闸从此与「下一臂恰好是谁」解耦。前四行的窗口收刀前后逐字节等价
            // （38/38/32/32 行、`wired` 与 `trunk` 命中不变）⇒ 没有顺手放宽任何一档。
            let mut arm = window(&code, start, end);
            if let Some((only_arm, _)) = arm.split_once("\n            Msg::") {
                arm = only_arm;
            }
            assert!(
                arm.contains(wired),
                "{start} 那一臂没接错误卡 ⇒ 白名单登了表、产品码却没接（表与码两份真相）"
            );
            assert!(
                arm.contains(trunk),
                "{start} 那一臂丢了主干原文／形制针 {trunk} ⇒ 换形改了字（i18n 零新键的前提）"
            );
            assert!(
                !arm.contains("push_log"),
                "{start} 那一臂还留着 `DIAG:` 的旧形制 ⇒ 同一句话两条出口（第二份真相）"
            );
        }
        // 反半：总数硬闸（防「没授权的扩面」）。火臂那一枚 = `Msg::ErrorDialog(text) => {`。
        assert_eq!(
            code.matches(wired).count(),
            WIRED_TRIGGERS.len() + 1,
            "枚数 = 表长 + 火臂一枚（今天 11 = 10 + 1）：多一枚 = 没登表的扩面，少一枚 = 登了表没接线"
        );
        // 禁针（简报 §2-1 第三枚 = 一个字都不许动的那一发）：`Msg::SkillPickerPick` 的守卫 ② 是主干
        // `CP:420-424` 的**手写 `if`** ⇒ 面板保持开着、只把 `error.Text` 写上，**不 throw、不弹框**。
        // 把它接成错误卡 = 把主干「留在原地报错」改成「弹框」= 火接错地方（本刀最贵的那一缺陷）。
        let guard2 = window(
            &code,
            concat!("if let Some(draft) = self.skill_pi", "cker.as_mut() {"),
            concat!("skill_picker_close(&mut self.sk", "ill_picker);"),
        );
        assert!(
            guard2.contains("draft.error"),
            "守卫 ② 不再写面板内联那一格 ⇒ 主干 `CP:420-424` 的手写形制改了"
        );
        assert!(
            !guard2.contains(wired),
            "守卫 ② 被接成了错误卡 ⇒ 简报 §2-1 明令禁止的那一发（未授权扩面）"
        );
    }

    /// ⑨ 台账与字典：那一行**早在册**（本卡一行都不新登记，33/13/13/9/11 那组数字一枚不动），
    /// 且那一行的 `enter` 档与卡体「不写 `DefaultButton`」互为反证。
    /// 取窗口径逐字同 `goal_panel_tests` 的判据七（那张档表是**私有 mod 里的常量**，在本 mod
    /// 里读不到，只能按原文量）。
    /// 变异证明：给 `MODAL_LEDGER` 追一行本卡 ⇒ 第一把红；把那一行的 `enter` 改成 `Close` ⇒
    /// 第三把红。
    /// ⚠ RA-B 同批改口（2026-09-28）：主干撤三张 ⇒ 基数尺 33 → **30**（本卡那一行原样在册，
    /// `line: 13831` 一枚字未动）；同批还有 `goal_panel_tests` 与 `skill_picker_tests` 两把同源尺。
    #[test]
    fn the_ledger_row_was_already_there_and_gains_no_new_row() {
        let source = include_str!("main.rs");
        let ledger = window(source, "const MODAL_LEDGER:", "fn ledger_tally(");
        assert_eq!(
            ledger.matches(concat!("ModalLedgerRow ", "{")).count(),
            30,
            "档表张数漂了：本卡一票否决新登记（那一行早在册，见下）"
        );
        assert_eq!(
            ledger.matches(concat!("card: \"error-", "dialog\"")).count(),
            1,
            "本卡在册且只在册一行"
        );
        assert_eq!(
            ledger
                .matches(concat!(
                    "line: 13831, card: \"error-dialog\", enter: ModalResu",
                    "lt::None"
                ))
                .count(),
            1,
            "那一行被改过 ⇒ `enter = None` 与卡体「不写 DefaultButton」的判据脱钩"
        );
    }
}

#[cfg(test)]
mod session_feedback_tests {
    //! 批 SFB1（#158 卡 B「会话反馈」，槽位键 = 宿主的第六格）的自家锁 —— **本 mod 由 SFB2
    //! 补落**：SFB1 在产品码四处注释里点名了「`session_feedback_tests` 那两把互斥锁」与「基数 7
    //! 那把尺」（`SESSION_FEEDBACK_LABELS` 的 doc / `session_feedback_close` 的 doc /
    //! `Msg::SessionFeedbackToggle` 开臂的注释 / 状态格 `session_feedback` 的注释），人却死在
    //! 150 轮上限上、一个 `mod` 都没落下 ⇒ 那四处注释当时是**假账**（注释指着不存在的尺）。
    //! SFB2 报告 §1 里那一行因此从「纯悬空」改成「已成形（SFB2 补齐三把尺）」。
    //! 三把尺的判据**全部取自已落地的产品码**与 ERR1/PS1 的兄弟先例，本 mod 一件行为都不新增、
    //! 一枚字面量都不新造 ⇒ 不是「为了让 match 齐全而编造行为」。
    //! 三条口径逐字同 `error_dialog_tests`：① 全文件计数型针一律 `concat!` 拆词（FX1：整串写出来
    //! 就把本行数进产品码）且过 crate 根的 [`code_only`]；② 能打在形制上的不降级成注释锁；
    //! ③ 取窗锚一律本卡独有的臂名，一把窗只量一件事（锚都不写 `fn ` 前缀，也不把兄弟 mod 的
    //! 取窗锚在本 mod 的注释里写全 —— MS1 §M-2 / PS1 §2 的自计数与抢窗两条坑）。
    use super::*;

    /// 取窗：`start` 之后、`end` 之前那一段（两枚锚都不在段内 ⇒ 计数不会把锚行自己数进去）。
    fn window<'a>(source: &'a str, start: &str, end: &str) -> &'a str {
        let (_, rest) = source
            .split_once(start)
            .unwrap_or_else(|| panic!("取窗锚 {start} 在文件里找不到"));
        match rest.split_once(end) {
            Some((body, _)) => body,
            None => panic!("取窗锚 {start} 之后找不到 {end}"),
        }
    }

    /// 「基数 7」那把尺（SFB1 在 `SESSION_FEEDBACK_LABELS` 的 doc 里点的名）：标签列与线值列
    /// **同长**、尾项都是「其他 / `other`」⇒ 两张表之间唯一的桥是下标，谁重排谁红。
    /// 这一把读的是**常量**（不打源码针）⇒ 与 `kernel.rs` 自家那把 `len() == 7` 一左一右。
    #[test]
    fn the_two_category_tables_stay_the_same_length() {
        assert_eq!(
            SESSION_FEEDBACK_LABELS.len(),
            7,
            "标签列的基数漂了 ⇒ 主干 `MW:16958` 那张七项表不再是这一列"
        );
        assert_eq!(
            SESSION_FEEDBACK_CATEGORIES.len(),
            SESSION_FEEDBACK_LABELS.len(),
            "两张表长度不等 ⇒ 提交那一发按 `SESSION_FEEDBACK_CATEGORIES[i]` 跳线值会错位"
        );
        assert_eq!(SESSION_FEEDBACK_CATEGORIES.last().copied(), Some("other"));
        assert_eq!(SESSION_FEEDBACK_LABELS.last().copied(), Some("其他"));
    }

    /// 反向半边（SFB1 在 `session_feedback_close` 的 doc 里点名的那把）：本族收点的**枚数**实测
    /// **18**，且十四发全住在「开另一张层」那一臂里 —— 逐臂验名，不降级成「只数一个数」。
    /// 账目 = 十四发兄弟层开臂（换会话 `Nav` / 文件菜单 / 输入区选择器 / 消息详情 / 跨会话召回 /
    /// 任务清单 / 轨迹 / 计划 / 目标 / 工作区菜单 / chip 菜单 / 分支后换会话 / 技能选择器（批 SKP1）/
    /// Cordis 面板（批 CD1））+ 本卡自己三发
    /// （「已开 ⇒ 收」/「取消」/「提交先摘草稿」）+ Esc 那一档一发。
    /// ⚠ **不含**错误弹层：ERR1 已验收「它不进本卡的互斥集合」⇒ 上面十四发里一臂都不许是错误卡
    ///   的开臂，本把也不给它加收点（SFB2 指令的排除条，与 §3 的保真审计同一条账）。
    /// 复跑：`grep -c 'session_feedback_close(&mut self\.session_feedback);' src/main.rs` ⇒ 18，
    /// 且 18 发全在产品码（`grep -cE '^[[:space:]]*//.*session_feedback_close' ` ⇒ 0）。
    /// 批 SKP1（#158 卡 A）：技能选择器那张入同级 mesh、开臂收这张一次 ⇒ 16→**17**。
    /// 批 CD1（#158 面 B/C）：Cordis 面板那张入同级 mesh、开臂收这张一次 ⇒ 17→**18**。
    /// 变异证明：摘掉任意一臂里那一发 ⇒ 本把红（SFB2 报告 §4 的变异轮实测）。
    #[test]
    fn every_sibling_open_arm_retires_this_card() {
        let source = include_str!("main.rs");
        let needle = concat!(
            "session_feedback_close(&mut self.",
            "session_feedback);"
        );
        let closes = code_only(source).matches(needle).count();
        assert_eq!(
            closes, 18,
            "会话反馈那一格的互斥枚数漂了（今数 {closes} 发）：少一处 = 开别张层时那张卡还挂着，\
             多一处 = 有人在往别的状态上收它"
        );
        for (start, end) in [
            (
                concat!("Msg::Nav(", "page) => {"),
                concat!("Msg::Scheme(", "scheme) => {"),
            ),
            (
                concat!("Msg::FileMenuToggle(", "seq, index) => {"),
                concat!("Msg::FileMenu", "Close => {"),
            ),
            (
                concat!("Msg::SelectorToggle(", "kind) => {"),
                concat!("Msg::Selector", "Close => {"),
            ),
            (
                concat!("Msg::DetailsToggle(", "key) => {"),
                concat!("Msg::Details", "Close => {"),
            ),
            (
                concat!("Msg::SessionRefList(", "items) => {"),
                concat!("Msg::CloseSession", "Refs => {"),
            ),
            (
                concat!("Msg::TodosPanelToggle", " => {"),
                concat!("Msg::TodosPanel", "Close => {"),
            ),
            (
                concat!("Msg::TrajectoryPanelToggle", " => {"),
                concat!("Msg::TrajectoryPanel", "Close => {"),
            ),
            (
                concat!("Msg::SchedulePanelToggle", " => {"),
                concat!("Msg::SchedulePanel", "Close => {"),
            ),
            (
                concat!("Msg::GoalPanelToggle", " => {"),
                concat!("Msg::GoalPanel", "Close => {"),
            ),
            (
                concat!("Msg::WorkspaceMenuToggle(", "id) => {"),
                concat!("Msg::WorkspaceMenu", "Close => {"),
            ),
            (
                concat!("Msg::DockMenuToggle(", "id) => {"),
                concat!("Msg::DockMenu", "Close => {"),
            ),
            (
                concat!("Msg::Branched(Ok((rows, child, ", "title))) => {"),
                concat!("Msg::Branched(Err(", "error)) =>"),
            ),
        ] {
            let arm = window(source, start, end);
            assert!(
                arm.contains(needle),
                "这一臂没写明收会话反馈那一格（同刻会两张同屏）：{start:?}"
            );
        }
    }

    /// 正向半边：开这张先收那十发兄弟**壳**，dock 那一枚走**借道**（`tests/dock_chrome.rs` 那把
    /// 19 枚的闸在白名单外 ⇒ 借用现成臂、不改那一文件、不新增计数，SFB2 报告 §1「不欠孪生」）；
    /// 摘会话 id 进草稿格那一发**只此一处**（守卫那一档一个状态都不动 = 主干连对话框都没建）；
    /// 卡上那颗「记录」与 Enter 都汇进同一枚提交臂（唯一写口，出口那一发不在卡上）。
    /// 变异证明：把开臂里任意一发兄弟壳换成直写 `= None` ⇒ 本把红；给守卫那一档补一发置格 ⇒
    /// 本把红（那一档置格就是把主干没有的行为自造出来）。
    #[test]
    fn this_card_opens_after_retiring_every_sibling_layer() {
        let source = include_str!("main.rs");
        let open = window(
            source,
            concat!("Msg::SessionFeedbackToggle", " => {"),
            concat!("Msg::SessionFeedbackClose", " => {"),
        );
        for shell in [
            "file_menu_close",
            "message_details_close",
            "session_ref_list_close",
            "workspace_menu_close",
            "todos_panel_close",
            "selector_close",
            "goal_panel_close",
            "danger_confirm_close",
            "schedule_panel_close",
        ] {
            assert!(
                open.contains(&format!("{shell}(&mut self.")),
                "开这张没走 {shell} 那一发壳"
            );
        }
        // 轨迹那一发是**壳方法**（`self.trajectory_panel_close()`，批 M4 的形制），不是自由函数 ⇒
        // 单独一条判据，别拿 `(&mut self.` 那半截去量它。
        assert!(
            open.contains(concat!("self.", "trajectory_panel_close()")),
            "开这张没收轨迹那一层（批 M4 那把壳方法）"
        );
        assert!(
            open.contains(concat!("self.update(Msg::DockMenu", "Close, context);")),
            "dock 那一枚不再借道现成臂 ⇒ 要么有人直写壳（白名单外那把 19 枚的闸会漂），\
             要么这一发被摘掉（同刻两张同屏）"
        );
        // 置格那一发全卡只此一处（守卫那一档不许动状态）。
        assert_eq!(
            open.matches(concat!("self.session_feedback = ", "Some(")).count(),
            1,
            "开臂里置格那一发漂了 ⇒ 守卫那一档开始动状态（主干那一发连对话框都没建）"
        );
        // 摘 `sid` 在开卡之前（主干 `Volatile.Read` 那一行的分叉等价物）：草稿格构造读的是
        // `self.active`，提交那一臂只读草稿格、不回查 `self.active`。
        assert!(open.contains(concat!("session_id: self.", "active.clone()")));
        let submit = window(
            source,
            concat!("Msg::SessionFeedbackSubmit", " => {"),
            concat!("Msg::SessionFeedbackSent(", "outcome) => {"),
        );
        assert!(
            !submit.contains("self.active"),
            "提交那一臂回查了 `self.active` ⇒ 卡活着时换会话这一条主干没有的路被造出来了"
        );
        assert!(submit.contains(concat!("run_session_feedback_", "record(")));
    }

}

/// 台账 #158 卡 A（批 SKP1）：**技能选择器 A 面**的源锁 + 行为锁。
/// 母本 = `MainWindow.Capabilities.cs:388-441`（`ShowCapabilitySkillsAsync`）+ 那台
/// `CapabilityDialog` 工厂（`:106-112`）+ 入口那颗 `SkillsMenuItem`（`:96`）。
/// 本 mod 只钉八件：主干时序（三发过期点检各走自己的路）/ 同级 mesh 的两个方向 /
/// 遮罩族别（`ContentDialog` 一族，无 light-dismiss）/ 收法壳 / 键盘三档与报位 /
/// 卡面几何与件数 / 入口那一颗的真名与列序 / 台账与 i18n 一个都不新登记。
/// 凡拿源码当证据的串一律 `concat!` 拆词（MS1 §M-2 的自计数坑：本 mod 自己就是
/// `include_str!("main.rs")` 的一枚读者）。
/// 批 CD1B（抢救刀）补档：批 CD1 落了 783 行产品码，**但没有写这张卡自己的锁** —— 它自己在四处
/// doc 注释里点了名的 `cordis_panel_tests`（`cordis_panel_close` 的 doc、壳字段的 doc、
/// `publish_keys` 那一发的注释、开臂的注释）当天是**悬空引用**。本 mod 把那些引用兑现成尺：
/// 收点形制与枚数 / 反向半边逐臂验名 / 键盘三档与第八格 / 四条锁死端点 / 本卡不许 fire 错误卡 /
/// RPC 只走 `kernel.rs` 的构造器。三条口径逐字同 `error_dialog_tests`：① 全文件计数型针一律
/// `concat!` 拆词（FX1/MS1 §M-2：整串写出来就把本行数进产品码，那十八把计数闸会当场假红）；
/// ② 反向哨兵（数 `== 0` 那种）**不过** `code_only` —— 注释里提一次正是它们要响的；
/// ③ 取窗一律按**臂边界**收（`fn arm`），免得重演 ERR2 那把白名单被「下一臂是谁」牵着走的假红。
/// 变异证明（红态原文见 `tmp/cd1-report.md` §5-CD1B）：摘掉开臂里那一发 `cordis_panel_close` ⇒ 判据①
/// 与判据②同时红；把 `publish_keys` 那一发摘掉 ⇒ 判据③红；把宿主第八格摘掉 ⇒ 判据③的末位那把红。
#[cfg(test)]
/// 批 CD3B（简报 §5.1 / 报告 §2-A 末行 + §5.1）：刀 3 那套「一次一卡 + 提交闸 / resolved 补登记 /
/// 非模态浮卡接线」的**三把新尺**。CD3 的生产码全写完且编译干净，但预算烧在源码锁针脚上 ⇒ 这三枚
/// 是**真没写**（不是「写了没跑」）。判据一律**等号形**（不用 `>=`）；视图片那把（尺③）的所有锚
/// `concat!` 拆词 ⇒ 本 mod 自己的引用不进 `code_only` 那本账（FX1 惯例），且 `code_only` 已剥掉
/// 那些提过函数名的注释，取窗不会开到注释上。
mod cordis_approval_tests {
    use super::*;

    /// 一条待审记录：只有 `request_id` 参与本族的每一道判据，其余六格是卡面文案的原料 ⇒ 逐格给
    /// **非空且相同**的值，这样「两发只差 id」这一档不会被别的键意外区分开。
    fn pending(request_id: &str) -> CordisPendingApproval {
        CordisPendingApproval {
            request_id: request_id.to_string(),
            agent_id: "agent-1".to_string(),
            plugin_id: "plugin-1".to_string(),
            package_id: "pkg-1".to_string(),
            mode: "run".to_string(),
            name: "那颗插件".to_string(),
            purpose: "跑一发看看".to_string(),
        }
    }

    /// 取窗：`start` 之后到 `stop` 之前（`code_only` 保留了换行与缩进 ⇒ 4 空格缩进的 `fn` 是合法
    /// 下锚）。锚一律拆词写 ⇒ 本 mod 不进自己的账。
    fn fn_window(haystack: &str, start: &str, stop: &str) -> String {
        let (_, rest) = haystack
            .split_once(start)
            .unwrap_or_else(|| panic!("取窗锚 {start} 在文件里找不到"));
        match rest.split_once(stop) {
            Some((window, _)) => window.to_string(),
            None => rest.to_string(),
        }
    }

    /// **尺①**（简报 §5.1-①）：四发不同 id 的 `request-run` ⇒ 屏幕上永远只有一张，其余排队；
    /// 重复 id 一格都不涨；`take_next` 那道**并列双尺**（在途 / 已有一张亮着）各自单独拦得住；
    /// 闸一松按 FIFO 推下一张。变异证明：摘 `take_next` 首句的 `return false` ⇒ 本把红。
    #[test]
    fn only_one_card_is_live_and_the_submit_gate_blocks_the_next() {
        let mut ledger = CordisApprovalLedger::default();
        for id in ["r-1", "r-2", "r-3", "r-4"] {
            assert!(
                cordis_remember_approval(&mut ledger, pending(id)),
                "{id} 第一次入场就被去重挡回"
            );
        }
        assert_eq!(ledger.seen.len(), 4, "去重集少记一笔 ⇒ 同 id 的重复帧以后还能入场");
        assert_eq!(ledger.queue.len(), 4, "四发都该排着（入队 ≠ 点亮）");
        assert_eq!(ledger.active, None, "入队就点亮 ⇒ 主干 `ShowNextCordisApproval` 那道闸没了");
        assert_eq!(ledger.submitting, false, "新建的账本不该自带在途");

        // 重复帧（`CD:127` 那颗 `seen.Add`）⇒ 不入队、不点亮。
        assert!(
            !cordis_remember_approval(&mut ledger, pending("r-2")),
            "同 id 的第二发没被去重挡回"
        );
        assert_eq!(ledger.queue.len(), 4, "被挡回那一发还是占了队列一格");
        assert_eq!(ledger.seen.len(), 4, "被挡回那一发重复记了账");

        // 点亮第一张（`CD:516` 出队）。
        assert!(ledger.take_next(), "队里有卡却不亮");
        assert_eq!(ledger.active, Some(pending("r-1")), "亮的不是队首那张（FIFO 序变了）");
        assert_eq!(ledger.queue.len(), 3, "点亮那一发多消耗了后面的卡");

        // 并列双尺 (a)：已有一张亮着 ⇒ 再点也不动（主干 `CD:512` 那句守卫的另一半）。
        assert!(!ledger.take_next(), "已有一张亮着还弹第二张 ⇒ 同屏两张卡");
        assert_eq!(ledger.active, Some(pending("r-1")), "第二次尝试改写了在屏那张");
        assert_eq!(ledger.queue.len(), 3, "第二次尝试多出了队");

        // 并列双尺 (b)：提交闸（按下即锁 = `CD:538-542` 那四颗一起变灰）。`active` 单独清空 ⇒
        // 这一发只测闸门那一半，不许靠「已有一张」蒙过去。
        ledger.submitting = true;
        ledger.active = None;
        assert!(!ledger.take_next(), "在途还弹下一张 ⇒ 用户能在两条 RPC 之间点第二颗");
        assert_eq!(ledger.active, None, "提交闸失效：在途期间点亮了新卡");
        assert_eq!(ledger.queue.len(), 3, "在途那一发把队首消费掉了却没点亮");
        ledger.submitting = false;
        assert!(ledger.take_next(), "闸松了还不推下一张 ⇒ 队列永远停在第二格");
        assert_eq!(ledger.active, Some(pending("r-2")), "闸松后推上去的不是第二张");
        assert_eq!(ledger.queue.len(), 2, "队列长度漂了");
    }

    /// **尺②**（简报 §5.1-②）：`request-run-resolved` 那发的**全部**状态动作 = 在审那张掉队 +
    /// **主动补登记 `seen`** + 末尾自动推下一张并复位提交闸，且**之后同一 id 的 `request-run`
    /// 永不回场**（`CD:164` 的不对称）；空串那一发一个字都不写（主干整段在 `if (requestId.Length > 0)` 里）。
    /// 变异证明：从 `cordis_drop_resolved` 里删掉 `seen` 那一发 ⇒ 本把红。
    #[test]
    fn a_resolved_request_leaves_the_queue_and_never_returns() {
        let mut ledger = CordisApprovalLedger::default();
        for id in ["r-1", "r-2", "r-3"] {
            cordis_remember_approval(&mut ledger, pending(id));
        }
        assert!(ledger.take_next(), "前置条件：第一张亮着");
        ledger.submitting = true; // 模拟按下那颗：闸在途、四颗钮变灰
        cordis_drop_resolved(&mut ledger, "r-1");

        assert_eq!(ledger.seen.len(), 3, "去重集格数漂了");
        assert_eq!(
            ledger.seen.iter().filter(|seen| *seen == "r-1").count(),
            1,
            "「r-1」在去重集里的记录数不对（0 = 之后回场没闸，2 = 重复登记）"
        );
        assert_eq!(
            ledger.active,
            Some(pending("r-2")),
            "收掉在审那张后没自动推下一张（`CD:171-178` + 末尾那一句 take_next）"
        );
        assert_eq!(ledger.submitting, false, "收卡不复位提交闸 ⇒ 剩下两张的钮永久变灰");
        assert_eq!(ledger.queue.len(), 1, "队列里同 id 的残留没筛掉");

        // **永不回场**：已 resolved 的 id 第二发 `request-run` 必须被挡（主干 resolved 里那句
        // 主动 `Add` 就是为了挡这一发；不补登记 ⇒ 卡会在服务端已经处理完之后重新亮起来）。
        assert!(
            !cordis_remember_approval(&mut ledger, pending("r-1")),
            "已 resolved 的 id 又能入场 ⇒ 那张卡会重新亮起来"
        );
        assert_eq!(ledger.queue.len(), 1, "被挡回那一发还是挤进了队列");
        assert_eq!(ledger.seen.len(), 3, "被挡回那一发重复记了账");
        assert_eq!(ledger.active, Some(pending("r-2")), "重复帧改写了在屏那张");

        // 变异探针 P3 逼出来的**那一档真判据**（P3 第一发把 `seen.push` 摘掉却整把绿 ⇒ 反证本尺
        // 之前只测到「`request-run` 自己记的那笔账」，没测到 `CD:164` 那次**主动补登记**）：
        // 主干 resolved 里那句 `Add` 之所以不是冗余，是因为存在 `requestId` **从没进过 `seen`** 的
        // 帧 —— 在别处结完账（in-row 那四颗、另一台客户端）、或壳漏掉了建卡那一发。那一发迟到
        // 的 `request-run` 才是 `CD:164` 唯一挡得住的东西。
        let mut late = CordisApprovalLedger::default();
        cordis_drop_resolved(&mut late, "r-7");
        assert_eq!(
            late.seen.len(),
            1,
            "resolved 那一发没主动补登记（`CD:164`）⇒ 同 id 的迟到建卡帧没了闸"
        );
        assert_eq!(late.queue.len(), 0, "resolved 凭空造了一格队列位");
        assert_eq!(late.active, None, "resolved 凭空点亮了一张卡");
        assert!(
            !cordis_remember_approval(&mut late, pending("r-7")),
            "已经结完账的 id 靠补登记之外的手段又入了场 ⇒ 那张卡会重新亮起来"
        );
        assert_eq!(late.queue.len(), 0, "被挡回那一发挤进了队列");
        assert_eq!(late.seen.len(), 1, "被挡回那一发重复记了账");

        // 空串：主干 `if (requestId.Length > 0)` 整段跳过 ⇒ 三格一格都不许动（末尾那发重拉在 `if`
        // 外面，由调用方发 ⇒ 归尺③那把接线锁管）。
        let mut quiet = CordisApprovalLedger::default();
        cordis_remember_approval(&mut quiet, pending("r-9"));
        quiet.submitting = true;
        cordis_drop_resolved(&mut quiet, "");
        assert_eq!(quiet.seen.len(), 1, "空 requestId 也被登记 ⇒ 之后真那一发进不了场");
        assert_eq!(quiet.queue.len(), 1, "空 requestId 把队列筛掉了");
        assert_eq!(quiet.submitting, true, "空 requestId 复位了提交闸");
        assert_eq!(quiet.active, None, "空 requestId 点亮了卡");
    }

    /// **尺③**（简报 §5.1-③，视图片接线锁）：卡体四颗钮各**恰好一枚** UIA id、`320`/`520`、
    /// `S8`、右对齐、四颗共读**同一格** `!submitting`；叠层入树序 `palette < approval <
    /// cordis-approval < file-menu`；**非模态反证** = `app_modal_host` / `ContentDialog` /
    /// `ModalLedgerRow` / `PaletteClose` 四枚「不许出现」。
    #[test]
    fn the_float_card_is_wired_in_order_and_stays_non_modal() {
        let code = code_only(include_str!("main.rs"));
        // ---- 卡体那一扇 ----
        let panel = fn_window(&code, concat!("fn cordis_approval_", "panel("), "\n    fn ");
        for id in [
            concat!("CordisApprove", "Allow"),
            concat!("CordisApprove", "Once"),
            concat!("CordisApprove", "Future"),
            concat!("CordisApprove", "Decline"),
        ] {
            assert_eq!(
                panel.matches(id).count(),
                1,
                "卡上那颗钮的 UIA id 数目不对（0 = 键名被换掉，2 = 手搓了第二颗）：{id}"
            );
        }
        assert_eq!(
            panel.matches(concat!("CordisApproval", "Card")).count(),
            1,
            "卡体那一枚 UIA id 不唯一（主干 `CD:491`；in-row 那四颗复用同名归 `cordis_panel_tests` 那族）"
        );
        assert_eq!(
            panel.matches(concat!("min_width(", "320.0)")).count(),
            1,
            "卡宽下限不是 `CD:486` 那颗 320（面 B 那台是 300/480，两型不许折成一档）"
        );
        assert_eq!(
            panel.matches(concat!("max_width(", "520.0)")).count(),
            1,
            "卡宽上限不是 `CD:487` 那颗 520"
        );
        assert_eq!(
            panel
                .matches("let enabled = !self.cordis_approvals.submitting;")
                .count(),
            1,
            "四颗钮不再共读那一格提交闸（各写各的 = 四颗能点出四种在途）"
        );
        assert_eq!(
            panel.matches(".is_enabled(enabled)").count(),
            4,
            "四颗钮里有人不读那道闸"
        );
        assert_eq!(
            panel
                .matches("horizontal_alignment(HorizontalAlignment::Right)")
                .count(),
            1,
            "按钮行不右对齐（主干 `CD:466` 那一行）"
        );
        // 间距 = `S8` 一族；简报 §3.1 已采纳 CD3 的实测：四颗钮在主干**不带** `Style` 键 ⇒
        // CD4 §4 那套 `CompactButtonStyle` / `Sp10` 不成立 ⇒ 这里钉的是实测口径 + 反证。
        assert!(panel.contains("spacing(space::S8)"), "卡里那几行没有 S8 间距");
        assert!(
            !panel.contains(concat!("Compact", "ButtonStyle")),
            "卡上冒出了主干没有的 Style 键（CD4 §4 那份描述与主干 `427-495` 不符）"
        );

        // ---- 叠层入树序（非模态：就住在 `"approval"` 之后、`"file-menu"` 之前）----
        let page = fn_window(&code, concat!("fn chat_", "page("), concat!("fn command_", "palette("));
        let at = |needle: &str| {
            page.find(needle)
                .unwrap_or_else(|| panic!("chat_page 里找不到 {needle}"))
        };
        let palette = at(concat!("KeyedView::new(", "\"palette\""));
        let approval = at(concat!("KeyedView::new(", "\"approval\""));
        let cordis = at(concat!("\"cordis-", "approval\","));
        let file_menu = at(concat!("\"file-", "menu\","));
        assert!(palette < approval, "既有顺序锁红了：审批卡不再排在补全浮层之后");
        assert!(approval < cordis, "刀 3 那枚浮卡没紧跟在面 B 的审批卡之后入树");
        assert!(
            cordis < file_menu,
            "浮卡排到了交付物菜单之后 ⇒ 被那张系统级菜单压住（主干 `CD:496-500` 是压在 `ApprovalHost` **之上**）"
        );
        assert_eq!(
            page.matches(concat!("\"cordis-", "approval\",")).count(),
            1,
            "那一格在 chat_page 里出现了第二处（= 同一张卡入树两遍）"
        );
        assert!(
            page.contains("if let Some(approval) = self.cordis_approvals.active.as_ref()"),
            "浮卡的显隐不再只从 `active` 那一格派生（主干 `CD:514` 那句 `Collapsed` 的同口径）"
        );

        // ---- 非模态反证：这四枚**不许**出现在卡体那一扇、也不许出现在那一格的入树语句里。
        // 进了 `app_modal_host` 那八格（互斥）/ 起了遮罩 / 登记进 mutex 台账 / 被 Esc 那道关一起
        // 收掉，就都不是主干那句「与 `ApprovalHost` 同屏并存」了。
        let push = fn_window(
            &page,
            concat!("\"cordis-", "approval\","),
            concat!("\"file-", "menu\","),
        );
        assert!(
            push.contains("self.cordis_approval_panel(approval, context, p)"),
            "那一格没接上卡体本体"
        );
        for forbidden in [
            concat!("app_modal_", "host"),
            concat!("Content", "Dialog"),
            concat!("Modal", "LedgerRow"),
            concat!("Palette", "Close"),
        ] {
            assert!(
                !panel.contains(forbidden) && !push.contains(forbidden),
                "浮卡被接成了模态宿主 / 遮罩 / 互斥台账 / Esc 关（未授权扩面）：{forbidden}"
            );
        }
    }
}

#[cfg(test)]
mod cordis_panel_tests {
    use super::*;

    fn code() -> String {
        code_only(include_str!("main.rs"))
    }

    /// 臂窗口：`start` 之后到**下一发 12 空格缩进的臂名**为止（两枚锚都不在段内 ⇒ 计数不会把
    /// 锚行自己数进去）。批 CD1B 起本族所有取窗都走这一把，不再拿「紧邻下家」当终点锚。
    fn arm<'a>(source: &'a str, start: &str) -> &'a str {
        let (_, rest) = source
            .split_once(start)
            .unwrap_or_else(|| panic!("取窗锚 {start} 在文件里找不到"));
        match rest.split_once("\n            Msg::") {
            Some((body, _)) => body,
            None => rest,
        }
    }

    /// 本卡收点那一发（拆词写 ⇒ 本 mod 不进那枚总数的账）。
    fn close_needle() -> String {
        concat!("cordis_panel_close(&mut self.cordis_", "panel);").to_string()
    }

    /// 判据①：这张卡**只**通过自己的壳退役（17 发 = 十四发同级开臂反向互斥 + 开臂瞬关 +
    /// 关臂 + Esc 档），且全文件**零**直写赋值形。
    /// 变异证明：摘掉任意一臂里那一发 ⇒ 本把红；直写 `self.cordis_panel = None;` ⇒ 第二把红。
    #[test]
    fn the_card_retires_only_through_its_shell_form() {
        let code = code();
        let closes = code.matches(&close_needle()).count();
        assert_eq!(
            closes, 17,
            "收点枚数漂了（今数 {closes} 发）：少一处 = 开别张层时这张卡还挂着，多一处 = 有人在往\
             别的状态上收它。17 发 = 十四发同级开臂 + 开臂瞬关 + 关臂 + Esc 档"
        );
        assert_eq!(
            code.matches(concat!("self.cordis_panel = No", "ne;")).count(),
            0,
            "出现了直写赋值形 ⇒ 形制交回「改动者自己去数」，上面那十七发的计数闸就假绿了"
        );
        // 壳本体的两档返回值（Esc 档据此决定要不要吞键，口径同 `skill_picker_close`）。
        let mut open: Option<CordisPanelDraft> = Some(CordisPanelDraft::default());
        assert!(cordis_panel_close(&mut open), "开着却报「这一发不是这张卡吃的」");
        assert_eq!(open, None);
        assert!(
            !cordis_panel_close(&mut open),
            "已经关着还回 true ⇒ 第二次收会误吞底下那一层的键"
        );
    }

    /// 判据②（反向半边）：十四发同级臂每一发都写明收这张卡 —— 这张卡进了同级 mesh，
    /// 「同刻至多一层」才对得起主干那颗应用级 `ContentDialog`（`CD:657` + `CP:111`）。
    #[test]
    fn every_sibling_open_arm_retires_this_card() {
        let code = code();
        let needle = close_needle();
        for start in [
            "Msg::Nav(page) => {",
            "Msg::FileMenuToggle(seq, index) => {",
            "Msg::SelectorToggle(kind) => {",
            "Msg::DetailsToggle(key) => {",
            "Msg::SessionRefList(items) => {",
            "Msg::TodosPanelToggle => {",
            "Msg::TrajectoryPanelToggle => {",
            "Msg::SessionFeedbackToggle => {",
            "Msg::SkillPickerToggle => {",
            "Msg::SchedulePanelToggle => {",
            "Msg::GoalPanelToggle => {",
            "Msg::WorkspaceMenuToggle(id) => {",
            "Msg::DockMenuToggle(id) => {",
            "Msg::Branched(Ok((rows, child, title))) => {",
        ] {
            assert!(
                arm(&code, start).contains(&needle),
                "这一臂没写明收 Cordis 面板那张（同刻会两张同屏）：{start:?}"
            );
        }
    }

    /// 判据③：键盘三档各一枚、`publish_keys` 并进浮层槽、宿主那一格里第八格在册且**压在技能之后**。
    #[test]
    fn the_three_keyboard_tiers_and_the_eighth_host_cell_are_wired() {
        let code = code();
        for tier in [
            concat!("Msg::PaletteClose ", "if self.cordis_panel.is_some()"),
            concat!("Msg::PaletteMove(_) ", "if self.cordis_panel.is_some()"),
            concat!("Msg::PaletteAccept ", "if self.cordis_panel.is_some()"),
            concat!("|| self.cordis_panel.", "is_some()"),
        ] {
            assert_eq!(
                code.matches(tier).count(),
                1,
                "这一档漂了（一枚不多、一枚不少）：{tier:?}"
            );
        }
        let host = arm_raw_cell();
        let skill = host
            .find(concat!("\"skill-", "picker\""))
            .expect("宿主少了技能选择器那一格");
        let cordis = host
            .find(concat!("\"cordis-", "panel\""))
            .expect("宿主少了 Cordis 面板那一格");
        assert_eq!(
            host.matches(concat!("\"cordis-", "panel\"")).count(),
            1,
            "槽位枚数变了：一处不多一处不少（不开时那棵节点根本不生成）"
        );
        assert!(
            skill < cordis,
            "Cordis 那张不再末位 ⇒ 它压不住技能选择器那张（主干那颗同样是应用级末位）"
        );
        assert!(
            host.contains(concat!("if self.cordis_panel.is_some()", " {")),
            "显隐判据没了 ⇒ 关着的时候也会画出一层遮罩"
        );
    }

    /// 宿主那一格（`fn app_modal_host(` → `fn error_dialog_layer(`）：口径逐字同
    /// `error_dialog_tests` 那把入树尺 —— 它量的是**原文**（注释不参与，那两枚锚本就住在码里）。
    fn arm_raw_cell() -> String {
        let source = include_str!("main.rs");
        source
            .split_once("fn app_modal_host(")
            .expect("找不到宿主")
            .1
            .split_once("fn error_dialog_layer(")
            .expect("宿主之后找不到错误卡那一层")
            .0
            .to_string()
    }

    /// 判据④：四条锁死端点在**全文件原文**里恒为 0 命中（PL1 §4 报警尺⑤；反向哨兵**不过**
    /// `code_only` ⇒ 注释里提一次也要响，所以这一把的针一律拆词写）。
    #[test]
    fn the_four_locked_cordis_endpoints_never_appear() {
        let raw = include_str!("main.rs");
        for forbidden in [
            concat!("dynamicCordisRunner/", "invoke"),
            concat!("dynamicCordisRunner/", "resolveInspectQuery"),
            concat!("dynamicCordisRunner/", "reportClientGuardFailure"),
            concat!("dynamicCordisRunner/", "reportRenderFailure"),
        ] {
            assert_eq!(
                raw.matches(forbidden).count(),
                0,
                "锁死端点漏进来了（架构限制，不是遗漏）：{forbidden:?}"
            );
        }
        // 正半：本刀唯一允许的那一发 = `inventory`，而且**只**由 `kernel.rs` 的构造器发出去。
        assert_eq!(
            code().matches(concat!("cordis_inventory(", ")")).count(),
            1,
            "`inventory` 那一发不再只经由 `Shell::run_cordis_inventory` 发出 ⇒ 出现第二份出口"
        );
    }

    /// 函数体窗口：`start` 之后到**下一发四空格缩进的 `fn `** 为止（量 helper 用这一把；
    /// `arm` 那一把只适用于 reducer 臂，拿它量 fn 体会一路铺到文件末尾）。
    fn body<'a>(source: &'a str, start: &str) -> &'a str {
        let (_, rest) = source
            .split_once(start)
            .unwrap_or_else(|| panic!("取窗锚 {start} 在文件里找不到"));
        match rest.split_once("\n    fn ") {
            Some((b, _)) => b,
            None => rest,
        }
    }

    /// 判据⑤：本卡**不许** fire 错误弹层 ⇒ 名单里那些臂与 helper 全部只落一行 `DIAG:` 取证。
    /// 批 CD2 抬账：追加 inspect 那两发臂的字面量与那颗 RPC 腿（CS1 §1.6 D-9①）。
    /// 批 CD3B 抬账：刀 3 那两枚新臂一并纳进这道反证。
    /// **批 ERR3 收窄（主代理授权 = 本简报 §2/§3）**：那把白名单闸从「本族不在表里」改成「本族在
    /// 表里、且只有登了表的那三枚落点许 fire」⇒ 本名单**摘掉**三枚已接火的：
    /// `Msg::CordisActDone`（`CD:784`+`CD:868`）、`Msg::CordisApprovalDone`（`CD:615`）、
    /// `fn cordis_take_row`（`CD:323/357/363` 那三发 `throw` 的卡身）。
    /// ⚠ **保留**的才是主干静默那一档的反证，一枚都不许跟着摘：
    /// `Msg::CordisPanelToggle`/`PanelClose`/`Inventory`（`CD:227-230` 与 `CD:641` 全静默）、
    /// `Msg::CordisRowRunStop`/`RowRemove`（前置闸住在 helper 里，臂本体不出声）、
    /// `Msg::CordisRowInspect`/`ClientCode` + `fn run_cordis_client_code`（`CD:926-934` 那个
    /// `catch` 把 `ex.Message` **画进折叠子区并照样点亮**，不是卡 ⇒ 报告 §2-C 末段）、
    /// `Msg::CordisApprove`（`CD:556-558` 那三把并列尺是**静默 return**）与
    /// `fn run_cordis_approval`（`CD:630-634` 的 `TryCordisResolveAsync` 吞 ⇒ 分叉那三枚
    /// `let _ = kernel.call(..)` 一个字都不许改成弹卡）。判据整体删除 = 退回。
    #[test]
    fn the_card_never_fires_the_error_dialog_channel() {
        let code = code();
        let wired = concat!("Msg::ErrorDial", "og(");
        for start in [
            "Msg::CordisPanelToggle => {",
            "Msg::CordisPanelClose => {",
            "Msg::CordisInventory(outcome) => {",
            "Msg::CordisRowRunStop(index) => {",
            "Msg::CordisRowRemove(index) => {",
            "Msg::CordisRowInspect(index) => {",
            "Msg::CordisClientCode(index, outcome) => {",
            // 批 CD3B：审批这一路**开臂那三把尺**在主干是静默 return（`CD:556-558`）⇒ 本刀接的是
            // **回执臂**那一格，这一枚反证**照留**（臂头不许长出一枚没授权的卡）。
            "Msg::CordisApprove(kind) => {",
        ] {
            assert!(
                !arm(&code, start).contains(wired),
                "这一臂把本族的失败出口接成了错误卡 ⇒ 未授权扩面：{start:?}"
            );
        }
        for helper in [
            // 批 CD3B：新审批那条 RPC 腿确实一声不吭（host 半路 throw = 静默 `let _ = kernel.call(..)`，
            // 逐字照主干 `CD:630-634` 的 `catch {}`）⇒ 这颗**照留**（本刀接的是回执臂，不是 RPC 腿）。
            concat!("fn run_cordis_", "approval"),
            "fn run_cordis_client_code",
            // 批 ERR3 同口径补的两枚：run/stop 与 `移除` 那两条 RPC 腿只**投回执**，卡住在
            // `Msg::CordisActDone` 那一臂（`CD:784`/`CD:868` 的 `catch` 在 `await` 之外）⇒ 腿里
            // 长出第二枚火 = 同一句话两条出口。收紧，不是放宽。
            concat!("fn run_cordis_ro", "w_action"),
            concat!("fn run_cordis_und", "efine"),
        ] {
            assert!(
                !body(&code, helper).contains(wired),
                "动作钮共用的前置闸 / inspect 那条腿被接成了错误卡 ⇒ 同样是未授权扩面：{helper:?}"
            );
        }
    }

    /// 判据⑥：RPC 腿**只消费** `kernel.rs` 那一份构造器 / 投影器（PL1 §2.2「零新模块、零 lib 欠账」）
    /// ⇒ main 侧一枚 `json!` 都不许多写、排序折叠都不许多实现、`requestId` 那一颗必须是 `None`
    /// （落盘是 `"requestId":null`，不是省键）、`settleUserRun` 只在 `has_client_half` 时发。
    #[test]
    fn rpc_goes_through_the_kernel_builders_only() {
        let code = code();
        // 针一律拆词写 ⇒ 本 mod 自己不进那枚「恰好一处」的账（FX1 / MS1 §M-2）。
        // 批 CD3B（报告 §2-C）：刀 3 的审批腿**合法地**多消费了同一族 lib 构造器（面板腿 +
        // 审批腿两条路 ⇒ 同一颗构造器两处调用），所以本针从「一律恰好一处」改成「按期望次数分组」。
        // ⚠ 次数不是照着报告那张表抄的：报告 §2-C 自己声明 `2`/`3` 两档「静态数过但没跑到那一行」。
        // 今晨真实 panic 给的 `left` = `cordis_run_host_half(` **2**（与表相符）；表里另外两档与
        // 实码不符，已按 `grep -n` 反证过的行号改正并在此登记：
        //   · `cordis_resolve_request_run(` 表 3 ⇒ **4**：9875（Decline 直接 await）/ 9891（host 半路
        //     throw 的静默 `let _`）/ 9913 与 9921（两档结算）—— 四发**全在** `fn run_cordis_approval`
        //     同一把腿的各分支里 ⇒ 合法消费点，不是手搓的第二份投影器。
        //   · `cordis_still_pending( 表 1 ⇒ **2**：4692（在审那张的判据）与 4697（队列 retain），
        //     两发都在 `cordis_reconcile_approvals` 那一发里、都读 lib 那同一颗尺 ⇒ 判据没在 main 重实现。
        // 判据形状（等号、逐名点名、拆词防自截）**一字未改** ⇒ 改的是数字，不是尺。
        let builders: [(&str, usize); 12] = [
            (concat!("cordis_run_host_ha", "lf("), 2),
            (concat!("cordis_stop_from_pa", "nel("), 1),
            (concat!("cordis_undefine_from_pa", "nel("), 1),
            (concat!("cordis_settle_user_", "run("), 1),
            (concat!("cordis_get_client_", "code("), 1),
            (concat!("cordis_host_half_", "ok("), 2),
            (concat!("cordis_host_half_mess", "age("), 2),
            (concat!("cordis_host_half_plugin_run_", "id("), 2),
            (concat!("parse_cordis_ro", "ws("), 1),
            (concat!("cordis_resolve_request_ru", "n("), 4),
            (concat!("cordis_pending_from_eve", "nt("), 1),
            (concat!("cordis_still_pe", "nding("), 2),
        ];
        for (builder, expected) in builders {
            assert_eq!(
                code.matches(builder).count(),
                expected,
                "lib 构造器那一发的消费点数目漂了（多一处 = 手搓第二份，少一处 = 腿断了）：{builder:?}"
            );
        }
        let run = arm(&code, "fn run_cordis_row_action");
        assert!(
            run.contains("&mode, None, false)"),
            "面板那一路的 `request_id` 不再是 `None`（或 `approve_future_versions` 不再是 `false`）"
        );
        assert!(
            run.contains("if settle {") && run.contains("let settle = row.has_client_half;"),
            "`settleUserRun` 不再只在 `row.has_client_half` 为真时发 ⇒ 主干 `CD:768-776` 那道闸改了"
        );
        // 排序 / 折叠不许在 main 侧重实现；`json!` 一颗都不许多。
        let leg = arm(&code, "fn run_cordis_inventory");
        for forbidden in [concat!("js", "on!"), concat!("sort_cordis_ro", "ws(")] {
            assert!(
                !run.contains(forbidden) && !leg.contains(forbidden),
                "RPC 腿里冒出了手搓件：{forbidden:?}"
            );
        }
    }

    /// 判据⑦（批 CD2 D-10 之一）：折叠子区的**收起臂**一发行都不发且不清 body、**展开臂**在途不画、
    /// 任何一发 `inventory` 的 `Ok` 落地都把折叠态复位（简报 §3 的三条禁令各钉一枚）。
    /// 变异证明：摘掉收起臂那句 `return` ⇒ 第二把红；给 `cordis_inspect_toggle` 补一句清 `body` ⇒
    /// 第三把；把 `draft.inspect.clear()` 从 `Ok` 臂挪进 `Err` 臂 ⇒ 第四把；在展开路当场写
    /// `Source` 那一型（= 造「读取中…」子态）⇒ 第五把。
    #[test]
    fn collapsing_the_inspect_area_sends_no_rpc_and_reopening_resets_it() {
        // ---- 纯状态那半：toggle 的三档（空格 / 已展开 / 已收起再点）----
        let mut slots: Vec<(usize, CordisInspect)> = Vec::new();
        assert!(
            !cordis_inspect_toggle(&mut slots, 3),
            "空格上的 toggle 不该报「收起」"
        );
        assert!(slots.is_empty(), "toggle 那一发凭空造了格子");
        slots.push((
            3,
            CordisInspect {
                open: true,
                body: Some(CordisInspectBody::Source("fn a() {}".to_string())),
            },
        ));
        assert!(
            cordis_inspect_toggle(&mut slots, 3),
            "已展开却没报「收起」⇒ 调用方会照发那一发 RPC"
        );
        assert!(!slots[0].1.open, "那一格没回收起");
        assert!(
            slots[0].1.body.is_some(),
            "收起路清了 body ⇒ 与主干反了（`Children.Clear()` 只在 `CD:892` 的展开路）"
        );
        assert!(
            !cordis_inspect_toggle(&mut slots, 3),
            "收起后再点该走展开路（= 重取）"
        );

        // ---- 源码那半：收起臂必须排在发腿之前、且那条纯函数压根不发 RPC ----
        let code = code();
        let window = arm(&code, "Msg::CordisRowInspect(index) => {");
        let toggle = window
            .find(concat!("cordis_inspect_tog", "gle(&mut draft.inspect, index)"))
            .expect("inspect 臂没有 toggle 那第一道判据（`CD:887`）");
        let leg = window
            .find(concat!("run_cordis_client_", "code(index"))
            .expect("inspect 臂没接上那条 RPC 腿");
        // 收起那一路的 `return` 必须排在**取行之前**（`CD:890`：那句 return 在 `Children.Clear()`
        // 与整个 await 之前）⇒ 只量「toggle 到取行」那一段，别拿后面那支的 `return` 蒙过去。
        let take = window
            .find(concat!("draft.rows.get(inde", "x).cloned()"))
            .expect("inspect 臂没有按下标取行那一句");
        assert!(
            toggle < take && take < leg,
            "收起判据 / 取行 / 发腿 三件事的顺序漂了"
        );
        assert_eq!(
            window[toggle..take].matches(concat!("retur", "n;")).count(),
            1,
            "收起那一路没有**唯一那一句**直接 return ⇒ 它照发那一发（`CD:890`）"
        );
        assert!(toggle < leg, "发腿排在了 toggle 之前 ⇒ 收起那一路也会发一发");
        let helper = {
            // 这两颗 helper 是**模块级** fn（列 0）⇒ 现成的 `body()` 那道「下一发四空格 `fn `」的
            // 终点锚会一路铺到 `impl Shell` 里去，故这里按名取窗。
            let (_, rest) = code
                .split_once(concat!("fn cordis_inspect_tog", "gle("))
                .expect("找不到 toggle 那颗纯函数");
            rest.split_once(concat!("fn cordis_inspect_", "open"))
                .map(|(window, _)| window)
                .expect("toggle 之后找不到 open 那颗纯函数")
        };
        assert_eq!(
            helper.matches(concat!("open = fa", "lse;")).count(),
            1,
            "收起那一支不是「只翻 Visibility 那一格」"
        );
        for forbidden in [
            concat!("body = N", "one"),
            concat!("run_cordis_", "client"),
            concat!("cordis_invent", "ory("),
        ] {
            assert!(
                !helper.contains(forbidden),
                "toggle 那颗纯函数里冒出了清 body / 发 RPC 的件：{forbidden:?}"
            );
        }
        // 展开臂**不置 open**（简报 §3 禁令②：不许造「读取中…」子态）⇒ 臂里只允许两型当场点亮：
        // `Note`（主干 `CD:895-899` 的「当前没有活动运行。」）与 `Failure`（N-1 那一支：`CD:370` 的
        // `throw` 其 `catch` 就在同一条点击腿里 ⇒ `CD:926-935` 画一行并照样点亮）。
        // `Source` = 那一发 RPC 的在途产物，**只许**长在回执臂里 ⇒ 零枚才是真。
        assert_eq!(
            window.matches(concat!("CordisInspectBody::So", "urce")).count(),
            0,
            "展开路当场画了源码格 = 凭空造了主干没有的在途态"
        );
        assert_eq!(
            window.matches(concat!("CordisInspectBody::No", "te")).count(),
            1,
            "「当前没有活动运行。」那一支（`CD:893-899`）没了 ⇒ 两道判据被并成了一把"
        );
        assert_eq!(
            window.matches(concat!("CordisInspectBody::Failu", "re")).count(),
            1,
            "内核不在那一档不再画进子区（N-1：主干 `CD:370` + `CD:926-935` ⇒ 可见出口在子区内）"
        );
        assert_eq!(
            window.matches(concat!("cordis_inspect_op", "en(")).count(),
            2,
            "当场点亮的两型合计不是两枚 ⇒ 有一支被改回静默、或多造了一型在途态"
        );

        // ---- 随 inventory 复位：只在 `Ok` 臂清，`Err` 臂保持上一次的表（`CD:227-230`）----
        let inventory = arm(&code, "Msg::CordisInventory(outcome) => {");
        let (ok_half, err_half) = inventory
            .split_once("Err(message) => {")
            .expect("清单那臂的 Err 出口换了形状");
        let reset = concat!("draft.inspect.cl", "ear();");
        assert_eq!(
            ok_half.matches(reset).count(),
            1,
            "inventory 落地没复位折叠态（简报 §3 禁令③：主干 `refresh()` 整树重建）"
        );
        assert_eq!(
            err_half.matches(reset).count(),
            0,
            "失败臂清了折叠态 ⇒ 主干那一刻行表与子区都保持上一次（`CD:227-230`）"
        );
    }

    /// 判据⑧（批 CD2 D-10 之二）：源码框的**每一个主干数值**都写死等号（CS1 §1.3 全表），另把三条
    /// 「不许」钉成负针（横向滚动 / 源码框描边底色 / `font_family`）+ 端点名不进本文件。
    /// 变异证明：`max_height(200.0)` 改成 180 ⇒ 第一把红；字号裸 `11.0` 换成 `type_ramp::CODE.size`
    /// ⇒ 第二把（那颗静默偏 1 DIP 的雷从此有尺）；给源码框补 `horizontal_scroll_bar_visibility` 或
    /// 再包一层 `Border` ⇒ 第三、第四把红。
    #[test]
    fn the_inspect_box_pins_the_trunk_numbers() {
        let code = code();
        let card = body(&code, "fn cordis_row_card");
        for (trunk, needle, want) in [
            ("`CD:920 MaxHeight = 200`", concat!(".max_height(200.", "0)"), 1usize),
            (
                "`CD:916 IsTextSelectionEnabled = true`",
                concat!(".is_text_selection_enabled(", "true)"),
                1,
            ),
            (
                "`CD:918 FontSize = 11`（裸值，表里没有 11 那一档）",
                concat!(".font_size(11.", "0)"),
                1,
            ),
            (
                "`CD:876 StackPanel{Spacing=Sp4}`（body + 子区两枚）",
                concat!("spacing(space::", "S4)"),
                2,
            ),
            (
                "`CD:881` 那颗钮**只**量 `ActiveRunId`（`busy` 不许并进来）",
                concat!(".is_enabled(has_", "run)"),
                1,
            ),
            (
                "`CD:882` 的 UIA 真名",
                concat!("\"CordisInspect", "\""),
                1,
            ),
            (
                "`CD:905-909` 标题行套现成的 CAPTION 档（= 主干 12）",
                concat!("type_ramp::CAPTION.", "size"),
                6,
            ),
            (
                "行卡的 `Opacity=.7` 只有 package / source 两枚（子区一枚都不许加）",
                concat!(".opacity(0.", "7)"),
                2,
            ),
            (
                "`CD:961` 整张行卡的底色只有一层（子区继承它，不许自设）",
                concat!(".back", "ground("),
                1,
            ),
            (
                "`CD:955-963` 整张行卡的描边只有一层",
                concat!(".border_", "brush("),
                1,
            ),
        ] {
            let got = card.matches(needle).count();
            assert_eq!(got, want, "{trunk} 那一档漂了（今数 {got} 枚）");
        }
        for forbidden in [
            concat!("horizontal_scroll_bar_visibili", "ty"),
            concat!(".font_", "family("),
            concat!("Consola", "s"),
            concat!("读取", "中"),
        ] {
            assert!(
                !card.contains(forbidden),
                "源码框里冒出了主干没有的件：{forbidden:?}"
            );
        }
        // 端点名那根 wire 字面量不进本文件（口径同上面那把四条锁死端点的报警尺 ⇒ 反向哨兵读**原文**，
        // 注释里提一次也要响 ⇒ 针一律拆词写）。
        let raw = include_str!("main.rs");
        assert_eq!(
            raw.matches(concat!("dynamicCordisRunner/ge", "tClientCode")).count(),
            0,
            "`getClientCode` 的端点名漏进了 main.rs（必须走 `kernel.rs` 的构造器）"
        );
        // 那条腿的回帧读法：**只**读 `code` 一颗（`CD:904`），而且**不剥 `ok`**（`getClientCode`
        // 路不是 `runHostHalf` 三件套 ⇒ 套 `cordis_host_half_ok` 就是把行为做反）。
        let leg = body(&code, "fn run_cordis_client_code");
        assert_eq!(
            leg.matches(concat!(".get(\"co", "de\")")).count(),
            1,
            "回帧读法不是「一颗 `code`」⇒ 多读的就是主干没有的第二份投影"
        );
        assert_eq!(
            leg.matches(concat!("Value::as", "_str")).count(),
            1,
            "`code` 的三态塌空串丢了（缺键 / 空串 / 非串 ⇒ 全落 `(空)`）"
        );
        for forbidden in [
            concat!("cordis_host_half_", "ok("),
            concat!("cordis_host_half_mess", "age("),
            concat!("parse_", "cordis"),
        ] {
            assert_eq!(
                leg.matches(forbidden).count(),
                0,
                "inspect 那条腿接成了 `runHostHalf` 那一族的剥壳件：{forbidden:?}"
            );
        }
        // 回执臂：两条出口都以「子区点亮」收尾，失败既不重拉清单也不弹错误卡（`CD:926-935`）。
        let receipt = arm(&code, "Msg::CordisClientCode(index, outcome) => {");
        assert_eq!(
            receipt.matches(concat!("cordis_inspect_ope", "n(")).count(),
            1,
            "回执那臂没把那一格写成已展开 ⇒ `CD:924`/`CD:934` 两条出口的 Visible 丢了"
        );
        assert!(
            !receipt.contains(concat!("run_cordis_inve", "ntory("))
                && !receipt.contains(wired_leg().as_str()),
            "inspect 的回执臂去重拉了清单 / 接成了错误卡"
        );
    }

    /// 拆词写：本 mod 不许把错误弹层那一根的**原文**计数带进任何闸里（注释里提一次也会改那枚裸串数）。
    fn wired_leg() -> String {
        concat!("Msg::ErrorDial", "og(").to_string()
    }
}

#[cfg(test)]
mod skill_picker_tests {
    use super::*;

    fn skp_source() -> &'static str {
        include_str!("main.rs")
    }
    /// 数串一律过 crate 根那颗 `code_only`（注释提一次不该改枚数）。
    fn skp_code() -> String {
        super::code_only(skp_source())
    }
    fn skp_window(hay: &str, start: &str, end: &str) -> String {
        let (_, rest) = hay
            .split_once(start)
            .unwrap_or_else(|| panic!("锚丢了：{start}"));
        let (body, _) = rest
            .split_once(end)
            .unwrap_or_else(|| panic!("锚丢了：{end}"));
        body.to_string()
    }
    fn skp_pos(hay: &str, needle: &str) -> usize {
        hay.find(needle).unwrap_or_else(|| panic!("少了 {needle}"))
    }
    /// 本族收点那一发（拆词写，免得本 mod 自己进计数）。
    fn close_needle() -> String {
        concat!("skill_picker_close(&mut self.", "skill_picker);").to_string()
    }
    fn draft(items: usize) -> SkillPickerDraft {
        SkillPickerDraft {
            session_id: "s1".to_string(),
            items: Vec::new(),
            error: if items == 0 {
                String::new()
            } else {
                "会话已切换".to_string()
            },
        }
    }

    /// 判据①：这张卡**只**通过自己的壳退役（17 发实测 = 13 发同级开臂反向互斥 +
    /// 「已开⇒收」+ 关臂 + 点选臂 + Esc 档），且全文件**零**直写赋值形。
    /// 变异证明：摘掉任意一臂里那一发 ⇒ 第一把红（`16 → 15`）；在本卡任何臂里直写
    /// `self.skill_picker = None;` ⇒ 第二把红。
    #[test]
    fn the_card_retires_only_through_its_shell_form() {
        let code = skp_code();
        let closes = code.matches(&close_needle()).count();
        assert_eq!(
            closes, 17,
            "收点枚数漂了（今数 {closes} 发）：少一处 = 开别张层时这张卡还挂着，\
             多一处 = 有人在往别的状态上收它。17 发 = 十三发同级开臂 + 开臂瞬关 + 关臂 + 点选臂 + Esc 档"
        );
        assert_eq!(
            code.matches(concat!("self.skill_picker = No", "ne;")).count(),
            0,
            "出现了直写赋值形 ⇒ 形制交回「改动者自己去数」，那十六发的计数闸就假绿了"
        );
        // 壳本体的两档返回值（借道那一档的臂据此决定要不要吞键，口径同 `goal_panel_close`）。
        let mut open = Some(draft(0));
        assert!(skill_picker_close(&mut open), "开着却报「这一发不是这张卡吃的」");
        assert_eq!(open, None);
        assert!(
            !skill_picker_close(&mut open),
            "已经关着还回 true ⇒ 第二次收会误吞底下那一层的键"
        );
    }

    /// 判据②（反向半边）：十二发同级臂每一发都写明收这张卡 —— 这张卡进了同级 mesh，
    /// 「同刻至多一层」才对得起主干那颗应用级 `ContentDialog`。
    /// 变异证明：把下面表里任意一臂里那一发删掉 ⇒ 只有那一臂红（臂名在断言里）。
    #[test]
    fn every_sibling_open_arm_retires_this_card() {
        let code = skp_code();
        for (start, end) in [
            ("Msg::Nav(page) => {", "Msg::Scheme("),
            ("Msg::FileMenuToggle(", "Msg::FileMenuClose"),
            ("Msg::SelectorToggle(", "Msg::SelectorClose"),
            ("Msg::DetailsToggle(", "Msg::DetailsClose"),
            ("Msg::SessionRefList(", "Msg::CloseSessionRefs"),
            ("Msg::TodosPanelToggle => {", "Msg::TodosPanelClose"),
            ("Msg::TrajectoryPanelToggle => {", "Msg::TrajectoryPanelClose"),
            ("Msg::SchedulePanelToggle => {", "Msg::SchedulePanelClose"),
            ("Msg::GoalPanelToggle => {", "Msg::GoalPanelClose"),
            ("Msg::WorkspaceMenuToggle(", "Msg::WorkspaceMenuClose"),
            ("Msg::DockMenuToggle(", "Msg::DockMenuClose"),
            (
                "Msg::Branched(Ok((rows, child, title))) => {",
                "Msg::Branched(Err(",
            ),
        ] {
            let arm = skp_window(&code, start, end);
            assert!(
                arm.contains(&close_needle()),
                "{start} 那一臂没写明收这张卡 ⇒ 它与这张卡会同屏（主干那颗是应用级模态，\
                 开一张就吃掉其余）"
            );
        }
    }

    /// 判据③（正面半边）：开这张卡的臂收齐那十一发同级层，dock 那一发**只借道**，
    /// 错误卡**一发都不收**（ERR1 的裁决：它与所有层不互斥）。
    /// 变异证明：把任一 needles 从开臂删掉 ⇒ 本把红；把 dock 那一发改成直写壳 ⇒ 第二把红；
    /// 给开臂补一发错误卡 ⇒ 第三把红。
    #[test]
    fn opening_this_card_retires_every_sibling_layer_but_the_error_card() {
        let code = skp_code();
        let open = skp_window(
            &code,
            "Msg::SkillPickerToggle => {",
            "Msg::SkillPickerClose => {",
        );
        for sibling in [
            "file_menu_close",
            "message_details_close",
            "session_ref_list_close",
            "workspace_menu_close",
            "todos_panel_close",
            "self.trajectory_panel_close(",
            "selector_close",
            "goal_panel_close",
            "danger_confirm_close",
            "schedule_panel_close",
            "session_feedback_close",
        ] {
            assert!(
                open.contains(sibling),
                "开这张卡没收 {sibling} ⇒ 两张同屏（主干那颗模态吃其余）"
            );
        }
        assert!(
            open.contains(concat!("if self.dock_menu.is_some() ", "{")),
            "dock 那一发不借道现成臂 = 要么直写壳（白名单外那把 19 枚的闸会漂），要么漏收"
        );
        assert!(
            !open.contains(concat!("dock_menu_clos", "e(")),
            "dock 的收点枚数由白名单外的 `tests/dock_chrome.rs` 钉着 ⇒ 本批一律走借道"
        );
        assert!(
            !open.contains(concat!("error_dialog_clos", "e(")),
            "错误卡进了本卡的互斥清单 = 改了 ERR1 的裁决（它与所有层不互斥）"
        );
        // 回执之前不落状态格 ⇒ 渲染只有「不在场 / 在场」两档（主干那两档，无等待档）。
        assert_eq!(
            open.matches(concat!("self.skill_picker = Som", "e(")).count(),
            0,
            "开臂就置格 ⇒ 多出一档主干没有的「等回执」渲染"
        );
        // 前置闸那一档一个状态都不动：守卫直接 return（不在这圈里收任何兄弟）。
        // ⚠ 取窗必须落在**本卡自己那一臂**里（`open` 已经是本臂的窗）：那枚守卫串在全文件有
        // 四发（本卡 / 会话反馈 / 计划 / 目标），拿整份 `code` 去取窗会把起点拽到会话反馈那一臂
        // 的守卫、终点停在本卡臂首 ⇒ 窗里装的全是**别人**的开臂收点（批 SKP2 现测：原判据因此
        // 恒红，与产品码落点无关）。判据本体（「那一档一枚收点都不许有」）一字未改。
        let guard_from = skp_pos(
            &open,
            concat!("|| self.active.as_deref().unw", "rap_or(\"\").trim().is_empty()"),
        );
        let guard_to = skp_pos(&open, concat!("} else", " {"));
        assert!(
            guard_to > guard_from,
            "本卡开臂里「前置闸 → 开卡分支」的序漂了 ⇒ 那一臂的形制改了"
        );
        let guard = &open[guard_from..guard_to];
        assert!(
            !guard.contains(concat!("_clos", "e(&mut self.")),
            "前置闸那一档开始收兄弟层 ⇒ 主干那一发连对话框都没建，本卡也不该动任何状态"
        );
    }

    /// 判据④：键盘三档各一枚、不并档，且报位那一发在 `publish_keys` 里（否则三档是死码，
    /// FA1-F-2 的老账）。报位序 = 错误卡之后、会话反馈之前（本卡是宿主末格 = 最上面那一层）。
    /// 变异证明：把 `Msg::PaletteMove` 那一档并进 Close ⇒ 第二把红；删掉报位那一发 ⇒ 第四把红；
    /// 把本卡三档挪到错误卡之前 ⇒ 第五把红。
    #[test]
    fn the_three_keyboard_tiers_are_three_arms_and_the_slot_is_registered() {
        let code = skp_code();
        let close = concat!("Msg::PaletteClose if self.skill_pic", "ker.is_some()");
        let move_tier = concat!("Msg::PaletteMove(_) if self.skill_pi", "cker.is_some()");
        let accept = concat!("Msg::PaletteAccept if self.skill_pic", "ker.is_some()");
        assert_eq!(code.matches(&close).count(), 1, "Esc 那一档没了或多了一档");
        assert_eq!(
            code.matches(&move_tier).count(),
            1,
            "↑/↓ 吞键那一档并到 Close 里了：卡开着时方向键会去动底下的浮层"
        );
        assert_eq!(
            code.matches(&accept).count(),
            1,
            "Enter 吞键那一档没了 ⇒ 卡开着时 Enter 会发给壳（主干那颗不写 `DefaultButton`）"
        );
        assert!(
            code.contains(concat!("|| self.skill_picker.is_", "some()")),
            "`publish_keys` 没把这一格并进浮层槽 ⇒ Esc 永远投不进来"
        );
        let err = skp_pos(&code, concat!("Msg::PaletteClose if self.", "error_dialog.is_some()"));
        let mine = skp_pos(&code, &close);
        let sfb = skp_pos(
            &code,
            concat!("Msg::PaletteClose if self.sess", "ion_feedback.is_some()"),
        );
        assert!(
            err < mine && mine < sfb,
            "三档的问序漂了：错误卡压过全部层故最先；本卡是宿主末格 ⇒ 在会话反馈之前"
        );
    }

    /// 判据⑤：遮罩抄 **`ContentDialog` 一族** —— 铺满 + 透明底 + **零** `on_pointer_pressed`
    /// （点卡外不关，主干一处都没设 `ShouldCloseOnOutsideClick`）；**不抄** light-dismiss 那两族。
    /// 变异证明：给遮罩挂一发 `on_pointer_pressed` ⇒ 第二把红；把透明底删掉 ⇒ 第一把红。
    #[test]
    fn the_scrim_is_the_content_dialog_family_with_no_light_dismiss() {
        let code = skp_code();
        let layer = skp_window(
            &code,
            "fn skill_picker_layer(&self",
            "fn skill_picker_card(",
        );
        assert!(
            layer.contains(concat!("background(p.trans", "parent.clone())")),
            "遮罩不是透明铺满 ⇒ 与族 D 那五张不同脸（主干那颗没有暗色遮罩）"
        );
        assert!(
            layer.contains("HorizontalAlignment::Stretch")
                && layer.contains("VerticalAlignment::Stretch"),
            "遮罩没铺满整窗 ⇒ 「点外面不关」会退化成「点外面穿透」"
        );
        assert!(
            !layer.contains("on_pointer_pressed"),
            "挂了 light-dismiss = 凭空造主干没有的行为（那是 `MenuFlyout` 两族的形制）"
        );
    }

    /// 判据⑥：卡面逐件对表 `CP:395-430` —— 正文 `Spacing=8 / Width=440` + 外滚
    /// `MaxHeight=480` + 四枚 `CapabilityText` 串全走 B 道 + 关闭钮一颗 + 行钮一颗一枚
    /// + **零** `automation_id`（主干那批钮零真名）+ **零** 选中开关。
    /// 变异证明：`space::S8` 改成 `S10` ⇒ 第一把红；给卡体加一发 `automation_id` ⇒ 第三把红。
    #[test]
    fn the_card_draws_every_face_mainline_has() {
        let code = skp_code();
        let card = skp_window(
            &code,
            "fn skill_picker_card(&self",
            "fn skill_picker_entry_cell(",
        );
        assert_eq!(card.matches(concat!("spacing(space::", "S8)")).count(), 1, "正文 `Spacing = 8` 那一发漂了（`CP:395`）");
        assert_eq!(
            card.matches(concat!(".width(440.", "0)")).count(),
            1,
            "正文定宽 440 漂了（`CP:395`，不套会话反馈那 380）"
        );
        assert_eq!(
            card.matches(concat!(".max_height(480.", "0)")).count(),
            1,
            "外滚 `MaxHeight = 480` 漂了（`CP:402`）"
        );
        assert_eq!(
            card.matches(".bt(").count(),
            4,
            "卡体四枚 `CapabilityText`（声明 / 空态 / 卡题 / 关闭）少一枚就是主干那件没画"
        );
        assert_eq!(card.matches(".l(").count(), 0, "A 面七枚串全在主干 `CapabilityText` 一侧 ⇒ 一发 `l` 都是把回落那半档抹掉");
        assert_eq!(
            card.matches(concat!("{title_row, scroll, cl", "ose}")).count()
                + card
                    .matches(concat!(".children((title_row, scroll, ", "close))"))
                    .count(),
            1,
            "「标题行 + 滚动件 + 关闭钮」三件套的声明序漂了（标题在滚外之上、关闭在滚外之下）"
        );
        assert_eq!(
            card.matches(concat!("KeyedView::new(format!(\"skill-", "row-{index}\"), row)")).count(),
            1,
            "行钮的逐行 keyed 槽没了 ⇒ 列表一变整棵重建（形制逐字同 `schedule-row-` 那一发）"
        );
        for key in ["skill-note", "skill-error", "skill-empty"] {
            assert!(card.contains(key), "少了 {key} 那一格（主干 `:396-430` 的常驻件）");
        }
        assert_eq!(
            card.matches(concat!("automation_", "id(")).count(),
            0,
            "卡体自造了 id ⇒ 主干那批 `Button` 一颗 `x:Name`/`Aut` 都没有（#101 仓规）"
        );
        assert_eq!(
            card.matches("is_text_selection_enabled").count(),
            0,
            "主干那四枚 `TextBlock` 一枚都没开选中 ⇒ 开了就是多做"
        );
        assert!(
            card.contains("Msg::SkillPickerPick(index)"),
            "行钮没把下标发出去 ⇒ 点选那一发落不了地"
        );
    }

    /// 判据⑦：入口只一颗 —— 主干真名 `SkillsMenuItem`（`CP:96`）全仓唯一、走 B 道、点它发
    /// `Toggle`、零字形；入带位置 = 计划之后、会话反馈之前（= `CP:82-92` 那句「插到会话反馈
    /// **之前**」的字面等价物）。
    /// 变异证明：把 `on_click` 换成 `Close` ⇒ 第二把红；把那一发挪到会话反馈之后 ⇒ 第三把红。
    #[test]
    fn the_entry_is_one_cell_with_the_trunk_automation_id_and_the_trunk_order() {
        let code = skp_code();
        assert_eq!(
            code.matches(concat!("SkillsMenu", "Item")).count(),
            1,
            "主干那枚 id 全仓唯一（`CP:96`）：多一枚就是自造 id，少一枚就是入口没接线"
        );
        let entry = skp_window(
            &code,
            "fn skill_picker_entry_cell(&self",
            "\nfn main() {",
        );
        assert!(
            entry.contains(concat!("context.message(Msg::SkillPicker", "Toggle)")),
            "入口那颗发的不是 Toggle ⇒ 点它开不了卡"
        );
        assert_eq!(entry.matches(".bt(").count(), 1, "入口文案只许一发 B 道");
        assert!(
            !entry.contains("FontIcon"),
            "那颗 `MenuFlyoutItem` 没有字形 ⇒ 分叉不许长出一枚主干查无此物的图标"
        );
        let band = skp_window(&code, "fn composer_band(", "fn agent_mode_trigger(");
        assert_eq!(
            band.matches(concat!("KeyedView::new(\"skill", "s\",")).count(),
            1,
            "入口在带里只许一发"
        );
        let schedules = skp_pos(&band, concat!("KeyedView::new(\"", "schedules\","));
        let mine = skp_pos(&band, concat!("KeyedView::new(\"ski", "lls\","));
        let feedback = skp_pos(&band, concat!("\"", "session-feedback"));
        assert!(
            schedules < mine && mine < feedback,
            "带内列序漂了：主干 `CP:82-92` 把技能插在「会话反馈」那一格**之前**、计划之后"
        );
    }

    /// 判据⑧：状态只一格里、回执只一处写它；端点字面量与参数形状一律住在 lib 那一侧；
    /// `MODAL_LEDGER` 一行都不新登记（这张卡早在册，`CP:402` 那一行）。
    /// 变异证明：往账本加一行 ⇒ 第四把红；在 main.rs 里写出端点字面量 ⇒ 第三把红。
    /// ⚠ RA-B 同批改口（2026-09-28）：主干撤三张 ⇒ 这一把量的是**文件级**行计数（台账 30 行 +
    /// 那行 `struct` 声明 = **31**，见 `MODAL_LEDGER` 抬头「两个口径」那段），旧值 34 = 33 + 1。
    /// 「本卡一行都不新登记」的判语不变 —— 变的还是基数。
    #[test]
    fn the_state_has_one_owner_and_the_wire_shape_stays_in_lib() {
        let code = skp_code();
        assert_eq!(
            code.matches(concat!("skill_picker: Option<SkillPickerDra", "ft>")).count(),
            1,
            "状态格只许一个持有者"
        );
        assert_eq!(
            code.matches(concat!("skill_picker: No", "ne,")).count(),
            1,
            "初始化那一发只许一处"
        );
        assert_eq!(
            code.matches(concat!("self.skill_picker = Som", "e(")).count(),
            1,
            "置格只许回执臂那一处（开臂置格 = 多出主干没有的等待档）"
        );
        assert_eq!(
            code.matches(concat!("ModalLedgerRow ", "{")).count(),
            31,
            "账本一行都不许新登记（这张卡的行早在册：`CP:402`）"
        );
        assert_eq!(
            code.matches(concat!("card: \"skill-pick", "er\"")).count(),
            1,
            "那张表里这张卡的行只许一处"
        );
        assert_eq!(
            code.matches(concat!("\"skills/", "list\"")).count(),
            0,
            "端点字面量不许出现在本文件（参数形状一律由 `kernel.rs::skills_list` 给）"
        );
        let run = skp_window(
            &code,
            "fn run_skill_picker_list(&self",
            "fn session_feedback_record(&self",
        );
        assert!(
            run.contains(concat!("let call = skills_lis", "t(session_id);")),
            "那一发没走 lib 的构造器 ⇒ 线上形状有了第二份真相"
        );
        assert!(
            run.contains(concat!("kernel.call(call.me", "thod, call.args)")),
            "回执没接 `Kernel::call` ⇒ 这一发压根发不出去"
        );
    }

    /// 判据⑨：token 插入逐字抄 `CP:436` 的**字符串形状**（前导空格只在「非空且末位不是空白」时
    /// 给、后面固定一枚空格、草稿一字不改）。
    /// ⚠ 偏差备案（报告 §6）：主干那一句写的是 `SelectionStart` 那一档（插在光标处并回挪光标），
    ///   分叉那颗 `TextBox` 由单向文本回调驱动（`Msg::Input`）、**没有**光标通道 ⇒ 只能落「追加」。
    /// 变异证明：把 `!out.is_empty()` 删掉 ⇒ 第一把红；把末位空格删掉 ⇒ 第三把红。
    #[test]
    fn the_token_insert_keeps_the_draft_and_pads_only_when_needed() {
        assert_eq!(skill_token_insert("", "demo"), "/demo ");
        assert_eq!(skill_token_insert("帮我看看", "demo"), "帮我看看 /demo ");
        assert_eq!(skill_token_insert("帮我看看 ", "demo"), "帮我看看 /demo ");
        assert_eq!(skill_token_insert("第一行\n", "demo"), "第一行\n/demo ");
    }
}

/// 台账 #162 B-1a（批 **CB1**）：族 A 加宽成**面驱动** + 族 A 第二格 `reset_confirm` 的源锁。
/// 母本 = `MainWindow.PermissionConfirm.cs:42-105`（族 A 第一发）与
/// `MainWindow.xaml.cs:10669-10685`（`ResetSectionAsync` 就地 new 的那颗 `ContentDialog`），
/// 两发在主干 `MODAL_LEDGER` **同列族 A、同 `enter: ModalResult::Close`** ⇒ 分叉的落点是
/// 「共卡体渲染 fn、不共状态格」（SL1 案甲′），**不是**新建第 12 张平行卡。
///
/// 判据一律**等号形**（本仓登记在册的坏形状 = `>= N` 下限形）；针一律 `concat!` 拆在两枚字面量
/// 之间（FX1 口径：整串写出来就是把本行数进产品码）；数产品码枚数的走 `code_only`（MS1 §M-2），
/// 而**反向哨兵**（数 `== 0` 那几把）按 `code_only` 自己的文档走**原文**，不剥注释。
#[cfg(test)]
mod confirm_family_tests {
    use super::*;

    fn window<'a>(source: &'a str, start: &str, end: &str) -> &'a str {
        let from = source.find(start).expect("起点锚漂了");
        let tail = &source[from + start.len()..];
        let extra = tail.find(end).expect("终点锚漂了");
        &source[from..from + start.len() + extra]
    }

    fn code() -> String {
        code_only(include_str!("main.rs"))
    }

    /// 判据①：一族**只有一套卡体**。两张格的宿主各造一张脸，再都交给同一枚共卡体 fn；
    /// 那套卡体里透明遮罩**恰好一枚**、`on_pointer_pressed` **恰好零枚**（族 A 两发同为
    /// `ShouldCloseOnOutsideClick = false` ⇒ 点卡外不关也不穿透）。
    /// 变异证明：把 `reset_confirm_card` 里那一发 `self.confirm_card(` 换成再抄一套卡体 ⇒
    /// 「两个调用点」那把红；把遮罩那一枚删掉或抄两枚 ⇒ 遮罩那把红。
    #[test]
    fn the_family_renders_through_one_card_body() {
        let source = include_str!("main.rs");
        let card = window(
            source,
            concat!("fn danger_confirm_", "card("),
            concat!("enum Workspace", "MenuAction"),
        );
        let shared = concat!(
            "fn confirm_",
            "card(&self, context: &mut ViewContext<Shell>, p: Palette, card: &ConfirmFace)"
        );
        assert_eq!(
            card.matches(shared).count(),
            1,
            "族 A 那套卡体的定义不在窗内，或冒出了第二套（新建平行卡正是要避免的多做）"
        );
        for host in [
            concat!("fn danger_", "confirm_card("),
            concat!("fn reset_", "confirm_card("),
        ] {
            assert_eq!(card.matches(host).count(), 1, "两张格的宿主各一枚：{host}");
        }
        assert_eq!(
            card.matches(concat!("self.", "confirm_card(")).count(),
            2,
            "两发共吃同一套卡体 = 恰好两个调用点，一枚不多（抄第二套）一枚不少（少一张脸）"
        );
        assert_eq!(
            card.matches(concat!("background(p.", "transparent")).count(),
            1,
            "族 A 的遮罩只许一枚：`awk` 实测全仓 11 张 A 族卡遮罩逐字同形（SL1 §1.2）"
        );
        assert_eq!(
            card.matches("on_pointer_pressed").count(),
            0,
            "遮罩不挂指针处理器 ⇒ 点卡外既不关也不穿透"
        );
    }

    /// 判据②：第二发的收点**形制与枚数** —— 走壳函数、等号形钉死 **17** 枚
    /// （13 发同级开臂 + `Msg::Nav` 切页 + 共享的 dismiss 关臂 + 本卡键盘 Close/Enter 两档），
    /// 且**不许**出现直写赋值形。
    /// 变异证明：摘掉 `Msg::Nav` 那一臂里的本卡收点 ⇒ 本把红；把那一发改成直写 `= None` ⇒ 两把红。
    #[test]
    fn the_second_cell_retires_through_its_shell_form() {
        let code = code();
        let needle = concat!("reset_confirm_", "close(&mut self.reset_confirm);");
        assert_eq!(
            code.matches(needle).count(),
            17,
            "族 A 第二发的互斥清单枚数漂了（今数 {} 发）：少一处 = 开别张层时它还挂着，\
             多一处 = 有人在往别的状态上收它",
            code.matches(needle).count()
        );
        assert_eq!(
            code.matches(concat!("self.reset_confirm = No", "ne;")).count(),
            0,
            "直写赋值形冒出来了 ⇒ 上面那十七发的计数闸就假绿了（口径同 `skill_picker_tests`）"
        );
        // 壳本体的两档返回值（Esc 那一档据此决定要不要吞键，口径逐字同 `danger_confirm_close`）。
        let mut open: Option<ResetConfirm> = Some(("general".to_string(), vec!["general".to_string()]));
        assert!(reset_confirm_close(&mut open), "开着却报「这一发不是这张卡吃的」");
        assert_eq!(open, None);
        assert!(
            !reset_confirm_close(&mut open),
            "已经关着还回 true ⇒ 第二次收会误吞底下那一层的键"
        );
    }

    /// 判据③：两张格**互不收**对方 = 主干没有的跨卡互斥不许自造。
    /// 证据：`_permissionConfirmShowing` 全仓只 4 命中、全在 `MainWindow.PermissionConfirm.cs`
    /// （@35/44/48/103）⇒ 那道重入闸只护 `danger-full-access` 一颗，`ResetSectionAsync` **没有**它。
    /// 反向哨兵 ⇒ 按 `code_only` 自己的文档数**原文**（注释提一次正是它们要响的）。
    #[test]
    fn the_two_cells_never_retire_each_other() {
        let source = include_str!("main.rs");
        let first = window(
            source,
            concat!("Msg::PaletteClose if self.permission", "_confirm.is_some() => {"),
            concat!("Msg::PaletteMove(_) if self.permission", "_confirm.is_some()"),
        );
        assert_eq!(
            first.matches(concat!("reset_confirm_", "close(")).count(),
            0,
            "第一发的键盘档顺手收了第二发 = 自造主干没有的跨卡互斥"
        );
        let second = window(
            source,
            concat!("Msg::PaletteClose if self.reset", "_confirm.is_some() => {"),
            concat!("Msg::PaletteMove(_) if self.reset", "_confirm.is_some()"),
        );
        assert_eq!(
            second.matches(concat!("danger_confirm_", "close(")).count(),
            0,
            "反向半边同样不许：第二发不收第一发"
        );
        let ask = window(
            source,
            concat!("fn ask_danger_", "full_access("),
            concat!("fn apply_default_", "permission("),
        );
        assert_eq!(
            ask.matches(concat!("reset_confirm_", "close(")).count(),
            0,
            "开第一发那颗的入口不许顺手收第二格（主干那道闸只护自己那颗）"
        );
    }

    /// 判据④：两张脸的差别**只落在主干不同的那几格**上（族 A 第二发：无勾选、两枚 id 都没有、
    /// 一个尺寸都没写），且第一发那四枚原样在册。
    /// 变异证明：把恢复档的 `panel_width: None` 改成 `Some(DANGER_CONFIRM_PANEL_WIDTH)`（= 复用 420）
    /// ⇒ 本把红（SL1 R-3：那是主干没有的宽度，也是这一族第二枚宽度常量）。
    #[test]
    fn the_two_faces_differ_exactly_where_the_trunk_does() {
        let source = include_str!("main.rs");
        let second = window(
            source,
            concat!("fn reset_confirm_", "card("),
            concat!("fn confirm_", "card("),
        );
        for (needle, why) in [
            (concat!("primary_uid: No", "ne"), "主干那颗一个 `Aut()` 都没挂"),
            (concat!("dialog_uid: No", "ne"), "同上：卡体也没有 id"),
            (concat!("show_ack: ", "false"), "主干那颗没有 `RiskAckCheckBox`"),
            (concat!("panel_width: No", "ne"), "那颗一个尺寸都没写 ⇒ 不覆也不另立常量"),
        ] {
            assert_eq!(second.matches(needle).count(), 1, "{why}：{needle} 在该档只许一枚");
        }
        let first = window(
            source,
            concat!("fn danger_confirm_", "card("),
            concat!("fn reset_confirm_", "card("),
        );
        for needle in [
            concat!("primary_uid: Some(\"", "ConfirmDangerFullAccessButton\""),
            concat!("dialog_uid: Some(\"", "PermissionConfirmDialog\""),
            concat!("show_ack: ", "true"),
            concat!("Some(DANGER_CONFIRM_", "PANEL_WIDTH)"),
        ] {
            assert_eq!(first.matches(needle).count(), 1, "第一发那四枚漂了：{needle}");
        }
        // 卡体那把 `is_enabled(!accent || card.acked)` 尺**一字未动**（SL1 R-2 的明令）。
        let shared = window(
            source,
            concat!("fn confirm_", "card(&self"),
            concat!("enum Workspace", "MenuAction"),
        );
        assert_eq!(
            shared.matches(concat!("is_enabled(!accent || ", "card.acked)")).count(),
            1,
            "那把尺只许一枚、且不许为了第二张脸改表达式"
        );
        assert!(shared.contains(concat!("if card.", "show_ack {")), "那一行包进 `if` 而不是删掉");
    }

    /// 判据⑤：键盘三档各**恰好一枚**、报位一枚、宿主那一格一枚且排在第一发之后。
    /// 变异证明：把报位那一枚删掉 ⇒ 第四把红（三档成死码，FA1-F-2 的老账）；
    /// 把 `Move` 那一档并进 `Close` ⇒ 第二把红。
    #[test]
    fn the_three_keyboard_tiers_and_the_host_cell_are_wired() {
        let code = code();
        for tier in [
            concat!("Msg::PaletteClose ", "if self.reset_confirm.is_some()"),
            concat!("Msg::PaletteMove(_) ", "if self.reset_confirm.is_some()"),
            concat!("Msg::PaletteAccept ", "if self.reset_confirm.is_some()"),
            concat!("|| self.reset_confirm.", "is_some()"),
        ] {
            assert_eq!(
                code.matches(tier).count(),
                1,
                "这一档漂了（一枚不多、一枚不少）：{tier}"
            );
        }
        let body = window(&code, concat!("fn ", "body("), concat!("fn column_", "splitter("));
        let key = concat!("\"", "reset-confirm\"");
        assert_eq!(body.matches(key).count(), 1, "槽位枚数变了：一处不多一处不少（不开时那棵节点不生成）");
        assert!(
            body.contains(concat!("self.reset_confirm_", "card(context, p)")),
            "宿主没把第二发交给那套卡体"
        );
        let first = body
            .find(concat!("\"", "permission-confirm\""))
            .expect("宿主少了第一发那一格");
        let second = body.find(key).expect("宿主少了第二发那一格");
        assert!(first < second, "第二发不排末位 ⇒ 它压不住第一发那张（入树序与问序得同序）");
    }

    /// 判据⑥：A 道走表 —— 族 A 第二发那三枚主干串在分叉各**恰好一枚出处**（本刀第一次把它们
    /// 用起来；`src/i18n.rs` 侧五枚**早已在册** ⇒ 字典零新登记，本刀一行没碰那一文件）。
    /// ⚠ 标题键的 `「」` 与 `{0}`、`PrimaryButtonText` 的键名 `恢复`（**不是** `恢复默认`）都一字
    /// 不许改：改了查不到 `ShellEnglish` 那一行 ⇒ A 道退化成硬字面量 = 中英同串 = 偏离。
    #[test]
    fn the_second_face_reads_the_registered_trunk_strings() {
        let code = code();
        for key in [
            concat!("恢复「{0}", "」默认"),
            concat!("将清空这些命名空间的用户设置：{0}", "。"),
            concat!("内核默认值会立即生效，", "此操作不可撤销。"),
        ] {
            assert_eq!(
                code.matches(key).count(),
                1,
                "主干那枚串在分叉只许一处出处（走 `l`/`lf`，不在这里再本地化第二遍）：{key}"
            );
        }
        assert_eq!(
            code.matches(concat!("primary: \"", "恢复\"")).count(),
            1,
            "`PrimaryButtonText` 的键名就是 `恢复`"
        );
        let cancel_foot = concat!("foot(\"取消\", false, ", "None, 2, Msg::DangerConfirmDismiss");
        assert_eq!(
            code.matches(cancel_foot).count(),
            1,
            "那一枚不许进 `ConfirmFace`：两发都是 `取消`，串只在共享卡体那一枚脚钮里出现一次才是唯一真相\
             （针里点名族 A 那枚 dismiss 消息，别的族 `foot` 里同字的 `取消` 一处也不算进来）"
        );
    }
}
